window.haloData = {"brands": [{"id": "bioderma", "name": "Bioderma", "description": {"vi": "Bioderma là thương hiệu dược mỹ phẩm đến từ Pháp, ra đời năm 1977 và thuộc NAOS – tập đoàn chuyên nghiên cứu, phát triển các giải pháp chăm sóc da dựa trên sự hiểu biết về sinh học làn da. Với định hướng tôn trọng cơ chế tự nhiên của da, Bioderma tập trung phát triển những công thức chăm sóc phù hợp với từng loại da và các nhu cầu khác nhau, đặc biệt là làn da nhạy cảm.\n\nTriết lý phát triển của Bioderma gắn liền với Ecobiology – cách tiếp cận xem làn da như một hệ sinh thái sống, chịu tác động đồng thời từ môi trường, lối sống và các yếu tố sinh học. Thay vì chỉ tập trung xử lý biểu hiện bên ngoài, thương hiệu hướng đến việc hỗ trợ các cơ chế tự nhiên, duy trì sự cân bằng và khả năng thích nghi của làn da.\n\nMột trong những dấu ấn nổi bật của Bioderma là việc ứng dụng công nghệ micellar trong sản phẩm làm sạch. Nước tẩy trang Sensibio H2O trở thành sản phẩm tiêu biểu của thương hiệu nhờ khả năng loại bỏ lớp trang điểm và tạp chất bằng công thức hướng đến nhu cầu của da nhạy cảm. Bên cạnh đó, Bioderma còn phát triển nhiều dòng sản phẩm chăm sóc chuyên biệt.\n\nTrong quá trình phát triển sản phẩm, Bioderma chú trọng lựa chọn thành phần phù hợp với đặc điểm sinh học của da, kết hợp các công nghệ và phức hợp chăm sóc riêng như D.A.F. Patent, Fluidactiv và Skin Barrier Therapy tùy từng dòng sản phẩm. Những công nghệ này được sử dụng nhằm hỗ trợ chăm sóc da nhạy cảm, da dầu hoặc da khô theo nhu cầu cụ thể.\n\nVới danh mục sản phẩm đa dạng, Bioderma mang đến nhiều lựa chọn từ nước tẩy trang, sữa rửa mặt, kem dưỡng, sản phẩm chăm sóc da cơ thể đến kem chống nắng. Thương hiệu được biết đến rộng rãi trên thị trường dược mỹ phẩm quốc tế và tại Việt Nam, đặc biệt trong lĩnh vực làm sạch và chăm sóc da nhạy cảm.", "en": "A French skincare brand with cleansing, moisturising and sun care products, including its Sensibio, Sébium and Atoderm ranges."}, "logo": "assets/catalog/brand-bioderma.jpg"}, {"id": "vichy", "name": "Vichy", "description": {"vi": "Vichy là thương hiệu dược mỹ phẩm có nguồn gốc từ Pháp, được thành lập năm 1931 và hiện thuộc tập đoàn L'Oréal. Thương hiệu lấy tên từ thành phố Vichy, nơi nổi tiếng với nguồn nước khoáng núi lửa tự nhiên. Trải qua nhiều thập kỷ phát triển, Vichy xây dựng vị thế trong lĩnh vực chăm sóc da và da đầu dựa trên sự kết hợp giữa nghiên cứu khoa học, kiến thức da liễu và các thành phần hoạt tính được lựa chọn cho từng nhu cầu sử dụng.\n\nĐiểm đặc trưng của thương hiệu là nước khoáng núi lửa Vichy, thành phần có nguồn gốc từ vùng núi lửa Auvergne tại Pháp. Nguồn nước khoáng này được đưa vào nhiều công thức của hãng nhằm hỗ trợ chăm sóc hàng rào bảo vệ da, duy trì cảm giác dễ chịu và tăng cường khả năng chống chịu của da trước các tác động thường ngày từ môi trường.\n\nVichy phát triển danh mục sản phẩm đa dạng, hướng đến những nhu cầu như cấp ẩm, chăm sóc da dầu mụn, hỗ trợ cải thiện dấu hiệu lão hóa, làm đều màu da, chống nắng và chăm sóc da đầu. Các sản phẩm được nghiên cứu với sự tham gia của chuyên gia trong lĩnh vực chăm sóc da, đồng thời trải qua những quy trình đánh giá phù hợp với đặc điểm từng công thức.\n\nVichy chú trọng phát triển các sản phẩm có kết cấu phù hợp với nhu cầu chăm sóc da hằng ngày, từ tinh chất, kem dưỡng, sữa rửa mặt đến kem chống nắng và dầu gội chuyên biệt. Tùy từng dòng sản phẩm, công thức có thể chứa các thành phần như Hyaluronic Acid, Niacinamide, Salicylic Acid, Vitamin C và các thành phần hỗ trợ chăm sóc da khác.\n\nVới lịch sử phát triển lâu năm, danh mục sản phẩm phong phú và định hướng nghiên cứu dựa trên khoa học da liễu, Vichy là một trong những thương hiệu dược mỹ phẩm Pháp được nhiều người tiêu dùng biết đến trên thị trường quốc tế, trong đó có Việt Nam.", "en": "A French skincare brand with facial skincare, sun care and scalp care products, including Minéral 89, Liftactiv and Dercos."}, "logo": "assets/catalog/brand-vichy.png"}, {"id": "laneige", "name": "Laneige", "description": {"vi": "LANEIGE là thương hiệu mỹ phẩm chăm sóc da và trang điểm cao cấp đến từ Hàn Quốc, được ra mắt vào năm 1994 và trực thuộc tập đoàn Amorepacific – một trong những tập đoàn mỹ phẩm hàng đầu Hàn Quốc. Tên gọi LANEIGE bắt nguồn từ tiếng Pháp, mang ý nghĩa “tuyết”, thể hiện hình ảnh làn da trong trẻo, tươi mát và tràn đầy sức sống.\n\nVới triết lý làm đẹp lấy độ ẩm làm nền tảng, LANEIGE tập trung nghiên cứu các giải pháp chăm sóc da nhằm cải thiện tình trạng thiếu nước, duy trì độ ẩm và hỗ trợ củng cố hàng rào bảo vệ da. Thương hiệu phát triển nhiều công nghệ và công thức chăm sóc da, nổi bật với Blue Hyaluronic Acid trong dòng Water Bank, cùng các sản phẩm dưỡng ẩm chuyên biệt dành cho da mặt và môi.\n\nCác dòng sản phẩm tiêu biểu của LANEIGE bao gồm Water Bank với các sản phẩm serum và kem dưỡng ẩm; Cream Skin kết hợp đặc tính của toner và kem dưỡng; Water Sleeping Mask chăm sóc da ban đêm; Lip Sleeping Mask dưỡng môi chuyên sâu; và Neo Cushion phục vụ nhu cầu trang điểm nền.\n\nLANEIGE hướng đến trải nghiệm chăm sóc da hiện đại, kết hợp giữa nghiên cứu khoa học, kết cấu sản phẩm dễ sử dụng và thiết kế tinh tế. Danh mục sản phẩm đa dạng giúp người dùng lựa chọn giải pháp phù hợp với từng loại da, nhu cầu dưỡng ẩm và thói quen làm đẹp.\n\nVới nhiều năm phát triển trên thị trường mỹ phẩm quốc tế, LANEIGE đã trở thành một trong những thương hiệu làm đẹp Hàn Quốc được biết đến rộng rãi, đặc biệt trong lĩnh vực chăm sóc và duy trì độ ẩm cho da.", "en": "A Korean beauty brand with skincare, lip care and complexion products, including its Water Bank and sleeping mask collections."}, "logo": "assets/catalog/brand-laneige.jpg"}, {"id": "maybelline", "name": "Maybelline", "description": {"vi": "Maybelline New York là thương hiệu mỹ phẩm trang điểm có nguồn gốc từ Hoa Kỳ, mang tinh thần sáng tạo và phong cách làm đẹp hiện đại của thành phố New York. \n\nThương hiệu cung cấp nhiều dòng sản phẩm trang điểm như kem nền, kem che khuyết điểm, phấn phủ, mascara, kẻ mắt và son môi.\n\nMaybelline hướng đến việc giúp người dùng tự tin thể hiện phong cách cá nhân thông qua những sản phẩm trang điểm đa dạng màu sắc, dễ sử dụng và phù hợp nhiều nhu cầu làm đẹp.", "en": "A makeup brand originating in the United States. This collection includes complexion, eye and lip makeup, alongside makeup removers."}, "logo": ""}, {"id": "dove", "name": "Dove", "description": {"vi": "Tên thương hiệu: Dove\nQuốc gia thương hiệu: Hoa Kỳ\nTập đoàn sở hữu: Unilever\nNgành hàng: Chăm sóc cá nhân – Chăm sóc cơ thể và tóc\n\nDove là thương hiệu chăm sóc cá nhân thuộc tập đoàn Unilever, được biết đến với các sản phẩm làm sạch và dưỡng ẩm cho da, cùng các giải pháp chăm sóc tóc hằng ngày.\n\nDanh mục Dove bao gồm sữa tắm, sản phẩm làm sạch cơ thể, dầu gội, dầu xả và các dòng chăm sóc cá nhân khác. Thương hiệu chú trọng kết hợp khả năng làm sạch với trải nghiệm chăm sóc da và tóc mềm mại.\n\nTại Việt Nam, Dove cung cấp nhiều dòng sữa tắm dưỡng ẩm, sữa tắm serum và sản phẩm chăm sóc tóc đáp ứng các nhu cầu khác nhau như làm sạch, dưỡng ẩm, phục hồi vẻ ngoài của tóc hư tổn và chăm sóc tóc dễ gãy rụng.\n\nDove cũng được biết đến với các hoạt động truyền thông hướng đến sự tự tin và vẻ đẹp đa dạng.", "en": "A personal care brand in the Unilever portfolio, with body cleansing, shampoo and conditioner products in this collection."}, "logo": "assets/catalog/brand-dove.jpg"}, {"id": "la-roche-posay", "name": "La Roche-Posay", "description": {"vi": "Tên thương hiệu: La Roche-Posay\nQuốc gia thương hiệu: Pháp\nNgành hàng: Dược mỹ phẩm – Chăm sóc da\n\nLa Roche-Posay là thương hiệu dược mỹ phẩm đến từ Pháp, nổi bật với các giải pháp chăm sóc da được phát triển dựa trên nghiên cứu khoa học và sự hợp tác với các chuyên gia da liễu.\n\nThương hiệu tập trung vào nhu cầu chăm sóc da nhạy cảm, da dầu mụn, da khô, da thiếu ẩm và làn da cần được bảo vệ trước tác động của ánh nắng mặt trời.\n\nMột trong những thành phần đặc trưng của thương hiệu là nước khoáng La Roche-Posay, được sử dụng trong nhiều công thức nhằm hỗ trợ làm dịu và chăm sóc da.\n\nDanh mục sản phẩm đa dạng với các dòng nổi bật như Effaclar dành cho da dầu mụn, Cicaplast hỗ trợ làm dịu và phục hồi hàng rào bảo vệ da, Anthelios chống nắng, Toleriane chăm sóc da nhạy cảm và Mela B3 dưỡng sáng.\n\nLa Roche-Posay chú trọng phát triển các công thức phù hợp với nhu cầu chăm sóc da hằng ngày, kết hợp hiệu quả sử dụng với khả năng dung nạp trên da nhạy cảm.", "en": "A French skincare brand with cleansing, moisturising and sun care ranges, including Effaclar, Cicaplast and Anthelios."}, "logo": "assets/catalog/brand-la-roche-posay.png"}, {"id": "kyunglab", "name": "KyungLab", "description": {"vi": "Tên thương hiệu: KYUNGLAB\nQuốc gia thương hiệu: Hàn Quốc\nNgành hàng: Mỹ phẩm chăm sóc da\n\nKYUNGLAB là thương hiệu mỹ phẩm chăm sóc da đến từ Hàn Quốc, cung cấp các dòng sản phẩm phục vụ nhu cầu làm sạch, cấp ẩm, làm dịu, dưỡng sáng và chăm sóc da có dấu hiệu lão hóa.\n\nDanh mục sản phẩm của KYUNGLAB bao gồm tinh chất dưỡng da, kem dưỡng, sản phẩm làm sạch, mặt nạ, kem chống nắng và mỹ phẩm trang điểm.\n\nThương hiệu phát triển nhiều dòng sản phẩm với các thành phần chăm sóc da như Hyaluronic Acid, Panthenol, peptide, chiết xuất rau má và các chiết xuất thực vật. Một số dòng sản phẩm đã được nâng cấp công thức và thiết kế bao bì.\n\nVới danh mục sản phẩm đa dạng, KYUNGLAB mang đến các lựa chọn chăm sóc da phù hợp với nhiều nhu cầu, từ quy trình dưỡng da hằng ngày đến chăm sóc chuyên sâu.", "en": "A Korean skincare brand with cleansers, ampoules, moisturisers and complexion products in this collection."}, "logo": "assets/catalog/brand-kyunglab.jpg"}, {"id": "cerave", "name": "CeraVe", "description": {"vi": "Tên thương hiệu: CeraVe\nQuốc gia thương hiệu: Hoa Kỳ\nNăm ra mắt: 2005\nNgành hàng: Dược mỹ phẩm – Chăm sóc da\n\nCeraVe là thương hiệu chăm sóc da đến từ Hoa Kỳ, được phát triển cùng các bác sĩ da liễu và ra mắt vào năm 2005.\n\nThương hiệu nổi bật với các sản phẩm làm sạch và dưỡng ẩm, tập trung vào việc duy trì và hỗ trợ phục hồi hàng rào bảo vệ tự nhiên của da.\n\nĐiểm đặc trưng của CeraVe là công thức chứa ba loại ceramide thiết yếu, giúp bổ sung các lipid quan trọng của hàng rào bảo vệ da, hỗ trợ giữ ẩm và giảm tình trạng mất nước.\n\nNhiều sản phẩm CeraVe còn kết hợp Hyaluronic Acid, Niacinamide và công nghệ MVE nhằm hỗ trợ dưỡng ẩm, làm dịu và chăm sóc da hiệu quả.\n\nDanh mục sản phẩm đa dạng, bao gồm sữa rửa mặt, kem dưỡng ẩm, sữa dưỡng thể, sản phẩm chăm sóc da dầu mụn và kem chống nắng.\n\nVới định hướng phát triển sản phẩm cùng các chuyên gia da liễu, CeraVe mang đến những giải pháp chăm sóc da hằng ngày phù hợp với nhiều loại da, từ da thường, da dầu đến da khô và da nhạy cảm.", "en": "A skincare brand originating in the United States, with facial cleansers, moisturisers and body care products."}, "logo": "assets/catalog/brand-cerave.png"}, {"id": "l-oreal-paris", "name": "L'Oréal Paris", "description": {"vi": "- L'Oréal Paris là thương hiệu mỹ phẩm đến từ Pháp, trực thuộc Tập đoàn L'Oréal, một trong những tập đoàn hàng đầu thế giới trong lĩnh vực làm đẹp.\n- Với lịch sử phát triển hơn 110 năm, L'Oréal Paris kết hợp nghiên cứu khoa học, công nghệ tiên tiến và sự đổi mới để phát triển các sản phẩm chăm sóc da, trang điểm, chăm sóc tóc và nhuộm tóc.\n- Thương hiệu hướng đến việc mang các giải pháp làm đẹp chất lượng, đa dạng và dễ tiếp cận tới người tiêu dùng trên toàn thế giới, trong đó có Việt Nam.", "en": "A French beauty brand with skincare and haircare ranges, including Glycolic Bright, Revitalift and Elseve."}, "logo": ""}, {"id": "usolab", "name": "Usolab", "description": {"vi": "Tên thương hiệu: USOLAB\nQuốc gia: Hàn Quốc\nNăm ra đời: 2005\nNgành hàng: Dược mỹ phẩm – Chăm sóc da chuyên sâu\n\nUSOLAB là thương hiệu dược mỹ phẩm đến từ Hàn Quốc, ra đời năm 2005, chuyên nghiên cứu và phát triển các sản phẩm chăm sóc da dựa trên nền tảng khoa học da liễu hiện đại.\n\nThương hiệu tập trung kết hợp các thành phần chăm sóc da với công nghệ nghiên cứu và phát triển công thức, nhằm mang đến giải pháp chăm sóc phù hợp với nhiều tình trạng da khác nhau.\n\nDanh mục sản phẩm USOLAB đa dạng, bao gồm tinh chất dưỡng da, kem dưỡng, sản phẩm làm sạch, mặt nạ, kem chống nắng và các dòng chăm sóc da chuyên sâu.\n\nCác dòng sản phẩm nổi bật hướng đến nhu cầu cấp ẩm, dưỡng sáng, làm dịu, chăm sóc da nhạy cảm và hỗ trợ cải thiện vẻ ngoài của làn da có dấu hiệu lão hóa.\n\nVới định hướng kết hợp nghiên cứu khoa học và các thành phần chăm sóc da, USOLAB mang đến nhiều lựa chọn cho quy trình chăm sóc da hằng ngày cũng như chăm sóc chuyên sâu.", "en": "A Korean skincare brand with cleansers, ampoules, moisturisers, masks and body care products in this collection."}, "logo": "assets/catalog/brand-usolab.png"}], "products": [{"id": "bioderma-01", "brandId": "bioderma", "brand": "Bioderma", "name": {"vi": "NƯỚC TẨY TRANG BIODERMA SENSIBIO H2O 500ML", "en": "Bioderma Sensibio H2O Micellar Water 500ml"}, "category": "Skincare", "type": "Nước tẩy trang cho da nhạy cảm", "size": "Chai 500ml", "country": "Pháp", "description": {"vi": "1. MÔ TẢ SẢN PHẨM\n\nTên sản phẩm: Nước Tẩy Trang Bioderma Sensibio H2O 500ml\nThương hiệu: Bioderma\nQuốc gia thương hiệu: Pháp\nQuy cách đóng gói: Chai 500ml\nPhân loại: Nước tẩy trang cho da nhạy cảm\n\nBioderma Sensibio H2O 500ml là nước tẩy trang ứng dụng công nghệ micellar, được phát triển cho làn da nhạy cảm. Các phân tử micelle hỗ trợ thu hút và loại bỏ lớp trang điểm, bụi bẩn cùng tạp chất trên bề mặt da mà không cần chà xát mạnh. Công thức hướng đến khả năng làm sạch nhẹ nhàng, duy trì cảm giác dễ chịu và hạn chế khô căng sau khi sử dụng.\n\n2. CÔNG DỤNG\n\n• Làm sạch bụi bẩn và lớp trang điểm thông thường.\n• Hỗ trợ loại bỏ tạp chất trên da mặt và vùng mắt.\n• Giúp duy trì cảm giác mềm mại, dễ chịu.\n• Phù hợp với quy trình làm sạch da nhạy cảm.\n\n3. THÀNH PHẦN\n\nCác thành phần nổi bật:\n\n• PEG-6 Caprylic/Capric Glycerides: Thành phần làm sạch theo cơ chế micellar.\n• Mannitol, Xylitol và Rhamnose: Các thành phần trong phức hợp chăm sóc da.\n• Fructooligosaccharides: Thành phần hỗ trợ công thức.\n• Cucumis Sativus Fruit Extract: Chiết xuất dưa leo.\n\nLưu ý: Các thành phần trên mang tính giới thiệu, không thay thế bảng INCI đầy đủ trên bao bì. Công thức có thể thay đổi theo phiên bản và thị trường.\n\n4. HƯỚNG DẪN SỬ DỤNG\n\n1. Thấm lượng nước tẩy trang vừa đủ lên bông cotton.\n2. Lau nhẹ nhàng trên mặt, mắt và môi.\n3. Lặp lại với bông sạch đến khi loại bỏ lớp trang điểm.\n4. Không cần rửa lại theo hướng dẫn của dòng Sensibio H2O; có thể tiếp tục làm sạch nếu quy trình cá nhân yêu cầu.\n\nLưu ý: Chỉ sử dụng ngoài da. Ngừng sử dụng nếu xuất hiện kích ứng kéo dài. Với các tình trạng da cần điều trị, nên tham khảo chuyên gia y tế.\n\n5. ĐỐI TƯỢNG SỬ DỤNG\n\n• Người có da nhạy cảm.\n• Người cần tẩy trang hằng ngày.\n• Người sử dụng kem chống nắng hoặc trang điểm thông thường.", "en": "1. PRODUCT DESCRIPTION\n\nBioderma Sensibio H2O is a gentle micellar cleansing water specifically developed for sensitive skin. Its micellar technology helps capture and remove makeup, dirt, pollution particles and everyday impurities from the skin without the need for vigorous rubbing. The lightweight, water-like formula is designed to respect skin comfort and leave the complexion feeling clean, fresh and soft. It can be incorporated into a daily cleansing routine for the face and eyes, including the removal of ordinary makeup and sunscreen.\n\n2. BENEFITS\n\n• Gently removes everyday makeup, dirt and surface impurities.\n• Helps cleanse sensitive skin without excessive friction.\n• Leaves skin feeling refreshed, soft and comfortable.\n• Supports a simple and convenient daily cleansing routine.\n• Suitable for use on the face and eye area as directed.\n\n3. INGREDIENTS\n\nKey ingredients and their functions:\n\n• PEG-6 Caprylic/Capric Glycerides: A cleansing ingredient that helps micelles lift impurities from the skin.\n• Mannitol: A sugar-derived skin-conditioning ingredient.\n• Xylitol: A moisturizing and skin-conditioning ingredient.\n• Rhamnose: A sugar-derived ingredient used in the skincare complex.\n• Fructooligosaccharides: A component of the skin-conditioning formula.\n• Cucumis Sativus (Cucumber) Fruit Extract: A botanical ingredient used in the formulation.\n\nNote: These are selected ingredients or formulation components, not a complete INCI declaration. Always verify the ingredient list against the actual product packaging, as formulations may vary by market and version.\n\n4. DIRECTIONS FOR USE\n\n1. Saturate a cotton pad with Sensibio H2O.\n2. Gently wipe the face and eye area to remove makeup and impurities.\n3. Repeat with a fresh cotton pad until it comes away clean.\n4. No rinsing is required according to the product's intended use; follow with the rest of your skincare routine.\n\n5. SUITABLE FOR\n\n• Sensitive and easily reactive skin.\n• People looking for a gentle daily makeup remover.\n• Individuals who regularly use sunscreen or light makeup.\n• Those who prefer a convenient micellar cleansing water."}, "image": "assets/catalog/product-bioderma-01.jpg", "gallery": {"vi": [{"src": "assets/catalog/vi/bioderma-01/thumbnail.webp", "label": "Thumbnail", "order": 0}, {"src": "assets/catalog/vi/bioderma-01/anh-1.webp", "label": "Ảnh 1", "order": 1}, {"src": "assets/catalog/vi/bioderma-01/anh-2.webp", "label": "Ảnh 2", "order": 2}, {"src": "assets/catalog/vi/bioderma-01/anh-3.webp", "label": "Ảnh 3", "order": 3}, {"src": "assets/catalog/vi/bioderma-01/anh-4.webp", "label": "Ảnh 4", "order": 4}, {"src": "assets/catalog/vi/bioderma-01/anh-5.webp", "label": "Ảnh 5", "order": 5}, {"src": "assets/catalog/vi/bioderma-01/anh-6.webp", "label": "Ảnh 6", "order": 6}, {"src": "assets/catalog/vi/bioderma-01/anh-7.webp", "label": "Ảnh 7", "order": 7}]}}, {"id": "bioderma-02", "brandId": "bioderma", "brand": "Bioderma", "name": {"vi": "NƯỚC TẨY TRANG BIODERMA SÉBIUM H2O 500ML", "en": "Bioderma Sébium H2O Micellar Water 500ml"}, "category": "Skincare", "type": "Nước tẩy trang cho da dầu", "size": "Chai 500ml", "country": "Pháp", "description": {"vi": "1. MÔ TẢ SẢN PHẨM\n\nTên sản phẩm: Nước Tẩy Trang Bioderma Sébium H2O 500ml\nThương hiệu: Bioderma\nQuốc gia thương hiệu: Pháp\nQuy cách đóng gói: Chai 500ml\nPhân loại: Nước tẩy trang cho da dầu\n\nBioderma Sébium H2O 500ml là nước tẩy trang micellar được phát triển cho da hỗn hợp, da dầu và da dễ nổi mụn. Sản phẩm giúp làm sạch dầu thừa, bụi bẩn và lớp trang điểm, đồng thời hỗ trợ chăm sóc bề mặt da có xu hướng tiết nhiều bã nhờn. Kết cấu dạng nước nhẹ, thuận tiện sử dụng trong bước làm sạch đầu tiên.\n\n2. CÔNG DỤNG\n\n• Loại bỏ bụi bẩn, dầu thừa và lớp trang điểm.\n• Hỗ trợ làm sạch bề mặt da dầu.\n• Mang lại cảm giác sạch thoáng.\n• Phù hợp sử dụng hằng ngày.\n\n3. THÀNH PHẦN\n\nCác thành phần nổi bật:\n\n• PEG-6 Caprylic/Capric Glycerides: Chất làm sạch micellar.\n• Zinc Gluconate: Thành phần chăm sóc da dầu.\n• Copper Sulfate: Thành phần trong công thức dành cho da dầu.\n• Mannitol, Xylitol và Rhamnose: Các thành phần hỗ trợ chăm sóc da.\n• Fragrance: Thành phần tạo hương trong công thức.\n\nLưu ý: Các thành phần trên mang tính giới thiệu, không thay thế bảng INCI đầy đủ trên bao bì. Công thức có thể thay đổi theo phiên bản và thị trường.\n\n4. HƯỚNG DẪN SỬ DỤNG\n\n1. Thấm sản phẩm lên bông tẩy trang.\n2. Lau nhẹ trên da mặt.\n3. Thay bông và tiếp tục đến khi sạch.\n4. Có thể tiếp tục rửa mặt với gel làm sạch phù hợp.\n\nLưu ý: Chỉ sử dụng ngoài da. Ngừng sử dụng nếu xuất hiện kích ứng kéo dài. Với các tình trạng da cần điều trị, nên tham khảo chuyên gia y tế.\n\n5. ĐỐI TƯỢNG SỬ DỤNG\n\n• Người có da dầu hoặc da hỗn hợp.\n• Người có da dễ nổi mụn.\n• Người cần nước tẩy trang cho da tiết nhiều dầu.", "en": "1. PRODUCT DESCRIPTION\n\nBioderma Sébium H2O is a micellar cleansing water developed for combination, oily and blemish-prone skin. It helps remove makeup, excess surface oil and daily impurities while leaving the skin feeling clean and refreshed. Its water-light texture makes it a convenient first step in a cleansing routine, particularly for individuals whose skin tends to become shiny during the day. The formula combines micellar cleansing agents with ingredients selected for oily-skin care.\n\n2. BENEFITS\n\n• Removes ordinary makeup and accumulated impurities.\n• Helps eliminate excess oil from the skin's surface.\n• Leaves the complexion feeling clean and refreshed.\n• Supports daily cleansing for combination and oily skin.\n• Provides a convenient first step before facial washing.\n\n3. INGREDIENTS\n\nKey ingredients and their functions:\n\n• PEG-6 Caprylic/Capric Glycerides: A micellar cleansing ingredient.\n• Zinc Gluconate: A skin-conditioning ingredient often used in oily-skin formulas.\n• Copper Sulfate: A component included in the oily-skin cleansing formula.\n• Mannitol: A sugar-derived skin-conditioning ingredient.\n• Xylitol and Rhamnose: Components of the skincare complex.\n• Fragrance: A fragrance ingredient included in the formula; check the packaging for the current composition.\n\nNote: These are selected ingredients or formulation components, not a complete INCI declaration. Always verify the ingredient list against the actual product packaging, as formulations may vary by market and version.\n\n4. DIRECTIONS FOR USE\n\n1. Apply a sufficient amount to a clean cotton pad.\n2. Gently wipe the face to remove makeup and surface impurities.\n3. Repeat as necessary until the cotton pad is clean.\n4. Continue with a suitable facial cleanser if desired.\n5. Follow with a moisturizer appropriate for oily or combination skin.\n\n5. SUITABLE FOR\n\n• Combination to oily skin.\n• Blemish-prone skin.\n• People experiencing excess facial shine.\n• Individuals looking for an everyday micellar makeup remover."}, "image": "assets/catalog/product-bioderma-02.jpg", "gallery": {"vi": [{"src": "assets/catalog/vi/bioderma-02/thumbnail.webp", "label": "Thumbnail", "order": 0}, {"src": "assets/catalog/vi/bioderma-02/anh-1.webp", "label": "Ảnh 1", "order": 1}, {"src": "assets/catalog/vi/bioderma-02/anh-2.webp", "label": "Ảnh 2", "order": 2}, {"src": "assets/catalog/vi/bioderma-02/anh-3.webp", "label": "Ảnh 3", "order": 3}, {"src": "assets/catalog/vi/bioderma-02/anh-4.webp", "label": "Ảnh 4", "order": 4}, {"src": "assets/catalog/vi/bioderma-02/anh-5.webp", "label": "Ảnh 5", "order": 5}, {"src": "assets/catalog/vi/bioderma-02/anh-6.webp", "label": "Ảnh 6", "order": 6}, {"src": "assets/catalog/vi/bioderma-02/anh-7.webp", "label": "Ảnh 7", "order": 7}]}}, {"id": "bioderma-03", "brandId": "bioderma", "brand": "Bioderma", "name": {"vi": "GEL RỬA MẶT BIODERMA SÉBIUM GEL MOUSSANT 200ML", "en": "Bioderma Sébium Gel Moussant Purifying Cleansing Foaming Gel 200ml"}, "category": "Skincare", "type": "Gel rửa mặt cho da dầu", "size": "Chai 200ml", "country": "Pháp", "description": {"vi": "1. MÔ TẢ SẢN PHẨM\n\nTên sản phẩm: Gel Rửa Mặt Bioderma Sébium Gel Moussant 200ml\nThương hiệu: Bioderma\nQuốc gia thương hiệu: Pháp\nQuy cách đóng gói: Chai 200ml\nPhân loại: Gel rửa mặt cho da dầu\n\nBioderma Sébium Gel Moussant 200ml là gel làm sạch dành cho da hỗn hợp đến da dầu. Công thức tạo bọt giúp loại bỏ bụi bẩn, mồ hôi và bã nhờn trên bề mặt da, đồng thời duy trì cảm giác sạch thoáng. Sản phẩm phù hợp sử dụng trong quy trình chăm sóc da dầu hằng ngày.\n\n2. CÔNG DỤNG\n\n• Làm sạch bụi bẩn và dầu thừa.\n• Giúp bề mặt da sạch thoáng.\n• Hỗ trợ chăm sóc da có xu hướng tiết nhiều bã nhờn.\n• Có thể sử dụng trong quy trình làm sạch sáng và tối.\n\n3. THÀNH PHẦN\n\nCác thành phần nổi bật:\n\n• Sodium Cocoamphoacetate: Chất hoạt động bề mặt làm sạch.\n• Sodium Laureth Sulfate: Chất làm sạch và tạo bọt.\n• Zinc Sulfate: Thành phần chăm sóc da dầu.\n• Copper Sulfate: Thành phần trong công thức.\n• Mannitol, Xylitol và Rhamnose: Các thành phần hỗ trợ chăm sóc da.\n\nLưu ý: Các thành phần trên mang tính giới thiệu, không thay thế bảng INCI đầy đủ trên bao bì. Công thức có thể thay đổi theo phiên bản và thị trường.\n\n4. HƯỚNG DẪN SỬ DỤNG\n\n1. Làm ướt mặt bằng nước.\n2. Lấy lượng gel vừa đủ và tạo bọt.\n3. Massage nhẹ nhàng trên da.\n4. Rửa sạch lại với nước.\n5. Sử dụng sáng và tối tùy nhu cầu.\n\nLưu ý: Chỉ sử dụng ngoài da. Ngừng sử dụng nếu xuất hiện kích ứng kéo dài. Với các tình trạng da cần điều trị, nên tham khảo chuyên gia y tế.\n\n5. ĐỐI TƯỢNG SỬ DỤNG\n\n• Người có da dầu, da hỗn hợp.\n• Người có da dễ nổi mụn.\n• Người cần gel làm sạch da mặt hằng ngày.", "en": "1. PRODUCT DESCRIPTION\n\nBioderma Sébium Gel Moussant is a foaming facial cleanser designed for combination, oily and blemish-prone skin. Its cleansing formula helps remove excess sebum, sweat, dirt and other daily impurities from the skin's surface. The gel transforms into a light foam when mixed with water, allowing the face to be cleansed thoroughly while maintaining a comfortable skin feel. It is suitable for incorporation into a regular morning and evening cleansing routine.\n\n2. BENEFITS\n\n• Cleanses the skin and removes daily impurities.\n• Helps wash away excess surface oil.\n• Leaves the complexion feeling fresh and clean.\n• Supports the daily care of combination and oily skin.\n• Prepares the skin for toners, serums and moisturizers.\n\n3. INGREDIENTS\n\nKey ingredients and their functions:\n\n• Sodium Cocoamphoacetate: A cleansing surfactant.\n• Sodium Laureth Sulfate: A cleansing and foaming agent.\n• Zinc Sulfate: A skin-conditioning ingredient used in oily-skin formulas.\n• Copper Sulfate: A component of the cleansing formula.\n• Mannitol: A sugar-derived skin-conditioning ingredient.\n• Xylitol and Rhamnose: Ingredients included in the skincare complex.\n\nNote: These are selected ingredients or formulation components, not a complete INCI declaration. Always verify the ingredient list against the actual product packaging, as formulations may vary by market and version.\n\n4. DIRECTIONS FOR USE\n\n1. Wet the face with lukewarm water.\n2. Dispense a small amount of cleansing gel into the palms.\n3. Work into a foam and gently massage over the face.\n4. Rinse thoroughly with water.\n5. Pat the skin dry and apply a suitable moisturizer.\n6. Use in the morning and evening according to skin tolerance.\n\n5. SUITABLE FOR\n\n• Combination and oily skin.\n• Blemish-prone skin.\n• People who prefer a foaming facial cleanser.\n• Individuals looking for a daily cleanser to remove excess oil."}, "image": "assets/catalog/product-bioderma-03.jpg", "gallery": {"vi": [{"src": "assets/catalog/vi/bioderma-03/thumbnail.webp", "label": "Thumbnail", "order": 0}, {"src": "assets/catalog/vi/bioderma-03/anh-1.webp", "label": "Ảnh 1", "order": 1}, {"src": "assets/catalog/vi/bioderma-03/anh-2.webp", "label": "Ảnh 2", "order": 2}, {"src": "assets/catalog/vi/bioderma-03/anh-3.webp", "label": "Ảnh 3", "order": 3}, {"src": "assets/catalog/vi/bioderma-03/anh-4.webp", "label": "Ảnh 4", "order": 4}, {"src": "assets/catalog/vi/bioderma-03/anh-5.webp", "label": "Ảnh 5", "order": 5}, {"src": "assets/catalog/vi/bioderma-03/anh-6.webp", "label": "Ảnh 6", "order": 6}, {"src": "assets/catalog/vi/bioderma-03/anh-7.webp", "label": "Ảnh 7", "order": 7}]}}, {"id": "bioderma-04", "brandId": "bioderma", "brand": "Bioderma", "name": {"vi": "GEL RỬA MẶT BIODERMA SENSIBIO GEL MOUSSANT 200ML", "en": "Bioderma Sensibio Gel Moussant Soothing Micellar Cleansing Foaming Gel 200ml"}, "category": "Skincare", "type": "Gel rửa mặt cho da nhạy cảm", "size": "Chai 200ml", "country": "Pháp", "description": {"vi": "1. MÔ TẢ SẢN PHẨM\n\nTên sản phẩm: Gel Rửa Mặt Bioderma Sensibio Gel Moussant 200ml\nThương hiệu: Bioderma\nQuốc gia thương hiệu: Pháp\nQuy cách đóng gói: Chai 200ml\nPhân loại: Gel rửa mặt cho da nhạy cảm\n\nBioderma Sensibio Gel Moussant 200ml là gel làm sạch dịu nhẹ hướng đến nhu cầu của da nhạy cảm. Sản phẩm tạo bọt nhẹ giúp làm sạch bụi bẩn, tạp chất và dầu thừa mà vẫn hỗ trợ duy trì độ ẩm, giảm cảm giác khô căng sau khi rửa mặt. Kết cấu gel dễ sử dụng trong quy trình chăm sóc da hằng ngày.\n\n2. CÔNG DỤNG\n\n• Làm sạch nhẹ nhàng bề mặt da.\n• Hỗ trợ duy trì độ ẩm sau khi rửa mặt.\n• Giúp da có cảm giác mềm mại, dễ chịu.\n• Phù hợp sử dụng sáng và tối.\n\n3. THÀNH PHẦN\n\nCác thành phần nổi bật:\n\n• Sodium Cocoamphoacetate: Chất làm sạch.\n• Sodium Lauroyl Sarcosinate: Chất hoạt động bề mặt.\n• Coco-Glucoside: Thành phần làm sạch.\n• Glyceryl Oleate: Hỗ trợ làm mềm da.\n• Mannitol, Xylitol và Rhamnose: Các thành phần chăm sóc da.\n\nLưu ý: Các thành phần trên mang tính giới thiệu, không thay thế bảng INCI đầy đủ trên bao bì. Công thức có thể thay đổi theo phiên bản và thị trường.\n\n4. HƯỚNG DẪN SỬ DỤNG\n\n1. Làm ướt mặt.\n2. Lấy lượng gel vừa đủ ra tay.\n3. Tạo bọt và massage nhẹ trên mặt.\n4. Rửa sạch lại bằng nước.\n5. Lau khô nhẹ nhàng và tiếp tục dưỡng ẩm.\n\nLưu ý: Chỉ sử dụng ngoài da. Ngừng sử dụng nếu xuất hiện kích ứng kéo dài. Với các tình trạng da cần điều trị, nên tham khảo chuyên gia y tế.\n\n5. ĐỐI TƯỢNG SỬ DỤNG\n\n• Người có da nhạy cảm.\n• Người có da thường đến da khô cần làm sạch dịu nhẹ.\n• Người muốn sữa rửa mặt sử dụng hằng ngày.", "en": "1. PRODUCT DESCRIPTION\n\nBioderma Sensibio Gel Moussant is a gentle foaming facial cleanser formulated for sensitive skin. Its gel texture develops into a soft foam that helps remove dirt, excess surface oil and impurities accumulated throughout the day. Designed with skin comfort in mind, the cleanser supports a pleasant washing experience without leaving the skin feeling unnecessarily tight. It can be used as part of a daily skincare routine for people who prefer a mild, rinse-off cleanser.\n\n2. BENEFITS\n\n• Gently removes dirt and everyday impurities.\n• Helps maintain a comfortable skin feel after cleansing.\n• Supports the daily cleansing needs of sensitive skin.\n• Leaves the skin feeling soft and refreshed.\n• Can be used as part of a morning and evening routine.\n\n3. INGREDIENTS\n\nKey ingredients and their functions:\n\n• Sodium Cocoamphoacetate: A cleansing ingredient.\n• Sodium Lauroyl Sarcosinate: A surfactant that supports facial cleansing.\n• Coco-Glucoside: A cleansing agent derived from sugar and fatty alcohol sources.\n• Glyceryl Oleate: A skin-conditioning ingredient that helps maintain softness.\n• Mannitol: A sugar-derived ingredient.\n• Xylitol and Rhamnose: Components of the skin-conditioning complex.\n\nNote: These are selected ingredients or formulation components, not a complete INCI declaration. Always verify the ingredient list against the actual product packaging, as formulations may vary by market and version.\n\n4. DIRECTIONS FOR USE\n\n1. Wet the face with water.\n2. Apply a small amount of gel to the palms.\n3. Gently lather and massage over the face.\n4. Avoid direct contact with the eyes.\n5. Rinse thoroughly and pat dry.\n6. Follow with a moisturizer suitable for sensitive skin.\n\n5. SUITABLE FOR\n\n• Sensitive skin.\n• Normal to dry skin seeking gentle cleansing.\n• People who experience discomfort from harsh cleansers.\n• Individuals looking for an everyday rinse-off facial cleanser."}, "image": "assets/catalog/product-bioderma-04.jpg", "gallery": {"vi": [{"src": "assets/catalog/vi/bioderma-04/thumbnail.webp", "label": "Thumbnail", "order": 0}, {"src": "assets/catalog/vi/bioderma-04/anh-1.webp", "label": "Ảnh 1", "order": 1}, {"src": "assets/catalog/vi/bioderma-04/anh-2.webp", "label": "Ảnh 2", "order": 2}, {"src": "assets/catalog/vi/bioderma-04/anh-3.webp", "label": "Ảnh 3", "order": 3}, {"src": "assets/catalog/vi/bioderma-04/anh-4.webp", "label": "Ảnh 4", "order": 4}, {"src": "assets/catalog/vi/bioderma-04/anh-5.webp", "label": "Ảnh 5", "order": 5}, {"src": "assets/catalog/vi/bioderma-04/anh-6.webp", "label": "Ảnh 6", "order": 6}, {"src": "assets/catalog/vi/bioderma-04/anh-7.webp", "label": "Ảnh 7", "order": 7}]}}, {"id": "bioderma-05", "brandId": "bioderma", "brand": "Bioderma", "name": {"vi": "KEM DƯỠNG BIODERMA ATODERM INTENSIVE BAUME 200ML", "en": "Bioderma Atoderm Intensive Baume Ultra-Soothing Balm 200ml"}, "category": "Skincare", "type": "Kem dưỡng cho da rất khô", "size": "Tuýp hoặc chai 200ml tùy phiên bản", "country": "Pháp", "description": {"vi": "1. MÔ TẢ SẢN PHẨM\n\nTên sản phẩm: Kem Dưỡng Bioderma Atoderm Intensive Baume 200ml\nThương hiệu: Bioderma\nQuốc gia thương hiệu: Pháp\nQuy cách đóng gói: Tuýp hoặc chai 200ml tùy phiên bản\nPhân loại: Kem dưỡng cho da rất khô\n\nBioderma Atoderm Intensive Baume 200ml là sản phẩm dưỡng ẩm chuyên sâu dành cho da rất khô, dễ ngứa và có hàng rào bảo vệ da suy yếu. Công thức giàu chất làm mềm và lipid chăm sóc da, giúp hạn chế mất nước, giảm cảm giác khô căng và hỗ trợ duy trì sự dễ chịu cho da. Sản phẩm có thể sử dụng trên mặt và cơ thể theo hướng dẫn.\n\n2. CÔNG DỤNG\n\n• Dưỡng ẩm chuyên sâu cho da khô và rất khô.\n• Hỗ trợ làm dịu cảm giác ngứa do khô da.\n• Giúp giảm cảm giác căng ráp.\n• Hỗ trợ củng cố hàng rào bảo vệ da.\n• Duy trì cảm giác mềm mại trên da.\n\n3. THÀNH PHẦN\n\nCác thành phần nổi bật:\n\n• Glycerin: Thành phần hút ẩm.\n• Mineral Oil: Thành phần làm mềm và hỗ trợ hạn chế mất nước.\n• Sunflower Seed Oil: Dầu hạt hướng dương.\n• Ceramide NP, AP và EOP: Các thành phần lipid chăm sóc da.\n• Phytosphingosine: Thành phần hỗ trợ hàng rào da.\n• Palmitamide MEA: Thành phần được sử dụng trong công thức chăm sóc da khô.\n\nLưu ý: Các thành phần trên mang tính giới thiệu, không thay thế bảng INCI đầy đủ trên bao bì. Công thức có thể thay đổi theo phiên bản và thị trường.\n\n4. HƯỚNG DẪN SỬ DỤNG\n\n1. Làm sạch da bằng sản phẩm dịu nhẹ.\n2. Lấy lượng kem vừa đủ.\n3. Thoa đều lên vùng da khô ở mặt hoặc cơ thể.\n4. Sử dụng 1–2 lần mỗi ngày hoặc theo hướng dẫn trên bao bì.\n\nLưu ý: Chỉ sử dụng ngoài da. Ngừng sử dụng nếu xuất hiện kích ứng kéo dài. Với các tình trạng da cần điều trị, nên tham khảo chuyên gia y tế.\n\n5. ĐỐI TƯỢNG SỬ DỤNG\n\n• Người có da khô và rất khô.\n• Người có da dễ ngứa do khô.\n• Người cần kem dưỡng ẩm chuyên sâu cho cơ thể và mặt.", "en": "1. PRODUCT DESCRIPTION\n\nBioderma Atoderm Intensive Baume is a rich moisturizing balm developed for very dry, sensitive and discomfort-prone skin. The formula combines moisturizing and emollient ingredients to help replenish skin softness and reduce moisture loss. It is particularly useful for skin that feels tight, rough or itchy due to dryness. The balm can be applied to the face and body as directed, making it a versatile option for daily intensive moisturizing care.\n\n2. BENEFITS\n\n• Provides intensive moisture for dry and very dry skin.\n• Helps reduce tightness and discomfort associated with dryness.\n• Softens rough, dry areas.\n• Supports the skin's protective moisture barrier.\n• Helps maintain a smoother and more comfortable skin feel.\n• Suitable for moisturizing both the face and body as directed.\n\n3. INGREDIENTS\n\nKey ingredients and their functions:\n\n• Glycerin: A humectant that helps attract and retain moisture.\n• Mineral Oil (Paraffinum Liquidum): An emollient that helps reduce moisture loss.\n• Helianthus Annuus (Sunflower) Seed Oil: A plant-derived emollient.\n• Ceramide NP, Ceramide AP and Ceramide EOP: Skin-identical lipid ingredients used in barrier-supporting skincare.\n• Phytosphingosine: A lipid-related skin-conditioning ingredient.\n• Palmitamide MEA: A skin-conditioning ingredient included in the formulation.\n\nNote: These are selected ingredients or formulation components, not a complete INCI declaration. Always verify the ingredient list against the actual product packaging, as formulations may vary by market and version.\n\n4. DIRECTIONS FOR USE\n\n1. Cleanse the skin with a gentle cleanser and pat dry.\n2. Apply a sufficient amount of balm to dry areas of the face or body.\n3. Massage gently until evenly distributed.\n4. Use once or twice daily, or as directed on the product packaging.\n5. Pay additional attention to areas experiencing dryness or roughness.\n\n5. SUITABLE FOR\n\n• Dry and very dry skin.\n• Skin experiencing tightness or itching associated with dryness.\n• Individuals who need intensive body and facial moisturization.\n• People looking for a rich barrier-supporting moisturizing balm."}, "image": "assets/catalog/product-bioderma-05.jpg", "gallery": {"vi": [{"src": "assets/catalog/vi/bioderma-05/thumbnail.webp", "label": "Thumbnail", "order": 0}, {"src": "assets/catalog/vi/bioderma-05/anh-1.webp", "label": "Ảnh 1", "order": 1}, {"src": "assets/catalog/vi/bioderma-05/anh-2.webp", "label": "Ảnh 2", "order": 2}, {"src": "assets/catalog/vi/bioderma-05/anh-3.webp", "label": "Ảnh 3", "order": 3}, {"src": "assets/catalog/vi/bioderma-05/anh-4.webp", "label": "Ảnh 4", "order": 4}, {"src": "assets/catalog/vi/bioderma-05/anh-5.webp", "label": "Ảnh 5", "order": 5}, {"src": "assets/catalog/vi/bioderma-05/anh-6.webp", "label": "Ảnh 6", "order": 6}, {"src": "assets/catalog/vi/bioderma-05/anh-7.webp", "label": "Ảnh 7", "order": 7}]}}, {"id": "bioderma-06", "brandId": "bioderma", "brand": "Bioderma", "name": {"vi": "SỮA TẮM BIODERMA ATODERM GEL DOUCHE 200ML", "en": "Bioderma Atoderm Gel Douche Gentle Shower Gel 200ml"}, "category": "Body care", "type": "Gel tắm cho da khô", "size": "Chai hoặc tuýp 200ml tùy phiên bản", "country": "Pháp", "description": {"vi": "1. MÔ TẢ SẢN PHẨM\n\nTên sản phẩm: Sữa Tắm Bioderma Atoderm Gel Douche 200ml\nThương hiệu: Bioderma\nQuốc gia thương hiệu: Pháp\nQuy cách đóng gói: Chai hoặc tuýp 200ml tùy phiên bản\nPhân loại: Gel tắm cho da khô\n\nBioderma Atoderm Gel Douche 200ml là sản phẩm làm sạch cơ thể được phát triển cho da thường đến da khô. Công thức dạng gel tạo bọt giúp loại bỏ bụi bẩn, mồ hôi và tạp chất, đồng thời hỗ trợ duy trì cảm giác mềm mại sau khi tắm. Sản phẩm phù hợp sử dụng trong quy trình vệ sinh cơ thể hằng ngày.\n\n2. CÔNG DỤNG\n\n• Làm sạch da cơ thể.\n• Hỗ trợ giảm cảm giác khô căng sau khi tắm.\n• Giúp da có cảm giác mềm mại.\n• Phù hợp với nhu cầu làm sạch thường xuyên.\n\n3. THÀNH PHẦN\n\nCác thành phần nổi bật:\n\n• Sodium Laureth Sulfate: Chất làm sạch.\n• Sodium Cocoamphoacetate: Hỗ trợ làm sạch và tạo bọt.\n• Glycerin: Hỗ trợ giữ ẩm.\n• Xylitol và Mannitol: Các thành phần chăm sóc da.\n• Niacinamide: Thành phần hỗ trợ hàng rào bảo vệ da.\n\nLưu ý: Các thành phần trên mang tính giới thiệu, không thay thế bảng INCI đầy đủ trên bao bì. Công thức có thể thay đổi theo phiên bản và thị trường.\n\n4. HƯỚNG DẪN SỬ DỤNG\n\n1. Làm ướt cơ thể.\n2. Lấy lượng gel tắm vừa đủ.\n3. Tạo bọt và massage nhẹ nhàng.\n4. Tắm sạch lại bằng nước.\n5. Thoa kem dưỡng ẩm sau khi tắm nếu cần.\n\nLưu ý: Chỉ sử dụng ngoài da. Ngừng sử dụng nếu xuất hiện kích ứng kéo dài. Với các tình trạng da cần điều trị, nên tham khảo chuyên gia y tế.\n\n5. ĐỐI TƯỢNG SỬ DỤNG\n\n• Người có da thường đến da khô.\n• Người muốn gel tắm dịu nhẹ.\n• Người cần sản phẩm làm sạch cơ thể hằng ngày.", "en": "1. PRODUCT DESCRIPTION\n\nBioderma Atoderm Gel Douche is a gentle shower gel designed for normal to dry skin. Its cleansing formula helps remove sweat, dirt and daily impurities from the body while supporting a comfortable after-shower skin feel. The gel produces a light foam and is suitable for regular cleansing. It can be paired with a body moisturizer to help maintain skin softness, particularly in dry environments or during colder weather.\n\n2. BENEFITS\n\n• Gently cleanses the skin of the body.\n• Removes sweat, dirt and daily impurities.\n• Helps minimize the feeling of dryness after washing.\n• Leaves the skin feeling fresh and comfortable.\n• Suitable for everyday body cleansing.\n\n3. INGREDIENTS\n\nKey ingredients and their functions:\n\n• Sodium Laureth Sulfate: A cleansing surfactant.\n• Sodium Cocoamphoacetate: A cleansing and foaming ingredient.\n• Glycerin: A humectant that supports moisture retention.\n• Xylitol: A moisturizing and skin-conditioning ingredient.\n• Mannitol: A sugar-derived ingredient.\n• Niacinamide: A vitamin B3 derivative used in skin-conditioning formulas; verify its presence on the current product label.\n\nNote: These are selected ingredients or formulation components, not a complete INCI declaration. Always verify the ingredient list against the actual product packaging, as formulations may vary by market and version.\n\n4. DIRECTIONS FOR USE\n\n1. Wet the body with water.\n2. Apply a suitable amount of shower gel to the hands or a soft washcloth.\n3. Gently massage over the skin to cleanse.\n4. Rinse thoroughly with water.\n5. Pat dry and follow with a body moisturizer if needed.\n\n5. SUITABLE FOR\n\n• Normal to dry skin.\n• Individuals who prefer a gentle daily shower gel.\n• People whose skin feels tight after bathing.\n• Those seeking a body cleanser for regular use."}, "image": "assets/catalog/product-bioderma-06.jpg", "gallery": {"vi": [{"src": "assets/catalog/vi/bioderma-06/thumbnail.webp", "label": "Thumbnail", "order": 0}, {"src": "assets/catalog/vi/bioderma-06/anh-1.webp", "label": "Ảnh 1", "order": 1}, {"src": "assets/catalog/vi/bioderma-06/anh-2.webp", "label": "Ảnh 2", "order": 2}, {"src": "assets/catalog/vi/bioderma-06/anh-3.webp", "label": "Ảnh 3", "order": 3}, {"src": "assets/catalog/vi/bioderma-06/anh-4.webp", "label": "Ảnh 4", "order": 4}, {"src": "assets/catalog/vi/bioderma-06/anh-5.webp", "label": "Ảnh 5", "order": 5}, {"src": "assets/catalog/vi/bioderma-06/anh-6.webp", "label": "Ảnh 6", "order": 6}, {"src": "assets/catalog/vi/bioderma-06/anh-7.webp", "label": "Ảnh 7", "order": 7}]}}, {"id": "bioderma-07", "brandId": "bioderma", "brand": "Bioderma", "name": {"vi": "KEM DƯỠNG BIODERMA SÉBIUM HYDRA 40ML", "en": "Bioderma Sébium Hydra Moisturizing Compensating Care 40ml"}, "category": "Skincare", "type": "Kem dưỡng ẩm cho da dầu mụn", "size": "Tuýp 40ml", "country": "Pháp", "description": {"vi": "1. MÔ TẢ SẢN PHẨM\n\nTên sản phẩm: Kem Dưỡng Bioderma Sébium Hydra 40ml\nThương hiệu: Bioderma\nQuốc gia thương hiệu: Pháp\nQuy cách đóng gói: Tuýp 40ml\nPhân loại: Kem dưỡng ẩm cho da dầu mụn\n\nBioderma Sébium Hydra 40ml là kem dưỡng ẩm dành cho da dầu, da dễ nổi mụn đang gặp tình trạng khô căng, đặc biệt khi sử dụng các sản phẩm chăm sóc mụn có thể làm da thiếu ẩm. Công thức kết hợp các chất giữ ẩm và làm mềm giúp hỗ trợ duy trì sự dễ chịu, giảm cảm giác căng ráp mà vẫn đáp ứng nhu cầu chăm sóc da dầu.\n\n2. CÔNG DỤNG\n\n• Bổ sung độ ẩm cho da dầu thiếu nước.\n• Giúp giảm cảm giác khô căng.\n• Hỗ trợ chăm sóc hàng rào độ ẩm.\n• Làm mềm da và cải thiện cảm giác khó chịu.\n\n3. THÀNH PHẦN\n\nCác thành phần nổi bật:\n\n• Glycerin: Thành phần giữ ẩm.\n• Mineral Oil: Thành phần làm mềm.\n• Ethylhexyl Palmitate: Hỗ trợ làm mềm da.\n• Glycyrrhetinic Acid: Thành phần chăm sóc da.\n• Allantoin: Hỗ trợ làm dịu da.\n• Tocopheryl Acetate: Dẫn xuất vitamin E.\n\nLưu ý: Các thành phần trên mang tính giới thiệu, không thay thế bảng INCI đầy đủ trên bao bì. Công thức có thể thay đổi theo phiên bản và thị trường.\n\n4. HƯỚNG DẪN SỬ DỤNG\n\n1. Làm sạch da và lau khô.\n2. Lấy lượng kem vừa đủ.\n3. Thoa đều lên mặt, tránh vùng mắt.\n4. Sử dụng sáng và tối hoặc theo nhu cầu.\n5. Ban ngày kết hợp chống nắng.\n\nLưu ý: Chỉ sử dụng ngoài da. Ngừng sử dụng nếu xuất hiện kích ứng kéo dài. Với các tình trạng da cần điều trị, nên tham khảo chuyên gia y tế.\n\n5. ĐỐI TƯỢNG SỬ DỤNG\n\n• Người có da dầu hoặc da dễ nổi mụn.\n• Người bị khô căng trong quá trình chăm sóc mụn.\n• Người cần kem dưỡng ẩm cho da dầu thiếu nước.", "en": "1. PRODUCT DESCRIPTION\n\nBioderma Sébium Hydra is a moisturizing facial cream designed for oily and blemish-prone skin experiencing dryness or discomfort. Skin may become dehydrated or feel tight when exposed to harsh environmental conditions or drying blemish-care routines. Sébium Hydra helps replenish moisture and soften the skin while providing the comfort needed in a balanced skincare routine. It is especially suitable when oily skin requires additional hydration rather than more intensive cleansing.\n\n2. BENEFITS\n\n• Moisturizes oily and blemish-prone skin.\n• Helps relieve tightness and dryness-related discomfort.\n• Softens the skin and improves its overall feel.\n• Supports the skin's moisture barrier.\n• Complements skincare routines that may leave the skin feeling dry.\n\n3. INGREDIENTS\n\nKey ingredients and their functions:\n\n• Glycerin: A moisture-attracting humectant.\n• Mineral Oil: An emollient that helps reduce moisture loss.\n• Ethylhexyl Palmitate: A skin-softening ingredient.\n• Glycyrrhetinic Acid: A skin-conditioning ingredient.\n• Allantoin: An ingredient commonly used in soothing skincare formulas.\n• Tocopheryl Acetate: A vitamin E derivative used in skin-conditioning products.\n\nNote: These are selected ingredients or formulation components, not a complete INCI declaration. Always verify the ingredient list against the actual product packaging, as formulations may vary by market and version.\n\n4. DIRECTIONS FOR USE\n\n1. Cleanse the face using a suitable gentle cleanser.\n2. Pat the skin dry.\n3. Apply a small amount of Sébium Hydra evenly over the face.\n4. Use in the morning and evening as needed.\n5. Apply sunscreen as the final step of the morning skincare routine.\n\n5. SUITABLE FOR\n\n• Oily and blemish-prone skin experiencing dehydration.\n• People whose skin feels dry during blemish-care routines.\n• Combination skin requiring additional moisture.\n• Individuals looking for a moisturizer designed for oily skin."}, "image": "assets/catalog/product-bioderma-07.jpg", "gallery": {"vi": [{"src": "assets/catalog/vi/bioderma-07/thumbnail.webp", "label": "Thumbnail", "order": 0}, {"src": "assets/catalog/vi/bioderma-07/anh-1.webp", "label": "Ảnh 1", "order": 1}, {"src": "assets/catalog/vi/bioderma-07/anh-2.webp", "label": "Ảnh 2", "order": 2}, {"src": "assets/catalog/vi/bioderma-07/anh-3.webp", "label": "Ảnh 3", "order": 3}, {"src": "assets/catalog/vi/bioderma-07/anh-4.webp", "label": "Ảnh 4", "order": 4}, {"src": "assets/catalog/vi/bioderma-07/anh-5.webp", "label": "Ảnh 5", "order": 5}, {"src": "assets/catalog/vi/bioderma-07/anh-6.webp", "label": "Ảnh 6", "order": 6}, {"src": "assets/catalog/vi/bioderma-07/anh-7.webp", "label": "Ảnh 7", "order": 7}]}}, {"id": "bioderma-08", "brandId": "bioderma", "brand": "Bioderma", "name": {"vi": "KEM DƯỠNG BIODERMA SENSIBIO DEFENSIVE 40ML", "en": "Bioderma Sensibio Defensive Active Soothing Cream 40ml"}, "category": "Skincare", "type": "Kem dưỡng cho da nhạy cảm", "size": "Tuýp 40ml", "country": "Pháp", "description": {"vi": "1. MÔ TẢ SẢN PHẨM\n\nTên sản phẩm: Kem Dưỡng Bioderma Sensibio Defensive 40ml\nThương hiệu: Bioderma\nQuốc gia thương hiệu: Pháp\nQuy cách đóng gói: Tuýp 40ml\nPhân loại: Kem dưỡng cho da nhạy cảm\n\nBioderma Sensibio Defensive 40ml là kem dưỡng chăm sóc da nhạy cảm, được phát triển nhằm hỗ trợ hàng rào bảo vệ da và giảm cảm giác khó chịu do tác động của môi trường. Công thức kết hợp các thành phần làm mềm, giữ ẩm và chống oxy hóa, giúp da duy trì cảm giác dễ chịu và mềm mại trong quy trình dưỡng da hằng ngày.\n\n2. CÔNG DỤNG\n\n• Cấp ẩm cho da nhạy cảm.\n• Hỗ trợ giảm cảm giác khô căng, khó chịu.\n• Giúp da mềm mại và mịn màng.\n• Hỗ trợ hàng rào bảo vệ da trước các tác động thường ngày.\n\n3. THÀNH PHẦN\n\nCác thành phần nổi bật:\n\n• Glycerin: Thành phần hút ẩm.\n• Squalane: Hỗ trợ làm mềm da.\n• Tocopherol: Thành phần chống oxy hóa.\n• Carnosine: Thành phần chống oxy hóa trong công thức.\n• Tetrapeptide-10: Peptide chăm sóc da.\n• Các thành phần dưỡng ẩm khác theo phiên bản sản phẩm.\n\nLưu ý: Các thành phần trên mang tính giới thiệu, không thay thế bảng INCI đầy đủ trên bao bì. Công thức có thể thay đổi theo phiên bản và thị trường.\n\n4. HƯỚNG DẪN SỬ DỤNG\n\n1. Làm sạch da và sử dụng toner nếu cần.\n2. Lấy lượng kem vừa đủ.\n3. Thoa đều lên mặt và cổ.\n4. Sử dụng sáng và tối.\n5. Kết hợp chống nắng vào ban ngày.\n\nLưu ý: Chỉ sử dụng ngoài da. Ngừng sử dụng nếu xuất hiện kích ứng kéo dài. Với các tình trạng da cần điều trị, nên tham khảo chuyên gia y tế.\n\n5. ĐỐI TƯỢNG SỬ DỤNG\n\n• Người có da nhạy cảm.\n• Người có da dễ khô căng hoặc khó chịu.\n• Người muốn kem dưỡng chăm sóc hàng rào da.", "en": "1. PRODUCT DESCRIPTION\n\nBioderma Sensibio Defensive is a moisturizing cream developed for sensitive skin exposed to everyday environmental stressors. Its formula combines moisturizing, emollient and antioxidant ingredients to help maintain skin comfort and support the protective moisture barrier. The cream is intended for daily use and helps reduce the sensation of dryness and tightness while leaving the skin feeling soft and smooth. It can be incorporated into a simple skincare routine for sensitive or easily uncomfortable skin.\n\n2. BENEFITS\n\n• Provides daily hydration for sensitive skin.\n• Helps relieve dryness-related tightness and discomfort.\n• Supports the skin's protective moisture barrier.\n• Leaves the skin feeling soft and smooth.\n• Provides antioxidant skin-conditioning care.\n\n3. INGREDIENTS\n\nKey ingredients and their functions:\n\n• Glycerin: A humectant that helps maintain moisture.\n• Squalane: An emollient that supports skin softness.\n• Tocopherol: A form of vitamin E with antioxidant properties.\n• Carnosine: An antioxidant ingredient.\n• Tetrapeptide-10: A peptide used in the product's skincare complex.\n• Additional emollients and stabilizers: Verify the complete ingredient list on the current packaging.\n\nNote: These are selected ingredients or formulation components, not a complete INCI declaration. Always verify the ingredient list against the actual product packaging, as formulations may vary by market and version.\n\n4. DIRECTIONS FOR USE\n\n1. Cleanse the face gently and pat dry.\n2. Apply a suitable amount of cream to the face and neck.\n3. Massage lightly until evenly distributed.\n4. Use in the morning and evening.\n5. Finish the morning routine with sunscreen.\n\n5. SUITABLE FOR\n\n• Sensitive and easily reactive skin.\n• Skin experiencing dryness or discomfort.\n• Individuals looking for daily barrier-supporting moisturization.\n• People who prefer a straightforward skincare routine."}, "image": "assets/catalog/product-bioderma-08.jpg", "gallery": {"vi": [{"src": "assets/catalog/vi/bioderma-08/thumbnail.webp", "label": "Thumbnail", "order": 0}, {"src": "assets/catalog/vi/bioderma-08/anh-1.webp", "label": "Ảnh 1", "order": 1}, {"src": "assets/catalog/vi/bioderma-08/anh-2.webp", "label": "Ảnh 2", "order": 2}, {"src": "assets/catalog/vi/bioderma-08/anh-3.webp", "label": "Ảnh 3", "order": 3}, {"src": "assets/catalog/vi/bioderma-08/anh-4.webp", "label": "Ảnh 4", "order": 4}, {"src": "assets/catalog/vi/bioderma-08/anh-5.webp", "label": "Ảnh 5", "order": 5}, {"src": "assets/catalog/vi/bioderma-08/anh-6.webp", "label": "Ảnh 6", "order": 6}, {"src": "assets/catalog/vi/bioderma-08/anh-7.webp", "label": "Ảnh 7", "order": 7}]}}, {"id": "bioderma-09", "brandId": "bioderma", "brand": "Bioderma", "name": {"vi": "SERUM BIODERMA HYDRABIO HYALU+ 30ML", "en": "Bioderma Hydrabio Hyalu+ Serum 30ml"}, "category": "Skincare", "type": "Serum cấp ẩm", "size": "Chai 30ml", "country": "Pháp", "description": {"vi": "1. MÔ TẢ SẢN PHẨM\n\nTên sản phẩm: Serum Bioderma Hydrabio Hyalu+ 30ml\nThương hiệu: Bioderma\nQuốc gia thương hiệu: Pháp\nQuy cách đóng gói: Chai 30ml\nPhân loại: Serum cấp ẩm\n\nBioderma Hydrabio Hyalu+ 30ml là tinh chất chăm sóc da thiếu nước, tập trung vào nhu cầu cấp ẩm và cải thiện vẻ ngoài của các nếp nhăn nhỏ do thiếu ẩm. Công thức kết hợp Hyaluronic Acid với các thành phần dưỡng da, giúp bề mặt da trông căng mịn, mềm mại và tươi tắn hơn khi sử dụng đều đặn.\n\n2. CÔNG DỤNG\n\n• Bổ sung độ ẩm cho da.\n• Giúp da trông căng mịn hơn.\n• Hỗ trợ cải thiện sự xuất hiện của nếp nhăn nhỏ do thiếu ẩm.\n• Giảm cảm giác khô căng.\n• Hỗ trợ duy trì hàng rào độ ẩm.\n\n3. THÀNH PHẦN\n\nCác thành phần nổi bật:\n\n• Sodium Hyaluronate: Thành phần giữ ẩm.\n• Hydrolyzed Hyaluronic Acid: Hyaluronic Acid thủy phân.\n• Niacinamide: Thành phần chăm sóc hàng rào da.\n• Carnosine: Thành phần chống oxy hóa.\n• Glycerin: Thành phần hút ẩm.\n• Các thành phần hỗ trợ công thức theo phiên bản.\n\nLưu ý: Các thành phần trên mang tính giới thiệu, không thay thế bảng INCI đầy đủ trên bao bì. Công thức có thể thay đổi theo phiên bản và thị trường.\n\n4. HƯỚNG DẪN SỬ DỤNG\n\n1. Làm sạch da và sử dụng nước cân bằng nếu có.\n2. Lấy lượng serum vừa đủ.\n3. Thoa đều lên mặt và cổ.\n4. Vỗ nhẹ cho sản phẩm thấm.\n5. Tiếp tục kem dưỡng và chống nắng ban ngày.\n\nLưu ý: Chỉ sử dụng ngoài da. Ngừng sử dụng nếu xuất hiện kích ứng kéo dài. Với các tình trạng da cần điều trị, nên tham khảo chuyên gia y tế.\n\n5. ĐỐI TƯỢNG SỬ DỤNG\n\n• Người có da thiếu nước.\n• Người có da khô căng.\n• Người quan tâm đến nếp nhăn nhỏ do thiếu ẩm.", "en": "1. PRODUCT DESCRIPTION\n\nBioderma Hydrabio Hyalu+ Serum is a facial serum designed to address dehydration and the appearance of fine lines associated with insufficient moisture. The formula combines hyaluronic acid ingredients with skin-conditioning components to help improve hydration, promote a plumper-looking complexion and support the skin's moisture barrier. Its serum texture is suitable for layering beneath a daily moisturizer, making it a useful addition to routines focused on hydration and smoother-looking skin.\n\n2. BENEFITS\n\n• Helps replenish moisture in dehydrated skin.\n• Promotes a smoother, plumper-looking complexion.\n• Helps reduce the appearance of fine dehydration lines.\n• Supports the skin's moisture barrier.\n• Leaves the skin feeling softer and more comfortable.\n• Complements both morning and evening moisturizing routines.\n\n3. INGREDIENTS\n\nKey ingredients and their functions:\n\n• Sodium Hyaluronate: A hyaluronic acid derivative that supports skin hydration.\n• Hydrolyzed Hyaluronic Acid: A form of hyaluronic acid used for moisturizing care.\n• Niacinamide: A vitamin B3 derivative that supports skin-conditioning and barrier care.\n• Carnosine: An antioxidant ingredient.\n• Glycerin: A humectant that helps attract moisture.\n• Additional ingredients: Refer to the complete INCI list on the product packaging.\n\nNote: These are selected ingredients or formulation components, not a complete INCI declaration. Always verify the ingredient list against the actual product packaging, as formulations may vary by market and version.\n\n4. DIRECTIONS FOR USE\n\n1. Cleanse the face and gently pat dry.\n2. Apply a suitable amount of serum to the face and neck.\n3. Spread evenly and allow the serum to absorb.\n4. Follow with a moisturizer suited to the skin type.\n5. Use sunscreen during the day.\n\n5. SUITABLE FOR\n\n• Dehydrated skin.\n• Skin experiencing tightness caused by lack of moisture.\n• Individuals concerned about fine dehydration lines.\n• People looking for a hydrating serum in their daily routine."}, "image": "assets/catalog/product-bioderma-09.jpg", "gallery": {"vi": [{"src": "assets/catalog/vi/bioderma-09/thumbnail.webp", "label": "Thumbnail", "order": 0}, {"src": "assets/catalog/vi/bioderma-09/anh-1.webp", "label": "Ảnh 1", "order": 1}, {"src": "assets/catalog/vi/bioderma-09/anh-2.webp", "label": "Ảnh 2", "order": 2}, {"src": "assets/catalog/vi/bioderma-09/anh-3.webp", "label": "Ảnh 3", "order": 3}, {"src": "assets/catalog/vi/bioderma-09/anh-4.webp", "label": "Ảnh 4", "order": 4}, {"src": "assets/catalog/vi/bioderma-09/anh-5.webp", "label": "Ảnh 5", "order": 5}, {"src": "assets/catalog/vi/bioderma-09/anh-6.webp", "label": "Ảnh 6", "order": 6}, {"src": "assets/catalog/vi/bioderma-09/anh-7.webp", "label": "Ảnh 7", "order": 7}]}}, {"id": "bioderma-10", "brandId": "bioderma", "brand": "Bioderma", "name": {"vi": "KEM CHỐNG NẮNG BIODERMA PHOTODERM AQUAFLUIDE SPF50+ 40ML", "en": "Bioderma Photoderm Aquafluide SPF50+ Sunscreen 40ml"}, "category": "Skincare", "type": "Kem chống nắng cho da mặt", "size": "Tuýp 40ml", "country": "Pháp", "description": {"vi": "1. MÔ TẢ SẢN PHẨM\n\nTên sản phẩm: Kem Chống Nắng Bioderma Photoderm Aquafluide SPF50+ 40ml\nThương hiệu: Bioderma\nQuốc gia thương hiệu: Pháp\nQuy cách đóng gói: Tuýp 40ml\nPhân loại: Kem chống nắng cho da mặt\n\nBioderma Photoderm Aquafluide SPF50+ 40ml là sản phẩm chống nắng dành cho da mặt với kết cấu dạng lỏng nhẹ, hướng đến nhu cầu bảo vệ da hằng ngày. Công thức sử dụng hệ màng lọc chống nắng để bảo vệ da trước tác động của tia UVA và UVB, đồng thời mang lại cảm giác dễ chịu khi sử dụng. Tùy phiên bản, sản phẩm có thể có màu hoặc không màu.\n\n2. CÔNG DỤNG\n\n• Bảo vệ da trước tác động của tia UVA và UVB.\n• Hỗ trợ hạn chế các dấu hiệu tổn thương da do ánh nắng.\n• Kết cấu lỏng nhẹ, dễ tán.\n• Phù hợp sử dụng trong quy trình chăm sóc da buổi sáng.\n\n3. THÀNH PHẦN\n\nCác thành phần nổi bật:\n\n• Hệ màng lọc UV: Thành phần chính giúp bảo vệ da trước tia cực tím.\n• Glycerin: Thành phần hỗ trợ giữ ẩm.\n• Các chất tạo màng và ổn định công thức chống nắng.\n• Danh sách màng lọc và INCI cần đối chiếu đúng phiên bản Photoderm Aquafluide SPF50+ đang lưu hành.\n\nLưu ý: Các thành phần trên mang tính giới thiệu, không thay thế bảng INCI đầy đủ trên bao bì. Công thức có thể thay đổi theo phiên bản và thị trường.\n\n4. HƯỚNG DẪN SỬ DỤNG\n\n1. Sử dụng ở bước cuối của quy trình dưỡng da buổi sáng.\n2. Thoa lượng chống nắng đầy đủ lên mặt và cổ trước khi ra nắng.\n3. Tán đều, tránh bỏ sót các vùng da.\n4. Thoa lại khoảng mỗi 2 giờ khi ở ngoài trời, đặc biệt sau khi đổ mồ hôi hoặc lau mặt.\n5. Kết hợp che chắn bằng mũ và kính.\n\nLưu ý: Chỉ sử dụng ngoài da. Ngừng sử dụng nếu xuất hiện kích ứng kéo dài. Với các tình trạng da cần điều trị, nên tham khảo chuyên gia y tế.\n\n5. ĐỐI TƯỢNG SỬ DỤNG\n\n• Người cần bảo vệ da mặt trước tia UV.\n• Người muốn chống nắng kết cấu nhẹ.\n• Người sử dụng chống nắng hằng ngày.", "en": "1. PRODUCT DESCRIPTION\n\nBioderma Photoderm Aquafluide SPF50+ is a lightweight facial sunscreen designed to provide high sun protection during everyday activities. Its fluid texture is intended to spread easily over the face and neck, making it suitable for use as the final step of a morning skincare routine. The formula uses UV filters to help protect the skin against UVA and UVB radiation. Product finishes, tint options and specific UV-filter combinations may vary by formulation and market, so the exact version should be checked before publication.\n\n2. BENEFITS\n\n• Provides high sun protection with SPF50+.\n• Helps protect the skin against UVA and UVB radiation.\n• Supports the prevention of sun-related skin damage when used correctly.\n• Offers a lightweight fluid texture for facial application.\n• Can be incorporated into a daily skincare and makeup routine.\n\n3. INGREDIENTS\n\nKey ingredients and their functions:\n\n• UV Filters: The primary ingredients responsible for UVA and UVB protection.\n• Glycerin: A moisturizing ingredient where included in the relevant formulation.\n• Film-forming and stabilizing agents: Help maintain sunscreen texture and performance.\n• Important: The exact UV filters and complete INCI list must be verified against the specific Photoderm Aquafluide SPF50+ version being sold.\n\nNote: These are selected ingredients or formulation components, not a complete INCI declaration. Always verify the ingredient list against the actual product packaging, as formulations may vary by market and version.\n\n4. DIRECTIONS FOR USE\n\n1. Apply as the final step of the morning skincare routine.\n2. Use a generous, even layer over the face, neck and other exposed areas.\n3. Apply before sun exposure, following the instructions on the packaging.\n4. Reapply frequently, especially after sweating, swimming or towel-drying.\n5. Use additional protective measures such as hats, sunglasses and shade.\n6. Do not rely on a thin layer of sunscreen for the labeled protection level.\n\n5. SUITABLE FOR\n\n• People seeking daily facial sun protection.\n• Individuals concerned about UV-related skin damage.\n• Those who prefer lightweight sunscreen textures.\n• People who want to wear sunscreen beneath makeup."}, "image": "assets/catalog/product-bioderma-10.jpg", "gallery": {"vi": [{"src": "assets/catalog/vi/bioderma-10/thumbnail.webp", "label": "Thumbnail", "order": 0}, {"src": "assets/catalog/vi/bioderma-10/anh-1.webp", "label": "Ảnh 1", "order": 1}, {"src": "assets/catalog/vi/bioderma-10/anh-2.webp", "label": "Ảnh 2", "order": 2}, {"src": "assets/catalog/vi/bioderma-10/anh-3.webp", "label": "Ảnh 3", "order": 3}, {"src": "assets/catalog/vi/bioderma-10/anh-4.webp", "label": "Ảnh 4", "order": 4}, {"src": "assets/catalog/vi/bioderma-10/anh-5.webp", "label": "Ảnh 5", "order": 5}, {"src": "assets/catalog/vi/bioderma-10/anh-6.webp", "label": "Ảnh 6", "order": 6}, {"src": "assets/catalog/vi/bioderma-10/anh-7.webp", "label": "Ảnh 7", "order": 7}]}}, {"id": "vichy-01", "brandId": "vichy", "brand": "Vichy", "name": {"vi": "TINH CHẤT KHOÁNG VICHY MINÉRAL 89 DAILY BOOSTER 50ML", "en": "Vichy Minéral 89 Daily Booster 50ml"}, "category": "Skincare", "type": "Serum cấp ẩm", "size": "Chai 50ml", "country": "Pháp", "description": {"vi": "1. MÔ TẢ SẢN PHẨM\n\nTên sản phẩm: Tinh Chất Khoáng Vichy Minéral 89 Daily Booster 50ml\nThương hiệu: Vichy\nQuốc gia thương hiệu: Pháp\nQuy cách đóng gói: Chai 50ml\nPhân loại: Serum cấp ẩm\n\nVichy Minéral 89 Daily Booster là tinh chất cấp ẩm nổi bật của thương hiệu Vichy, kết hợp 89% nước khoáng núi lửa Vichy và Hyaluronic Acid. Sản phẩm có kết cấu gel lỏng, dễ tán và nhanh thấm, giúp bổ sung độ ẩm cho da, hỗ trợ củng cố hàng rào bảo vệ da và mang lại cảm giác căng mịn, tươi tắn. Công thức không chứa hương liệu và phù hợp để sử dụng như bước dưỡng đầu tiên sau khi làm sạch da.\n\n2. CÔNG DỤNG\n\n• Cấp ẩm tức thì, giúp da mềm mại và căng mịn.\n• Hỗ trợ hàng rào bảo vệ da.\n• Giảm cảm giác khô căng do thiếu ẩm.\n• Chuẩn bị bề mặt da cho các bước dưỡng tiếp theo.\n\n3. THÀNH PHẦN\n\nCác thành phần nổi bật:\n\n• 89% nước khoáng núi lửa Vichy: Thành phần đặc trưng của sản phẩm.\n• Sodium Hyaluronate: Dạng muối của Hyaluronic Acid, hỗ trợ giữ ẩm.\n• Glycerin: Thành phần hút ẩm.\n• Propanediol: Hỗ trợ giữ ẩm và tạo kết cấu.\n• Biosaccharide Gum-1: Thành phần chăm sóc và giữ ẩm.\n\nLưu ý: Đây là các thành phần tiêu biểu, không thay thế danh sách INCI đầy đủ. Công thức có thể khác nhau giữa các phiên bản sản phẩm.\n\n4. HƯỚNG DẪN SỬ DỤNG\n\n1. Làm sạch da mặt.\n2. Lấy 1–2 lần nhấn tinh chất ra lòng bàn tay.\n3. Thoa đều lên mặt và cổ.\n4. Tiếp tục kem dưỡng; ban ngày dùng thêm chống nắng.\n\nLưu ý: Chỉ sử dụng ngoài da. Tránh tiếp xúc trực tiếp với mắt. Ngừng sử dụng nếu xuất hiện kích ứng kéo dài.\n\n5. ĐỐI TƯỢNG SỬ DỤNG\n\n• Người có da thiếu ẩm hoặc khô căng.\n• Người cần serum cấp ẩm hằng ngày.\n• Người muốn hỗ trợ chăm sóc hàng rào bảo vệ da.", "en": "1. PRODUCT DESCRIPTION\n\nVichy Minéral 89 Daily Booster is a lightweight hydrating serum designed to replenish moisture and support the skin's protective barrier. Formulated with 89% Vichy Volcanic Water and hyaluronic acid, it helps the skin feel hydrated, smoother and more comfortable throughout the day. Its fresh gel-like texture absorbs easily and layers well with other skincare products. This daily booster is an ideal first serum step after cleansing, especially when the skin feels dehydrated, tight or exposed to everyday environmental stressors.\n\n2. BENEFITS\n\n• Provides immediate hydration and helps maintain skin moisture.\n• Supports the skin's natural moisture barrier.\n• Helps reduce the feeling of tightness caused by dehydration.\n• Leaves skin looking smoother, fresher and plumper.\n• Prepares the skin for moisturizer and subsequent skincare steps.\n\n3. INGREDIENTS\n\nKey ingredients and their functions:\n\n• 89% Vichy Volcanic Water: Mineral-rich water used as the signature ingredient in the formula.\n• Sodium Hyaluronate: A form of hyaluronic acid that helps retain moisture.\n• Glycerin: A humectant that attracts and holds water.\n• Propanediol: A solvent and moisturizing ingredient.\n• Biosaccharide Gum-1: A skin-conditioning ingredient that helps support hydration.\n\nNote: The ingredients listed above are selected formulation components and do not represent the complete INCI list. Formulations may vary by product version and market. Always verify the ingredients against the actual product packaging.\n\n4. DIRECTIONS FOR USE\n\n1. Cleanse the face and gently pat dry.\n2. Dispense one or two pumps into the palms.\n3. Apply evenly over the face and neck.\n4. Allow the serum to absorb before applying moisturizer.\n5. Use morning and evening; finish the daytime routine with sunscreen.\n\n5. SUITABLE FOR\n\n• Dehydrated skin requiring daily hydration.\n• People experiencing tightness or dryness.\n• Individuals seeking a lightweight serum.\n• People looking to support their skin's moisture barrier."}, "image": "assets/catalog/product-vichy-01.jpg", "gallery": {"vi": [{"src": "assets/catalog/vi/vichy-01/thumbnail.webp", "label": "Thumbnail", "order": 0}, {"src": "assets/catalog/vi/vichy-01/anh-1.webp", "label": "Ảnh 1", "order": 1}, {"src": "assets/catalog/vi/vichy-01/anh-2.webp", "label": "Ảnh 2", "order": 2}, {"src": "assets/catalog/vi/vichy-01/anh-3.webp", "label": "Ảnh 3", "order": 3}, {"src": "assets/catalog/vi/vichy-01/anh-4.webp", "label": "Ảnh 4", "order": 4}, {"src": "assets/catalog/vi/vichy-01/anh-5.webp", "label": "Ảnh 5", "order": 5}, {"src": "assets/catalog/vi/vichy-01/anh-6.webp", "label": "Ảnh 6", "order": 6}, {"src": "assets/catalog/vi/vichy-01/anh-7.webp", "label": "Ảnh 7", "order": 7}]}}, {"id": "vichy-02", "brandId": "vichy", "brand": "Vichy", "name": {"vi": "TINH CHẤT VICHY LIFTACTIV B3 DARK SPOTS SERUM 30ML", "en": "Vichy Liftactiv B3 Dark Spots Serum 30ml"}, "category": "Skincare", "type": "Serum hỗ trợ cải thiện đốm nâu", "size": "Chai 30ml", "country": "Pháp", "description": {"vi": "1. MÔ TẢ SẢN PHẨM\n\nTên sản phẩm: Tinh Chất Vichy Liftactiv B3 Dark Spots Serum 30ml\nThương hiệu: Vichy\nQuốc gia thương hiệu: Pháp\nQuy cách đóng gói: Chai 30ml\nPhân loại: Serum hỗ trợ cải thiện đốm nâu\n\nVichy Liftactiv B3 Dark Spots Serum 30ml là tinh chất chăm sóc da hướng đến tình trạng thâm nám, đốm nâu và da không đều màu. Theo công bố của Vichy, công thức kết hợp 13% phức hợp thành phần hoạt tính, trong đó có 5% Niacinamide cùng các thành phần hỗ trợ thay mới bề mặt da. Sản phẩm giúp cải thiện vẻ ngoài của các đốm nâu và mang lại làn da trông sáng, đều màu hơn khi sử dụng đều đặn.\n\n2. CÔNG DỤNG\n\n• Hỗ trợ làm mờ sự xuất hiện của đốm nâu.\n• Giúp da trông sáng và đều màu hơn.\n• Hỗ trợ cải thiện bề mặt da xỉn màu.\n• Bổ sung thành phần chăm sóc da trong quy trình chống lão hóa.\n\n3. THÀNH PHẦN\n\nCác thành phần nổi bật:\n\n• 5% Niacinamide (Vitamin B3): Hỗ trợ cải thiện tình trạng da không đều màu.\n• Glycolic Acid (AHA): Hỗ trợ làm mới bề mặt da.\n• HEPES: Thành phần hỗ trợ chăm sóc bề mặt da.\n• Hydroxyethyl Urea: Hỗ trợ giữ ẩm.\n• Tranexamic Acid: Thành phần hỗ trợ cải thiện sự xuất hiện của đốm nâu.\n• Allantoin: Thành phần chăm sóc và làm dịu da.\n\nLưu ý: Đây là các thành phần tiêu biểu, không thay thế danh sách INCI đầy đủ. Công thức có thể khác nhau giữa các phiên bản sản phẩm.\n\n4. HƯỚNG DẪN SỬ DỤNG\n\n1. Làm sạch và lau khô da.\n2. Lấy lượng serum vừa đủ, thoa đều lên mặt.\n3. Tránh vùng mắt và vùng da đang kích ứng.\n4. Sử dụng theo khả năng dung nạp, có thể dùng sáng và tối theo hướng dẫn hãng.\n5. Ban ngày kết hợp kem chống nắng.\n\nLưu ý: Chỉ sử dụng ngoài da. Tránh tiếp xúc trực tiếp với mắt. Ngừng sử dụng nếu xuất hiện kích ứng kéo dài.\n\n5. ĐỐI TƯỢNG SỬ DỤNG\n\n• Người có đốm nâu, thâm sau mụn.\n• Người có da không đều màu.\n• Người muốn chăm sóc các dấu hiệu lão hóa sắc tố.", "en": "1. PRODUCT DESCRIPTION\n\nVichy Liftactiv B3 Dark Spots Serum is a targeted facial serum developed to address the visible appearance of dark spots, uneven skin tone and dullness. Its formula features niacinamide alongside exfoliating and skin-conditioning ingredients to help promote a more even-looking complexion over time. The serum can be incorporated into a routine focused on pigmentation-related concerns and visible signs of skin aging. Consistent sunscreen use is especially important when caring for uneven skin tone.\n\n2. BENEFITS\n\n• Helps reduce the visible appearance of dark spots.\n• Supports a brighter and more even-looking complexion.\n• Helps improve the appearance of dull, uneven skin.\n• Supports smoother-looking skin texture.\n• Complements skincare routines targeting pigmentation-related concerns.\n\n3. INGREDIENTS\n\nKey ingredients and their functions:\n\n• Niacinamide (Vitamin B3): Helps improve the appearance of uneven skin tone.\n• Glycolic Acid (AHA): Supports exfoliation of the skin's surface.\n• HEPES: A skin-conditioning ingredient.\n• Hydroxyethyl Urea: Helps maintain skin hydration.\n• Tranexamic Acid: An ingredient used in formulas targeting visible discoloration.\n• Allantoin: A skin-conditioning ingredient commonly used for soothing care.\n\nNote: The ingredients listed above are selected formulation components and do not represent the complete INCI list. Formulations may vary by product version and market. Always verify the ingredients against the actual product packaging.\n\n4. DIRECTIONS FOR USE\n\n1. Cleanse and dry the face.\n2. Apply a suitable amount of serum evenly over the face, avoiding the eye area.\n3. Begin with a frequency appropriate for skin tolerance.\n4. Follow with moisturizer.\n5. Use broad-spectrum sunscreen during the day.\n6. Reduce frequency or discontinue use if persistent irritation develops.\n\n5. SUITABLE FOR\n\n• People concerned about dark spots and post-blemish marks.\n• Individuals with uneven-looking skin tone.\n• Those experiencing dullness.\n• People seeking a serum for visible pigmentation-related aging concerns."}, "image": "assets/catalog/product-vichy-02.jpg", "gallery": {"vi": [{"src": "assets/catalog/vi/vichy-02/thumbnail.webp", "label": "Thumbnail", "order": 0}, {"src": "assets/catalog/vi/vichy-02/anh-1.webp", "label": "Ảnh 1", "order": 1}, {"src": "assets/catalog/vi/vichy-02/anh-2.webp", "label": "Ảnh 2", "order": 2}, {"src": "assets/catalog/vi/vichy-02/anh-3.webp", "label": "Ảnh 3", "order": 3}, {"src": "assets/catalog/vi/vichy-02/anh-4.webp", "label": "Ảnh 4", "order": 4}, {"src": "assets/catalog/vi/vichy-02/anh-5.webp", "label": "Ảnh 5", "order": 5}, {"src": "assets/catalog/vi/vichy-02/anh-6.webp", "label": "Ảnh 6", "order": 6}, {"src": "assets/catalog/vi/vichy-02/anh-7.webp", "label": "Ảnh 7", "order": 7}]}}, {"id": "vichy-03", "brandId": "vichy", "brand": "Vichy", "name": {"vi": "SỮA RỬA MẶT VICHY PURETÉ THERMALE 3-IN-1 CLEANSER 200ML", "en": "Vichy Pureté Thermale 3-in-1 Cleanser 200ml"}, "category": "Skincare", "type": "Sữa làm sạch và tẩy trang", "size": "Tuýp 200ml", "country": "Pháp", "description": {"vi": "1. MÔ TẢ SẢN PHẨM\n\nTên sản phẩm: Sữa Rửa Mặt Vichy Pureté Thermale 3-in-1 Cleanser 200ml\nThương hiệu: Vichy\nQuốc gia thương hiệu: Pháp\nQuy cách đóng gói: Tuýp 200ml\nPhân loại: Sữa làm sạch và tẩy trang\n\nVichy Pureté Thermale 3-in-1 Cleanser 200ml là sản phẩm làm sạch đa chức năng dành cho nhu cầu chăm sóc da, đặc biệt là da nhạy cảm. Sản phẩm kết hợp bước làm sạch, tẩy trang và chăm sóc da trong một công thức dạng sữa, giúp loại bỏ bụi bẩn, tạp chất và lớp trang điểm thông thường mà vẫn duy trì cảm giác mềm mại, dễ chịu.\n\n2. CÔNG DỤNG\n\n• Làm sạch bụi bẩn và tạp chất trên da.\n• Hỗ trợ loại bỏ lớp trang điểm thông thường.\n• Giúp da có cảm giác mềm mại sau khi làm sạch.\n• Thuận tiện khi muốn tối giản bước làm sạch.\n\n3. THÀNH PHẦN\n\nCác thành phần nổi bật:\n\n• Aqua: Thành phần nền.\n• Paraffinum Liquidum: Thành phần làm mềm.\n• Isopropyl Myristate: Hỗ trợ làm mềm và hòa tan tạp chất.\n• Butylene Glycol: Thành phần giữ ẩm.\n• Butyrospermum Parkii Seedcake Extract: Thành phần có nguồn gốc từ bơ hạt mỡ.\n• Parfum: Thành phần tạo hương.\n\nLưu ý: Đây là các thành phần tiêu biểu, không thay thế danh sách INCI đầy đủ. Công thức có thể khác nhau giữa các phiên bản sản phẩm.\n\n4. HƯỚNG DẪN SỬ DỤNG\n\n1. Lấy lượng sản phẩm vừa đủ lên bông tẩy trang hoặc tay sạch.\n2. Massage nhẹ trên mặt để làm sạch.\n3. Lau đi bằng bông mềm; có thể rửa lại với nước theo nhu cầu.\n4. Tiếp tục các bước dưỡng da.\n\nLưu ý: Chỉ sử dụng ngoài da. Tránh tiếp xúc trực tiếp với mắt. Ngừng sử dụng nếu xuất hiện kích ứng kéo dài.\n\n5. ĐỐI TƯỢNG SỬ DỤNG\n\n• Người có da thường hoặc da nhạy cảm.\n• Người cần sản phẩm làm sạch và tẩy trang tiện dụng.\n• Người muốn hạn chế cảm giác khô căng sau khi làm sạch.", "en": "1. PRODUCT DESCRIPTION\n\nVichy Pureté Thermale 3-in-1 Cleanser is a convenient cleansing product combining the functions of a cleansing milk, makeup remover and toner-like cleansing step. Its creamy texture helps remove everyday makeup, dirt and surface impurities while leaving the skin feeling soft and comfortable. Designed for gentle daily use, the formula is particularly suitable for people who prefer a simplified cleansing routine without a strong foaming sensation.\n\n2. BENEFITS\n\n• Helps remove everyday makeup and surface impurities.\n• Cleanses the face in a gentle, convenient step.\n• Leaves skin feeling soft and comfortable.\n• Helps minimize the sensation of dryness after cleansing.\n• Supports a simplified daily skincare routine.\n\n3. INGREDIENTS\n\nKey ingredients and their functions:\n\n• Mineral Oil (Paraffinum Liquidum): An emollient that helps dissolve makeup and soften skin.\n• Isopropyl Myristate: A skin-conditioning ingredient that assists with makeup removal.\n• Butylene Glycol: A solvent and moisturizing ingredient.\n• Butyrospermum Parkii Seedcake Extract: A botanical ingredient derived from shea.\n• Water: The primary base of the formulation.\n• Fragrance: A fragrance ingredient; check the current product label.\n\nNote: The ingredients listed above are selected formulation components and do not represent the complete INCI list. Formulations may vary by product version and market. Always verify the ingredients against the actual product packaging.\n\n4. DIRECTIONS FOR USE\n\n1. Apply a suitable amount to a cotton pad or clean fingertips.\n2. Gently massage or wipe across the face to remove makeup and impurities.\n3. Remove excess product with a soft cotton pad.\n4. Rinse with water if preferred or follow the instructions on the product packaging.\n5. Continue with moisturizer or other skincare products.\n\n5. SUITABLE FOR\n\n• Normal and sensitive skin seeking gentle cleansing.\n• People who prefer creamy cleansing textures.\n• Individuals looking for a multifunctional makeup remover.\n• Those who want a simple daily cleansing routine."}, "image": "assets/catalog/product-vichy-03.jpg", "gallery": {"vi": [{"src": "assets/catalog/vi/vichy-03/thumbnail.webp", "label": "Thumbnail", "order": 0}, {"src": "assets/catalog/vi/vichy-03/anh-1.webp", "label": "Ảnh 1", "order": 1}, {"src": "assets/catalog/vi/vichy-03/anh-2.webp", "label": "Ảnh 2", "order": 2}, {"src": "assets/catalog/vi/vichy-03/anh-3.webp", "label": "Ảnh 3", "order": 3}, {"src": "assets/catalog/vi/vichy-03/anh-4.webp", "label": "Ảnh 4", "order": 4}, {"src": "assets/catalog/vi/vichy-03/anh-5.webp", "label": "Ảnh 5", "order": 5}, {"src": "assets/catalog/vi/vichy-03/anh-6.webp", "label": "Ảnh 6", "order": 6}, {"src": "assets/catalog/vi/vichy-03/anh-7.webp", "label": "Ảnh 7", "order": 7}]}}, {"id": "vichy-04", "brandId": "vichy", "brand": "Vichy", "name": {"vi": "NƯỚC TẨY TRANG VICHY PURETÉ THERMALE MINERAL MICELLAR WATER 400ML", "en": "Vichy Pureté Thermale Mineral Micellar Water 400ml"}, "category": "Skincare", "type": "Nước tẩy trang cho da nhạy cảm", "size": "Chai 400ml", "country": "Pháp", "description": {"vi": "1. MÔ TẢ SẢN PHẨM\n\nTên sản phẩm: Nước Tẩy Trang Vichy Pureté Thermale Mineral Micellar Water 400ml\nThương hiệu: Vichy\nQuốc gia thương hiệu: Pháp\nQuy cách đóng gói: Chai 400ml\nPhân loại: Nước tẩy trang cho da nhạy cảm\n\nVichy Pureté Thermale Mineral Micellar Water 400ml là nước tẩy trang sử dụng công nghệ Micellar, giúp thu hút và loại bỏ bụi bẩn, dầu thừa cùng lớp trang điểm trên da. Công thức chứa Panthenol và các thành phần giữ ẩm, hướng đến nhu cầu làm sạch của làn da nhạy cảm, mang lại cảm giác mềm mại sau khi sử dụng.\n\n2. CÔNG DỤNG\n\n• Hỗ trợ loại bỏ bụi bẩn, dầu thừa và lớp trang điểm.\n• Làm sạch da mặt bằng bông tẩy trang.\n• Giúp da có cảm giác mềm mại.\n• Phù hợp trong quy trình làm sạch hằng ngày.\n\n3. THÀNH PHẦN\n\nCác thành phần nổi bật:\n\n• Poloxamer 184: Thành phần hỗ trợ làm sạch theo cơ chế micellar.\n• Panthenol: Thành phần chăm sóc và làm dịu da.\n• Glycerin: Hỗ trợ giữ ẩm.\n• Hexylene Glycol: Thành phần dung môi và hỗ trợ công thức.\n• Sodium Cocoamphoacetate: Chất làm sạch.\n• Parfum: Thành phần tạo hương.\n\nLưu ý: Đây là các thành phần tiêu biểu, không thay thế danh sách INCI đầy đủ. Công thức có thể khác nhau giữa các phiên bản sản phẩm.\n\n4. HƯỚNG DẪN SỬ DỤNG\n\n1. Thấm nước tẩy trang lên bông cotton.\n2. Lau nhẹ trên mặt theo chiều từ trong ra ngoài.\n3. Lặp lại đến khi bông sạch.\n4. Tiếp tục rửa mặt nếu cần, đặc biệt khi sử dụng trang điểm lâu trôi.\n\nLưu ý: Chỉ sử dụng ngoài da. Tránh tiếp xúc trực tiếp với mắt. Ngừng sử dụng nếu xuất hiện kích ứng kéo dài.\n\n5. ĐỐI TƯỢNG SỬ DỤNG\n\n• Người có da nhạy cảm.\n• Người thường xuyên sử dụng chống nắng hoặc trang điểm.\n• Người cần nước tẩy trang dung tích lớn.", "en": "1. PRODUCT DESCRIPTION\n\nVichy Pureté Thermale Mineral Micellar Water is a water-based facial cleanser designed to remove makeup, excess oil and everyday impurities without harsh rubbing. Micellar cleansing agents help lift particles from the skin's surface, while skin-conditioning ingredients support a comfortable, refreshed feeling after use. Its lightweight texture makes it suitable for regular cleansing and makeup removal, particularly for people with sensitive skin.\n\n2. BENEFITS\n\n• Removes ordinary makeup, dirt and surface impurities.\n• Helps cleanse the skin without excessive friction.\n• Leaves the complexion feeling fresh and comfortable.\n• Supports gentle daily makeup removal.\n• Provides a convenient cleansing step before moisturizing.\n\n3. INGREDIENTS\n\nKey ingredients and their functions:\n\n• Poloxamer 184: A micellar cleansing agent.\n• Panthenol: A skin-conditioning ingredient associated with soothing care.\n• Glycerin: Helps attract and retain moisture.\n• Hexylene Glycol: A solvent and formulation-supporting ingredient.\n• Sodium Cocoamphoacetate: A cleansing surfactant.\n• Fragrance: Check the actual product version for its presence.\n\nNote: The ingredients listed above are selected formulation components and do not represent the complete INCI list. Formulations may vary by product version and market. Always verify the ingredients against the actual product packaging.\n\n4. DIRECTIONS FOR USE\n\n1. Saturate a cotton pad with micellar water.\n2. Gently wipe the face to remove makeup and impurities.\n3. Use a fresh cotton pad and repeat as necessary.\n4. Avoid rubbing the delicate eye area.\n5. Continue with the rest of the skincare routine; rinse if desired.\n\n5. SUITABLE FOR\n\n• Sensitive skin.\n• People seeking a lightweight makeup remover.\n• Individuals who regularly wear sunscreen or everyday makeup.\n• Those looking for a convenient cleansing water."}, "image": "assets/catalog/product-vichy-04.jpg", "gallery": {"vi": [{"src": "assets/catalog/vi/vichy-04/thumbnail.webp", "label": "Thumbnail", "order": 0}, {"src": "assets/catalog/vi/vichy-04/anh-1.webp", "label": "Ảnh 1", "order": 1}, {"src": "assets/catalog/vi/vichy-04/anh-2.webp", "label": "Ảnh 2", "order": 2}, {"src": "assets/catalog/vi/vichy-04/anh-3.webp", "label": "Ảnh 3", "order": 3}, {"src": "assets/catalog/vi/vichy-04/anh-4.webp", "label": "Ảnh 4", "order": 4}, {"src": "assets/catalog/vi/vichy-04/anh-5.webp", "label": "Ảnh 5", "order": 5}, {"src": "assets/catalog/vi/vichy-04/anh-6.webp", "label": "Ảnh 6", "order": 6}, {"src": "assets/catalog/vi/vichy-04/anh-7.webp", "label": "Ảnh 7", "order": 7}]}}, {"id": "vichy-05", "brandId": "vichy", "brand": "Vichy", "name": {"vi": "DẦU GỘI VICHY DERCOS ANTI-DANDRUFF DS NORMAL TO OILY HAIR 200ML", "en": "Vichy Dercos Anti-Dandruff DS Shampoo for Normal to Oily Hair 200ml"}, "category": "Haircare", "type": "Dầu gội chăm sóc da đầu có gàu", "size": "Chai 200ml", "country": "Pháp", "description": {"vi": "1. MÔ TẢ SẢN PHẨM\n\nTên sản phẩm: Dầu Gội Vichy Dercos Anti-Dandruff DS Normal to Oily Hair 200ml\nThương hiệu: Vichy\nQuốc gia thương hiệu: Pháp\nQuy cách đóng gói: Chai 200ml\nPhân loại: Dầu gội chăm sóc da đầu có gàu\n\nVichy Dercos Anti-Dandruff DS Normal to Oily Hair 200ml là dầu gội chuyên biệt dành cho da đầu thường đến dầu có gàu và cảm giác ngứa. Công thức được Vichy giới thiệu với Selenium Disulfide và Salicylic Acid, giúp làm sạch vảy gàu, giảm tình trạng gàu nhìn thấy được và hỗ trợ kiểm soát bã nhờn trên da đầu.\n\n2. CÔNG DỤNG\n\n• Làm sạch tóc và da đầu.\n• Hỗ trợ loại bỏ vảy gàu nhìn thấy được.\n• Giúp giảm cảm giác ngứa do gàu.\n• Hỗ trợ kiểm soát dầu thừa trên da đầu.\n\n3. THÀNH PHẦN\n\nCác thành phần nổi bật:\n\n• Selenium Sulfide: Thành phần chăm sóc da đầu có gàu.\n• Salicylic Acid: Hỗ trợ loại bỏ vảy da chết.\n• Sodium Laureth Sulfate: Chất làm sạch.\n• Coco-Betaine: Hỗ trợ làm sạch và tạo bọt.\n• Glycerin: Thành phần giữ ẩm.\n• Menthol: Mang lại cảm giác mát.\n• Dimethicone: Hỗ trợ làm mượt tóc.\n\nLưu ý: Đây là các thành phần tiêu biểu, không thay thế danh sách INCI đầy đủ. Công thức có thể khác nhau giữa các phiên bản sản phẩm.\n\n4. HƯỚNG DẪN SỬ DỤNG\n\n1. Làm ướt tóc và da đầu.\n2. Thoa lượng dầu gội vừa đủ, massage nhẹ nhàng.\n3. Ở lần dùng đầu tiên, có thể lưu trên tóc và da đầu khoảng 2 phút theo hướng dẫn hãng.\n4. Xả sạch bằng nước.\n5. Sử dụng khoảng 3 lần mỗi tuần trong giai đoạn chăm sóc ban đầu hoặc theo hướng dẫn trên nhãn.\n\nLưu ý: Chỉ sử dụng ngoài da. Tránh tiếp xúc trực tiếp với mắt. Ngừng sử dụng nếu xuất hiện kích ứng kéo dài.\n\n5. ĐỐI TƯỢNG SỬ DỤNG\n\n• Người có da đầu thường đến dầu bị gàu.\n• Người có cảm giác ngứa do gàu.\n• Người muốn dầu gội chuyên biệt cho da đầu có vảy gàu.", "en": "1. PRODUCT DESCRIPTION\n\nVichy Dercos Anti-Dandruff DS Shampoo for Normal to Oily Hair is a specialized shampoo designed for scalps experiencing visible dandruff, excess oil and dandruff-related itching. Its cleansing formula combines anti-dandruff ingredients with agents that help remove flakes and accumulated sebum. The shampoo supports a cleaner, fresher scalp and can be incorporated into a targeted dandruff-care routine according to the manufacturer's directions.\n\n2. BENEFITS\n\n• Helps reduce visible dandruff flakes.\n• Cleanses excess oil and impurities from the scalp.\n• Helps relieve itching associated with dandruff.\n• Supports a fresher and cleaner scalp.\n• Suitable for targeted care of normal to oily scalps.\n\n3. INGREDIENTS\n\nKey ingredients and their functions:\n\n• Selenium Disulfide (Selenium Sulfide): An anti-dandruff active ingredient.\n• Salicylic Acid: Helps loosen and remove visible scalp flakes.\n• Sodium Laureth Sulfate: A cleansing surfactant.\n• Coco-Betaine: A cleansing and foaming ingredient.\n• Glycerin: A moisturizing ingredient.\n• Menthol: Provides a cooling sensation.\n• Dimethicone: A conditioning ingredient that helps smooth the hair.\n\nNote: The ingredients listed above are selected formulation components and do not represent the complete INCI list. Formulations may vary by product version and market. Always verify the ingredients against the actual product packaging.\n\n4. DIRECTIONS FOR USE\n\n1. Wet the hair and scalp thoroughly.\n2. Apply an appropriate amount of shampoo.\n3. Massage gently into the scalp.\n4. Leave on for the contact time specified on the packaging, then rinse thoroughly.\n5. Follow the recommended initial-use and maintenance schedule on the label.\n6. Avoid direct contact with the eyes and do not apply to broken or irritated skin.\n\n5. SUITABLE FOR\n\n• People with normal to oily scalps experiencing dandruff.\n• Individuals with visible scalp flakes.\n• People experiencing dandruff-related itching.\n• Those seeking a specialized anti-dandruff shampoo."}, "image": "assets/catalog/product-vichy-05.jpg", "gallery": {"vi": [{"src": "assets/catalog/vi/vichy-05/thumbnail.webp", "label": "Thumbnail", "order": 0}, {"src": "assets/catalog/vi/vichy-05/anh-1.webp", "label": "Ảnh 1", "order": 1}, {"src": "assets/catalog/vi/vichy-05/anh-2.webp", "label": "Ảnh 2", "order": 2}, {"src": "assets/catalog/vi/vichy-05/anh-3.webp", "label": "Ảnh 3", "order": 3}, {"src": "assets/catalog/vi/vichy-05/anh-4.webp", "label": "Ảnh 4", "order": 4}, {"src": "assets/catalog/vi/vichy-05/anh-5.webp", "label": "Ảnh 5", "order": 5}, {"src": "assets/catalog/vi/vichy-05/anh-6.webp", "label": "Ảnh 6", "order": 6}, {"src": "assets/catalog/vi/vichy-05/anh-7.webp", "label": "Ảnh 7", "order": 7}]}}, {"id": "vichy-06", "brandId": "vichy", "brand": "Vichy", "name": {"vi": "GEL DƯỠNG VICHY NORMADERM PHYTOSOLUTION DOUBLE-CORRECTION", "en": "Vichy Normaderm Phytosolution Double-Correction Daily Care"}, "category": "Skincare", "type": "Gel dưỡng cho da dầu mụn", "size": "Cần xác nhận dung tích trên bao bì", "country": "Pháp", "description": {"vi": "1. MÔ TẢ SẢN PHẨM\n\nTên sản phẩm: Gel Dưỡng Vichy Normaderm Phytosolution Double-Correction\nThương hiệu: Vichy\nQuốc gia thương hiệu: Pháp\nQuy cách đóng gói: Cần xác nhận dung tích trên bao bì\nPhân loại: Gel dưỡng cho da dầu mụn\n\nVichy Normaderm Phytosolution Double-Correction là gel dưỡng chăm sóc da dầu và da dễ nổi mụn. Công thức kết hợp Salicylic Acid, thành phần từ quá trình lên men Bifida và các chất giữ ẩm, giúp hỗ trợ cải thiện sự xuất hiện của khuyết điểm, chăm sóc lỗ chân lông và duy trì độ ẩm mà không tạo cảm giác quá nặng trên da.\n\n2. CÔNG DỤNG\n\n• Hỗ trợ cải thiện sự xuất hiện của các nốt mụn và khuyết điểm.\n• Giúp bề mặt da trông mịn hơn.\n• Hỗ trợ chăm sóc lỗ chân lông.\n• Cấp ẩm và hỗ trợ hàng rào bảo vệ da.\n\n3. THÀNH PHẦN\n\nCác thành phần nổi bật:\n\n• Salicylic Acid: Thành phần hỗ trợ làm thông thoáng lỗ chân lông.\n• Bifida Ferment Lysate: Thành phần có nguồn gốc từ quá trình lên men.\n• Glycerin: Hỗ trợ giữ ẩm.\n• Kaolin: Thành phần khoáng hỗ trợ hấp thụ dầu.\n• Zinc Sulfate: Thành phần chăm sóc da.\n• Sodium Hyaluronate: Hỗ trợ giữ ẩm.\n\nLưu ý: Đây là các thành phần tiêu biểu, không thay thế danh sách INCI đầy đủ. Công thức có thể khác nhau giữa các phiên bản sản phẩm.\n\n4. HƯỚNG DẪN SỬ DỤNG\n\n1. Làm sạch da và sử dụng serum nếu có.\n2. Lấy lượng gel dưỡng vừa đủ.\n3. Thoa đều lên mặt, tránh vùng mắt.\n4. Sử dụng theo hướng dẫn trên bao bì; ban ngày kết hợp chống nắng.\n\nLưu ý: Chỉ sử dụng ngoài da. Tránh tiếp xúc trực tiếp với mắt. Ngừng sử dụng nếu xuất hiện kích ứng kéo dài.\n\n5. ĐỐI TƯỢNG SỬ DỤNG\n\n• Người có da dầu hoặc hỗn hợp thiên dầu.\n• Người có da dễ nổi mụn.\n• Người muốn gel dưỡng kết cấu nhẹ.", "en": "1. PRODUCT DESCRIPTION\n\nVichy Normaderm Phytosolution Double-Correction Daily Care is a lightweight moisturizing treatment developed for oily and blemish-prone skin. Its formula combines exfoliating, moisturizing and skin-conditioning ingredients to help improve the appearance of blemishes while supporting the skin's moisture barrier. The gel-like texture is designed for daily use and helps maintain hydration without an excessively heavy finish.\n\n2. BENEFITS\n\n• Helps improve the appearance of blemishes and skin imperfections.\n• Supports clearer-looking pores.\n• Helps improve the appearance of uneven skin texture.\n• Provides hydration for oily skin.\n• Supports the skin's protective moisture barrier.\n\n3. INGREDIENTS\n\nKey ingredients and their functions:\n\n• Salicylic Acid: A beta hydroxy acid used in blemish-care formulas.\n• Bifida Ferment Lysate: A fermentation-derived skin-conditioning ingredient.\n• Glycerin: A humectant that supports hydration.\n• Kaolin: A mineral ingredient that can absorb excess oil.\n• Zinc Sulfate: A skin-conditioning ingredient.\n• Sodium Hyaluronate: A hyaluronic acid derivative that helps retain moisture.\n\nNote: The ingredients listed above are selected formulation components and do not represent the complete INCI list. Formulations may vary by product version and market. Always verify the ingredients against the actual product packaging.\n\n4. DIRECTIONS FOR USE\n\n1. Cleanse the face using a suitable cleanser.\n2. Apply a small amount of the product evenly over the face.\n3. Avoid direct contact with the eyes.\n4. Use according to the manufacturer's recommended frequency and skin tolerance.\n5. Apply sunscreen during the day.\n\n5. SUITABLE FOR\n\n• Oily and combination skin.\n• Blemish-prone skin.\n• People concerned about clogged-looking pores.\n• Individuals seeking a lightweight daily moisturizer."}, "image": "assets/catalog/product-vichy-06.jpg", "gallery": {"vi": [{"src": "assets/catalog/vi/vichy-06/thumbnail.webp", "label": "Thumbnail", "order": 0}, {"src": "assets/catalog/vi/vichy-06/anh-1.webp", "label": "Ảnh 1", "order": 1}, {"src": "assets/catalog/vi/vichy-06/anh-2.webp", "label": "Ảnh 2", "order": 2}, {"src": "assets/catalog/vi/vichy-06/anh-3.webp", "label": "Ảnh 3", "order": 3}, {"src": "assets/catalog/vi/vichy-06/anh-4.webp", "label": "Ảnh 4", "order": 4}, {"src": "assets/catalog/vi/vichy-06/anh-5.webp", "label": "Ảnh 5", "order": 5}, {"src": "assets/catalog/vi/vichy-06/anh-6.webp", "label": "Ảnh 6", "order": 6}, {"src": "assets/catalog/vi/vichy-06/anh-7.webp", "label": "Ảnh 7", "order": 7}]}}, {"id": "vichy-07", "brandId": "vichy", "brand": "Vichy", "name": {"vi": "TINH CHẤT VICHY NORMADERM PROBIO-BHA ANTI-IMPERFECTIONS SERUM", "en": "Vichy Normaderm Probio-BHA Anti-Imperfections Serum"}, "category": "Skincare", "type": "Serum cho da dầu mụn", "size": "Cần xác nhận dung tích trên bao bì", "country": "Pháp", "description": {"vi": "1. MÔ TẢ SẢN PHẨM\n\nTên sản phẩm: Tinh Chất Vichy Normaderm Probio-BHA Anti-Imperfections Serum\nThương hiệu: Vichy\nQuốc gia thương hiệu: Pháp\nQuy cách đóng gói: Cần xác nhận dung tích trên bao bì\nPhân loại: Serum cho da dầu mụn\n\nVichy Normaderm Probio-BHA Anti-Imperfections Serum là tinh chất chăm sóc da dầu, da dễ nổi mụn và có bề mặt không đều. Công thức kết hợp Glycolic Acid, Salicylic Acid và thành phần có nguồn gốc từ quá trình lên men, hướng đến việc hỗ trợ cải thiện mụn đầu đen, dầu thừa và bề mặt da thô ráp. Do chứa acid tẩy tế bào chết, sản phẩm cần được sử dụng với tần suất phù hợp khả năng dung nạp.\n\n2. CÔNG DỤNG\n\n• Hỗ trợ giảm sự xuất hiện của khuyết điểm.\n• Giúp làm thông thoáng lỗ chân lông.\n• Hỗ trợ cải thiện bề mặt da thô ráp.\n• Giúp kiểm soát dầu thừa và mụn đầu đen.\n\n3. THÀNH PHẦN\n\nCác thành phần nổi bật:\n\n• Glycolic Acid (AHA): Hỗ trợ làm mới bề mặt da.\n• Salicylic Acid (BHA): Hỗ trợ làm thông thoáng lỗ chân lông.\n• Vitreoscilla Ferment: Thành phần có nguồn gốc từ quá trình lên men.\n• Panthenol: Thành phần chăm sóc và làm dịu da.\n• Glycerin: Hỗ trợ giữ ẩm.\n• Alcohol Denat.: Thành phần dung môi có trong công thức.\n\nLưu ý: Đây là các thành phần tiêu biểu, không thay thế danh sách INCI đầy đủ. Công thức có thể khác nhau giữa các phiên bản sản phẩm.\n\n4. HƯỚNG DẪN SỬ DỤNG\n\n1. Làm sạch và lau khô da.\n2. Lấy khoảng 5 giọt serum, thoa đều lên mặt, tránh vùng mắt.\n3. Bắt đầu với tần suất phù hợp; hướng dẫn hãng là mỗi ngày một lần.\n4. Giảm tần suất nếu có dấu hiệu kích ứng.\n5. Sử dụng chống nắng hằng ngày.\n\nLưu ý: Chỉ sử dụng ngoài da. Tránh tiếp xúc trực tiếp với mắt. Ngừng sử dụng nếu xuất hiện kích ứng kéo dài.\n\n5. ĐỐI TƯỢNG SỬ DỤNG\n\n• Người có da dầu, da dễ nổi mụn.\n• Người có mụn đầu đen và lỗ chân lông dễ bít tắc.\n• Người muốn cải thiện kết cấu bề mặt da.", "en": "1. PRODUCT DESCRIPTION\n\nVichy Normaderm Probio-BHA Anti-Imperfections Serum is a targeted facial serum developed for oily, blemish-prone skin and uneven skin texture. Combining exfoliating acids with skin-conditioning ingredients, the formula helps improve the appearance of blemishes, blackheads and congested-looking pores. Because it contains exfoliating acids, careful introduction and consistent sun protection are important when incorporating this serum into a skincare routine.\n\n2. BENEFITS\n\n• Helps reduce the visible appearance of blemishes.\n• Supports smoother-looking skin texture.\n• Helps improve the appearance of clogged pores and blackheads.\n• Supports the care of oily and blemish-prone skin.\n• Helps remove dead skin cells from the skin's surface.\n\n3. INGREDIENTS\n\nKey ingredients and their functions:\n\n• Glycolic Acid (AHA): Helps exfoliate the skin's surface.\n• Salicylic Acid (BHA): Helps exfoliate and clear excess buildup from pores.\n• Vitreoscilla Ferment: A fermentation-derived skin-conditioning ingredient.\n• Panthenol: A skin-conditioning ingredient.\n• Glycerin: Supports moisture retention.\n• Alcohol Denat.: A solvent used in the formulation.\n\nNote: The ingredients listed above are selected formulation components and do not represent the complete INCI list. Formulations may vary by product version and market. Always verify the ingredients against the actual product packaging.\n\n4. DIRECTIONS FOR USE\n\n1. Cleanse the face and allow the skin to dry.\n2. Apply a small amount evenly over the face, avoiding the eyes and lips.\n3. Start gradually according to skin tolerance and the product label.\n4. Follow with a suitable moisturizer.\n5. Use sunscreen during the day.\n6. Avoid combining multiple strong exfoliating treatments in the same routine unless professionally advised.\n\n5. SUITABLE FOR\n\n• Oily and blemish-prone skin.\n• People concerned about blackheads.\n• Individuals with uneven-looking skin texture.\n• Those looking for an exfoliating skincare serum."}, "image": "assets/catalog/product-vichy-07.jpg", "gallery": {"vi": [{"src": "assets/catalog/vi/vichy-07/thumbnail.webp", "label": "Thumbnail", "order": 0}, {"src": "assets/catalog/vi/vichy-07/anh-1.webp", "label": "Ảnh 1", "order": 1}, {"src": "assets/catalog/vi/vichy-07/anh-2.webp", "label": "Ảnh 2", "order": 2}, {"src": "assets/catalog/vi/vichy-07/anh-3.webp", "label": "Ảnh 3", "order": 3}, {"src": "assets/catalog/vi/vichy-07/anh-4.webp", "label": "Ảnh 4", "order": 4}, {"src": "assets/catalog/vi/vichy-07/anh-5.webp", "label": "Ảnh 5", "order": 5}, {"src": "assets/catalog/vi/vichy-07/anh-6.webp", "label": "Ảnh 6", "order": 6}, {"src": "assets/catalog/vi/vichy-07/anh-7.webp", "label": "Ảnh 7", "order": 7}]}}, {"id": "vichy-08", "brandId": "vichy", "brand": "Vichy", "name": {"vi": "TINH CHẤT VICHY LIFTACTIV H.A. EPIDERMIC FILLER", "en": "Vichy Liftactiv H.A. Epidermic Filler Serum"}, "category": "Skincare", "type": "Serum dưỡng ẩm và chăm sóc nếp nhăn", "size": "Cần xác nhận dung tích trên bao bì", "country": "Pháp", "description": {"vi": "1. MÔ TẢ SẢN PHẨM\n\nTên sản phẩm: Tinh Chất Vichy Liftactiv H.A. Epidermic Filler\nThương hiệu: Vichy\nQuốc gia thương hiệu: Pháp\nQuy cách đóng gói: Cần xác nhận dung tích trên bao bì\nPhân loại: Serum dưỡng ẩm và chăm sóc nếp nhăn\n\nVichy Liftactiv H.A. Epidermic Filler là tinh chất dưỡng da hướng đến nhu cầu cấp ẩm và cải thiện sự xuất hiện của nếp nhăn. Công thức kết hợp Hyaluronic Acid với các thành phần chăm sóc da, giúp da trông căng mịn, mềm mại và hỗ trợ cải thiện vẻ ngoài của các đường nhăn nhỏ, đặc biệt tại vùng trán, khóe mắt và rãnh cười.\n\n2. CÔNG DỤNG\n\n• Bổ sung độ ẩm cho da.\n• Giúp da có cảm giác căng mịn.\n• Hỗ trợ làm mờ sự xuất hiện của nếp nhăn nhỏ.\n• Hỗ trợ chăm sóc các dấu hiệu lão hóa.\n\n3. THÀNH PHẦN\n\nCác thành phần nổi bật:\n\n• Sodium Hyaluronate: Thành phần cấp ẩm.\n• Glycerin: Hỗ trợ hút ẩm.\n• HEPES: Thành phần chăm sóc bề mặt da.\n• Rye Seed Extract: Chiết xuất hạt lúa mạch đen.\n• Calcium Pantothenate: Dẫn xuất vitamin B5.\n• Ascorbyl Glucoside: Dẫn xuất vitamin C.\n• Peptide: Thành phần hỗ trợ chăm sóc da.\n\nLưu ý: Đây là các thành phần tiêu biểu, không thay thế danh sách INCI đầy đủ. Công thức có thể khác nhau giữa các phiên bản sản phẩm.\n\n4. HƯỚNG DẪN SỬ DỤNG\n\n1. Làm sạch da mặt.\n2. Lấy lượng tinh chất vừa đủ.\n3. Thoa nhẹ lên vùng có nếp nhăn và toàn bộ khuôn mặt.\n4. Sử dụng sáng và tối theo hướng dẫn hãng.\n5. Tiếp tục kem dưỡng và chống nắng ban ngày.\n\nLưu ý: Chỉ sử dụng ngoài da. Tránh tiếp xúc trực tiếp với mắt. Ngừng sử dụng nếu xuất hiện kích ứng kéo dài.\n\n5. ĐỐI TƯỢNG SỬ DỤNG\n\n• Người có da thiếu ẩm.\n• Người bắt đầu xuất hiện nếp nhăn nhỏ.\n• Người muốn chăm sóc da có dấu hiệu lão hóa.", "en": "1. PRODUCT DESCRIPTION\n\nVichy Liftactiv H.A. Epidermic Filler Serum is a hydrating facial treatment designed to address the appearance of fine lines and wrinkles. Its formula features hyaluronic acid and selected skin-conditioning ingredients to help the skin appear smoother, plumper and more hydrated. The lightweight serum can be applied as part of a daily anti-aging skincare routine, including areas where fine lines are more noticeable.\n\n2. BENEFITS\n\n• Provides hydration for smoother-looking skin.\n• Helps reduce the visible appearance of fine lines.\n• Promotes a plumper-looking complexion.\n• Supports skin softness and comfort.\n• Complements skincare routines focused on visible signs of aging.\n\n3. INGREDIENTS\n\nKey ingredients and their functions:\n\n• Sodium Hyaluronate: A form of hyaluronic acid that helps retain moisture.\n• Glycerin: A moisture-attracting humectant.\n• HEPES: A skin-conditioning ingredient.\n• Rye Seed Extract: A botanical ingredient used in skincare.\n• Calcium Pantothenate: A vitamin B5-related ingredient.\n• Ascorbyl Glucoside: A vitamin C derivative.\n• Peptide Ingredients: Used in skin-conditioning formulas; verify the specific INCI names on the packaging.\n\nNote: The ingredients listed above are selected formulation components and do not represent the complete INCI list. Formulations may vary by product version and market. Always verify the ingredients against the actual product packaging.\n\n4. DIRECTIONS FOR USE\n\n1. Cleanse the face and pat dry.\n2. Dispense a suitable amount of serum.\n3. Apply gently over the face and areas with visible fine lines.\n4. Allow the serum to absorb before applying moisturizer.\n5. Use in the morning and evening according to the product instructions.\n6. Finish the daytime routine with sunscreen.\n\n5. SUITABLE FOR\n\n• People concerned about fine lines and wrinkles.\n• Dehydrated skin.\n• Individuals looking for a plumping facial serum.\n• Those incorporating anti-aging skincare into their daily routine."}, "image": "assets/catalog/product-vichy-08.jpg", "gallery": {"vi": [{"src": "assets/catalog/vi/vichy-08/thumbnail.webp", "label": "Thumbnail", "order": 0}, {"src": "assets/catalog/vi/vichy-08/anh-1.webp", "label": "Ảnh 1", "order": 1}, {"src": "assets/catalog/vi/vichy-08/anh-2.webp", "label": "Ảnh 2", "order": 2}, {"src": "assets/catalog/vi/vichy-08/anh-3.webp", "label": "Ảnh 3", "order": 3}, {"src": "assets/catalog/vi/vichy-08/anh-4.webp", "label": "Ảnh 4", "order": 4}, {"src": "assets/catalog/vi/vichy-08/anh-5.webp", "label": "Ảnh 5", "order": 5}, {"src": "assets/catalog/vi/vichy-08/anh-6.webp", "label": "Ảnh 6", "order": 6}, {"src": "assets/catalog/vi/vichy-08/anh-7.webp", "label": "Ảnh 7", "order": 7}]}}, {"id": "vichy-09", "brandId": "vichy", "brand": "Vichy", "name": {"vi": "TINH CHẤT VICHY MINÉRAL 89 PROBIOTIC FRACTIONS CONCENTRATE", "en": "Vichy Minéral 89 Probiotic Fractions Concentrate"}, "category": "Skincare", "type": "Serum hỗ trợ phục hồi độ ẩm", "size": "Cần xác nhận dung tích trên bao bì", "country": "Pháp", "description": {"vi": "1. MÔ TẢ SẢN PHẨM\n\nTên sản phẩm: Tinh Chất Vichy Minéral 89 Probiotic Fractions Concentrate\nThương hiệu: Vichy\nQuốc gia thương hiệu: Pháp\nQuy cách đóng gói: Cần xác nhận dung tích trên bao bì\nPhân loại: Serum hỗ trợ phục hồi độ ẩm\n\nVichy Minéral 89 Probiotic Fractions Concentrate là tinh chất chăm sóc da thuộc dòng Minéral 89, kết hợp nước khoáng núi lửa Vichy với các thành phần có nguồn gốc từ quá trình lên men. Sản phẩm hướng đến nhu cầu chăm sóc làn da thiếu sức sống, dễ bị ảnh hưởng bởi các yếu tố môi trường và có dấu hiệu thiếu ẩm, giúp da trông khỏe khoắn, mềm mại hơn.\n\n2. CÔNG DỤNG\n\n• Hỗ trợ duy trì độ ẩm cho da.\n• Giúp da trông tươi tắn và rạng rỡ hơn.\n• Hỗ trợ chăm sóc hàng rào bảo vệ da.\n• Cải thiện cảm giác khô căng, mệt mỏi trên da.\n\n3. THÀNH PHẦN\n\nCác thành phần nổi bật:\n\n• Nước khoáng núi lửa Vichy: Thành phần đặc trưng của thương hiệu.\n• Probiotic Fractions: Các thành phần có nguồn gốc từ quá trình lên men.\n• Các chất giữ ẩm và chăm sóc da: Cần đối chiếu danh sách INCI trên phiên bản sản phẩm thực tế.\n\nLưu ý: Đây là các thành phần tiêu biểu, không thay thế danh sách INCI đầy đủ. Công thức có thể khác nhau giữa các phiên bản sản phẩm.\n\n4. HƯỚNG DẪN SỬ DỤNG\n\n1. Làm sạch da và dùng nước cân bằng nếu có.\n2. Lấy lượng tinh chất vừa đủ.\n3. Thoa đều lên mặt và cổ.\n4. Vỗ nhẹ để sản phẩm thấm.\n5. Tiếp tục kem dưỡng và chống nắng vào ban ngày.\n\nLưu ý: Chỉ sử dụng ngoài da. Tránh tiếp xúc trực tiếp với mắt. Ngừng sử dụng nếu xuất hiện kích ứng kéo dài.\n\n5. ĐỐI TƯỢNG SỬ DỤNG\n\n• Người có da thiếu ẩm, thiếu sức sống.\n• Người muốn bổ sung serum chăm sóc hàng rào da.\n• Người cần dưỡng da hằng ngày.", "en": "1. PRODUCT DESCRIPTION\n\nVichy Minéral 89 Probiotic Fractions Concentrate is a facial serum designed to support hydration and improve the appearance of skin affected by everyday environmental stressors. The formula combines Vichy Volcanic Water with fermentation-derived ingredients and other skin-conditioning components. It helps the complexion feel more comfortable and appear refreshed, making it a suitable addition to routines focused on dehydrated or tired-looking skin.\n\n2. BENEFITS\n\n• Helps maintain skin hydration.\n• Supports a softer and more comfortable skin feel.\n• Helps improve the appearance of tired-looking skin.\n• Supports daily care of the skin's moisture barrier.\n• Promotes a fresher and healthier-looking complexion.\n\n3. INGREDIENTS\n\nKey ingredients and their functions:\n\n• Vichy Volcanic Water: The brand's signature mineral-rich water.\n• Probiotic Fractions: Fermentation-derived ingredients used in the formula.\n• Moisturizing and skin-conditioning ingredients: The complete ingredient names and concentrations must be checked against the product packaging.\n• The exact formulation should not be assumed to match other Minéral 89 products.\n\nNote: The ingredients listed above are selected formulation components and do not represent the complete INCI list. Formulations may vary by product version and market. Always verify the ingredients against the actual product packaging.\n\n4. DIRECTIONS FOR USE\n\n1. Cleanse the face and gently pat dry.\n2. Apply a suitable amount of concentrate to the face and neck.\n3. Spread evenly and allow it to absorb.\n4. Follow with moisturizer.\n5. Use sunscreen during the day.\n\n5. SUITABLE FOR\n\n• Dehydrated or tired-looking skin.\n• People seeking additional moisturizing care.\n• Individuals concerned about everyday environmental stressors.\n• Those looking for a lightweight skin-conditioning serum."}, "image": "assets/catalog/product-vichy-09.jpg", "gallery": {"vi": [{"src": "assets/catalog/vi/vichy-09/thumbnail.webp", "label": "Thumbnail", "order": 0}, {"src": "assets/catalog/vi/vichy-09/anh-1.webp", "label": "Ảnh 1", "order": 1}, {"src": "assets/catalog/vi/vichy-09/anh-2.webp", "label": "Ảnh 2", "order": 2}, {"src": "assets/catalog/vi/vichy-09/anh-3.webp", "label": "Ảnh 3", "order": 3}, {"src": "assets/catalog/vi/vichy-09/anh-4.webp", "label": "Ảnh 4", "order": 4}, {"src": "assets/catalog/vi/vichy-09/anh-5.webp", "label": "Ảnh 5", "order": 5}, {"src": "assets/catalog/vi/vichy-09/anh-6.webp", "label": "Ảnh 6", "order": 6}, {"src": "assets/catalog/vi/vichy-09/anh-7.webp", "label": "Ảnh 7", "order": 7}]}}, {"id": "vichy-10", "brandId": "vichy", "brand": "Vichy", "name": {"vi": "GEL CHỐNG NẮNG VICHY CAPITAL SOLEIL UV-AGE DAILY SPF50+", "en": "Vichy Capital Soleil UV-Age Daily SPF50+ Sunscreen"}, "category": "Skincare", "type": "Chống nắng bảo vệ da hằng ngày", "size": "Cần xác nhận dung tích trên bao bì", "country": "Pháp", "description": {"vi": "1. MÔ TẢ SẢN PHẨM\n\nTên sản phẩm: Gel Chống Nắng Vichy Capital Soleil UV-Age Daily SPF50+\nThương hiệu: Vichy\nQuốc gia thương hiệu: Pháp\nQuy cách đóng gói: Cần xác nhận dung tích trên bao bì\nPhân loại: Chống nắng bảo vệ da hằng ngày\n\nVichy Capital Soleil UV-Age Daily SPF50+ là sản phẩm chống nắng sử dụng hằng ngày, hướng đến nhu cầu bảo vệ da trước tác động của tia UV và hỗ trợ chăm sóc các dấu hiệu lão hóa do ánh nắng. Kết cấu dạng lỏng nhẹ phù hợp để sử dụng ở bước cuối quy trình dưỡng da buổi sáng, trước khi trang điểm.\n\n2. CÔNG DỤNG\n\n• Bảo vệ da trước tác động của tia UV với chỉ số SPF50+.\n• Hỗ trợ hạn chế các dấu hiệu lão hóa sớm do ánh nắng.\n• Giúp duy trì thói quen chống nắng hằng ngày.\n• Phù hợp sử dụng trước bước trang điểm.\n\n3. THÀNH PHẦN\n\nCác thành phần nổi bật:\n\n• Hệ màng lọc chống nắng: Giúp bảo vệ da trước tia UV.\n• Các thành phần chăm sóc da và hỗ trợ chống oxy hóa: Theo công thức công bố của sản phẩm.\n• Danh sách INCI cụ thể cần được đối chiếu trên bao bì phiên bản đang lưu hành.\n\nLưu ý: Đây là các thành phần tiêu biểu, không thay thế danh sách INCI đầy đủ. Công thức có thể khác nhau giữa các phiên bản sản phẩm.\n\n4. HƯỚNG DẪN SỬ DỤNG\n\n1. Lắc sản phẩm nếu hướng dẫn trên bao bì yêu cầu.\n2. Thoa lượng chống nắng đầy đủ lên mặt và cổ ở bước cuối dưỡng da buổi sáng.\n3. Thoa trước khi tiếp xúc ánh nắng.\n4. Thoa lại khoảng mỗi 2 giờ khi hoạt động ngoài trời, đặc biệt sau khi đổ mồ hôi hoặc lau mặt.\n5. Kết hợp mũ, kính và biện pháp che chắn.\n\nLưu ý: Chỉ sử dụng ngoài da. Tránh tiếp xúc trực tiếp với mắt. Ngừng sử dụng nếu xuất hiện kích ứng kéo dài.\n\n5. ĐỐI TƯỢNG SỬ DỤNG\n\n• Người cần chống nắng hằng ngày.\n• Người quan tâm đến dấu hiệu lão hóa do ánh nắng.\n• Người muốn sản phẩm chống nắng kết cấu nhẹ.", "en": "1. PRODUCT DESCRIPTION\n\nVichy Capital Soleil UV-Age Daily SPF50+ is a facial sunscreen developed to provide high UV protection while complementing skincare routines focused on visible signs of photoaging. Its lightweight fluid texture is designed for comfortable everyday application on the face and neck. The sunscreen uses UV filters to help protect the skin against UVA and UVB radiation, an important step in reducing the risk of sun-related skin damage and premature visible aging.\n\n2. BENEFITS\n\n• Provides high sun protection with SPF50+.\n• Helps protect the skin against UVA and UVB radiation.\n• Supports the prevention of premature visible aging caused by sun exposure.\n• Offers a lightweight texture for daily facial use.\n• Can be incorporated into morning skincare routines before makeup.\n\n3. INGREDIENTS\n\nKey ingredients and their functions:\n\n• UV Filters: Help protect the skin from ultraviolet radiation.\n• Skin-Conditioning Ingredients: Support the cosmetic texture and skincare benefits of the formula.\n• Antioxidant Ingredients: May be included depending on the specific formulation.\n• Important: The exact UV filters and complete INCI list must be verified against the product version being sold.\n\nNote: The ingredients listed above are selected formulation components and do not represent the complete INCI list. Formulations may vary by product version and market. Always verify the ingredients against the actual product packaging.\n\n4. DIRECTIONS FOR USE\n\n1. Shake the product if instructed on the packaging.\n2. Apply generously and evenly over the face and neck before sun exposure.\n3. Use as the final step of the morning skincare routine.\n4. Reapply frequently, especially after sweating, swimming or towel-drying.\n5. Combine sunscreen with protective clothing, sunglasses and shade.\n6. Avoid prolonged sun exposure, even when using sunscreen.\n\n5. SUITABLE FOR\n\n• People seeking daily facial sun protection.\n• Individuals concerned about photoaging.\n• Those who prefer lightweight sunscreen textures.\n• People incorporating sunscreen into an anti-aging skincare routine."}, "image": "assets/catalog/product-vichy-10.jpg", "gallery": {"vi": [{"src": "assets/catalog/vi/vichy-10/thumbnail.webp", "label": "Thumbnail", "order": 0}, {"src": "assets/catalog/vi/vichy-10/anh-1.webp", "label": "Ảnh 1", "order": 1}, {"src": "assets/catalog/vi/vichy-10/anh-2.webp", "label": "Ảnh 2", "order": 2}, {"src": "assets/catalog/vi/vichy-10/anh-3.webp", "label": "Ảnh 3", "order": 3}, {"src": "assets/catalog/vi/vichy-10/anh-4.webp", "label": "Ảnh 4", "order": 4}, {"src": "assets/catalog/vi/vichy-10/anh-5.webp", "label": "Ảnh 5", "order": 5}, {"src": "assets/catalog/vi/vichy-10/anh-6.webp", "label": "Ảnh 6", "order": 6}, {"src": "assets/catalog/vi/vichy-10/anh-7.webp", "label": "Ảnh 7", "order": 7}]}}, {"id": "laneige-01", "brandId": "laneige", "brand": "Laneige", "name": {"vi": "MẶT NẠ NGỦ DƯỠNG MÔI LANEIGE LIP SLEEPING MASK EX BERRY 20G", "en": "LANEIGE Lip Sleeping Mask EX Berry 20g"}, "category": "Skincare", "type": "Mặt nạ ngủ dưỡng môi", "size": "Hũ 20g", "country": "Hàn Quốc", "description": {"vi": "1. MÔ TẢ SẢN PHẨM\n\nTên sản phẩm: Mặt Nạ Ngủ Dưỡng Môi Laneige Lip Sleeping Mask EX Berry 20g\nThương hiệu: LANEIGE\nQuốc gia thương hiệu: Hàn Quốc\nQuy cách đóng gói: Hũ 20g\nPhân loại: Mặt nạ ngủ dưỡng môi\n\nMặt Nạ Ngủ Dưỡng Môi Laneige Lip Sleeping Mask EX Berry 20g là sản phẩm chăm sóc môi chuyên sâu sử dụng vào buổi tối. Công thức giàu thành phần làm mềm và khóa ẩm, kết hợp phức hợp chiết xuất quả mọng, giúp làm mềm lớp da khô trên môi, cải thiện cảm giác khô ráp và mang lại đôi môi căng mịn hơn vào sáng hôm sau.\n\n2. CÔNG DỤNG\n\n• Cấp ẩm và hỗ trợ khóa ẩm cho môi trong khi ngủ.\n• Làm mềm lớp da khô, bong tróc trên bề mặt môi.\n• Giúp môi mềm mại, căng mịn hơn.\n• Hỗ trợ chăm sóc môi khô thường xuyên.\n\n3. THÀNH PHẦN\n\nCác thành phần nổi bật:\n\n• Shea Butter: Bơ hạt mỡ giúp làm mềm và dưỡng môi.\n• Murumuru Seed Butter: Bơ thực vật hỗ trợ khóa ẩm.\n• Diisostearyl Malate: Thành phần làm mềm môi.\n• Chiết xuất quả dâu tây, mâm xôi, việt quất và nam việt quất: Các thành phần thực vật trong công thức.\n• Sodium Hyaluronate: Thành phần giữ ẩm.\n• Ascorbyl Glucoside: Dẫn xuất vitamin C.\n\nLưu ý: Đây là các thành phần nổi bật, không thay thế bảng INCI đầy đủ. Thành phần có thể thay đổi theo phiên bản, mã màu hoặc hương.\n\n4. HƯỚNG DẪN SỬ DỤNG\n\n1. Làm sạch môi vào buổi tối.\n2. Lấy lượng mặt nạ vừa đủ bằng dụng cụ sạch.\n3. Thoa đều một lớp lên môi.\n4. Để qua đêm và nhẹ nhàng làm sạch vào sáng hôm sau.\n\nLưu ý: Chỉ dùng ngoài da. Tránh tiếp xúc trực tiếp với mắt. Ngừng sử dụng nếu có dấu hiệu kích ứng.\n\n5. ĐỐI TƯỢNG SỬ DỤNG\n\n• Người có môi khô, dễ bong tróc.\n• Người muốn chăm sóc môi chuyên sâu ban đêm.\n• Người thường xuyên sử dụng son lì.", "en": "1. PRODUCT DESCRIPTION\n\nLANEIGE Lip Sleeping Mask EX Berry is a rich overnight lip treatment designed to nourish dry, rough and flaky lips. Its cushiony balm texture forms a moisturizing layer over the lips while you sleep, helping reduce the appearance of dryness and leaving the lips feeling softer and smoother by morning. The Berry version offers a fruity sensory experience and is especially useful as the final step of an evening skincare routine.\n\n2. BENEFITS\n\n• Provides intensive overnight moisture for dry lips.\n• Helps soften rough, flaky lip surfaces.\n• Supports a smoother and more supple lip appearance.\n• Helps reduce moisture loss during the night.\n• Creates a comfortable conditioning layer over the lips.\n\n3. INGREDIENTS\n\nKey ingredients and their functions:\n\n• Berry Fruit Complex: Berry-derived ingredients used for lip-conditioning and antioxidant care.\n• Vitamin C: An antioxidant component associated with the product's berry complex.\n• Coconut Oil: An emollient that helps soften lips.\n• Shea Butter: A rich conditioning ingredient that helps retain moisture.\n• Additional emollients and waxes: Contribute to the protective balm texture.\n\nNote: The ingredients above are selected formulation components or product-line information, not a complete INCI declaration. Ingredient lists may vary by formulation, shade, region and production version. Verify the actual packaging before publication.\n\n4. DIRECTIONS FOR USE\n\n1. Complete the evening skincare routine.\n2. Using a clean applicator, spread a generous layer over the lips.\n3. Leave the mask on overnight.\n4. In the morning, gently remove any remaining product if desired.\n5. Reapply whenever additional lip conditioning is needed.\n\nPrecautions: For external use only. Discontinue use if irritation occurs. Avoid applying to damaged skin. Keep out of reach of children.\n\n5. SUITABLE FOR\n\n• People with dry or flaky lips.\n• Individuals experiencing rough lip texture.\n• Those seeking an intensive overnight lip treatment.\n• People who prefer rich, balm-textured lip care."}, "image": "assets/catalog/product-laneige-01.webp", "gallery": {"vi": [{"src": "assets/catalog/vi/laneige-01/thumbnail.webp", "label": "Thumbnail", "order": 0}, {"src": "assets/catalog/vi/laneige-01/anh-1.webp", "label": "Ảnh 1", "order": 1}, {"src": "assets/catalog/vi/laneige-01/anh-2.webp", "label": "Ảnh 2", "order": 2}, {"src": "assets/catalog/vi/laneige-01/anh-3.webp", "label": "Ảnh 3", "order": 3}, {"src": "assets/catalog/vi/laneige-01/anh-4.webp", "label": "Ảnh 4", "order": 4}, {"src": "assets/catalog/vi/laneige-01/anh-5.webp", "label": "Ảnh 5", "order": 5}, {"src": "assets/catalog/vi/laneige-01/anh-6.webp", "label": "Ảnh 6", "order": 6}, {"src": "assets/catalog/vi/laneige-01/anh-7.webp", "label": "Ảnh 7", "order": 7}]}}, {"id": "laneige-02", "brandId": "laneige", "brand": "Laneige", "name": {"vi": "SON DƯỠNG MÔI LANEIGE LIP GLOWY BALM 10G", "en": "LANEIGE Lip Glowy Balm 10g"}, "category": "Skincare", "type": "Son dưỡng môi có màu nhẹ", "size": "Tuýp 10g", "country": "Hàn Quốc", "description": {"vi": "1. MÔ TẢ SẢN PHẨM\n\nTên sản phẩm: Son Dưỡng Môi Laneige Lip Glowy Balm 10g\nThương hiệu: LANEIGE\nQuốc gia thương hiệu: Hàn Quốc\nQuy cách đóng gói: Tuýp 10g\nPhân loại: Son dưỡng môi có màu nhẹ\n\nSon Dưỡng Môi Laneige Lip Glowy Balm 10g là sản phẩm dưỡng môi tiện dụng với kết cấu bóng nhẹ và khả năng làm mềm môi. Sản phẩm có các phiên bản màu và hương khác nhau, phù hợp sử dụng ban ngày để dưỡng môi, tạo vẻ căng bóng tự nhiên mà không cần lớp son màu đậm.\n\n2. CÔNG DỤNG\n\n• Giúp môi mềm mại và hạn chế cảm giác khô.\n• Tạo hiệu ứng môi căng bóng.\n• Mang lại sắc màu nhẹ tùy phiên bản.\n• Thiết kế tuýp tiện lợi để sử dụng trong ngày.\n\n3. THÀNH PHẦN\n\nCác thành phần nổi bật:\n\n• Hydrogenated Polyisobutene: Thành phần làm mềm và tạo độ bóng.\n• Shea Butter: Bơ hạt mỡ giúp dưỡng môi.\n• Murumuru Seed Butter: Thành phần dưỡng mềm.\n• Tocopherol: Thành phần chống oxy hóa.\n• Chiết xuất quả mọng: Thành phần thực vật được ghi nhận trong công thức phiên bản Berry.\n• Sắc tố màu và hương liệu thay đổi tùy phiên bản.\n\nLưu ý: Đây là các thành phần nổi bật, không thay thế bảng INCI đầy đủ. Thành phần có thể thay đổi theo phiên bản, mã màu hoặc hương.\n\n4. HƯỚNG DẪN SỬ DỤNG\n\n1. Làm sạch môi trước khi sử dụng.\n2. Bóp nhẹ tuýp để lấy lượng son vừa đủ.\n3. Thoa đều trực tiếp lên môi.\n4. Dặm lại trong ngày khi môi khô hoặc cần tăng độ bóng.\n\nLưu ý: Chỉ dùng ngoài da. Tránh tiếp xúc trực tiếp với mắt. Ngừng sử dụng nếu có dấu hiệu kích ứng.\n\n5. ĐỐI TƯỢNG SỬ DỤNG\n\n• Người muốn dưỡng môi hằng ngày.\n• Người thích hiệu ứng môi bóng nhẹ.\n• Người cần sản phẩm dưỡng môi tiện mang theo.", "en": "1. PRODUCT DESCRIPTION\n\nLANEIGE Lip Glowy Balm is a portable daily lip moisturizer that combines a glossy finish with comfortable lip-conditioning care. Its lightweight balm texture glides over the lips to help soften dryness while creating a fresh, naturally luminous appearance. The convenient tube format makes it easy to reapply throughout the day, either on bare lips or over compatible lip makeup. The fragrance or shade variant should be specified separately when listing the product online.\n\n2. BENEFITS\n\n• Moisturizes and softens dry lips.\n• Provides a smooth, glossy-looking finish.\n• Helps reduce the feeling of lip tightness.\n• Supports comfortable daily lip care.\n• Convenient for on-the-go application.\n\n3. INGREDIENTS\n\nKey ingredients and their functions:\n\n• Emollient Oils: Help soften and condition the lip surface.\n• Shea Butter: A moisturizing emollient used in lip-care formulas.\n• Film-Forming Ingredients: Help create a smooth, glossy finish.\n• Variant-Specific Ingredients: Fragrance and color components may differ; check the actual tube for the full INCI list.\n\nNote: The ingredients above are selected formulation components or product-line information, not a complete INCI declaration. Ingredient lists may vary by formulation, shade, region and production version. Verify the actual packaging before publication.\n\n4. DIRECTIONS FOR USE\n\n1. Apply a small amount directly to clean lips.\n2. Spread evenly using the tube applicator.\n3. Reapply during the day whenever lips feel dry.\n4. Wear alone or layer over lip color as desired.\n\nPrecautions: For external use only. Discontinue use if irritation occurs. Avoid applying to damaged skin. Keep out of reach of children.\n\n5. SUITABLE FOR\n\n• People with dry or uncomfortable lips.\n• Individuals seeking everyday lip hydration.\n• Those who prefer a glossy lip finish.\n• People looking for portable lip care."}, "image": "assets/catalog/product-laneige-02.webp", "gallery": {"vi": [{"src": "assets/catalog/vi/laneige-02/thumbnail.webp", "label": "Thumbnail", "order": 0}, {"src": "assets/catalog/vi/laneige-02/anh-1.webp", "label": "Ảnh 1", "order": 1}, {"src": "assets/catalog/vi/laneige-02/anh-2.webp", "label": "Ảnh 2", "order": 2}, {"src": "assets/catalog/vi/laneige-02/anh-3.webp", "label": "Ảnh 3", "order": 3}, {"src": "assets/catalog/vi/laneige-02/anh-4.webp", "label": "Ảnh 4", "order": 4}, {"src": "assets/catalog/vi/laneige-02/anh-5.webp", "label": "Ảnh 5", "order": 5}, {"src": "assets/catalog/vi/laneige-02/anh-6.webp", "label": "Ảnh 6", "order": 6}, {"src": "assets/catalog/vi/laneige-02/anh-7.webp", "label": "Ảnh 7", "order": 7}]}}, {"id": "laneige-03", "brandId": "laneige", "brand": "Laneige", "name": {"vi": "NƯỚC CÂN BẰNG DƯỠNG ẨM LANEIGE CREAM SKIN CERAPEPTIDE REFINER 170ML", "en": "LANEIGE Cream Skin Cerapeptide Refiner 170ml"}, "category": "Skincare", "type": "Nước cân bằng dưỡng ẩm", "size": "Chai 170ml", "country": "Hàn Quốc", "description": {"vi": "1. MÔ TẢ SẢN PHẨM\n\nTên sản phẩm: Nước Cân Bằng Dưỡng Ẩm Laneige Cream Skin Cerapeptide Refiner 170ml\nThương hiệu: LANEIGE\nQuốc gia thương hiệu: Hàn Quốc\nQuy cách đóng gói: Chai 170ml\nPhân loại: Nước cân bằng dưỡng ẩm\n\nLaneige Cream Skin Cerapeptide Refiner 170ml là nước cân bằng kết hợp đặc tính cấp ẩm của toner với cảm giác giàu dưỡng của kem dưỡng. Công thức Cerapeptide kết hợp ceramide và peptide giúp cấp ẩm, làm mềm da và hỗ trợ củng cố hàng rào bảo vệ độ ẩm. Kết cấu lỏng, dễ thoa và phù hợp dùng sau bước làm sạch.\n\n2. CÔNG DỤNG\n\n• Bổ sung độ ẩm cho da sau khi rửa mặt.\n• Giúp da mềm mại và căng mịn.\n• Hỗ trợ hàng rào bảo vệ độ ẩm.\n• Giúp giảm cảm giác khô căng, thiếu ẩm.\n• Chuẩn bị bề mặt da cho các bước dưỡng tiếp theo.\n\n3. THÀNH PHẦN\n\nCác thành phần nổi bật:\n\n• Ceramide NP: Thành phần lipid hỗ trợ hàng rào bảo vệ da.\n• Acetyl Tetrapeptide-11: Peptide chăm sóc da.\n• Glycerin: Thành phần hút ẩm.\n• Squalane: Hỗ trợ làm mềm và giảm mất nước.\n• Meadowfoam Seed Oil: Dầu thực vật làm mềm da.\n• Hyaluronic Acid: Hỗ trợ cấp ẩm.\n• Camellia Japonica Flower Extract: Chiết xuất hoa sơn trà.\n\nLưu ý: Đây là các thành phần nổi bật, không thay thế bảng INCI đầy đủ. Thành phần có thể thay đổi theo phiên bản, mã màu hoặc hương.\n\n4. HƯỚNG DẪN SỬ DỤNG\n\n1. Làm sạch da mặt.\n2. Cho lượng nước cân bằng vừa đủ ra lòng bàn tay hoặc bông cotton.\n3. Thoa nhẹ lên mặt và cổ, tránh vùng mắt.\n4. Vỗ nhẹ cho sản phẩm thấm.\n5. Tiếp tục sử dụng serum và kem dưỡng nếu cần.\n\nLưu ý: Chỉ dùng ngoài da. Tránh tiếp xúc trực tiếp với mắt. Ngừng sử dụng nếu có dấu hiệu kích ứng.\n\n5. ĐỐI TƯỢNG SỬ DỤNG\n\n• Người có da khô hoặc thiếu ẩm.\n• Người muốn nước cân bằng giàu dưỡng.\n• Người cần hỗ trợ chăm sóc hàng rào độ ẩm.", "en": "1. PRODUCT DESCRIPTION\n\nLANEIGE Cream Skin Cerapeptide Refiner is a moisturizing toner designed to combine the freshness of a liquid refiner with the nourishing feel of a lightweight cream. It helps replenish moisture immediately after cleansing and supports a smoother, softer complexion. The formula features the brand's Cerapeptide concept, bringing together ceramide-related barrier care and peptide-based skin conditioning. Its fluid texture makes it suitable for layering beneath serums and moisturizers, particularly when skin feels dehydrated or tight.\n\n2. BENEFITS\n\n• Provides hydration immediately after cleansing.\n• Helps soften and smooth dry skin.\n• Supports the skin's moisture barrier.\n• Prepares the complexion for subsequent skincare steps.\n• Offers cream-like conditioning in a lightweight liquid texture.\n\n3. INGREDIENTS\n\nKey ingredients and their functions:\n\n• Ceramide NP: A skin-identical lipid that supports the moisture barrier.\n• Peptide Ingredients: Skin-conditioning components associated with the Cerapeptide concept.\n• Glycerin: A humectant that helps retain water.\n• Emollient Ingredients: Support softness and a comfortable skin feel.\n• The exact peptide names and complete INCI should be checked against the 170ml packaging.\n\nNote: The ingredients above are selected formulation components or product-line information, not a complete INCI declaration. Ingredient lists may vary by formulation, shade, region and production version. Verify the actual packaging before publication.\n\n4. DIRECTIONS FOR USE\n\n1. Cleanse the face and gently pat dry.\n2. Dispense an appropriate amount into clean palms or onto a cotton pad.\n3. Gently press or sweep the product over the face and neck.\n4. Apply another thin layer if additional hydration is needed.\n5. Continue with serum, moisturizer and daytime sunscreen.\n\nPrecautions: For external use only. Discontinue use if irritation occurs. Avoid applying to damaged skin. Keep out of reach of children.\n\n5. SUITABLE FOR\n\n• Dry or dehydrated skin.\n• People experiencing tightness after cleansing.\n• Individuals seeking a moisturizing toner.\n• Those who prefer lightweight yet nourishing skincare."}, "image": "assets/catalog/product-laneige-03.webp", "gallery": {"vi": [{"src": "assets/catalog/vi/laneige-03/thumbnail.webp", "label": "Thumbnail", "order": 0}, {"src": "assets/catalog/vi/laneige-03/anh-1.webp", "label": "Ảnh 1", "order": 1}, {"src": "assets/catalog/vi/laneige-03/anh-2.webp", "label": "Ảnh 2", "order": 2}, {"src": "assets/catalog/vi/laneige-03/anh-3.webp", "label": "Ảnh 3", "order": 3}, {"src": "assets/catalog/vi/laneige-03/anh-4.webp", "label": "Ảnh 4", "order": 4}, {"src": "assets/catalog/vi/laneige-03/anh-5.webp", "label": "Ảnh 5", "order": 5}, {"src": "assets/catalog/vi/laneige-03/anh-6.webp", "label": "Ảnh 6", "order": 6}, {"src": "assets/catalog/vi/laneige-03/anh-7.webp", "label": "Ảnh 7", "order": 7}]}}, {"id": "laneige-04", "brandId": "laneige", "brand": "Laneige", "name": {"vi": "TINH CHẤT DƯỠNG ẨM LANEIGE WATER BANK BLUE HYALURONIC SERUM 50ML", "en": "LANEIGE Water Bank Blue Hyaluronic Serum 50ml"}, "category": "Skincare", "type": "Serum dưỡng ẩm", "size": "Chai 50ml", "country": "Hàn Quốc", "description": {"vi": "1. MÔ TẢ SẢN PHẨM\n\nTên sản phẩm: Tinh Chất Dưỡng Ẩm Laneige Water Bank Blue Hyaluronic Serum 50ml\nThương hiệu: LANEIGE\nQuốc gia thương hiệu: Hàn Quốc\nQuy cách đóng gói: Chai 50ml\nPhân loại: Serum dưỡng ẩm\n\nTinh Chất Dưỡng Ẩm Laneige Water Bank Blue Hyaluronic Serum 50ml là sản phẩm chăm sóc da mặt thuộc dòng Water Bank, nổi bật với Blue Hyaluronic Acid. Công thức hướng đến nhu cầu cấp ẩm, cải thiện cảm giác khô căng và giúp da trông căng mịn, khỏe khoắn hơn. Kết cấu serum phù hợp sử dụng trước kem dưỡng trong quy trình chăm sóc da.\n\n2. CÔNG DỤNG\n\n• Bổ sung độ ẩm cho da.\n• Hỗ trợ giảm cảm giác khô căng.\n• Giúp bề mặt da mềm mại, căng mịn.\n• Hỗ trợ duy trì hàng rào độ ẩm.\n• Chuẩn bị da cho bước kem dưỡng.\n\n3. THÀNH PHẦN\n\nCác thành phần nổi bật:\n\n• Hydrolyzed Hyaluronic Acid: Hyaluronic Acid thủy phân hỗ trợ cấp ẩm.\n• Glycerin: Thành phần hút ẩm.\n• Squalane: Hỗ trợ làm mềm da.\n• Betaine: Thành phần giữ ẩm.\n• Beta-Glucan: Thành phần chăm sóc và làm dịu da.\n• Lactobacillus Ferment Lysate: Thành phần lên men trong công thức.\n\nLưu ý: Đây là các thành phần nổi bật, không thay thế bảng INCI đầy đủ. Thành phần có thể thay đổi theo phiên bản, mã màu hoặc hương.\n\n4. HƯỚNG DẪN SỬ DỤNG\n\n1. Làm sạch da và dùng nước cân bằng.\n2. Lấy 1–2 lần nhấn serum hoặc lượng vừa đủ.\n3. Thoa đều lên mặt và cổ.\n4. Vỗ nhẹ để sản phẩm thấm.\n5. Tiếp tục với kem dưỡng phù hợp.\n\nLưu ý: Chỉ dùng ngoài da. Tránh tiếp xúc trực tiếp với mắt. Ngừng sử dụng nếu có dấu hiệu kích ứng.\n\n5. ĐỐI TƯỢNG SỬ DỤNG\n\n• Người có da thiếu ẩm, khô căng.\n• Người muốn serum cấp ẩm hằng ngày.\n• Người cần chăm sóc hàng rào độ ẩm.", "en": "1. PRODUCT DESCRIPTION\n\nLANEIGE Water Bank Blue Hyaluronic Serum is a hydrating facial serum from the Water Bank collection, designed to replenish moisture and improve the appearance of dehydrated skin. Its lightweight texture spreads easily and fits between toner and moisturizer in a daily skincare routine. Featuring the collection's Blue Hyaluronic Acid technology, the serum helps the complexion feel smoother, more supple and comfortable while supporting the skin's moisture barrier.\n\n2. BENEFITS\n\n• Helps replenish hydration in dehydrated skin.\n• Supports a smoother and plumper-looking complexion.\n• Helps relieve tightness associated with dryness.\n• Supports the skin's protective moisture barrier.\n• Layers comfortably beneath facial moisturizer.\n\n3. INGREDIENTS\n\nKey ingredients and their functions:\n\n• Blue Hyaluronic Acid: The collection's signature hyaluronic-acid-based moisturizing technology.\n• Hyaluronic Acid Derivatives: Help attract and retain water.\n• Glycerin: Supports moisture retention.\n• Skin-Conditioning Ingredients: Help maintain a soft, comfortable skin feel.\n• The complete INCI must be verified for the specific 50ml serum version.\n\nNote: The ingredients above are selected formulation components or product-line information, not a complete INCI declaration. Ingredient lists may vary by formulation, shade, region and production version. Verify the actual packaging before publication.\n\n4. DIRECTIONS FOR USE\n\n1. Cleanse and tone the face.\n2. Dispense a suitable amount of serum.\n3. Apply evenly over the face and neck.\n4. Gently press until absorbed.\n5. Follow with a Water Bank moisturizer or another suitable cream.\n6. Use morning and evening; apply sunscreen during the day.\n\nPrecautions: For external use only. Discontinue use if irritation occurs. Avoid applying to damaged skin. Keep out of reach of children.\n\n5. SUITABLE FOR\n\n• Dehydrated skin.\n• People concerned about roughness caused by insufficient moisture.\n• Individuals looking for a lightweight hydrating serum.\n• Those seeking daily moisture-barrier support."}, "image": "assets/catalog/product-laneige-04.webp", "gallery": {"vi": [{"src": "assets/catalog/vi/laneige-04/thumbnail.webp", "label": "Thumbnail", "order": 0}, {"src": "assets/catalog/vi/laneige-04/anh-1.webp", "label": "Ảnh 1", "order": 1}, {"src": "assets/catalog/vi/laneige-04/anh-2.webp", "label": "Ảnh 2", "order": 2}, {"src": "assets/catalog/vi/laneige-04/anh-3.webp", "label": "Ảnh 3", "order": 3}, {"src": "assets/catalog/vi/laneige-04/anh-4.webp", "label": "Ảnh 4", "order": 4}, {"src": "assets/catalog/vi/laneige-04/anh-5.webp", "label": "Ảnh 5", "order": 5}, {"src": "assets/catalog/vi/laneige-04/anh-6.webp", "label": "Ảnh 6", "order": 6}, {"src": "assets/catalog/vi/laneige-04/anh-7.webp", "label": "Ảnh 7", "order": 7}]}}, {"id": "laneige-05", "brandId": "laneige", "brand": "Laneige", "name": {"vi": "KEM DƯỠNG LANEIGE WATER BANK BLUE HYALURONIC GEL CREAM 50ML", "en": "LANEIGE Water Bank Blue Hyaluronic Gel Cream 50ml"}, "category": "Skincare", "type": "Kem dưỡng dạng gel cho da dầu và hỗn hợp", "size": "Hũ 50ml", "country": "Hàn Quốc", "description": {"vi": "1. MÔ TẢ SẢN PHẨM\n\nTên sản phẩm: Kem Dưỡng Laneige Water Bank Blue Hyaluronic Gel Cream 50ml\nThương hiệu: LANEIGE\nQuốc gia thương hiệu: Hàn Quốc\nQuy cách đóng gói: Hũ 50ml\nPhân loại: Kem dưỡng dạng gel cho da dầu và hỗn hợp\n\nLaneige Water Bank Blue Hyaluronic Gel Cream 50ml là kem dưỡng ẩm kết cấu gel thuộc dòng Water Bank, được thiết kế hướng đến da dầu và da hỗn hợp. Sản phẩm giúp bổ sung độ ẩm, tạo cảm giác tươi mát và hỗ trợ cân bằng dầu – ẩm, phù hợp với làn da tiết dầu nhưng vẫn có dấu hiệu thiếu nước.\n\n2. CÔNG DỤNG\n\n• Cấp ẩm cho da dầu và da hỗn hợp.\n• Hỗ trợ cân bằng cảm giác dầu – ẩm.\n• Giúp da mềm mại và dễ chịu.\n• Mang lại cảm giác mát nhẹ nhờ kết cấu gel.\n• Hỗ trợ hàng rào bảo vệ độ ẩm.\n\n3. THÀNH PHẦN\n\nCác thành phần nổi bật:\n\n• Blue Hyaluronic Acid: Thành phần cấp ẩm đặc trưng của dòng Water Bank.\n• Betaine: Hỗ trợ giữ ẩm và làm dịu da.\n• Chiết xuất lá bạc hà: Thành phần thực vật được giới thiệu trong công thức.\n• Các chất dưỡng ẩm và làm mềm da khác: Theo bảng thành phần của phiên bản 50ml.\n\nLưu ý: Đây là các thành phần nổi bật, không thay thế bảng INCI đầy đủ. Thành phần có thể thay đổi theo phiên bản, mã màu hoặc hương.\n\n4. HƯỚNG DẪN SỬ DỤNG\n\n1. Sử dụng sau bước serum.\n2. Lấy lượng kem gel vừa đủ.\n3. Thoa đều lên mặt và cổ.\n4. Massage nhẹ đến khi sản phẩm thấm.\n5. Dùng buổi sáng và tối; ban ngày kết hợp chống nắng.\n\nLưu ý: Chỉ dùng ngoài da. Tránh tiếp xúc trực tiếp với mắt. Ngừng sử dụng nếu có dấu hiệu kích ứng.\n\n5. ĐỐI TƯỢNG SỬ DỤNG\n\n• Người có da dầu hoặc da hỗn hợp.\n• Người có da dầu nhưng thiếu ẩm.\n• Người thích kem dưỡng kết cấu gel nhẹ.", "en": "1. PRODUCT DESCRIPTION\n\nLANEIGE Water Bank Blue Hyaluronic Gel Cream is a refreshing facial moisturizer developed for skin that needs hydration without a heavy cream finish. Its cooling gel texture spreads smoothly and helps replenish moisture while leaving the complexion feeling fresh and comfortable. The Water Bank gel formula is particularly suited to oily and combination skin, including skin that produces excess oil yet still experiences dehydration. It can be used in morning and evening routines.\n\n2. BENEFITS\n\n• Provides hydration in a lightweight gel texture.\n• Helps maintain moisture without a heavy finish.\n• Supports a comfortable moisture-and-oil balance.\n• Leaves the skin feeling fresh and smooth.\n• Supports the skin's moisture barrier.\n\n3. INGREDIENTS\n\nKey ingredients and their functions:\n\n• Hydrolyzed Hyaluronic Acid: A moisturizing hyaluronic acid derivative.\n• Glycerin: A humectant that attracts moisture.\n• Betaine: Helps support hydration.\n• Meadowfoam Seed Oil: A lightweight emollient.\n• Jojoba Esters: Skin-conditioning ingredients that support softness.\n• Tocopherol: An antioxidant form of vitamin E.\n\nNote: The ingredients above are selected formulation components or product-line information, not a complete INCI declaration. Ingredient lists may vary by formulation, shade, region and production version. Verify the actual packaging before publication.\n\n4. DIRECTIONS FOR USE\n\n1. Cleanse and tone the face.\n2. Apply serum if included in the routine.\n3. Take an appropriate amount of gel cream.\n4. Spread evenly over the face and neck.\n5. Gently massage until absorbed.\n6. Use morning and evening; apply sunscreen during the day.\n\nPrecautions: For external use only. Discontinue use if irritation occurs. Avoid applying to damaged skin. Keep out of reach of children.\n\n5. SUITABLE FOR\n\n• Oily and combination skin.\n• Dehydrated skin that prefers light textures.\n• People who dislike heavy moisturizers.\n• Individuals seeking refreshing daily hydration."}, "image": "assets/catalog/product-laneige-05.webp", "gallery": {"vi": [{"src": "assets/catalog/vi/laneige-05/thumbnail.webp", "label": "Thumbnail", "order": 0}, {"src": "assets/catalog/vi/laneige-05/anh-1.webp", "label": "Ảnh 1", "order": 1}, {"src": "assets/catalog/vi/laneige-05/anh-2.webp", "label": "Ảnh 2", "order": 2}, {"src": "assets/catalog/vi/laneige-05/anh-3.webp", "label": "Ảnh 3", "order": 3}, {"src": "assets/catalog/vi/laneige-05/anh-4.webp", "label": "Ảnh 4", "order": 4}, {"src": "assets/catalog/vi/laneige-05/anh-5.webp", "label": "Ảnh 5", "order": 5}, {"src": "assets/catalog/vi/laneige-05/anh-6.webp", "label": "Ảnh 6", "order": 6}, {"src": "assets/catalog/vi/laneige-05/anh-7.webp", "label": "Ảnh 7", "order": 7}]}}, {"id": "laneige-06", "brandId": "laneige", "brand": "Laneige", "name": {"vi": "KEM DƯỠNG LANEIGE WATER BANK BLUE HYALURONIC MOISTURE CREAM 50ML", "en": "LANEIGE Water Bank Blue Hyaluronic Moisture Cream 50ml"}, "category": "Skincare", "type": "Kem dưỡng cho da thường đến da khô", "size": "Hũ 50ml", "country": "Hàn Quốc", "description": {"vi": "1. MÔ TẢ SẢN PHẨM\n\nTên sản phẩm: Kem Dưỡng Laneige Water Bank Blue Hyaluronic Moisture Cream 50ml\nThương hiệu: LANEIGE\nQuốc gia thương hiệu: Hàn Quốc\nQuy cách đóng gói: Hũ 50ml\nPhân loại: Kem dưỡng cho da thường đến da khô\n\nLaneige Water Bank Blue Hyaluronic Moisture Cream 50ml là kem dưỡng ẩm thuộc dòng Water Bank, hướng đến nhu cầu chăm sóc da thường đến da khô, đặc biệt khi da có cảm giác thiếu ẩm và xỉn màu. Công thức kết hợp các thành phần cấp ẩm và lipid chăm sóc da, giúp da mềm mại, căng mịn và hỗ trợ duy trì hàng rào độ ẩm.\n\n2. CÔNG DỤNG\n\n• Cấp ẩm và duy trì độ ẩm cho da.\n• Hỗ trợ giảm khô căng.\n• Giúp da mềm mại, trông căng mịn hơn.\n• Hỗ trợ củng cố hàng rào bảo vệ độ ẩm.\n• Cải thiện vẻ ngoài thiếu sức sống do da khô.\n\n3. THÀNH PHẦN\n\nCác thành phần nổi bật:\n\n• Glycerin: Thành phần hút ẩm.\n• Blue Hyaluronic Acid: Thành phần cấp ẩm đặc trưng.\n• Meadowfoam Seed Oil: Dầu thực vật giúp làm mềm da.\n• Betaine: Hỗ trợ giữ ẩm.\n• Tocopherol: Thành phần chống oxy hóa.\n• Các thành phần chăm sóc hàng rào da: Theo công thức công bố của phiên bản 50ml.\n\nLưu ý: Đây là các thành phần nổi bật, không thay thế bảng INCI đầy đủ. Thành phần có thể thay đổi theo phiên bản, mã màu hoặc hương.\n\n4. HƯỚNG DẪN SỬ DỤNG\n\n1. Làm sạch da, dùng toner và serum.\n2. Lấy lượng kem vừa đủ.\n3. Thoa đều lên mặt và cổ.\n4. Massage nhẹ cho kem thấm.\n5. Dùng sáng và tối; ban ngày kết hợp kem chống nắng.\n\nLưu ý: Chỉ dùng ngoài da. Tránh tiếp xúc trực tiếp với mắt. Ngừng sử dụng nếu có dấu hiệu kích ứng.\n\n5. ĐỐI TƯỢNG SỬ DỤNG\n\n• Người có da thường đến da khô.\n• Người có da thiếu ẩm, xỉn màu.\n• Người cần kem dưỡng sử dụng hằng ngày.", "en": "1. PRODUCT DESCRIPTION\n\nLANEIGE Water Bank Blue Hyaluronic Moisture Cream is a nourishing daily moisturizer designed for normal to dry skin. It combines the Water Bank collection's hydrating technology with emollient and barrier-supporting ingredients to help replenish moisture and improve the appearance of dry, dull skin. Its soft cream texture provides a comfortable moisturizing layer while helping the complexion feel smoother, more supple and better conditioned.\n\n2. BENEFITS\n\n• Provides lasting hydration for normal to dry skin.\n• Helps soften rough and dehydrated areas.\n• Supports the skin's moisture barrier.\n• Promotes a smoother, more supple appearance.\n• Helps relieve dryness-related tightness.\n\n3. INGREDIENTS\n\nKey ingredients and their functions:\n\n• Hydrolyzed Hyaluronic Acid: Helps support skin hydration.\n• Glycerin: A humectant that helps retain moisture.\n• Squalane: An emollient that supports skin softness.\n• Ceramide NP: Helps maintain the skin's moisture barrier.\n• Panthenol: A moisturizing and skin-conditioning ingredient.\n• Allantoin: Supports a comfortable skin feel.\n\nNote: The ingredients above are selected formulation components or product-line information, not a complete INCI declaration. Ingredient lists may vary by formulation, shade, region and production version. Verify the actual packaging before publication.\n\n4. DIRECTIONS FOR USE\n\n1. Cleanse the face and apply toner.\n2. Apply a hydrating serum if desired.\n3. Take a suitable amount of moisture cream.\n4. Smooth evenly over the face and neck.\n5. Gently massage until absorbed.\n6. Use in the morning and evening, with sunscreen during the day.\n\nPrecautions: For external use only. Discontinue use if irritation occurs. Avoid applying to damaged skin. Keep out of reach of children.\n\n5. SUITABLE FOR\n\n• Normal to dry skin.\n• Skin experiencing dehydration and roughness.\n• People seeking a nourishing everyday moisturizer.\n• Individuals wanting moisture-barrier support."}, "image": "assets/catalog/product-laneige-06.webp", "gallery": {"vi": [{"src": "assets/catalog/vi/laneige-06/thumbnail.webp", "label": "Thumbnail", "order": 0}, {"src": "assets/catalog/vi/laneige-06/anh-1.webp", "label": "Ảnh 1", "order": 1}, {"src": "assets/catalog/vi/laneige-06/anh-2.webp", "label": "Ảnh 2", "order": 2}, {"src": "assets/catalog/vi/laneige-06/anh-3.webp", "label": "Ảnh 3", "order": 3}, {"src": "assets/catalog/vi/laneige-06/anh-4.webp", "label": "Ảnh 4", "order": 4}, {"src": "assets/catalog/vi/laneige-06/anh-5.webp", "label": "Ảnh 5", "order": 5}, {"src": "assets/catalog/vi/laneige-06/anh-6.webp", "label": "Ảnh 6", "order": 6}, {"src": "assets/catalog/vi/laneige-06/anh-7.webp", "label": "Ảnh 7", "order": 7}]}}, {"id": "laneige-07", "brandId": "laneige", "brand": "Laneige", "name": {"vi": "KEM DƯỠNG LANEIGE WATER BANK BLUE HYALURONIC INTENSIVE CREAM 50ML", "en": "LANEIGE Water Bank Blue Hyaluronic Intensive Cream 50ml"}, "category": "Skincare", "type": "Kem dưỡng chuyên sâu cho da khô và nhạy cảm", "size": "Hũ 50ml", "country": "Hàn Quốc", "description": {"vi": "1. MÔ TẢ SẢN PHẨM\n\nTên sản phẩm: Kem Dưỡng Laneige Water Bank Blue Hyaluronic Intensive Cream 50ml\nThương hiệu: LANEIGE\nQuốc gia thương hiệu: Hàn Quốc\nQuy cách đóng gói: Hũ 50ml\nPhân loại: Kem dưỡng chuyên sâu cho da khô và nhạy cảm\n\nLaneige Water Bank Blue Hyaluronic Intensive Cream 50ml là kem dưỡng có kết cấu giàu dưỡng dành cho da khô và da dễ nhạy cảm. Công thức kết hợp Blue Hyaluronic Acid, ceramide và các thành phần lipid giúp làm mềm da, hỗ trợ giảm tình trạng khô căng và củng cố hàng rào bảo vệ độ ẩm.\n\n2. CÔNG DỤNG\n\n• Dưỡng ẩm chuyên sâu cho da khô.\n• Hỗ trợ giảm cảm giác căng rát do khô da.\n• Giúp da mềm mại, dễ chịu.\n• Hỗ trợ hàng rào bảo vệ độ ẩm.\n• Phù hợp khi cần kem dưỡng kết cấu giàu dưỡng.\n\n3. THÀNH PHẦN\n\nCác thành phần nổi bật:\n\n• Glycerin: Thành phần hút ẩm.\n• Squalane: Hỗ trợ làm mềm da.\n• Ceramide NP: Thành phần lipid chăm sóc hàng rào da.\n• Hydrolyzed Hyaluronic Acid và Sodium Hyaluronate: Hỗ trợ cấp ẩm.\n• Niacinamide: Thành phần chăm sóc da.\n• Acetyl Tetrapeptide-2: Peptide trong công thức.\n• Fragrance: Sản phẩm có hương liệu theo bảng INCI công bố.\n\nLưu ý: Đây là các thành phần nổi bật, không thay thế bảng INCI đầy đủ. Thành phần có thể thay đổi theo phiên bản, mã màu hoặc hương.\n\n4. HƯỚNG DẪN SỬ DỤNG\n\n1. Sử dụng sau toner và serum.\n2. Lấy lượng kem vừa đủ.\n3. Thoa đều lên mặt và cổ.\n4. Massage nhẹ đến khi kem thấm.\n5. Dùng sáng và tối; ban ngày sử dụng chống nắng.\n\nLưu ý: Chỉ dùng ngoài da. Tránh tiếp xúc trực tiếp với mắt. Ngừng sử dụng nếu có dấu hiệu kích ứng.\n\n5. ĐỐI TƯỢNG SỬ DỤNG\n\n• Người có da khô hoặc rất khô.\n• Người có da dễ nhạy cảm và thiếu ẩm.\n• Người muốn kem dưỡng giàu dưỡng chất.", "en": "1. PRODUCT DESCRIPTION\n\nLANEIGE Water Bank Blue Hyaluronic Intensive Cream is a rich moisturizer designed for very dry skin that requires additional nourishment and moisture retention. Its comforting cream texture combines hydrating and emollient ingredients to help reduce the feeling of tightness and support a more resilient moisture barrier. The formula is especially useful when skin feels rough, uncomfortable or affected by dryness, including during cold weather or in air-conditioned environments.\n\n2. BENEFITS\n\n• Provides intensive moisturization for very dry skin.\n• Helps reduce dryness-related tightness.\n• Supports the skin's protective moisture barrier.\n• Softens rough and flaky-feeling areas.\n• Helps the complexion feel more comfortable and supple.\n\n3. INGREDIENTS\n\nKey ingredients and their functions:\n\n• Hydrolyzed Hyaluronic Acid: A moisturizing ingredient.\n• Squalane: An emollient that supports skin softness.\n• Ceramide NP: A barrier-supporting lipid.\n• Glycerin: A moisture-attracting humectant.\n• Niacinamide: A skin-conditioning form of vitamin B3.\n• Centella-Derived Compounds: Asiaticoside, madecassic acid and asiatic acid appear in the referenced formulation.\n\nNote: The ingredients above are selected formulation components or product-line information, not a complete INCI declaration. Ingredient lists may vary by formulation, shade, region and production version. Verify the actual packaging before publication.\n\n4. DIRECTIONS FOR USE\n\n1. Cleanse and tone the skin.\n2. Apply a hydrating serum if desired.\n3. Take a small amount of intensive cream.\n4. Spread gently over the face and neck.\n5. Apply an additional thin layer to particularly dry areas if needed.\n6. Use morning and evening; finish daytime care with sunscreen.\n\nPrecautions: For external use only. Discontinue use if irritation occurs. Avoid applying to damaged skin. Keep out of reach of children.\n\n5. SUITABLE FOR\n\n• Dry and very dry skin.\n• People experiencing roughness or tightness from dryness.\n• Individuals seeking a richer moisturizing cream.\n• Those needing extra moisture during dry weather."}, "image": "assets/catalog/product-laneige-07.webp", "gallery": {"vi": [{"src": "assets/catalog/vi/laneige-07/thumbnail.webp", "label": "Thumbnail", "order": 0}, {"src": "assets/catalog/vi/laneige-07/anh-1.webp", "label": "Ảnh 1", "order": 1}, {"src": "assets/catalog/vi/laneige-07/anh-2.webp", "label": "Ảnh 2", "order": 2}, {"src": "assets/catalog/vi/laneige-07/anh-3.webp", "label": "Ảnh 3", "order": 3}, {"src": "assets/catalog/vi/laneige-07/anh-4.webp", "label": "Ảnh 4", "order": 4}, {"src": "assets/catalog/vi/laneige-07/anh-5.webp", "label": "Ảnh 5", "order": 5}, {"src": "assets/catalog/vi/laneige-07/anh-6.webp", "label": "Ảnh 6", "order": 6}, {"src": "assets/catalog/vi/laneige-07/anh-7.webp", "label": "Ảnh 7", "order": 7}]}}, {"id": "laneige-08", "brandId": "laneige", "brand": "Laneige", "name": {"vi": "KEM DƯỠNG MẮT LANEIGE WATER BANK BLUE HYALURONIC EYE CREAM 25ML", "en": "LANEIGE Water Bank Blue Hyaluronic Eye Cream 25ml"}, "category": "Skincare", "type": "Kem dưỡng vùng mắt", "size": "Hũ 25ml", "country": "Hàn Quốc", "description": {"vi": "1. MÔ TẢ SẢN PHẨM\n\nTên sản phẩm: Kem Dưỡng Mắt Laneige Water Bank Blue Hyaluronic Eye Cream 25ml\nThương hiệu: LANEIGE\nQuốc gia thương hiệu: Hàn Quốc\nQuy cách đóng gói: Hũ 25ml\nPhân loại: Kem dưỡng vùng mắt\n\nKem Dưỡng Mắt Laneige Water Bank Blue Hyaluronic Eye Cream 25ml là sản phẩm chăm sóc vùng da quanh mắt, nổi bật với Blue Hyaluronic Acid. Sản phẩm hướng đến việc bổ sung độ ẩm, cải thiện cảm giác khô căng và giúp vùng da mắt trông mềm mịn, tươi tắn hơn.\n\n2. CÔNG DỤNG\n\n• Cấp ẩm cho vùng da quanh mắt.\n• Hỗ trợ giảm cảm giác khô căng.\n• Giúp vùng da mắt mềm mại, mịn màng.\n• Hỗ trợ cải thiện vẻ ngoài của các nếp nhăn nhỏ do thiếu ẩm.\n\n3. THÀNH PHẦN\n\nCác thành phần nổi bật:\n\n• Blue Hyaluronic Acid: Thành phần cấp ẩm đặc trưng của dòng sản phẩm.\n• Các chất giữ ẩm và làm mềm da: Hỗ trợ chăm sóc vùng mắt.\n• Bảng thành phần INCI đầy đủ cần đối chiếu trên bao bì 25ml trước khi đăng thông tin chi tiết.\n\nLưu ý: Đây là các thành phần nổi bật, không thay thế bảng INCI đầy đủ. Thành phần có thể thay đổi theo phiên bản, mã màu hoặc hương.\n\n4. HƯỚNG DẪN SỬ DỤNG\n\n1. Làm sạch da và hoàn thành bước serum.\n2. Lấy lượng kem nhỏ cho cả hai bên mắt.\n3. Chấm nhẹ quanh vùng xương hốc mắt.\n4. Dùng ngón áp út vỗ nhẹ, tránh để kem tiếp xúc trực tiếp với mắt.\n5. Sử dụng sáng và tối.\n\nLưu ý: Chỉ dùng ngoài da. Tránh tiếp xúc trực tiếp với mắt. Ngừng sử dụng nếu có dấu hiệu kích ứng.\n\n5. ĐỐI TƯỢNG SỬ DỤNG\n\n• Người có vùng da quanh mắt khô, thiếu ẩm.\n• Người muốn chăm sóc vùng da mắt hằng ngày.\n• Người quan tâm đến các nếp nhăn nhỏ do khô da.", "en": "1. PRODUCT DESCRIPTION\n\nLANEIGE Water Bank Blue Hyaluronic Eye Cream is a moisturizing treatment developed for the delicate skin around the eyes. Its conditioning cream texture helps replenish moisture and soften the appearance of fine lines associated with dehydration. The formula combines hyaluronic acid derivatives with additional skincare ingredients, including niacinamide and caffeine, to support a smoother and more refreshed-looking eye area. It can be incorporated into both morning and evening skincare routines.\n\n2. BENEFITS\n\n• Moisturizes the delicate eye area.\n• Helps soften the appearance of fine dehydration lines.\n• Supports smoother-looking skin around the eyes.\n• Helps maintain a comfortable, conditioned eye area.\n• Complements daily facial hydration routines.\n\n3. INGREDIENTS\n\nKey ingredients and their functions:\n\n• Sodium Hyaluronate: A moisture-retaining hyaluronic acid derivative.\n• Hydrolyzed Hyaluronic Acid: Supports hydration.\n• Niacinamide: A skin-conditioning ingredient.\n• Caffeine: Used in eye-care formulations to support a refreshed appearance.\n• Glycerin: A humectant that helps attract moisture.\n• Tocopherol: An antioxidant form of vitamin E.\n\nNote: The ingredients above are selected formulation components or product-line information, not a complete INCI declaration. Ingredient lists may vary by formulation, shade, region and production version. Verify the actual packaging before publication.\n\n4. DIRECTIONS FOR USE\n\n1. Cleanse the face and apply toner or serum.\n2. Take a small amount of eye cream.\n3. Dot gently around the orbital bone area.\n4. Pat lightly with a fingertip until absorbed.\n5. Avoid direct contact with the eyes.\n6. Use morning and evening.\n\nPrecautions: For external use only. Discontinue use if irritation occurs. Avoid applying to damaged skin. Keep out of reach of children.\n\n5. SUITABLE FOR\n\n• People with dry or dehydrated skin around the eyes.\n• Individuals concerned about fine dehydration lines.\n• Those seeking daily eye-area moisturization.\n• People looking for a dedicated eye cream."}, "image": "assets/catalog/product-laneige-08.webp", "gallery": {"vi": [{"src": "assets/catalog/vi/laneige-08/thumbnail.webp", "label": "Thumbnail", "order": 0}, {"src": "assets/catalog/vi/laneige-08/anh-1.webp", "label": "Ảnh 1", "order": 1}, {"src": "assets/catalog/vi/laneige-08/anh-2.webp", "label": "Ảnh 2", "order": 2}, {"src": "assets/catalog/vi/laneige-08/anh-3.webp", "label": "Ảnh 3", "order": 3}, {"src": "assets/catalog/vi/laneige-08/anh-4.webp", "label": "Ảnh 4", "order": 4}, {"src": "assets/catalog/vi/laneige-08/anh-5.webp", "label": "Ảnh 5", "order": 5}, {"src": "assets/catalog/vi/laneige-08/anh-6.webp", "label": "Ảnh 6", "order": 6}, {"src": "assets/catalog/vi/laneige-08/anh-7.webp", "label": "Ảnh 7", "order": 7}]}}, {"id": "laneige-09", "brandId": "laneige", "brand": "Laneige", "name": {"vi": "MẶT NẠ NGỦ LANEIGE WATER SLEEPING MASK 70ML", "en": "LANEIGE Water Sleeping Mask 70ml"}, "category": "Skincare", "type": "Mặt nạ ngủ dưỡng ẩm da mặt", "size": "Hũ 70ml", "country": "Hàn Quốc", "description": {"vi": "1. MÔ TẢ SẢN PHẨM\n\nTên sản phẩm: Mặt Nạ Ngủ Laneige Water Sleeping Mask 70ml\nThương hiệu: LANEIGE\nQuốc gia thương hiệu: Hàn Quốc\nQuy cách đóng gói: Hũ 70ml\nPhân loại: Mặt nạ ngủ dưỡng ẩm da mặt\n\nMặt Nạ Ngủ Laneige Water Sleeping Mask 70ml là sản phẩm dưỡng ẩm sử dụng ở bước cuối của quy trình chăm sóc da buổi tối. Kết cấu gel nhẹ giúp bổ sung độ ẩm, mang lại cảm giác mềm mịn và tươi tắn cho làn da vào sáng hôm sau. Dòng sản phẩm được Laneige giới thiệu với công nghệ chăm sóc da ban đêm và các thành phần dưỡng ẩm.\n\n2. CÔNG DỤNG\n\n• Bổ sung độ ẩm trong thời gian ngủ.\n• Hỗ trợ giảm cảm giác khô căng.\n• Giúp da mềm mại, mịn màng hơn vào sáng hôm sau.\n• Mang lại cảm giác thư giãn khi chăm sóc da buổi tối.\n\n3. THÀNH PHẦN\n\nCác thành phần nổi bật:\n\n• Squalane: Thành phần làm mềm và hỗ trợ giữ ẩm.\n• Các thành phần có nguồn gốc từ quá trình lên men: Được giới thiệu trong công nghệ chăm sóc da ban đêm của dòng sản phẩm.\n• Các chất cấp ẩm và tạo kết cấu gel: Theo bảng thành phần trên bao bì phiên bản 70ml.\n\nLưu ý: Đây là các thành phần nổi bật, không thay thế bảng INCI đầy đủ. Thành phần có thể thay đổi theo phiên bản, mã màu hoặc hương.\n\n4. HƯỚNG DẪN SỬ DỤNG\n\n1. Làm sạch da và sử dụng các bước dưỡng thông thường.\n2. Lấy lượng mặt nạ vừa đủ ở bước cuối cùng buổi tối.\n3. Thoa đều lên mặt, tránh mắt và môi.\n4. Để sản phẩm trên da qua đêm.\n5. Rửa mặt nhẹ nhàng vào sáng hôm sau.\n\nLưu ý: Chỉ dùng ngoài da. Tránh tiếp xúc trực tiếp với mắt. Ngừng sử dụng nếu có dấu hiệu kích ứng.\n\n5. ĐỐI TƯỢNG SỬ DỤNG\n\n• Người có da thiếu ẩm, khô căng.\n• Người muốn tăng cường dưỡng ẩm ban đêm.\n• Người thích mặt nạ ngủ dạng gel.", "en": "1. PRODUCT DESCRIPTION\n\nLANEIGE Water Sleeping Mask is an overnight facial treatment designed to replenish moisture and help skin look refreshed by morning. Its smooth gel-like texture is intended to be applied as the final step of an evening skincare routine, forming a comfortable hydrating layer while the skin rests. The mask helps improve the appearance of dryness and dullness, leaving the complexion feeling softer and smoother after overnight use. The exact formulation should be matched to the specific 70ml version because the Water Sleeping Mask line has undergone updates.\n\n2. BENEFITS\n\n• Provides overnight moisturizing care.\n• Helps reduce the appearance of dryness and dullness.\n• Leaves the skin feeling softer and smoother.\n• Supports a refreshed-looking complexion in the morning.\n• Adds an intensive hydration step to the evening routine.\n\n3. INGREDIENTS\n\nKey ingredients and their functions:\n\n• Hydrating Ingredients: Help attract and retain moisture overnight.\n• Emollient Ingredients: Support softness and comfort.\n• Skin-Conditioning Ingredients: Contribute to the mask's cosmetic benefits.\n• Important: The specific active ingredients and INCI must be checked against the 70ml packaging; different Water Sleeping Mask generations may have different formulas.\n\nNote: The ingredients above are selected formulation components or product-line information, not a complete INCI declaration. Ingredient lists may vary by formulation, shade, region and production version. Verify the actual packaging before publication.\n\n4. DIRECTIONS FOR USE\n\n1. Complete the evening cleansing and skincare routine.\n2. Apply a suitable layer of the mask as the final step.\n3. Spread evenly across the face, avoiding the eyes and lips.\n4. Leave on overnight according to the product instructions.\n5. Rinse or cleanse the face in the morning.\n6. Use at the frequency recommended on the product label.\n\nPrecautions: For external use only. Discontinue use if irritation occurs. Avoid applying to damaged skin. Keep out of reach of children.\n\n5. SUITABLE FOR\n\n• Dry or dehydrated skin.\n• People concerned about dull-looking skin.\n• Individuals wanting an overnight hydration treatment.\n• Those seeking a convenient sleeping mask."}, "image": "assets/catalog/product-laneige-09.webp", "gallery": {"vi": [{"src": "assets/catalog/vi/laneige-09/thumbnail.webp", "label": "Thumbnail", "order": 0}, {"src": "assets/catalog/vi/laneige-09/anh-1.webp", "label": "Ảnh 1", "order": 1}, {"src": "assets/catalog/vi/laneige-09/anh-2.webp", "label": "Ảnh 2", "order": 2}, {"src": "assets/catalog/vi/laneige-09/anh-3.webp", "label": "Ảnh 3", "order": 3}, {"src": "assets/catalog/vi/laneige-09/anh-4.webp", "label": "Ảnh 4", "order": 4}, {"src": "assets/catalog/vi/laneige-09/anh-5.webp", "label": "Ảnh 5", "order": 5}, {"src": "assets/catalog/vi/laneige-09/anh-6.webp", "label": "Ảnh 6", "order": 6}, {"src": "assets/catalog/vi/laneige-09/anh-7.webp", "label": "Ảnh 7", "order": 7}]}}, {"id": "laneige-10", "brandId": "laneige", "brand": "Laneige", "name": {"vi": "PHẤN NƯỚC LANEIGE NEO CUSHION MATTE 15G", "en": "LANEIGE NEO Cushion Matte 15g"}, "category": "Makeup", "type": "Phấn nước trang điểm mịn lì", "size": "Hộp 15g", "country": "Hàn Quốc", "description": {"vi": "1. MÔ TẢ SẢN PHẨM\n\nTên sản phẩm: Phấn Nước Laneige Neo Cushion Matte 15g\nThương hiệu: LANEIGE\nQuốc gia thương hiệu: Hàn Quốc\nQuy cách đóng gói: Hộp 15g\nPhân loại: Phấn nước trang điểm mịn lì\n\nPhấn Nước Laneige Neo Cushion Matte 15g là sản phẩm trang điểm nền kết hợp khả năng che phủ và chăm sóc da. Công thức tạo hiệu ứng mịn lì, mỏng nhẹ và hỗ trợ duy trì lớp nền đều màu. Thiết kế hộp phấn kèm bông dặm tiện lợi, phù hợp sử dụng tại nhà hoặc dặm lại trong ngày.\n\n2. CÔNG DỤNG\n\n• Tạo lớp nền đều màu, mịn lì.\n• Hỗ trợ che phủ khuyết điểm trên da.\n• Giúp da trông mịn màng, tự nhiên.\n• Thuận tiện khi trang điểm và dặm lại.\n• Có nhiều tông màu phù hợp sắc độ da khác nhau.\n\n3. THÀNH PHẦN\n\nCác thành phần nổi bật:\n\n• Hyaluronic Acid: Thành phần hỗ trợ cấp ẩm.\n• Panthenol: Thành phần chăm sóc da.\n• Các sắc tố màu: Tạo màu nền theo mã sản phẩm.\n• Các chất tạo màng và làm mượt: Hỗ trợ độ bám của lớp nền.\n• Thành phần chi tiết thay đổi theo mã màu, cần đối chiếu bảng INCI tương ứng.\n\nLưu ý: Đây là các thành phần nổi bật, không thay thế bảng INCI đầy đủ. Thành phần có thể thay đổi theo phiên bản, mã màu hoặc hương.\n\n4. HƯỚNG DẪN SỬ DỤNG\n\n1. Làm sạch, dưỡng ẩm và chống nắng trước khi trang điểm.\n2. Dùng bông phấn lấy lượng cushion vừa đủ.\n3. Dặm nhẹ từ giữa mặt ra ngoài.\n4. Tán thêm một lớp mỏng ở vùng cần che phủ.\n5. Đóng nắp kín sau khi sử dụng.\n\nLưu ý: Chỉ dùng ngoài da. Tránh tiếp xúc trực tiếp với mắt. Ngừng sử dụng nếu có dấu hiệu kích ứng.\n\n5. ĐỐI TƯỢNG SỬ DỤNG\n\n• Người muốn lớp nền mịn lì.\n• Người có da thường, hỗn hợp hoặc da dầu.\n• Người cần sản phẩm nền tiện dụng hằng ngày.", "en": "1. PRODUCT DESCRIPTION\n\nLANEIGE NEO Cushion Matte is a compact cushion foundation developed to create a smooth, even-looking complexion with a soft matte finish. The cushion format allows controlled application and convenient touch-ups throughout the day. Its foundation formula helps visually conceal uneven skin tone, redness and minor imperfections while creating a polished makeup look. Coverage, color match and additional features may vary by product generation and shade. The exact shade code should be confirmed before publication.\n\n2. BENEFITS\n\n• Helps even out the appearance of skin tone.\n• Provides cosmetic coverage for minor imperfections.\n• Creates a soft matte makeup finish.\n• Allows convenient application and touch-ups.\n• Offers a portable foundation format.\n\n3. INGREDIENTS\n\nKey ingredients and their functions:\n\n• Pigments: Provide foundation color and cosmetic coverage.\n• Silicone-Based Ingredients: Commonly support smooth application and texture.\n• Film-Forming Ingredients: Help foundation adhere to the skin.\n• Conditioning Ingredients: May support a comfortable finish.\n• UV Filters: Some NEO Cushion Matte versions include SPF protection; verify the exact SPF and PA rating on the packaging before making a claim.\n• Colorants and the complete INCI vary by shade and formulation.\n\nNote: The ingredients above are selected formulation components or product-line information, not a complete INCI declaration. Ingredient lists may vary by formulation, shade, region and production version. Verify the actual packaging before publication.\n\n4. DIRECTIONS FOR USE\n\n1. Complete skincare and apply sunscreen before makeup.\n2. Open the compact and press the puff gently onto the cushion.\n3. Pat a thin layer onto the face, starting from the center.\n4. Build coverage gradually where needed.\n5. Blend along the jawline and hairline.\n6. Close the compact securely and clean or replace the puff regularly.\n\nPrecautions: For external use only. Discontinue use if irritation occurs. Avoid applying to damaged skin. Keep out of reach of children.\n\n5. SUITABLE FOR\n\n• People seeking a matte foundation finish.\n• Individuals wanting more even-looking skin tone.\n• Those who prefer cushion makeup for portability.\n• People who need convenient makeup touch-ups."}, "image": "assets/catalog/product-laneige-10.webp", "gallery": {"vi": [{"src": "assets/catalog/vi/laneige-10/thumbnail.webp", "label": "Thumbnail", "order": 0}, {"src": "assets/catalog/vi/laneige-10/anh-1.webp", "label": "Ảnh 1", "order": 1}, {"src": "assets/catalog/vi/laneige-10/anh-2.webp", "label": "Ảnh 2", "order": 2}, {"src": "assets/catalog/vi/laneige-10/anh-3.webp", "label": "Ảnh 3", "order": 3}, {"src": "assets/catalog/vi/laneige-10/anh-4.webp", "label": "Ảnh 4", "order": 4}, {"src": "assets/catalog/vi/laneige-10/anh-5.webp", "label": "Ảnh 5", "order": 5}, {"src": "assets/catalog/vi/laneige-10/anh-6.webp", "label": "Ảnh 6", "order": 6}, {"src": "assets/catalog/vi/laneige-10/anh-7.webp", "label": "Ảnh 7", "order": 7}]}}, {"id": "maybelline-01", "brandId": "maybelline", "brand": "Maybelline", "name": {"vi": "KEM NỀN MAYBELLINE FIT ME MATTE + PORELESS FOUNDATION 30ML", "en": "Maybelline Fit Me Matte + Poreless Foundation 30ml"}, "category": "Makeup", "type": "Kem nền dạng lỏng", "size": "30ml", "country": "Hoa Kỳ", "description": {"vi": "1. MÔ TẢ SẢN PHẨM\n\nTên sản phẩm: Kem Nền Maybelline Fit Me Matte + Poreless Foundation 30ml\nThương hiệu: Maybelline New York\nQuốc gia thương hiệu: Hoa Kỳ\nQuy cách đóng gói: 30ml\nPhân loại: Kem nền dạng lỏng\n\nKem Nền Maybelline Fit Me Matte + Poreless Foundation 30ml là sản phẩm trang điểm nền có kết cấu lỏng, mỏng nhẹ, hướng đến làn da thường đến da dầu. Công thức sử dụng các hạt phấn siêu nhỏ để hỗ trợ kiểm soát bóng nhờn, tạo hiệu ứng mịn lì và làm mờ sự hiện diện của lỗ chân lông. Sản phẩm có nhiều tông màu để lựa chọn theo sắc độ da.\n\n2. CÔNG DỤNG\n\n• Tạo lớp nền đều màu và tự nhiên.\n• Hỗ trợ che phủ khuyết điểm nhẹ đến vừa.\n• Giảm vẻ bóng nhờn, tạo hiệu ứng mịn lì.\n• Giúp bề mặt da trông mịn màng hơn.\n\n3. THÀNH PHẦN\n\nCác thành phần nổi bật:\n\n• Nylon-12: Hỗ trợ tạo hiệu ứng mịn trên bề mặt da.\n• Silica: Hỗ trợ hấp thụ dầu thừa.\n• Cyclohexasiloxane và Cyclopentasiloxane: Giúp sản phẩm dễ tán.\n• Tocopherol: Thành phần chống oxy hóa.\n• Iron Oxides và Titanium Dioxide: Chất tạo màu, tùy phiên bản.\n\nLưu ý: Danh sách trên không thay thế bảng thành phần INCI đầy đủ. Công thức và sắc tố màu có thể khác nhau giữa các phiên bản.\n\n4. HƯỚNG DẪN SỬ DỤNG\n\n1. Làm sạch, dưỡng ẩm và sử dụng chống nắng phù hợp.\n2. Lấy lượng kem nền vừa đủ lên mặt.\n3. Dùng mút, cọ hoặc đầu ngón tay tán đều từ giữa mặt ra ngoài.\n4. Tăng thêm một lớp mỏng ở vùng cần che phủ.\n\nLưu ý: Chỉ dùng ngoài da. Ngừng sử dụng nếu có kích ứng. Không dùng chung sản phẩm trang điểm mắt để hạn chế nguy cơ nhiễm khuẩn.\n\n5. ĐỐI TƯỢNG SỬ DỤNG\n\n• Người có da thường, da hỗn hợp hoặc da dầu.\n• Người muốn lớp nền mịn lì, tự nhiên.\n• Người cần trang điểm hằng ngày.", "en": "1. PRODUCT DESCRIPTION\n\nMaybelline Fit Me Matte + Poreless Foundation is a lightweight liquid foundation designed to create a natural-looking matte complexion. Developed especially for normal to oily skin, the formula helps control the appearance of shine while visually minimizing the look of pores. Its blendable texture provides buildable coverage that helps even out skin tone without creating an excessively heavy makeup finish. The foundation is suitable for everyday makeup and can be layered to achieve the desired level of coverage.\n\n2. BENEFITS\n\n• Helps even out the appearance of skin tone.\n• Provides a natural-looking matte finish.\n• Helps control the appearance of excess shine.\n• Visually minimizes the appearance of pores.\n• Offers buildable coverage with a lightweight feel.\n• Blends smoothly for everyday makeup application.\n\n3. INGREDIENTS\n\nKey ingredients and their functions:\n\n• Dimethicone: A silicone-based ingredient that helps create a smooth makeup finish.\n• Cyclohexasiloxane: A volatile silicone that supports lightweight application.\n• Silica: A mineral powder commonly used to absorb excess oil.\n• Glycerin: A humectant that supports moisture retention.\n• Pigments, including Iron Oxides and Titanium Dioxide: Provide foundation color and coverage; composition varies by shade.\n\nNote: The ingredients listed above are selected or representative formulation components, not a verified complete INCI list. Exact ingredients may vary by shade, market and product version. Confirm against the actual product packaging before publication.\n\n4. DIRECTIONS FOR USE\n\n1. Cleanse and moisturize the face.\n2. Apply sunscreen before makeup during the day.\n3. Dispense a small amount of foundation onto the back of the hand.\n4. Apply to the face using fingertips, a makeup sponge or a foundation brush.\n5. Blend evenly from the center of the face outward.\n6. Build coverage gradually where needed and set with powder if desired.\n\nPrecautions: For external use only. Discontinue use if irritation occurs. Avoid direct contact with the eyes unless the product is specifically intended for the eye area. Keep out of reach of children.\n\n5. SUITABLE FOR\n\n• Normal to oily skin.\n• People seeking a matte foundation finish.\n• Individuals concerned about visible pores and excess shine.\n• Those looking for buildable everyday foundation coverage."}, "image": "assets/catalog/product-maybelline-01.jpg", "gallery": {"vi": [{"src": "assets/catalog/vi/maybelline-01/thumbnail.webp", "label": "Thumbnail", "order": 0}, {"src": "assets/catalog/vi/maybelline-01/anh-1.webp", "label": "Ảnh 1", "order": 1}, {"src": "assets/catalog/vi/maybelline-01/anh-2.webp", "label": "Ảnh 2", "order": 2}, {"src": "assets/catalog/vi/maybelline-01/anh-3.webp", "label": "Ảnh 3", "order": 3}, {"src": "assets/catalog/vi/maybelline-01/anh-4.webp", "label": "Ảnh 4", "order": 4}, {"src": "assets/catalog/vi/maybelline-01/anh-5.webp", "label": "Ảnh 5", "order": 5}, {"src": "assets/catalog/vi/maybelline-01/anh-6.webp", "label": "Ảnh 6", "order": 6}, {"src": "assets/catalog/vi/maybelline-01/anh-7.webp", "label": "Ảnh 7", "order": 7}]}}, {"id": "maybelline-02", "brandId": "maybelline", "brand": "Maybelline", "name": {"vi": "KEM CHE KHUYẾT ĐIỂM MAYBELLINE FIT ME CONCEALER 6,8ML", "en": "Maybelline Fit Me Concealer 6.8ml"}, "category": "Skincare", "type": "Kem che khuyết điểm dạng lỏng", "size": "6,8ml", "country": "Hoa Kỳ", "description": {"vi": "1. MÔ TẢ SẢN PHẨM\n\nTên sản phẩm: Kem Che Khuyết Điểm Maybelline Fit Me Concealer 6,8ml\nThương hiệu: Maybelline New York\nQuốc gia thương hiệu: Hoa Kỳ\nQuy cách đóng gói: 6,8ml\nPhân loại: Kem che khuyết điểm dạng lỏng\n\nKem Che Khuyết Điểm Maybelline Fit Me Concealer 6,8ml là sản phẩm trang điểm dạng lỏng, giúp che phủ quầng thâm, vùng da không đều màu và các khuyết điểm nhỏ. Công thức không chứa dầu được Maybelline giới thiệu với khả năng tạo lớp che phủ tự nhiên, dễ tán và phù hợp nhiều tông da.\n\n2. CÔNG DỤNG\n\n• Hỗ trợ che phủ quầng thâm dưới mắt.\n• Làm đều màu vùng da có khuyết điểm.\n• Giúp lớp trang điểm trông tự nhiên.\n• Dễ sử dụng để che phủ từng vùng nhỏ.\n\n3. THÀNH PHẦN\n\nCác thành phần nổi bật:\n\n• Glycerin: Thành phần giữ ẩm.\n• Cyclopentasiloxane: Giúp kem dễ tán.\n• Hydrogenated Polyisobutene: Thành phần làm mềm.\n• Tocopherol: Thành phần chống oxy hóa.\n• Iron Oxides và Titanium Dioxide: Các chất tạo màu tùy tông.\n\nLưu ý: Danh sách trên không thay thế bảng thành phần INCI đầy đủ. Công thức và sắc tố màu có thể khác nhau giữa các phiên bản.\n\n4. HƯỚNG DẪN SỬ DỤNG\n\n1. Chọn màu kem phù hợp với tông da.\n2. Chấm một lượng nhỏ lên vùng cần che phủ.\n3. Dùng ngón tay, mút hoặc cọ tán nhẹ.\n4. Phủ phấn nếu muốn cố định lớp trang điểm.\n\nLưu ý: Chỉ dùng ngoài da. Ngừng sử dụng nếu có kích ứng. Không dùng chung sản phẩm trang điểm mắt để hạn chế nguy cơ nhiễm khuẩn.\n\n5. ĐỐI TƯỢNG SỬ DỤNG\n\n• Người muốn che quầng thâm và vùng da không đều màu.\n• Người thích lớp che phủ tự nhiên.\n• Người cần sản phẩm che khuyết điểm sử dụng hằng ngày.", "en": "1. PRODUCT DESCRIPTION\n\nMaybelline Fit Me Concealer is a lightweight liquid concealer developed to help cover the appearance of dark circles, blemishes, redness and uneven skin tone. Its smooth texture blends easily into the skin, creating a natural-looking finish without the appearance of heavy makeup. The applicator allows precise placement on targeted areas, making the product suitable for both everyday makeup and additional coverage when needed.\n\n2. BENEFITS\n\n• Helps conceal the appearance of dark circles.\n• Visually reduces the appearance of blemishes and redness.\n• Helps create a more even-looking complexion.\n• Offers lightweight, blendable coverage.\n• Allows targeted application to small areas.\n• Can be used alone or with foundation.\n\n3. INGREDIENTS\n\nKey ingredients and their functions:\n\n• Water: A primary base of the liquid formula.\n• Cyclopentasiloxane: A silicone that supports smooth application.\n• Glycerin: A moisturizing humectant.\n• Dimethicone: Helps create a soft and even finish.\n• Iron Oxides: Pigments that provide color and coverage.\n• Titanium Dioxide: A white pigment used in cosmetic formulas; its presence does not establish an SPF rating.\n\nNote: The ingredients listed above are selected or representative formulation components, not a verified complete INCI list. Exact ingredients may vary by shade, market and product version. Confirm against the actual product packaging before publication.\n\n4. DIRECTIONS FOR USE\n\n1. Complete the skincare routine and apply foundation if desired.\n2. Use the applicator to place small dots on areas requiring coverage.\n3. Gently blend using fingertips, a sponge or a concealer brush.\n4. Apply additional thin layers for greater coverage.\n5. Set with a light dusting of powder if needed.\n\nPrecautions: For external use only. Discontinue use if irritation occurs. Avoid direct contact with the eyes unless the product is specifically intended for the eye area. Keep out of reach of children.\n\n5. SUITABLE FOR\n\n• People concerned about visible dark circles.\n• Individuals seeking to conceal blemishes or redness.\n• Those who prefer natural-looking concealer.\n• People wanting targeted coverage without heavy makeup."}, "image": "assets/catalog/product-maybelline-02.jpg", "gallery": {"vi": [{"src": "assets/catalog/vi/maybelline-02/thumbnail.webp", "label": "Thumbnail", "order": 0}, {"src": "assets/catalog/vi/maybelline-02/anh-1.webp", "label": "Ảnh 1", "order": 1}, {"src": "assets/catalog/vi/maybelline-02/anh-2.webp", "label": "Ảnh 2", "order": 2}, {"src": "assets/catalog/vi/maybelline-02/anh-3.webp", "label": "Ảnh 3", "order": 3}, {"src": "assets/catalog/vi/maybelline-02/anh-4.webp", "label": "Ảnh 4", "order": 4}, {"src": "assets/catalog/vi/maybelline-02/anh-5.webp", "label": "Ảnh 5", "order": 5}, {"src": "assets/catalog/vi/maybelline-02/anh-6.webp", "label": "Ảnh 6", "order": 6}, {"src": "assets/catalog/vi/maybelline-02/anh-7.webp", "label": "Ảnh 7", "order": 7}]}}, {"id": "maybelline-03", "brandId": "maybelline", "brand": "Maybelline", "name": {"vi": "PHẤN NỀN MAYBELLINE FIT ME MATTE + PORELESS POWDER 8,5G", "en": "Maybelline Fit Me Matte + Poreless Powder 8.5g"}, "category": "Makeup", "type": "Phấn nền dạng nén", "size": "8,5g", "country": "Hoa Kỳ", "description": {"vi": "1. MÔ TẢ SẢN PHẨM\n\nTên sản phẩm: Phấn Nền Maybelline Fit Me Matte + Poreless Powder 8,5g\nThương hiệu: Maybelline New York\nQuốc gia thương hiệu: Hoa Kỳ\nQuy cách đóng gói: 8,5g\nPhân loại: Phấn nền dạng nén\n\nPhấn Nền Maybelline Fit Me Matte + Poreless Powder 8,5g là sản phẩm trang điểm dạng nén có kết cấu hạt phấn mịn, giúp làm đều màu da và tạo hiệu ứng mịn lì. Sản phẩm phù hợp sử dụng riêng hoặc kết hợp với kem nền để hoàn thiện lớp trang điểm, đặc biệt khi muốn hạn chế bóng dầu.\n\n2. CÔNG DỤNG\n\n• Hỗ trợ kiểm soát bóng dầu.\n• Tạo hiệu ứng bề mặt da mịn lì.\n• Làm đều màu và hỗ trợ che phủ nhẹ.\n• Giúp hoàn thiện và dặm lại lớp trang điểm.\n\n3. THÀNH PHẦN\n\nCác thành phần nổi bật:\n\n• Talc: Thành phần nền tạo kết cấu phấn.\n• Perlite: Khoáng chất hỗ trợ hấp thụ dầu.\n• Triisostearin: Thành phần tạo độ kết dính.\n• Phenyl Trimethicone: Hỗ trợ cảm giác mượt.\n• Magnesium Stearate: Hỗ trợ độ bám của phấn.\n• Iron Oxides: Chất tạo màu tùy tông.\n\nLưu ý: Danh sách trên không thay thế bảng thành phần INCI đầy đủ. Công thức và sắc tố màu có thể khác nhau giữa các phiên bản.\n\n4. HƯỚNG DẪN SỬ DỤNG\n\n1. Dùng bông phấn hoặc cọ lấy lượng phấn vừa đủ.\n2. Tán đều trên trán, mũi, má và cằm.\n3. Tập trung vào vùng dễ bóng dầu.\n4. Có thể dùng riêng hoặc sau kem nền.\n\nLưu ý: Chỉ dùng ngoài da. Ngừng sử dụng nếu có kích ứng. Không dùng chung sản phẩm trang điểm mắt để hạn chế nguy cơ nhiễm khuẩn.\n\n5. ĐỐI TƯỢNG SỬ DỤNG\n\n• Người có da thường, hỗn hợp thiên dầu hoặc da dầu.\n• Người thích hiệu ứng trang điểm mịn lì.\n• Người cần phấn dặm lại trong ngày.", "en": "1. PRODUCT DESCRIPTION\n\nMaybelline Fit Me Matte + Poreless Powder is a pressed face powder designed to help create a smooth, shine-controlled makeup finish. The lightweight powder helps absorb excess surface oil and visually soften the appearance of pores while providing a natural-looking matte effect. It can be applied alone for a light complexion-enhancing finish or layered over liquid foundation to help set makeup. Its compact format makes it convenient for touch-ups throughout the day.\n\n2. BENEFITS\n\n• Helps absorb excess surface oil.\n• Provides a smooth, matte-looking finish.\n• Visually softens the appearance of pores.\n• Helps set liquid foundation and concealer.\n• Offers convenient makeup touch-ups.\n• Supports a more even-looking complexion.\n\n3. INGREDIENTS\n\nKey ingredients and their functions:\n\n• Talc: A mineral powder used to improve texture and absorb oil.\n• Perlite: A mineral-derived ingredient that helps absorb excess oil.\n• Silica: Helps provide a smooth, matte finish.\n• Dimethicone: A skin-conditioning silicone.\n• Iron Oxides: Color pigments that vary by shade.\n• Titanium Dioxide: A cosmetic pigment; does not independently indicate sunscreen protection.\n\nNote: The ingredients listed above are selected or representative formulation components, not a verified complete INCI list. Exact ingredients may vary by shade, market and product version. Confirm against the actual product packaging before publication.\n\n4. DIRECTIONS FOR USE\n\n1. Complete skincare and apply foundation or concealer if desired.\n2. Pick up a small amount of powder using a puff or makeup brush.\n3. Apply gently to the forehead, nose, chin and other areas prone to shine.\n4. Blend evenly to avoid visible powder buildup.\n5. Reapply lightly as needed throughout the day.\n\nPrecautions: For external use only. Discontinue use if irritation occurs. Avoid direct contact with the eyes unless the product is specifically intended for the eye area. Keep out of reach of children.\n\n5. SUITABLE FOR\n\n• Normal to oily skin.\n• People concerned about facial shine.\n• Individuals seeking a matte powder finish.\n• Those looking for a convenient pressed powder."}, "image": "assets/catalog/product-maybelline-03.jpg", "gallery": {"vi": [{"src": "assets/catalog/vi/maybelline-03/thumbnail.webp", "label": "Thumbnail", "order": 0}, {"src": "assets/catalog/vi/maybelline-03/anh-1.webp", "label": "Ảnh 1", "order": 1}, {"src": "assets/catalog/vi/maybelline-03/anh-2.webp", "label": "Ảnh 2", "order": 2}, {"src": "assets/catalog/vi/maybelline-03/anh-3.webp", "label": "Ảnh 3", "order": 3}, {"src": "assets/catalog/vi/maybelline-03/anh-4.webp", "label": "Ảnh 4", "order": 4}, {"src": "assets/catalog/vi/maybelline-03/anh-5.webp", "label": "Ảnh 5", "order": 5}, {"src": "assets/catalog/vi/maybelline-03/anh-6.webp", "label": "Ảnh 6", "order": 6}, {"src": "assets/catalog/vi/maybelline-03/anh-7.webp", "label": "Ảnh 7", "order": 7}]}}, {"id": "maybelline-04", "brandId": "maybelline", "brand": "Maybelline", "name": {"vi": "MASCARA MAYBELLINE HYPER CURL WATERPROOF 9,2ML", "en": "Maybelline Hyper Curl Waterproof Mascara 9.2ml"}, "category": "Makeup", "type": "Mascara chống nước", "size": "9,2ml", "country": "Hoa Kỳ", "description": {"vi": "1. MÔ TẢ SẢN PHẨM\n\nTên sản phẩm: Mascara Maybelline Hyper Curl Waterproof 9,2ml\nThương hiệu: Maybelline New York\nQuốc gia thương hiệu: Hoa Kỳ\nQuy cách đóng gói: 9,2ml\nPhân loại: Mascara chống nước\n\nMascara Maybelline Hyper Curl Waterproof 9,2ml là sản phẩm trang điểm mắt giúp tạo hiệu ứng mi dày và cong. Đầu cọ được thiết kế để tiếp cận sợi mi từ chân đến ngọn, hỗ trợ chuốt đều và giữ dáng mi. Theo thông tin thương hiệu, sản phẩm hướng đến hiệu ứng cong mi và độ bền màu kéo dài.\n\n2. CÔNG DỤNG\n\n• Tạo hiệu ứng lông mi dày hơn.\n• Giúp hàng mi trông cong và nổi bật.\n• Hỗ trợ giữ dáng mi khi trang điểm.\n• Công thức chống nước, hạn chế lem trôi.\n\n3. THÀNH PHẦN\n\nCác thành phần nổi bật:\n\n• Công thức gồm hệ sáp, chất tạo màng và sắc tố màu giúp mascara bám trên sợi mi.\n• Thành phần INCI chi tiết của phiên bản 9,2ml cần đối chiếu trên bao bì; không mặc định công thức giống các dòng mascara khác.\n\nLưu ý: Danh sách trên không thay thế bảng thành phần INCI đầy đủ. Công thức và sắc tố màu có thể khác nhau giữa các phiên bản.\n\n4. HƯỚNG DẪN SỬ DỤNG\n\n1. Mở nắp và lấy cọ ra khỏi thân sản phẩm.\n2. Gạt bớt mascara thừa nếu cần.\n3. Đặt cọ gần chân mi, chải theo đường zigzag lên ngọn.\n4. Lặp lại đến khi đạt độ dày và cong mong muốn.\n5. Sử dụng sản phẩm tẩy trang mắt phù hợp để làm sạch.\n\nLưu ý: Chỉ dùng ngoài da. Ngừng sử dụng nếu có kích ứng. Không dùng chung sản phẩm trang điểm mắt để hạn chế nguy cơ nhiễm khuẩn.\n\n5. ĐỐI TƯỢNG SỬ DỤNG\n\n• Người có mi ngắn, mỏng hoặc thưa.\n• Người muốn tạo hiệu ứng mi cong, dày.\n• Người cần mascara chống nước.", "en": "1. PRODUCT DESCRIPTION\n\nMaybelline Hyper Curl Waterproof Mascara is an eye makeup product designed to enhance the appearance of curled, defined lashes. Its mascara formula coats the lashes to create a darker, more noticeable look while the curved brush helps lift and shape them during application. The waterproof formulation is intended to improve resistance to moisture during normal daily activities. It is suitable for people who want a curled lash appearance without using false eyelashes.\n\n2. BENEFITS\n\n• Enhances the appearance of curled lashes.\n• Helps lift and define eyelashes.\n• Provides a darker, more noticeable lash look.\n• Offers a waterproof makeup finish.\n• Helps separate and coat lashes during application.\n• Suitable for everyday eye makeup.\n\n3. INGREDIENTS\n\nKey ingredients and their functions:\n\n• Film-Forming Polymers: Help mascara adhere to lashes.\n• Waxes: Support mascara texture and lash shaping.\n• Iron Oxides: Provide dark pigment.\n• Emollient Ingredients: Help distribute the formula over lashes.\n• The complete waterproof formula should be checked against the current packaging.\n\nNote: The ingredients listed above are selected or representative formulation components, not a verified complete INCI list. Exact ingredients may vary by shade, market and product version. Confirm against the actual product packaging before publication.\n\n4. DIRECTIONS FOR USE\n\n1. Begin with clean, dry eyelashes.\n2. Position the curved mascara brush at the base of the upper lashes.\n3. Sweep upward from roots to tips with a gentle curling motion.\n4. Apply another thin coat if additional definition is desired.\n5. Allow the mascara to dry before touching the lashes.\n6. Remove gently using a suitable waterproof eye makeup remover.\n\nPrecautions: For external use only. Discontinue use if irritation occurs. Avoid direct contact with the eyes unless the product is specifically intended for the eye area. Keep out of reach of children.\n\n5. SUITABLE FOR\n\n• People seeking curled and defined eyelashes.\n• Individuals who prefer waterproof mascara.\n• Those looking for everyday lash enhancement.\n• People wanting a mascara with a curved applicator."}, "image": "assets/catalog/product-maybelline-04.jpg", "gallery": {"vi": [{"src": "assets/catalog/vi/maybelline-04/thumbnail.webp", "label": "Thumbnail", "order": 0}, {"src": "assets/catalog/vi/maybelline-04/anh-1.webp", "label": "Ảnh 1", "order": 1}, {"src": "assets/catalog/vi/maybelline-04/anh-2.webp", "label": "Ảnh 2", "order": 2}, {"src": "assets/catalog/vi/maybelline-04/anh-3.webp", "label": "Ảnh 3", "order": 3}, {"src": "assets/catalog/vi/maybelline-04/anh-4.webp", "label": "Ảnh 4", "order": 4}, {"src": "assets/catalog/vi/maybelline-04/anh-5.webp", "label": "Ảnh 5", "order": 5}, {"src": "assets/catalog/vi/maybelline-04/anh-6.webp", "label": "Ảnh 6", "order": 6}, {"src": "assets/catalog/vi/maybelline-04/anh-7.webp", "label": "Ảnh 7", "order": 7}]}}, {"id": "maybelline-05", "brandId": "maybelline", "brand": "Maybelline", "name": {"vi": "MASCARA MAYBELLINE LASH SENSATIONAL SKY HIGH WATERPROOF 6ML", "en": "Maybelline Lash Sensational Sky High Waterproof Mascara 6ml"}, "category": "Makeup", "type": "Mascara làm dài mi chống nước", "size": "6ml", "country": "Hoa Kỳ", "description": {"vi": "1. MÔ TẢ SẢN PHẨM\n\nTên sản phẩm: Mascara Maybelline Lash Sensational Sky High Waterproof 6ml\nThương hiệu: Maybelline New York\nQuốc gia thương hiệu: Hoa Kỳ\nQuy cách đóng gói: 6ml\nPhân loại: Mascara làm dài mi chống nước\n\nMascara Maybelline Lash Sensational Sky High Waterproof 6ml là sản phẩm trang điểm mắt giúp tạo hiệu ứng hàng mi dài, tơi và dày. Đầu cọ Flex Tower linh hoạt hỗ trợ chải từng sợi mi từ chân đến ngọn. Công thức được hãng giới thiệu với chiết xuất tre và các thành phần tạo màng, giúp mascara bám trên mi trong quá trình sử dụng.\n\n2. CÔNG DỤNG\n\n• Tạo hiệu ứng mi dài và dày hơn.\n• Giúp các sợi mi trông tơi, rõ nét.\n• Hỗ trợ chải đều từ chân đến ngọn mi.\n• Công thức chống nước, phù hợp khi cần trang điểm lâu trôi.\n\n3. THÀNH PHẦN\n\nCác thành phần nổi bật:\n\n• Isododecane: Dung môi thường dùng trong sản phẩm lâu trôi.\n• Beeswax và Carnauba Wax: Các loại sáp tạo kết cấu.\n• Rice Bran Wax: Sáp cám gạo.\n• Bambusa Vulgaris Extract: Chiết xuất tre.\n• Iron Oxides: Sắc tố màu, tùy phiên bản.\n\nLưu ý: Danh sách trên không thay thế bảng thành phần INCI đầy đủ. Công thức và sắc tố màu có thể khác nhau giữa các phiên bản.\n\n4. HƯỚNG DẪN SỬ DỤNG\n\n1. Đặt cọ mascara sát chân mi.\n2. Chải từ chân lên ngọn bằng chuyển động nhẹ.\n3. Chuốt thêm nếu muốn tăng hiệu ứng.\n4. Tẩy trang bằng sản phẩm dành cho trang điểm mắt chống nước.\n\nLưu ý: Chỉ dùng ngoài da. Ngừng sử dụng nếu có kích ứng. Không dùng chung sản phẩm trang điểm mắt để hạn chế nguy cơ nhiễm khuẩn.\n\n5. ĐỐI TƯỢNG SỬ DỤNG\n\n• Người có mi ngắn hoặc mi thưa.\n• Người muốn hiệu ứng mi dài, tơi.\n• Người cần mascara chống nước.", "en": "1. PRODUCT DESCRIPTION\n\nMaybelline Lash Sensational Sky High Waterproof Mascara is a lengthening and volumizing mascara designed to create the appearance of longer, more defined eyelashes. Featuring the Sky High mascara concept and a flexible brush, the product helps coat lashes from root to tip, including shorter lashes that may be difficult to reach with conventional brushes. The waterproof formula is designed to resist moisture and help maintain the finished lash look during everyday wear.\n\n2. BENEFITS\n\n• Creates the appearance of longer eyelashes.\n• Helps build visible lash volume.\n• Defines and separates lashes.\n• Helps coat shorter lashes with its flexible brush.\n• Provides a waterproof finish.\n• Supports a dramatic yet customizable lash look.\n\n3. INGREDIENTS\n\nKey ingredients and their functions:\n\n• Bamboo Extract: A botanical ingredient associated with the Sky High mascara formula.\n• Film-Forming Polymers: Help create a lasting mascara coating.\n• Waxes: Provide texture and support lash definition.\n• Iron Oxides: Provide dark pigment.\n• Conditioning Ingredients: Help distribute the formula evenly.\n• The exact ingredients vary by waterproof version and market.\n\nNote: The ingredients listed above are selected or representative formulation components, not a verified complete INCI list. Exact ingredients may vary by shade, market and product version. Confirm against the actual product packaging before publication.\n\n4. DIRECTIONS FOR USE\n\n1. Ensure eyelashes are clean and dry.\n2. Place the flexible brush close to the lash roots.\n3. Sweep upward toward the tips using a gentle zigzag motion.\n4. Repeat with thin layers to build length and volume.\n5. Avoid allowing excessive product to accumulate between coats.\n6. Remove carefully using an eye makeup remover suitable for waterproof formulas.\n\nPrecautions: For external use only. Discontinue use if irritation occurs. Avoid direct contact with the eyes unless the product is specifically intended for the eye area. Keep out of reach of children.\n\n5. SUITABLE FOR\n\n• People seeking longer-looking eyelashes.\n• Individuals wanting both length and volume.\n• Those who prefer waterproof eye makeup.\n• People looking for a flexible mascara brush."}, "image": "assets/catalog/product-maybelline-05.jpg", "gallery": {"vi": [{"src": "assets/catalog/vi/maybelline-05/thumbnail.webp", "label": "Thumbnail", "order": 0}, {"src": "assets/catalog/vi/maybelline-05/anh-1.webp", "label": "Ảnh 1", "order": 1}, {"src": "assets/catalog/vi/maybelline-05/anh-2.webp", "label": "Ảnh 2", "order": 2}, {"src": "assets/catalog/vi/maybelline-05/anh-3.webp", "label": "Ảnh 3", "order": 3}, {"src": "assets/catalog/vi/maybelline-05/anh-3-ban-2.webp", "label": "Ảnh 3 (bản 2)", "order": 3}, {"src": "assets/catalog/vi/maybelline-05/anh-4.webp", "label": "Ảnh 4", "order": 4}, {"src": "assets/catalog/vi/maybelline-05/anh-5.webp", "label": "Ảnh 5", "order": 5}, {"src": "assets/catalog/vi/maybelline-05/anh-7.webp", "label": "Ảnh 7", "order": 7}]}}, {"id": "maybelline-06", "brandId": "maybelline", "brand": "Maybelline", "name": {"vi": "BÚT KẺ MẮT MAYBELLINE HYPER SHARP LINER EXTREME 0,4G", "en": "Maybelline Hyper Sharp Liner Extreme 0.4g"}, "category": "Makeup", "type": "Bút kẻ mắt nước", "size": "0,4g", "country": "Hoa Kỳ", "description": {"vi": "1. MÔ TẢ SẢN PHẨM\n\nTên sản phẩm: Bút Kẻ Mắt Maybelline Hyper Sharp Liner Extreme 0,4g\nThương hiệu: Maybelline New York\nQuốc gia thương hiệu: Hoa Kỳ\nQuy cách đóng gói: 0,4g\nPhân loại: Bút kẻ mắt nước\n\nBút Kẻ Mắt Maybelline Hyper Sharp Liner Extreme 0,4g là sản phẩm kẻ mắt nước có đầu cọ sắc mảnh, giúp tạo đường eyeliner từ mỏng đến đậm tùy phong cách. Công nghệ Ink Capsule được Maybelline giới thiệu nhằm hỗ trợ mực ra đều, lên màu rõ và duy trì đường kẻ bền màu.\n\n2. CÔNG DỤNG\n\n• Tạo đường kẻ mắt sắc nét.\n• Đầu cọ mảnh giúp điều chỉnh độ dày đường kẻ.\n• Hỗ trợ tạo kiểu eyeliner tự nhiên hoặc cá tính.\n• Công thức được hãng giới thiệu có khả năng kháng nước và hạn chế lem.\n\n3. THÀNH PHẦN\n\nCác thành phần nổi bật:\n\n• Hệ sắc tố màu tạo đường kẻ đen hoặc nâu.\n• Các chất tạo màng giúp mực bám trên da.\n• Dung môi và thành phần điều chỉnh độ nhớt giúp mực ra đều.\n• Danh sách INCI cụ thể cần đối chiếu trên nhãn theo màu BK1 hoặc BR1.\n\nLưu ý: Danh sách trên không thay thế bảng thành phần INCI đầy đủ. Công thức và sắc tố màu có thể khác nhau giữa các phiên bản.\n\n4. HƯỚNG DẪN SỬ DỤNG\n\n1. Lắc hoặc chuẩn bị bút theo hướng dẫn trên bao bì.\n2. Bắt đầu kẻ các nét ngắn sát chân mi trên.\n3. Nối các nét thành đường liền mạch.\n4. Điều chỉnh độ dày và đuôi mắt theo phong cách mong muốn.\n5. Dùng sản phẩm tẩy trang mắt để làm sạch.\n\nLưu ý: Chỉ dùng ngoài da. Ngừng sử dụng nếu có kích ứng. Không dùng chung sản phẩm trang điểm mắt để hạn chế nguy cơ nhiễm khuẩn.\n\n5. ĐỐI TƯỢNG SỬ DỤNG\n\n• Người muốn kẻ eyeliner mảnh và sắc nét.\n• Người trang điểm mắt hằng ngày.\n• Người thích phong cách kẻ mắt linh hoạt.", "en": "1. PRODUCT DESCRIPTION\n\nMaybelline Hyper Sharp Liner Extreme is a precision eyeliner designed to create defined eye makeup looks, from thin everyday lines to bolder winged styles. Its fine applicator tip allows controlled placement close to the lash line, helping users shape and emphasize the eyes. The liquid liner format is suitable for creating sharp edges and building line intensity through careful layering. The exact finish and water-resistance claims should be checked against the specific product version.\n\n2. BENEFITS\n\n• Helps create precise eyeliner lines.\n• Defines and emphasizes the eye shape.\n• Suitable for thin lines and winged eyeliner styles.\n• Allows controlled application along the lash line.\n• Supports a range of everyday and dramatic makeup looks.\n\n3. INGREDIENTS\n\nKey ingredients and their functions:\n\n• Cosmetic Pigments: Provide eyeliner color.\n• Film-Forming Polymers: Help the product form a defined line.\n• Water or Solvents: Support the liquid texture.\n• Viscosity-Control Ingredients: Help maintain consistent application.\n• The complete ingredient list must be checked against the specific eyeliner version.\n\nNote: The ingredients listed above are selected or representative formulation components, not a verified complete INCI list. Exact ingredients may vary by shade, market and product version. Confirm against the actual product packaging before publication.\n\n4. DIRECTIONS FOR USE\n\n1. Ensure eyelids are clean and dry.\n2. Open the eyeliner and remove excess product from the applicator if necessary.\n3. Draw a thin line close to the upper lash line.\n4. Extend the line outward to create a wing if desired.\n5. Allow the eyeliner to dry before applying additional eye makeup.\n6. Remove gently with an appropriate eye makeup remover.\n\nPrecautions: For external use only. Discontinue use if irritation occurs. Avoid direct contact with the eyes unless the product is specifically intended for the eye area. Keep out of reach of children.\n\n5. SUITABLE FOR\n\n• People who prefer precise eyeliner application.\n• Individuals who enjoy winged eyeliner.\n• Those seeking defined eye makeup.\n• Makeup users wanting a fine applicator tip."}, "image": "assets/catalog/product-maybelline-06.jpg", "gallery": {"vi": [{"src": "assets/catalog/vi/maybelline-06/thumbnail.webp", "label": "Thumbnail", "order": 0}, {"src": "assets/catalog/vi/maybelline-06/anh-1.webp", "label": "Ảnh 1", "order": 1}, {"src": "assets/catalog/vi/maybelline-06/anh-2.webp", "label": "Ảnh 2", "order": 2}, {"src": "assets/catalog/vi/maybelline-06/anh-3.webp", "label": "Ảnh 3", "order": 3}, {"src": "assets/catalog/vi/maybelline-06/anh-4.webp", "label": "Ảnh 4", "order": 4}, {"src": "assets/catalog/vi/maybelline-06/anh-5.webp", "label": "Ảnh 5", "order": 5}, {"src": "assets/catalog/vi/maybelline-06/anh-6.webp", "label": "Ảnh 6", "order": 6}, {"src": "assets/catalog/vi/maybelline-06/anh-7.webp", "label": "Ảnh 7", "order": 7}]}}, {"id": "maybelline-07", "brandId": "maybelline", "brand": "Maybelline", "name": {"vi": "SON KEM MAYBELLINE SUPER STAY VINYL INK 4,2ML", "en": "Maybelline Super Stay Vinyl Ink Liquid Lipcolor 4.2ml"}, "category": "Makeup", "type": "Son kem bóng lâu trôi", "size": "4,2ml", "country": "Hoa Kỳ", "description": {"vi": "1. MÔ TẢ SẢN PHẨM\n\nTên sản phẩm: Son Kem Maybelline Super Stay Vinyl Ink 4,2ml\nThương hiệu: Maybelline New York\nQuốc gia thương hiệu: Hoa Kỳ\nQuy cách đóng gói: 4,2ml\nPhân loại: Son kem bóng lâu trôi\n\nSon Kem Maybelline Super Stay Vinyl Ink 4,2ml là dòng son kem có hiệu ứng bóng vinyl, kết hợp màu son rõ nét với độ bám màu lâu trôi. Công thức Khóa Màu được Maybelline giới thiệu có khả năng chống lem, chống trôi và duy trì màu son lên đến 16 giờ trong điều kiện thử nghiệm của hãng.\n\n2. CÔNG DỤNG\n\n• Tạo hiệu ứng môi bóng nổi bật.\n• Cho màu son rõ và đều.\n• Hỗ trợ hạn chế lem, trôi khi sử dụng.\n• Có nhiều tông màu cho các phong cách trang điểm.\n\n3. THÀNH PHẦN\n\nCác thành phần nổi bật:\n\n• Isododecane: Thành phần thường dùng trong công thức son lâu trôi.\n• Hệ polymer tạo màng: Hỗ trợ độ bám và hiệu ứng bóng.\n• Các chất làm mềm và sắc tố màu: Tạo kết cấu, màu son.\n• Bảng INCI chi tiết thay đổi theo màu; cần đối chiếu phiên bản thực tế.\n\nLưu ý: Danh sách trên không thay thế bảng thành phần INCI đầy đủ. Công thức và sắc tố màu có thể khác nhau giữa các phiên bản.\n\n4. HƯỚNG DẪN SỬ DỤNG\n\n1. Lắc đều sản phẩm ít nhất 5 giây trước khi sử dụng.\n2. Đảm bảo môi sạch và khô.\n3. Thoa son từ giữa môi ra hai bên.\n4. Đợi lớp son ổn định, hạn chế bặm môi ngay sau khi thoa.\n\nLưu ý: Chỉ dùng ngoài da. Ngừng sử dụng nếu có kích ứng. Không dùng chung sản phẩm trang điểm mắt để hạn chế nguy cơ nhiễm khuẩn.\n\n5. ĐỐI TƯỢNG SỬ DỤNG\n\n• Người yêu thích son kem bóng.\n• Người muốn màu son rõ và lâu trôi.\n• Người cần son trang điểm hằng ngày hoặc dự tiệc.", "en": "1. PRODUCT DESCRIPTION\n\nMaybelline Super Stay Vinyl Ink Liquid Lipcolor is a long-wear liquid lip color developed to deliver bold color with a glossy, vinyl-inspired finish. Its formula combines color pigments with film-forming ingredients to create a vibrant lip look designed for extended wear. Unlike conventional matte liquid lipsticks, Vinyl Ink emphasizes a shiny appearance while providing strong color payoff. The product should be shaken before application as directed by the brand.\n\n2. BENEFITS\n\n• Delivers bold, vibrant lip color.\n• Creates a glossy vinyl-like finish.\n• Offers long-wear lip makeup performance.\n• Helps define and enhance the appearance of lips.\n• Provides smooth color application.\n• Available in multiple shades for different makeup styles.\n\n3. INGREDIENTS\n\nKey ingredients and their functions:\n\n• Color Pigments: Provide shade-specific lip color.\n• Film-Forming Polymers: Help support long-wear performance.\n• Silicone-Based Ingredients: Contribute to spreadability and finish.\n• Emollient Ingredients: Support a comfortable lip feel.\n• Fragrance and Colorants: May vary by shade and market.\n\nNote: The ingredients listed above are selected or representative formulation components, not a verified complete INCI list. Exact ingredients may vary by shade, market and product version. Confirm against the actual product packaging before publication.\n\n4. DIRECTIONS FOR USE\n\n1. Ensure lips are clean and dry.\n2. Shake the product thoroughly before use.\n3. Use the applicator to outline the lips.\n4. Fill in the lips with an even layer of color.\n5. Allow the product to set without rubbing the lips together immediately.\n6. Remove at the end of the day using a suitable lip makeup remover.\n\nPrecautions: For external use only. Discontinue use if irritation occurs. Avoid direct contact with the eyes unless the product is specifically intended for the eye area. Keep out of reach of children.\n\n5. SUITABLE FOR\n\n• People who enjoy bold lip colors.\n• Individuals seeking glossy long-wear lipstick.\n• Those who prefer liquid lip products.\n• Makeup users looking for a statement lip finish."}, "image": "assets/catalog/product-maybelline-07.jpg", "gallery": {"vi": [{"src": "assets/catalog/vi/maybelline-07/thumbnail.webp", "label": "Thumbnail", "order": 0}, {"src": "assets/catalog/vi/maybelline-07/anh-1.webp", "label": "Ảnh 1", "order": 1}, {"src": "assets/catalog/vi/maybelline-07/anh-2.webp", "label": "Ảnh 2", "order": 2}, {"src": "assets/catalog/vi/maybelline-07/anh-3.webp", "label": "Ảnh 3", "order": 3}, {"src": "assets/catalog/vi/maybelline-07/anh-4.webp", "label": "Ảnh 4", "order": 4}, {"src": "assets/catalog/vi/maybelline-07/anh-5.webp", "label": "Ảnh 5", "order": 5}, {"src": "assets/catalog/vi/maybelline-07/anh-6.webp", "label": "Ảnh 6", "order": 6}, {"src": "assets/catalog/vi/maybelline-07/anh-7.webp", "label": "Ảnh 7", "order": 7}]}}, {"id": "maybelline-08", "brandId": "maybelline", "brand": "Maybelline", "name": {"vi": "SON THỎI MAYBELLINE COLOR SENSATIONAL ULTIMATTE 1,7G", "en": "Maybelline Color Sensational Ultimatte Slim Lipstick 1.7g"}, "category": "Makeup", "type": "Son thỏi lì", "size": "1,7g", "country": "Hoa Kỳ", "description": {"vi": "1. MÔ TẢ SẢN PHẨM\n\nTên sản phẩm: Son Thỏi Maybelline Color Sensational Ultimatte 1,7g\nThương hiệu: Maybelline New York\nQuốc gia thương hiệu: Hoa Kỳ\nQuy cách đóng gói: 1,7g\nPhân loại: Son thỏi lì\n\nSon Thỏi Maybelline Color Sensational Ultimatte 1,7g là dòng son thỏi với thiết kế thân mảnh, kết cấu lì mịn và cảm giác nhẹ môi. Sản phẩm hướng đến lớp son có màu sắc rõ nét, tạo hiệu ứng lì hiện đại và phù hợp nhiều phong cách trang điểm.\n\n2. CÔNG DỤNG\n\n• Tạo hiệu ứng môi lì mịn.\n• Cho màu son nổi bật.\n• Kết cấu nhẹ, dễ thoa.\n• Thiết kế thỏi mảnh thuận tiện mang theo.\n\n3. THÀNH PHẦN\n\nCác thành phần nổi bật:\n\n• Hệ sáp và chất làm mềm giúp tạo kết cấu son thỏi.\n• Các sắc tố màu tạo tông son theo từng phiên bản.\n• Thành phần INCI cụ thể cần đối chiếu trên nhãn màu son 1,7g; không sử dụng bảng thành phần của màu khác để thay thế.\n\nLưu ý: Danh sách trên không thay thế bảng thành phần INCI đầy đủ. Công thức và sắc tố màu có thể khác nhau giữa các phiên bản.\n\n4. HƯỚNG DẪN SỬ DỤNG\n\n1. Làm sạch và dưỡng môi nếu cần.\n2. Thoa son từ giữa môi trên theo đường viền môi.\n3. Tô đều môi dưới.\n4. Có thể thoa thêm một lớp để tăng độ đậm màu.\n\nLưu ý: Chỉ dùng ngoài da. Ngừng sử dụng nếu có kích ứng. Không dùng chung sản phẩm trang điểm mắt để hạn chế nguy cơ nhiễm khuẩn.\n\n5. ĐỐI TƯỢNG SỬ DỤNG\n\n• Người yêu thích son lì.\n• Người muốn màu son rõ nhưng cảm giác nhẹ môi.\n• Người cần son thỏi tiện dụng cho trang điểm hằng ngày.", "en": "1. PRODUCT DESCRIPTION\n\nMaybelline Color Sensational Ultimatte is a slim-format lipstick designed to deliver rich color with a modern matte finish. Its lightweight lipstick texture glides across the lips, creating a soft-looking matte effect without the thick appearance of traditional heavy lip products. The narrow bullet allows more controlled application around the lip contours, making it suitable for both everyday makeup and more defined lip looks. Color intensity and undertones vary by shade.\n\n2. BENEFITS\n\n• Provides rich, visible lip color.\n• Creates a soft matte finish.\n• Offers a lightweight lipstick feel.\n• Allows controlled application with its slim bullet.\n• Helps define the appearance of the lips.\n• Suitable for everyday and occasion makeup.\n\n3. INGREDIENTS\n\nKey ingredients and their functions:\n\n• Color Pigments: Create the lipstick shade.\n• Dimethicone: A silicone ingredient that supports smooth application.\n• Waxes: Provide the lipstick's solid structure.\n• Emollient Ingredients: Help the product glide across the lips.\n• Silica or Other Texture Modifiers: May contribute to the matte finish.\n• The complete formula varies by shade and product version.\n\nNote: The ingredients listed above are selected or representative formulation components, not a verified complete INCI list. Exact ingredients may vary by shade, market and product version. Confirm against the actual product packaging before publication.\n\n4. DIRECTIONS FOR USE\n\n1. Ensure lips are clean and free of excess moisture.\n2. Apply lip balm beforehand if needed, allowing it to absorb.\n3. Glide the lipstick from the center of the upper lip toward the corners.\n4. Repeat on the lower lip.\n5. Use the slim tip to define the lip contours.\n6. Reapply when necessary.\n\nPrecautions: For external use only. Discontinue use if irritation occurs. Avoid direct contact with the eyes unless the product is specifically intended for the eye area. Keep out of reach of children.\n\n5. SUITABLE FOR\n\n• People who prefer matte lipstick.\n• Individuals seeking a lightweight lip color.\n• Those who enjoy precise lipstick application.\n• Makeup users looking for a slim bullet format."}, "image": "assets/catalog/product-maybelline-08.jpg", "gallery": {"vi": [{"src": "assets/catalog/vi/maybelline-08/thumbnail.webp", "label": "Thumbnail", "order": 0}, {"src": "assets/catalog/vi/maybelline-08/anh-1.webp", "label": "Ảnh 1", "order": 1}, {"src": "assets/catalog/vi/maybelline-08/anh-2.webp", "label": "Ảnh 2", "order": 2}, {"src": "assets/catalog/vi/maybelline-08/anh-3.webp", "label": "Ảnh 3", "order": 3}, {"src": "assets/catalog/vi/maybelline-08/anh-4.webp", "label": "Ảnh 4", "order": 4}, {"src": "assets/catalog/vi/maybelline-08/anh-5.webp", "label": "Ảnh 5", "order": 5}, {"src": "assets/catalog/vi/maybelline-08/anh-6.webp", "label": "Ảnh 6", "order": 6}, {"src": "assets/catalog/vi/maybelline-08/anh-7.webp", "label": "Ảnh 7", "order": 7}]}}, {"id": "maybelline-09", "brandId": "maybelline", "brand": "Maybelline", "name": {"vi": "SON KEM MAYBELLINE SUPER STAY MATTE INK CITY EDITION 5ML", "en": "Maybelline Super Stay Matte Ink City Edition Liquid Lipstick 5ml"}, "category": "Makeup", "type": "Son kem lì lâu trôi", "size": "5ml", "country": "Hoa Kỳ", "description": {"vi": "1. MÔ TẢ SẢN PHẨM\n\nTên sản phẩm: Son Kem Maybelline Super Stay Matte Ink City Edition 5ml\nThương hiệu: Maybelline New York\nQuốc gia thương hiệu: Hoa Kỳ\nQuy cách đóng gói: 5ml\nPhân loại: Son kem lì lâu trôi\n\nSon Kem Maybelline Super Stay Matte Ink City Edition 5ml là dòng son kem lì có sắc màu nổi bật và độ bám màu cao. Thiết kế đầu cọ giúp thoa son tương đối chính xác, phù hợp tạo lớp son lì rõ nét cho trang điểm hằng ngày hoặc những dịp cần duy trì màu môi lâu.\n\n2. CÔNG DỤNG\n\n• Tạo lớp son lì rõ màu.\n• Hỗ trợ duy trì màu son trong nhiều giờ.\n• Hạn chế lem trôi sau khi lớp son ổn định.\n• Có nhiều màu sắc để lựa chọn.\n\n3. THÀNH PHẦN\n\nCác thành phần nổi bật:\n\n• Hệ polymer tạo màng giúp duy trì lớp son.\n• Các chất làm mềm và dung môi tạo kết cấu son kem.\n• Sắc tố màu tùy từng mã màu.\n• Bảng INCI chính xác cần đối chiếu theo mã màu và bao bì 5ml.\n\nLưu ý: Danh sách trên không thay thế bảng thành phần INCI đầy đủ. Công thức và sắc tố màu có thể khác nhau giữa các phiên bản.\n\n4. HƯỚNG DẪN SỬ DỤNG\n\n1. Làm sạch môi, loại bỏ dầu thừa nếu có.\n2. Dùng đầu cọ viền môi và tô đều phần bên trong.\n3. Đợi son khô, hạn chế bặm môi ngay sau khi thoa.\n4. Sử dụng sản phẩm tẩy trang môi phù hợp để làm sạch.\n\nLưu ý: Chỉ dùng ngoài da. Ngừng sử dụng nếu có kích ứng. Không dùng chung sản phẩm trang điểm mắt để hạn chế nguy cơ nhiễm khuẩn.\n\n5. ĐỐI TƯỢNG SỬ DỤNG\n\n• Người thích son kem lì, màu rõ.\n• Người cần màu son bám lâu.\n• Người trang điểm hằng ngày hoặc trong các dịp đặc biệt.", "en": "1. PRODUCT DESCRIPTION\n\nMaybelline Super Stay Matte Ink City Edition is a liquid lipstick collection featuring intense color and a matte finish inspired by urban makeup trends. The formula is designed to provide long-lasting color with strong pigmentation and a defined lip look. Its precision applicator helps distribute color evenly and shape the lip contours. As a City Edition product, the available shades and packaging may differ from the standard Super Stay Matte Ink range.\n\n2. BENEFITS\n\n• Delivers highly pigmented lip color.\n• Creates a bold matte finish.\n• Offers long-lasting lip makeup performance.\n• Helps define lip contours with a precision applicator.\n• Supports a variety of statement makeup looks.\n• Available in edition-specific shades.\n\n3. INGREDIENTS\n\nKey ingredients and their functions:\n\n• Color Pigments: Provide shade-specific color intensity.\n• Film-Forming Polymers: Support long-wear performance.\n• Silicone-Based Ingredients: Help create a smooth application texture.\n• Texture-Control Agents: Support the matte finish.\n• Fragrance and Colorants: May vary by shade and edition.\n• The complete INCI should be verified against the City Edition packaging.\n\nNote: The ingredients listed above are selected or representative formulation components, not a verified complete INCI list. Exact ingredients may vary by shade, market and product version. Confirm against the actual product packaging before publication.\n\n4. DIRECTIONS FOR USE\n\n1. Start with clean, dry lips.\n2. Remove excess product from the applicator if necessary.\n3. Outline the lips using the applicator tip.\n4. Fill in the lips with a thin, even layer.\n5. Allow the formula to set before eating or drinking.\n6. Remove gently with an appropriate long-wear lip makeup remover.\n\nPrecautions: For external use only. Discontinue use if irritation occurs. Avoid direct contact with the eyes unless the product is specifically intended for the eye area. Keep out of reach of children.\n\n5. SUITABLE FOR\n\n• People who prefer bold matte lip color.\n• Individuals looking for long-wear liquid lipstick.\n• Those who enjoy highly pigmented makeup.\n• Makeup users interested in edition-specific lipstick shades."}, "image": "assets/catalog/product-maybelline-09.jpg", "gallery": {"vi": [{"src": "assets/catalog/vi/maybelline-09/thumbnail.webp", "label": "Thumbnail", "order": 0}, {"src": "assets/catalog/vi/maybelline-09/anh-1.webp", "label": "Ảnh 1", "order": 1}, {"src": "assets/catalog/vi/maybelline-09/anh-2.webp", "label": "Ảnh 2", "order": 2}, {"src": "assets/catalog/vi/maybelline-09/anh-3.webp", "label": "Ảnh 3", "order": 3}, {"src": "assets/catalog/vi/maybelline-09/anh-4.webp", "label": "Ảnh 4", "order": 4}, {"src": "assets/catalog/vi/maybelline-09/anh-5.webp", "label": "Ảnh 5", "order": 5}, {"src": "assets/catalog/vi/maybelline-09/anh-6.webp", "label": "Ảnh 6", "order": 6}, {"src": "assets/catalog/vi/maybelline-09/anh-7.webp", "label": "Ảnh 7", "order": 7}]}}, {"id": "maybelline-10", "brandId": "maybelline", "brand": "Maybelline", "name": {"vi": "NƯỚC TẨY TRANG MẮT VÀ MÔI MAYBELLINE EYE & LIP MAKEUP REMOVER 150ML", "en": "Maybelline Eye & Lip Makeup Remover 150ml"}, "category": "Skincare", "type": "Nước tẩy trang mắt và môi", "size": "150ml", "country": "Hoa Kỳ", "description": {"vi": "1. MÔ TẢ SẢN PHẨM\n\nTên sản phẩm: Nước Tẩy Trang Mắt Và Môi Maybelline Eye & Lip Makeup Remover 150ml\nThương hiệu: Maybelline New York\nQuốc gia thương hiệu: Hoa Kỳ\nQuy cách đóng gói: 150ml\nPhân loại: Nước tẩy trang mắt và môi\n\nNước Tẩy Trang Mắt Và Môi Maybelline Eye & Lip Makeup Remover 150ml là sản phẩm chuyên dùng để làm sạch lớp trang điểm ở vùng mắt và môi. Công thức tẩy trang hai pha hỗ trợ loại bỏ mascara, eyeliner và son lâu trôi, giúp quá trình làm sạch thuận tiện hơn mà không cần chà xát mạnh.\n\n2. CÔNG DỤNG\n\n• Hỗ trợ loại bỏ lớp trang điểm mắt và môi.\n• Làm sạch mascara và son có độ bám cao.\n• Giúp hạn chế thao tác chà xát khi tẩy trang.\n• Phù hợp bổ sung vào quy trình làm sạch cuối ngày.\n\n3. THÀNH PHẦN\n\nCác thành phần nổi bật:\n\n• Pha dầu: Hỗ trợ hòa tan lớp trang điểm bền màu.\n• Pha nước: Hỗ trợ làm sạch sau khi lớp trang điểm được hòa tan.\n• Các thành phần làm sạch và ổn định công thức: Cần đối chiếu INCI trên chai 150ml để ghi chính xác tên chất.\n\nLưu ý: Danh sách trên không thay thế bảng thành phần INCI đầy đủ. Công thức và sắc tố màu có thể khác nhau giữa các phiên bản.\n\n4. HƯỚNG DẪN SỬ DỤNG\n\n1. Lắc đều chai để hai pha hòa quyện.\n2. Thấm lượng sản phẩm vừa đủ lên bông tẩy trang.\n3. Áp nhẹ lên vùng mắt hoặc môi trong vài giây.\n4. Lau nhẹ theo chiều phù hợp, lặp lại nếu còn lớp trang điểm.\n5. Tiếp tục các bước làm sạch da theo nhu cầu.\n\nLưu ý: Chỉ dùng ngoài da. Ngừng sử dụng nếu có kích ứng. Không dùng chung sản phẩm trang điểm mắt để hạn chế nguy cơ nhiễm khuẩn.\n\n5. ĐỐI TƯỢNG SỬ DỤNG\n\n• Người thường xuyên trang điểm mắt và môi.\n• Người sử dụng mascara hoặc son lâu trôi.\n• Người cần sản phẩm tẩy trang chuyên biệt cho mắt và môi.", "en": "1. PRODUCT DESCRIPTION\n\nMaybelline Eye & Lip Makeup Remover is a targeted makeup remover developed for the delicate eye and lip areas. Its cleansing formula helps dissolve and lift mascara, eyeliner and lip color, including many long-wear or waterproof makeup products. The remover is designed to reduce the need for excessive rubbing, making it a convenient part of an evening makeup-removal routine. Some versions use a dual-phase formula, so the bottle should be shaken before use when instructed on the label.\n\n2. BENEFITS\n\n• Helps remove eye and lip makeup.\n• Assists in dissolving long-wear makeup.\n• Can help remove waterproof mascara and eyeliner.\n• Reduces the need for harsh rubbing when used correctly.\n• Supports a convenient end-of-day cleansing routine.\n\n3. INGREDIENTS\n\nKey ingredients and their functions:\n\n• Cleansing Solvents: Help dissolve makeup pigments and film-forming ingredients.\n• Emollient Ingredients: Help loosen long-wear makeup.\n• Water-Based Components: Support the cleansing formula.\n• Additional Ingredients: Depend on the exact regional version and should be verified against the bottle's INCI list.\n\nNote: The ingredients listed above are selected or representative formulation components, not a verified complete INCI list. Exact ingredients may vary by shade, market and product version. Confirm against the actual product packaging before publication.\n\n4. DIRECTIONS FOR USE\n\n1. Shake the bottle if the product uses a dual-phase formula.\n2. Apply a sufficient amount to a clean cotton pad.\n3. Hold the pad gently over closed eyelids or lips for several seconds.\n4. Wipe carefully to remove dissolved makeup without excessive rubbing.\n5. Repeat with a fresh cotton pad if necessary.\n6. Follow with a gentle facial cleanser if desired.\n\nPrecautions: For external use only. Discontinue use if irritation occurs. Avoid direct contact with the eyes unless the product is specifically intended for the eye area. Keep out of reach of children.\n\n5. SUITABLE FOR\n\n• People who regularly wear eye makeup.\n• Individuals using waterproof mascara or eyeliner.\n• People wearing long-lasting lip color.\n• Those seeking a dedicated eye and lip makeup remover."}, "image": "assets/catalog/product-maybelline-10.jpg", "gallery": {"vi": [{"src": "assets/catalog/vi/maybelline-10/thumbnail.webp", "label": "Thumbnail", "order": 0}, {"src": "assets/catalog/vi/maybelline-10/anh-1.webp", "label": "Ảnh 1", "order": 1}, {"src": "assets/catalog/vi/maybelline-10/anh-2.webp", "label": "Ảnh 2", "order": 2}, {"src": "assets/catalog/vi/maybelline-10/anh-3.webp", "label": "Ảnh 3", "order": 3}, {"src": "assets/catalog/vi/maybelline-10/anh-4.webp", "label": "Ảnh 4", "order": 4}, {"src": "assets/catalog/vi/maybelline-10/anh-5.webp", "label": "Ảnh 5", "order": 5}, {"src": "assets/catalog/vi/maybelline-10/anh-6.webp", "label": "Ảnh 6", "order": 6}, {"src": "assets/catalog/vi/maybelline-10/anh-7.webp", "label": "Ảnh 7", "order": 7}]}}, {"id": "dove-01", "brandId": "dove", "brand": "Dove", "name": {"vi": "SỮA TẮM DOVE DƯỠNG ẨM CHUYÊN SÂU 900G", "en": "Dove Deep Moisture Body Wash 900g"}, "category": "Body care", "type": "Sữa tắm dưỡng ẩm", "size": "Chai 900g", "country": "Hoa Kỳ", "description": {"vi": "1. MÔ TẢ SẢN PHẨM\n\nTên sản phẩm: Sữa Tắm Dove Dưỡng Ẩm Chuyên Sâu 900g\nThương hiệu: Dove\nQuốc gia thương hiệu: Hoa Kỳ\nQuy cách đóng gói: Chai 900g\nPhân loại: Sữa tắm dưỡng ẩm\n\nSữa Tắm Dove Dưỡng Ẩm Chuyên Sâu 900g là sản phẩm làm sạch và chăm sóc da cơ thể hằng ngày. Công thức được giới thiệu với 1/4 kem dưỡng ẩm và dưỡng chất lợi khuẩn da, giúp loại bỏ bụi bẩn, mồ hôi, đồng thời hỗ trợ duy trì cảm giác mềm mại, ẩm mượt sau khi tắm. Sản phẩm có kết cấu dễ tạo bọt, thích hợp sử dụng thường xuyên.\n\n2. CÔNG DỤNG\n\n• Làm sạch bụi bẩn, mồ hôi và tạp chất trên da.\n• Hỗ trợ duy trì độ ẩm, giảm cảm giác khô căng sau khi tắm.\n• Giúp da có cảm giác mềm mại và mịn màng.\n• Mang lại cảm giác sạch sẽ, dễ chịu khi sử dụng hằng ngày.\n\n3. THÀNH PHẦN\n\nCác thành phần nổi bật:\n\n• Glycerin: Thành phần hút ẩm, hỗ trợ duy trì độ ẩm cho da.\n• Alpha-Glucan Oligosaccharide: Thành phần được sử dụng trong công thức chăm sóc da.\n• Sodium Cocoyl Isethionate: Chất hoạt động bề mặt giúp làm sạch.\n• Cocamidopropyl Betaine: Hỗ trợ làm sạch và tạo bọt.\n• Stearic Acid và Palmitic Acid: Các acid béo tham gia tạo kết cấu sản phẩm.\n\nLưu ý: Đây là các thành phần tiêu biểu, không thay thế bảng thành phần INCI đầy đủ trên bao bì. Công thức có thể thay đổi theo phiên bản.\n\n4. HƯỚNG DẪN SỬ DỤNG\n\n1. Làm ướt toàn bộ cơ thể bằng nước sạch.\n2. Lấy lượng sữa tắm vừa đủ vào tay hoặc bông tắm.\n3. Tạo bọt và massage nhẹ nhàng trên da.\n4. Tắm sạch lại với nước. Có thể sử dụng hằng ngày.\n\nLưu ý: Chỉ sử dụng ngoài da. Tránh tiếp xúc với mắt; nếu dính vào mắt, rửa kỹ bằng nước. Ngừng sử dụng nếu xuất hiện kích ứng kéo dài.\n\n5. ĐỐI TƯỢNG SỬ DỤNG\n\n• Người có da thường đến da khô.\n• Người cần sữa tắm kết hợp làm sạch và dưỡng ẩm.\n• Người muốn chăm sóc da cơ thể hằng ngày.", "en": "1. PRODUCT DESCRIPTION\n\nDove Deep Moisture Body Wash is a nourishing daily body cleanser designed to leave skin feeling clean, soft and moisturized after showering. Its creamy, rich lather helps remove sweat, dirt and everyday impurities while providing a comfortable cleansing experience. Featuring Dove's signature moisturizing approach, this body wash is particularly suitable for people who want to care for skin dryness as part of their daily bathing routine. The 900g family-size format is convenient for regular household use.\n\n2. BENEFITS\n\n• Gently removes dirt, sweat and daily impurities.\n• Helps maintain soft, smooth skin after bathing.\n• Provides moisturizing care during cleansing.\n• Creates a rich and creamy lather.\n• Supports daily body care without a heavy or greasy after-feel.\n\n3. INGREDIENTS\n\nKey ingredients and their functions:\n\n• Glycerin: A humectant that helps attract moisture to the skin.\n• Cocamidopropyl Betaine: A cleansing and foam-supporting ingredient.\n• Sodium Cocoyl Isethionate: A cleansing surfactant.\n• Sodium Methyl Lauroyl Taurate: A cleansing agent.\n• Alpha-Glucan Oligosaccharide: A skin-conditioning ingredient.\n• Stearic Acid and Palmitic Acid: Fatty acids that support the cleansing formula's texture.\n\nNote: These are selected ingredients or ingredient categories, not necessarily the complete INCI list. Verify the formula and labeling of the actual product before publication.\n\n4. DIRECTIONS FOR USE\n\n1. Wet the body thoroughly with water.\n2. Dispense a suitable amount into the palms or onto a shower puff.\n3. Work into a creamy lather.\n4. Gently massage over the body.\n5. Rinse thoroughly with clean water.\n6. Pat dry and follow with body lotion if desired.\n\nPrecautions: For external use only. Avoid contact with eyes. If contact occurs, rinse thoroughly with water. Discontinue use if irritation occurs.\n\n5. SUITABLE FOR\n\n• Normal to dry skin.\n• People seeking a moisturizing daily body wash.\n• Individuals who experience dryness after showering.\n• Families looking for a large-format body cleanser."}, "image": "assets/catalog/product-dove-01.jpg", "gallery": {"vi": [{"src": "assets/catalog/vi/dove-01/thumbnail.webp", "label": "Thumbnail", "order": 0}, {"src": "assets/catalog/vi/dove-01/anh-1.webp", "label": "Ảnh 1", "order": 1}, {"src": "assets/catalog/vi/dove-01/anh-2.webp", "label": "Ảnh 2", "order": 2}, {"src": "assets/catalog/vi/dove-01/anh-3.webp", "label": "Ảnh 3", "order": 3}, {"src": "assets/catalog/vi/dove-01/anh-4.webp", "label": "Ảnh 4", "order": 4}, {"src": "assets/catalog/vi/dove-01/anh-5.webp", "label": "Ảnh 5", "order": 5}, {"src": "assets/catalog/vi/dove-01/anh-6.webp", "label": "Ảnh 6", "order": 6}, {"src": "assets/catalog/vi/dove-01/anh-7.webp", "label": "Ảnh 7", "order": 7}]}}, {"id": "dove-02", "brandId": "dove", "brand": "Dove", "name": {"vi": "SỮA TẮM DOVE DA MỊN THƠM MÁT 900G", "en": "Dove Invigorating Body Wash 900g"}, "category": "Body care", "type": "Sữa tắm dưỡng thể", "size": "Chai 900g", "country": "Hoa Kỳ", "description": {"vi": "1. MÔ TẢ SẢN PHẨM\n\nTên sản phẩm: Sữa Tắm Dove Da Mịn Thơm Mát 900g\nThương hiệu: Dove\nQuốc gia thương hiệu: Hoa Kỳ\nQuy cách đóng gói: Chai 900g\nPhân loại: Sữa tắm dưỡng thể\n\nSữa Tắm Dove Da Mịn Thơm Mát 900g là sản phẩm làm sạch cơ thể kết hợp các thành phần chăm sóc da. Công thức được giới thiệu với dầu bơ và chiết xuất hoa cúc Calendula, giúp mang lại cảm giác mềm mại, tươi mát và hương thơm dễ chịu sau khi tắm.\n\n2. CÔNG DỤNG\n\n• Làm sạch bụi bẩn và mồ hôi trên cơ thể.\n• Hỗ trợ duy trì cảm giác mềm mịn trên da.\n• Mang lại cảm giác tươi mát, sảng khoái.\n• Giúp cơ thể có hương thơm dễ chịu.\n\n3. THÀNH PHẦN\n\nCác thành phần nổi bật:\n\n• Dầu bơ (Avocado Oil): Hỗ trợ làm mềm da.\n• Chiết xuất hoa cúc Calendula: Thành phần thực vật chăm sóc da.\n• Glycerin: Hỗ trợ giữ ẩm.\n• Alpha-Glucan Oligosaccharide: Thành phần chăm sóc da.\n• Các chất hoạt động bề mặt: Giúp làm sạch bụi bẩn và dầu thừa.\n\nLưu ý: Đây là các thành phần tiêu biểu, không thay thế bảng thành phần INCI đầy đủ trên bao bì. Công thức có thể thay đổi theo phiên bản.\n\n4. HƯỚNG DẪN SỬ DỤNG\n\n1. Làm ướt cơ thể.\n2. Lấy lượng sữa tắm vừa đủ vào lòng bàn tay hoặc bông tắm.\n3. Tạo bọt và massage nhẹ nhàng.\n4. Xả sạch bằng nước.\n\nLưu ý: Chỉ sử dụng ngoài da. Tránh tiếp xúc với mắt; nếu dính vào mắt, rửa kỹ bằng nước. Ngừng sử dụng nếu xuất hiện kích ứng kéo dài.\n\n5. ĐỐI TƯỢNG SỬ DỤNG\n\n• Người cần làm sạch cơ thể hằng ngày.\n• Người yêu thích hương thơm tươi mát.\n• Người muốn duy trì cảm giác mềm mại trên da.", "en": "1. PRODUCT DESCRIPTION\n\nDove Invigorating Body Wash is a refreshing daily body cleanser formulated with avocado oil and calendula flower extract. Its creamy foam helps wash away sweat and everyday impurities while leaving the skin feeling soft, clean and refreshed. The invigorating fragrance adds an uplifting sensory element to the shower experience. Designed for everyday bathing, this body wash combines effective cleansing with Dove's focus on maintaining comfortable, moisturized skin.\n\n2. BENEFITS\n\n• Gently cleanses the body and removes daily impurities.\n• Helps maintain a soft and smooth skin feel.\n• Provides a refreshing bathing experience.\n• Leaves a pleasant, fresh fragrance on the skin.\n• Combines cleansing with skin-conditioning care.\n\n3. INGREDIENTS\n\nKey ingredients and their functions:\n\n• Persea Gratissima (Avocado) Oil: A plant-derived emollient.\n• Calendula Officinalis Flower Extract: A botanical skin-conditioning ingredient.\n• Glycerin: Helps maintain skin hydration.\n• Cocamidopropyl Betaine: A cleansing ingredient.\n• Sodium Cocoyl Isethionate: A cleansing surfactant.\n• Tocopherol: An antioxidant form of vitamin E.\n\nNote: These are selected ingredients or ingredient categories, not necessarily the complete INCI list. Verify the formula and labeling of the actual product before publication.\n\n4. DIRECTIONS FOR USE\n\n1. Wet the skin with water.\n2. Apply a suitable amount to the hands or a shower puff.\n3. Lather gently and massage across the body.\n4. Rinse thoroughly with water.\n5. Use daily as part of the bathing routine.\n\nPrecautions: For external use only. Avoid contact with eyes. If contact occurs, rinse thoroughly with water. Discontinue use if irritation occurs.\n\n5. SUITABLE FOR\n\n• People who enjoy refreshing shower fragrances.\n• Normal skin seeking daily cleansing.\n• Individuals wanting soft, comfortable skin after showering.\n• People looking for a fragrant body wash."}, "image": "assets/catalog/product-dove-02.jpg", "gallery": {"vi": [{"src": "assets/catalog/vi/dove-02/thumbnail.webp", "label": "Thumbnail", "order": 0}, {"src": "assets/catalog/vi/dove-02/anh-1.webp", "label": "Ảnh 1", "order": 1}, {"src": "assets/catalog/vi/dove-02/anh-2.webp", "label": "Ảnh 2", "order": 2}, {"src": "assets/catalog/vi/dove-02/anh-3.webp", "label": "Ảnh 3", "order": 3}, {"src": "assets/catalog/vi/dove-02/anh-4.webp", "label": "Ảnh 4", "order": 4}, {"src": "assets/catalog/vi/dove-02/anh-5.webp", "label": "Ảnh 5", "order": 5}, {"src": "assets/catalog/vi/dove-02/anh-6.webp", "label": "Ảnh 6", "order": 6}, {"src": "assets/catalog/vi/dove-02/anh-7.webp", "label": "Ảnh 7", "order": 7}]}}, {"id": "dove-03", "brandId": "dove", "brand": "Dove", "name": {"vi": "SỮA TẮM DOVE DA MỊN HƯƠNG HOA 900G", "en": "Dove Sakura Blossoms Body Wash 900g"}, "category": "Body care", "type": "Sữa tắm dưỡng thể", "size": "Chai 900g", "country": "Hoa Kỳ", "description": {"vi": "1. MÔ TẢ SẢN PHẨM\n\nTên sản phẩm: Sữa Tắm Dove Da Mịn Hương Hoa 900g\nThương hiệu: Dove\nQuốc gia thương hiệu: Hoa Kỳ\nQuy cách đóng gói: Chai 900g\nPhân loại: Sữa tắm dưỡng thể\n\nSữa Tắm Dove Da Mịn Hương Hoa 900g là dòng sữa tắm chăm sóc cơ thể với hương hoa anh đào. Sản phẩm được giới thiệu với chiết xuất hoa anh đào và muối hồng, giúp làm sạch da và mang lại cảm giác mềm mại, sạch thoáng cùng hương thơm nhẹ nhàng sau khi tắm.\n\n2. CÔNG DỤNG\n\n• Làm sạch bụi bẩn và mồ hôi trên cơ thể.\n• Hỗ trợ duy trì cảm giác mềm mịn của da.\n• Mang lại hương hoa anh đào dễ chịu.\n• Giúp da có cảm giác sạch thoáng sau khi tắm.\n\n3. THÀNH PHẦN\n\nCác thành phần nổi bật:\n\n• Chiết xuất hoa anh đào: Thành phần thực vật được giới thiệu trong dòng sản phẩm.\n• Muối hồng: Thành phần được nhấn mạnh trong giới thiệu sản phẩm.\n• Glycerin: Hỗ trợ giữ ẩm.\n• Sodium Cocoyl Isethionate: Chất làm sạch.\n• Hương liệu: Tạo mùi hương đặc trưng.\n\nLưu ý: Đây là các thành phần tiêu biểu, không thay thế bảng thành phần INCI đầy đủ trên bao bì. Công thức có thể thay đổi theo phiên bản.\n\n4. HƯỚNG DẪN SỬ DỤNG\n\n1. Làm ướt da cơ thể.\n2. Lấy lượng sữa tắm vừa đủ vào tay hoặc bông tắm.\n3. Tạo bọt và massage nhẹ nhàng.\n4. Tắm sạch lại bằng nước.\n\nLưu ý: Chỉ sử dụng ngoài da. Tránh tiếp xúc với mắt; nếu dính vào mắt, rửa kỹ bằng nước. Ngừng sử dụng nếu xuất hiện kích ứng kéo dài.\n\n5. ĐỐI TƯỢNG SỬ DỤNG\n\n• Người có nhu cầu làm sạch cơ thể hằng ngày.\n• Người yêu thích hương hoa anh đào.\n• Người muốn da mềm mại và thơm mát sau khi tắm.", "en": "1. PRODUCT DESCRIPTION\n\nDove Sakura Blossoms Body Wash is a daily body cleanser featuring cherry blossom extract and a floral fragrance. Its creamy foam gently removes sweat, dirt and everyday impurities while helping the skin feel soft and smooth. Inspired by the delicate scent of sakura blossoms, the formula provides a pleasant shower experience and leaves the skin feeling refreshed. The 900g format is suitable for regular use in a household body-care routine.\n\n2. BENEFITS\n\n• Cleanses the body gently and effectively.\n• Helps leave skin feeling soft and smooth.\n• Provides a delicate cherry blossom fragrance.\n• Creates a rich, creamy foam.\n• Supports a comfortable everyday shower routine.\n\n3. INGREDIENTS\n\nKey ingredients and their functions:\n\n• Prunus Serrulata Flower Extract: Cherry blossom extract used for skin conditioning.\n• Glycerin: A moisturizing humectant.\n• Cocamidopropyl Betaine: A cleansing surfactant.\n• Sodium Cocoyl Isethionate: Helps cleanse the skin.\n• Alpha-Glucan Oligosaccharide: A skin-conditioning ingredient.\n• Fragrance: Provides the product's floral scent.\n\nNote: These are selected ingredients or ingredient categories, not necessarily the complete INCI list. Verify the formula and labeling of the actual product before publication.\n\n4. DIRECTIONS FOR USE\n\n1. Wet the body thoroughly.\n2. Dispense the body wash onto the hands or a shower puff.\n3. Lather and massage gently over the skin.\n4. Rinse thoroughly with clean water.\n5. Use daily or as needed.\n\nPrecautions: For external use only. Avoid contact with eyes. If contact occurs, rinse thoroughly with water. Discontinue use if irritation occurs.\n\n5. SUITABLE FOR\n\n• People who enjoy floral fragrances.\n• Normal skin seeking everyday cleansing.\n• Individuals looking for a soft-skin body wash.\n• Those who prefer a cherry blossom-inspired shower experience."}, "image": "assets/catalog/product-dove-03.jpg", "gallery": {"vi": [{"src": "assets/catalog/vi/dove-03/thumbnail.webp", "label": "Thumbnail", "order": 0}, {"src": "assets/catalog/vi/dove-03/anh-1.webp", "label": "Ảnh 1", "order": 1}, {"src": "assets/catalog/vi/dove-03/anh-2.webp", "label": "Ảnh 2", "order": 2}, {"src": "assets/catalog/vi/dove-03/anh-3.webp", "label": "Ảnh 3", "order": 3}, {"src": "assets/catalog/vi/dove-03/anh-4.webp", "label": "Ảnh 4", "order": 4}, {"src": "assets/catalog/vi/dove-03/anh-5.webp", "label": "Ảnh 5", "order": 5}, {"src": "assets/catalog/vi/dove-03/anh-6.webp", "label": "Ảnh 6", "order": 6}, {"src": "assets/catalog/vi/dove-03/anh-7.webp", "label": "Ảnh 7", "order": 7}]}}, {"id": "dove-04", "brandId": "dove", "brand": "Dove", "name": {"vi": "SỮA TẮM SERUM DOVE PRO-CERAMIDE PAMPERING CARE 500G", "en": "Dove Pro-Ceramide Pampering Care Serum Body Wash 500g"}, "category": "Body care", "type": "Sữa tắm serum cho da khô", "size": "Chai 500g", "country": "Hoa Kỳ", "description": {"vi": "1. MÔ TẢ SẢN PHẨM\n\nTên sản phẩm: Sữa Tắm Serum Dove Pro-Ceramide Pampering Care 500g\nThương hiệu: Dove\nQuốc gia thương hiệu: Hoa Kỳ\nQuy cách đóng gói: Chai 500g\nPhân loại: Sữa tắm serum cho da khô\n\nSữa Tắm Serum Dove Pro-Ceramide Pampering Care 500g là sản phẩm làm sạch và dưỡng ẩm cơ thể dành cho nhu cầu chăm sóc da khô. Công thức được giới thiệu với Pro-Ceramide, bơ hạt mỡ và hương vanilla, giúp hỗ trợ hàng rào độ ẩm của da, mang lại cảm giác mềm mại, ẩm mượt sau khi tắm.\n\n2. CÔNG DỤNG\n\n• Làm sạch da cơ thể hằng ngày.\n• Hỗ trợ bổ sung và duy trì độ ẩm cho da khô.\n• Giúp hạn chế cảm giác khô căng.\n• Hỗ trợ chăm sóc hàng rào bảo vệ da.\n• Mang lại hương vanilla dễ chịu.\n\n3. THÀNH PHẦN\n\nCác thành phần nổi bật:\n\n• Ceramide NP, Ceramide AP và Ceramide EOP: Các ceramide hỗ trợ hàng rào bảo vệ da.\n• Bơ hạt mỡ (Shea Butter): Hỗ trợ làm mềm da.\n• Glycerin: Thành phần hút ẩm.\n• Phytosphingosine và Cholesterol: Các thành phần lipid chăm sóc da.\n• Sodium Cocoyl Isethionate: Chất làm sạch.\n\nLưu ý: Đây là các thành phần tiêu biểu, không thay thế bảng thành phần INCI đầy đủ trên bao bì. Công thức có thể thay đổi theo phiên bản.\n\n4. HƯỚNG DẪN SỬ DỤNG\n\n1. Làm ướt cơ thể.\n2. Lấy lượng sữa tắm vừa đủ vào tay hoặc bông tắm.\n3. Tạo bọt và massage nhẹ nhàng lên da.\n4. Tắm sạch lại bằng nước.\n\nLưu ý: Chỉ sử dụng ngoài da. Tránh tiếp xúc với mắt; nếu dính vào mắt, rửa kỹ bằng nước. Ngừng sử dụng nếu xuất hiện kích ứng kéo dài.\n\n5. ĐỐI TƯỢNG SỬ DỤNG\n\n• Người có da cơ thể khô, dễ khô căng.\n• Người muốn làm sạch kết hợp dưỡng ẩm.\n• Người cần chăm sóc hàng rào độ ẩm của da.", "en": "1. PRODUCT DESCRIPTION\n\nDove Pro-Ceramide Pampering Care Serum Body Wash is a moisturizing body cleanser developed to care for dry-feeling skin during showering. Featuring Dove's Pro-Ceramide serum concept, the formula combines ceramide-related ingredients with shea butter to support skin softness and moisture-barrier care. Its creamy lather cleanses everyday impurities while leaving a comfortable, nourished skin feel. The warm vanilla fragrance creates a pampering shower experience, making the product particularly appealing to people who enjoy rich, comforting body-care scents.\n\n2. BENEFITS\n\n• Gently cleanses the body without excessive rubbing.\n• Helps improve the feel of dry, rough skin.\n• Supports the skin's moisture barrier.\n• Leaves skin feeling soft and conditioned.\n• Provides a comforting vanilla fragrance.\n• Combines body cleansing with moisturizing care.\n\n3. INGREDIENTS\n\nKey ingredients and their functions:\n\n• Ceramide NP, Ceramide AP and Ceramide EOP: Skin-identical lipids associated with barrier-supporting care.\n• Butyrospermum Parkii (Shea) Butter: An emollient that helps soften dry skin.\n• Glycerin: A humectant that helps retain moisture.\n• Cholesterol: A lipid component used in barrier-care formulations.\n• Phytosphingosine: A lipid-related skin-conditioning ingredient.\n• Sodium Cocoyl Isethionate: A cleansing surfactant.\n\nNote: These are selected ingredients or ingredient categories, not necessarily the complete INCI list. Verify the formula and labeling of the actual product before publication.\n\n4. DIRECTIONS FOR USE\n\n1. Wet the body with water.\n2. Apply an appropriate amount to the palms or shower puff.\n3. Work into a soft lather and massage gently over the body.\n4. Rinse thoroughly.\n5. Use daily and follow with body moisturizer when needed.\n\nPrecautions: For external use only. Avoid contact with eyes. If contact occurs, rinse thoroughly with water. Discontinue use if irritation occurs.\n\n5. SUITABLE FOR\n\n• Dry or rough-feeling skin.\n• People looking for moisturizing body cleansing.\n• Individuals who enjoy vanilla-inspired fragrances.\n• Those seeking ceramide-related body-care ingredients."}, "image": "assets/catalog/product-dove-04.jpg", "gallery": {"vi": [{"src": "assets/catalog/vi/dove-04/thumbnail.webp", "label": "Thumbnail", "order": 0}, {"src": "assets/catalog/vi/dove-04/anh-1.webp", "label": "Ảnh 1", "order": 1}, {"src": "assets/catalog/vi/dove-04/anh-2.webp", "label": "Ảnh 2", "order": 2}, {"src": "assets/catalog/vi/dove-04/anh-3.webp", "label": "Ảnh 3", "order": 3}, {"src": "assets/catalog/vi/dove-04/anh-4.webp", "label": "Ảnh 4", "order": 4}, {"src": "assets/catalog/vi/dove-04/anh-5.webp", "label": "Ảnh 5", "order": 5}, {"src": "assets/catalog/vi/dove-04/anh-6.webp", "label": "Ảnh 6", "order": 6}, {"src": "assets/catalog/vi/dove-04/anh-7.webp", "label": "Ảnh 7", "order": 7}]}}, {"id": "dove-05", "brandId": "dove", "brand": "Dove", "name": {"vi": "SỮA TẮM SERUM DOVE PRO-CERAMIDE SENSITIVE RELIEF 500G", "en": "Dove Pro-Ceramide Sensitive Relief Serum Body Wash 500g"}, "category": "Body care", "type": "Sữa tắm serum cho da nhạy cảm", "size": "Chai 500g", "country": "Hoa Kỳ", "description": {"vi": "1. MÔ TẢ SẢN PHẨM\n\nTên sản phẩm: Sữa Tắm Serum Dove Pro-Ceramide Sensitive Relief 500g\nThương hiệu: Dove\nQuốc gia thương hiệu: Hoa Kỳ\nQuy cách đóng gói: Chai 500g\nPhân loại: Sữa tắm serum cho da nhạy cảm\n\nSữa Tắm Serum Dove Pro-Ceramide Sensitive Relief 500g là sản phẩm làm sạch cơ thể hướng đến nhu cầu chăm sóc da nhạy cảm. Công thức kết hợp các thành phần làm sạch với ceramide và chất giữ ẩm, giúp duy trì cảm giác mềm mại, dễ chịu và hỗ trợ hàng rào bảo vệ da sau khi tắm.\n\n2. CÔNG DỤNG\n\n• Làm sạch da cơ thể.\n• Hỗ trợ duy trì độ ẩm tự nhiên.\n• Giúp hạn chế cảm giác khô căng sau khi tắm.\n• Hỗ trợ chăm sóc hàng rào bảo vệ da.\n• Mang lại cảm giác mềm mại.\n\n3. THÀNH PHẦN\n\nCác thành phần nổi bật:\n\n• Ceramide NP, Ceramide AP và Ceramide EOP: Hỗ trợ hàng rào bảo vệ da.\n• Glycerin: Hỗ trợ giữ ẩm.\n• Phytosphingosine và Cholesterol: Các thành phần lipid chăm sóc da.\n• Cocamidopropyl Betaine và Sodium Cocoyl Isethionate: Chất làm sạch.\n• Perfume: Thành phần tạo hương được ghi nhận trong công thức sản phẩm.\n\nLưu ý: Đây là các thành phần tiêu biểu, không thay thế bảng thành phần INCI đầy đủ trên bao bì. Công thức có thể thay đổi theo phiên bản.\n\n4. HƯỚNG DẪN SỬ DỤNG\n\n1. Làm ướt cơ thể.\n2. Lấy lượng sữa tắm vừa đủ, tạo bọt.\n3. Massage nhẹ nhàng, không chà xát mạnh.\n4. Xả sạch với nước. Người có da rất nhạy cảm nên thử trên vùng da nhỏ trước khi dùng.\n\nLưu ý: Chỉ sử dụng ngoài da. Tránh tiếp xúc với mắt; nếu dính vào mắt, rửa kỹ bằng nước. Ngừng sử dụng nếu xuất hiện kích ứng kéo dài.\n\n5. ĐỐI TƯỢNG SỬ DỤNG\n\n• Người có làn da nhạy cảm.\n• Người có da dễ khô căng.\n• Người muốn sữa tắm chứa thành phần hỗ trợ hàng rào độ ẩm.", "en": "1. PRODUCT DESCRIPTION\n\nDove Pro-Ceramide Sensitive Relief Serum Body Wash is a body cleanser developed with the needs of sensitive skin in mind. Its Pro-Ceramide formula includes ceramide-related skin-conditioning ingredients and gentle cleansing agents to help remove everyday impurities while supporting a comfortable skin feel. The product is intended for daily cleansing when skin requires additional attention to dryness and moisture-barrier care. The formula should not be described as fragrance-free without checking the actual packaging, as the published ingredient list includes perfume.\n\n2. BENEFITS\n\n• Gently cleanses sweat and everyday impurities.\n• Supports the skin's moisture barrier.\n• Helps maintain softness and hydration.\n• Provides a comfortable bathing experience for sensitive skin.\n• Offers ceramide-related skin-conditioning care.\n\n3. INGREDIENTS\n\nKey ingredients and their functions:\n\n• Ceramide NP, Ceramide AP and Ceramide EOP: Barrier-supporting lipid ingredients.\n• Glycerin: A moisturizing humectant.\n• Cholesterol: A skin-conditioning lipid.\n• Phytosphingosine: A component used in ceramide-related formulations.\n• Cocamidopropyl Betaine: A cleansing and foaming ingredient.\n• Perfume: Listed in the published formulation; fragrance-sensitive users should review the label.\n\nNote: These are selected ingredients or ingredient categories, not necessarily the complete INCI list. Verify the formula and labeling of the actual product before publication.\n\n4. DIRECTIONS FOR USE\n\n1. Wet the body thoroughly.\n2. Apply a small amount to the palms or a soft shower puff.\n3. Lather and massage gently without scrubbing.\n4. Rinse completely with water.\n5. Pat dry and apply a suitable moisturizer if needed.\n\nPrecautions: For external use only. Avoid contact with eyes. If contact occurs, rinse thoroughly with water. Discontinue use if irritation occurs.\n\n5. SUITABLE FOR\n\n• Sensitive skin requiring gentle daily cleansing.\n• People with dry or easily uncomfortable skin.\n• Individuals seeking ceramide-related body care.\n• Those who prefer moisturizing shower products."}, "image": "assets/catalog/product-dove-05.jpg", "gallery": {"vi": [{"src": "assets/catalog/vi/dove-05/thumbnail.webp", "label": "Thumbnail", "order": 0}, {"src": "assets/catalog/vi/dove-05/anh-1.webp", "label": "Ảnh 1", "order": 1}, {"src": "assets/catalog/vi/dove-05/anh-2.webp", "label": "Ảnh 2", "order": 2}, {"src": "assets/catalog/vi/dove-05/anh-3.webp", "label": "Ảnh 3", "order": 3}, {"src": "assets/catalog/vi/dove-05/anh-4.webp", "label": "Ảnh 4", "order": 4}, {"src": "assets/catalog/vi/dove-05/anh-5.webp", "label": "Ảnh 5", "order": 5}, {"src": "assets/catalog/vi/dove-05/anh-6.webp", "label": "Ảnh 6", "order": 6}, {"src": "assets/catalog/vi/dove-05/anh-7.webp", "label": "Ảnh 7", "order": 7}]}}, {"id": "dove-06", "brandId": "dove", "brand": "Dove", "name": {"vi": "SỮA TẮM SERUM DOVE PRO-CERAMIDE INVIGORATING 500G", "en": "Dove Pro-Ceramide Invigorating Serum Body Wash 500g"}, "category": "Body care", "type": "Sữa tắm serum tươi mát", "size": "Chai 500g", "country": "Hoa Kỳ", "description": {"vi": "1. MÔ TẢ SẢN PHẨM\n\nTên sản phẩm: Sữa Tắm Serum Dove Pro-Ceramide Invigorating 500g\nThương hiệu: Dove\nQuốc gia thương hiệu: Hoa Kỳ\nQuy cách đóng gói: Chai 500g\nPhân loại: Sữa tắm serum tươi mát\n\nSữa Tắm Serum Dove Pro-Ceramide Invigorating 500g là dòng sữa tắm kết hợp khả năng làm sạch với các thành phần dưỡng ẩm và chăm sóc da. Công thức được giới thiệu với Pro-Ceramide, dầu bơ và chiết xuất hoa cúc Calendula, giúp da có cảm giác mềm mịn, sạch thoáng và tươi mát sau khi tắm.\n\n2. CÔNG DỤNG\n\n• Làm sạch bụi bẩn và mồ hôi.\n• Hỗ trợ duy trì độ ẩm cho da.\n• Giúp da mềm mại, hạn chế khô căng.\n• Hỗ trợ chăm sóc hàng rào bảo vệ da.\n• Mang lại cảm giác tươi mát, sảng khoái.\n\n3. THÀNH PHẦN\n\nCác thành phần nổi bật:\n\n• Ceramide NP, Ceramide AP và Ceramide EOP: Hỗ trợ hàng rào bảo vệ da.\n• Dầu bơ (Avocado Oil): Hỗ trợ làm mềm da.\n• Chiết xuất hoa cúc Calendula: Thành phần thực vật chăm sóc da.\n• Glycerin: Hỗ trợ giữ ẩm.\n• Tocopherol: Thành phần chống oxy hóa.\n\nLưu ý: Đây là các thành phần tiêu biểu, không thay thế bảng thành phần INCI đầy đủ trên bao bì. Công thức có thể thay đổi theo phiên bản.\n\n4. HƯỚNG DẪN SỬ DỤNG\n\n1. Làm ướt cơ thể.\n2. Lấy lượng sữa tắm vừa đủ.\n3. Tạo bọt và massage nhẹ nhàng toàn thân.\n4. Tắm sạch lại bằng nước.\n\nLưu ý: Chỉ sử dụng ngoài da. Tránh tiếp xúc với mắt; nếu dính vào mắt, rửa kỹ bằng nước. Ngừng sử dụng nếu xuất hiện kích ứng kéo dài.\n\n5. ĐỐI TƯỢNG SỬ DỤNG\n\n• Người cần sữa tắm sử dụng hằng ngày.\n• Người yêu thích cảm giác tươi mát.\n• Người muốn làm sạch kết hợp chăm sóc độ ẩm cho da.", "en": "1. PRODUCT DESCRIPTION\n\nDove Pro-Ceramide Invigorating Serum Body Wash is a refreshing body cleanser combining Dove's Pro-Ceramide serum concept with avocado oil and calendula flower extract. The formula helps remove daily impurities while providing skin-conditioning care and a pleasant fresh fragrance. Ceramide-related ingredients support the skin's moisture barrier, while the creamy cleansing texture helps leave the body feeling soft and comfortable after showering. It is suitable for people seeking both a refreshing sensory experience and moisturizing body care.\n\n2. BENEFITS\n\n• Gently removes dirt, sweat and daily impurities.\n• Supports the skin's moisture barrier.\n• Helps maintain a soft and smooth skin feel.\n• Provides a refreshing fragrance.\n• Combines moisturizing care with everyday cleansing.\n\n3. INGREDIENTS\n\nKey ingredients and their functions:\n\n• Ceramide NP, Ceramide AP and Ceramide EOP: Lipid ingredients associated with moisture-barrier support.\n• Persea Gratissima (Avocado) Oil: A plant-derived emollient.\n• Calendula Officinalis Flower Extract: A botanical skin-conditioning ingredient.\n• Glycerin: Helps attract and retain moisture.\n• Cholesterol and Phytosphingosine: Lipid-related skin-conditioning ingredients.\n• Tocopherol: An antioxidant form of vitamin E.\n\nNote: These are selected ingredients or ingredient categories, not necessarily the complete INCI list. Verify the formula and labeling of the actual product before publication.\n\n4. DIRECTIONS FOR USE\n\n1. Wet the body with clean water.\n2. Dispense a suitable amount of body wash.\n3. Massage gently to create a creamy lather.\n4. Rinse thoroughly with water.\n5. Use as part of the daily shower routine.\n\nPrecautions: For external use only. Avoid contact with eyes. If contact occurs, rinse thoroughly with water. Discontinue use if irritation occurs.\n\n5. SUITABLE FOR\n\n• People who prefer refreshing body-wash fragrances.\n• Normal to dry skin seeking moisturizing cleansing.\n• Individuals interested in ceramide-related body care.\n• Those looking for a refreshing daily shower product."}, "image": "assets/catalog/product-dove-06.jpg", "gallery": {"vi": [{"src": "assets/catalog/vi/dove-06/thumbnail.webp", "label": "Thumbnail", "order": 0}, {"src": "assets/catalog/vi/dove-06/anh-1.webp", "label": "Ảnh 1", "order": 1}, {"src": "assets/catalog/vi/dove-06/anh-2.webp", "label": "Ảnh 2", "order": 2}, {"src": "assets/catalog/vi/dove-06/anh-3.webp", "label": "Ảnh 3", "order": 3}, {"src": "assets/catalog/vi/dove-06/anh-4.webp", "label": "Ảnh 4", "order": 4}, {"src": "assets/catalog/vi/dove-06/anh-5.webp", "label": "Ảnh 5", "order": 5}, {"src": "assets/catalog/vi/dove-06/anh-6.webp", "label": "Ảnh 6", "order": 6}, {"src": "assets/catalog/vi/dove-06/anh-7.webp", "label": "Ảnh 7", "order": 7}]}}, {"id": "dove-07", "brandId": "dove", "brand": "Dove", "name": {"vi": "DẦU GỘI DOVE PHỤC HỒI HƯ TỔN 325G", "en": "Dove Damage Repair Shampoo 325g"}, "category": "Haircare", "type": "Dầu gội chăm sóc tóc hư tổn", "size": "Chai 325g", "country": "Hoa Kỳ", "description": {"vi": "1. MÔ TẢ SẢN PHẨM\n\nTên sản phẩm: Dầu Gội Dove Phục Hồi Hư Tổn 325g\nThương hiệu: Dove\nQuốc gia thương hiệu: Hoa Kỳ\nQuy cách đóng gói: Chai 325g\nPhân loại: Dầu gội chăm sóc tóc hư tổn\n\nDầu Gội Dove Phục Hồi Hư Tổn 325g là sản phẩm làm sạch và chăm sóc mái tóc khô xơ, dễ rối và có dấu hiệu hư tổn do tạo kiểu hoặc tác động môi trường. Công thức kết hợp các thành phần làm sạch với chất dưỡng tóc, giúp tóc có cảm giác mềm mượt và dễ chải hơn sau khi gội.\n\n2. CÔNG DỤNG\n\n• Làm sạch tóc và da đầu.\n• Hỗ trợ giảm cảm giác khô xơ và rối tóc.\n• Giúp tóc mềm mại, dễ chải.\n• Hỗ trợ cải thiện vẻ ngoài của tóc hư tổn.\n\n3. THÀNH PHẦN\n\nCác thành phần nổi bật:\n\n• Sodium Laureth Sulfate: Chất làm sạch thường gặp trong công thức dầu gội.\n• Cocamidopropyl Betaine: Hỗ trợ làm sạch và tạo bọt.\n• Dimethiconol: Thành phần làm mượt tóc.\n• Glycerin: Hỗ trợ giữ ẩm.\n• Các thành phần dưỡng tóc khác cần đối chiếu theo bảng INCI của phiên bản 325g.\n\nLưu ý: Đây là các thành phần tiêu biểu, không thay thế bảng thành phần INCI đầy đủ trên bao bì. Công thức có thể thay đổi theo phiên bản.\n\n4. HƯỚNG DẪN SỬ DỤNG\n\n1. Làm ướt tóc và da đầu.\n2. Lấy lượng dầu gội vừa đủ, massage nhẹ nhàng.\n3. Xả sạch lại với nước.\n4. Có thể sử dụng tiếp kem xả Dove Phục Hồi Hư Tổn.\n\nLưu ý: Chỉ sử dụng ngoài da. Tránh tiếp xúc với mắt; nếu dính vào mắt, rửa kỹ bằng nước. Ngừng sử dụng nếu xuất hiện kích ứng kéo dài.\n\n5. ĐỐI TƯỢNG SỬ DỤNG\n\n• Người có tóc khô xơ, dễ rối.\n• Người có tóc hư tổn do tạo kiểu hoặc nhiệt.\n• Người muốn chăm sóc tóc hằng ngày.", "en": "1. PRODUCT DESCRIPTION\n\nDove Damage Repair Shampoo is a daily hair cleanser developed for hair that feels dry, rough or weakened by styling and environmental exposure. Its cleansing formula removes excess oil and accumulated impurities from the scalp while helping the hair feel smoother and more manageable. The product is intended to complement a damage-care routine, especially for hair affected by frequent brushing, heat styling or chemical treatments. Regular use with a matching conditioner can help improve the cosmetic appearance and feel of damaged hair.\n\n2. BENEFITS\n\n• Cleanses the scalp and hair.\n• Helps improve the feel of dry and rough hair.\n• Supports smoother-looking hair lengths.\n• Helps reduce tangling during the hair-care routine.\n• Prepares hair for conditioning and additional care.\n\n3. INGREDIENTS\n\nKey ingredients and their functions:\n\n• Cleansing Surfactants: Remove oil and impurities from the scalp and hair.\n• Conditioning Agents: Help improve hair smoothness and manageability.\n• Silicone-Based Ingredients: May help reduce friction between hair fibers.\n• Fragrance: Provides the shampoo's scent.\n• The exact ingredients of the 325g Vietnam-market formula require verification against the product label.\n\nNote: These are selected ingredients or ingredient categories, not necessarily the complete INCI list. Verify the formula and labeling of the actual product before publication.\n\n4. DIRECTIONS FOR USE\n\n1. Wet the hair and scalp thoroughly.\n2. Apply a suitable amount of shampoo to the scalp.\n3. Massage gently using the fingertips.\n4. Work the foam through the hair lengths.\n5. Rinse thoroughly with water.\n6. Follow with Dove Damage Repair Conditioner.\n\nPrecautions: For external use only. Avoid contact with eyes. If contact occurs, rinse thoroughly with water. Discontinue use if irritation occurs.\n\n5. SUITABLE FOR\n\n• Dry, rough or damaged-looking hair.\n• Hair exposed to frequent heat styling.\n• People seeking a daily shampoo for damaged hair.\n• Individuals wanting smoother, more manageable hair."}, "image": "assets/catalog/product-dove-07.jpg", "gallery": {"vi": [{"src": "assets/catalog/vi/dove-07/thumbnail.webp", "label": "Thumbnail", "order": 0}, {"src": "assets/catalog/vi/dove-07/anh-1.webp", "label": "Ảnh 1", "order": 1}, {"src": "assets/catalog/vi/dove-07/anh-2.webp", "label": "Ảnh 2", "order": 2}, {"src": "assets/catalog/vi/dove-07/anh-3.webp", "label": "Ảnh 3", "order": 3}, {"src": "assets/catalog/vi/dove-07/anh-4.webp", "label": "Ảnh 4", "order": 4}, {"src": "assets/catalog/vi/dove-07/anh-5.webp", "label": "Ảnh 5", "order": 5}, {"src": "assets/catalog/vi/dove-07/anh-6.webp", "label": "Ảnh 6", "order": 6}, {"src": "assets/catalog/vi/dove-07/anh-7.webp", "label": "Ảnh 7", "order": 7}]}}, {"id": "dove-08", "brandId": "dove", "brand": "Dove", "name": {"vi": "DẦU GỘI DOVE NGĂN GÃY RỤNG TÓC 325G", "en": "Dove Hair Fall Rescue Shampoo 325g"}, "category": "Haircare", "type": "Dầu gội chăm sóc tóc dễ gãy", "size": "Chai 325g", "country": "Hoa Kỳ", "description": {"vi": "1. MÔ TẢ SẢN PHẨM\n\nTên sản phẩm: Dầu Gội Dove Ngăn Gãy Rụng Tóc 325g\nThương hiệu: Dove\nQuốc gia thương hiệu: Hoa Kỳ\nQuy cách đóng gói: Chai 325g\nPhân loại: Dầu gội chăm sóc tóc dễ gãy\n\nDầu Gội Dove Ngăn Gãy Rụng Tóc 325g là sản phẩm làm sạch và chăm sóc tóc dễ gãy do khô xơ, hư tổn. Công thức được giới thiệu với các thành phần dưỡng tóc, giúp sợi tóc mềm mại, dễ chải và hỗ trợ hạn chế tình trạng gãy tóc do ma sát trong quá trình chăm sóc.\n\n2. CÔNG DỤNG\n\n• Làm sạch tóc và da đầu.\n• Hỗ trợ giảm gãy tóc do khô xơ, rối tóc.\n• Giúp tóc mềm mượt và dễ chải.\n• Hỗ trợ chăm sóc sợi tóc yếu, dễ hư tổn.\n\n3. THÀNH PHẦN\n\nCác thành phần nổi bật:\n\n• Dầu hạt hướng dương: Thành phần dưỡng tóc được giới thiệu trong dòng sản phẩm.\n• Chiết xuất lá trà xanh: Thành phần thực vật chăm sóc tóc.\n• Dimethiconol: Hỗ trợ làm mượt sợi tóc.\n• Glycerin: Hỗ trợ giữ ẩm.\n• Hệ chất làm sạch cần đối chiếu theo bảng INCI trên nhãn phiên bản 325g.\n\nLưu ý: Đây là các thành phần tiêu biểu, không thay thế bảng thành phần INCI đầy đủ trên bao bì. Công thức có thể thay đổi theo phiên bản.\n\n4. HƯỚNG DẪN SỬ DỤNG\n\n1. Làm ướt tóc.\n2. Lấy lượng dầu gội vừa đủ, massage nhẹ lên tóc và da đầu.\n3. Xả sạch với nước.\n4. Kết hợp kem xả ở thân và ngọn tóc nếu cần.\n\nLưu ý: Chỉ sử dụng ngoài da. Tránh tiếp xúc với mắt; nếu dính vào mắt, rửa kỹ bằng nước. Ngừng sử dụng nếu xuất hiện kích ứng kéo dài.\n\n5. ĐỐI TƯỢNG SỬ DỤNG\n\n• Người có tóc yếu, dễ gãy khi chải.\n• Người có tóc khô xơ, dễ rối.\n• Người cần chăm sóc tóc dễ hư tổn.\n\nLưu ý: Sản phẩm chăm sóc tóc gãy do hư tổn, không phải thuốc điều trị rụng tóc do bệnh lý.", "en": "1. PRODUCT DESCRIPTION\n\nDove Hair Fall Rescue Shampoo is a hair cleanser designed for hair that is prone to breakage during washing, brushing or styling. Its formula removes excess scalp oil and everyday impurities while providing conditioning care to help hair feel smoother and less prone to tangling. The product focuses on the cosmetic care of weakened hair fibers and breakage-related hair fall; it should not be described as a treatment for medical hair loss or scalp disorders.\n\n2. BENEFITS\n\n• Cleanses hair and scalp effectively.\n• Helps improve the feel of weakened hair.\n• Supports smoother and more manageable hair.\n• Helps reduce tangling that may contribute to breakage.\n• Complements a hair-care routine for breakage-prone lengths.\n\n3. INGREDIENTS\n\nKey ingredients and their functions:\n\n• Cleansing Surfactants: Help remove scalp oil and impurities.\n• Hair-Conditioning Agents: Support smoothness and manageability.\n• Film-Forming Ingredients: May help reduce friction between hair strands.\n• Fragrance: Provides the product's scent.\n• Specific actives and the full INCI list for the 325g variant must be checked against the packaging.\n\nNote: These are selected ingredients or ingredient categories, not necessarily the complete INCI list. Verify the formula and labeling of the actual product before publication.\n\n4. DIRECTIONS FOR USE\n\n1. Wet the scalp and hair thoroughly.\n2. Apply a suitable amount of shampoo.\n3. Massage gently into the scalp without scratching.\n4. Rinse thoroughly with water.\n5. Follow with a conditioner, focusing on the mid-lengths and ends.\n6. Avoid rough towel-drying and excessive pulling on wet hair.\n\nPrecautions: For external use only. Avoid contact with eyes. If contact occurs, rinse thoroughly with water. Discontinue use if irritation occurs.\n\n5. SUITABLE FOR\n\n• Hair prone to breakage.\n• Individuals experiencing hair fall associated with broken strands.\n• People whose hair tangles easily.\n• Those seeking a daily shampoo for weakened hair lengths."}, "image": "assets/catalog/product-dove-08.jpg", "gallery": {"vi": [{"src": "assets/catalog/vi/dove-08/thumbnail.webp", "label": "Thumbnail", "order": 0}, {"src": "assets/catalog/vi/dove-08/anh-1.webp", "label": "Ảnh 1", "order": 1}, {"src": "assets/catalog/vi/dove-08/anh-2.webp", "label": "Ảnh 2", "order": 2}, {"src": "assets/catalog/vi/dove-08/anh-3.webp", "label": "Ảnh 3", "order": 3}, {"src": "assets/catalog/vi/dove-08/anh-4.webp", "label": "Ảnh 4", "order": 4}, {"src": "assets/catalog/vi/dove-08/anh-5.webp", "label": "Ảnh 5", "order": 5}, {"src": "assets/catalog/vi/dove-08/anh-6.webp", "label": "Ảnh 6", "order": 6}, {"src": "assets/catalog/vi/dove-08/anh-7.webp", "label": "Ảnh 7", "order": 7}]}}, {"id": "dove-09", "brandId": "dove", "brand": "Dove", "name": {"vi": "KEM XẢ DOVE PHỤC HỒI HƯ TỔN 320G", "en": "Dove Damage Repair Conditioner 320g"}, "category": "Haircare", "type": "Kem xả chăm sóc tóc hư tổn", "size": "Chai 320g", "country": "Hoa Kỳ", "description": {"vi": "1. MÔ TẢ SẢN PHẨM\n\nTên sản phẩm: Kem Xả Dove Phục Hồi Hư Tổn 320g\nThương hiệu: Dove\nQuốc gia thương hiệu: Hoa Kỳ\nQuy cách đóng gói: Chai 320g\nPhân loại: Kem xả chăm sóc tóc hư tổn\n\nKem Xả Dove Phục Hồi Hư Tổn 320g là sản phẩm chăm sóc tóc sử dụng sau khi gội, dành cho mái tóc khô xơ, dễ rối và có dấu hiệu hư tổn. Công thức chứa các thành phần làm mềm và dưỡng tóc, giúp sợi tóc suôn mượt, dễ chải và giảm ma sát khi chải tóc.\n\n2. CÔNG DỤNG\n\n• Làm mềm tóc sau khi gội.\n• Hỗ trợ giảm rối và gãy tóc khi chải.\n• Giúp tóc suôn mượt, dễ vào nếp.\n• Hỗ trợ chăm sóc thân và ngọn tóc khô xơ.\n\n3. THÀNH PHẦN\n\nCác thành phần nổi bật:\n\n• Cetearyl Alcohol: Thành phần làm mềm tóc.\n• Behentrimonium Chloride: Thành phần dưỡng tóc và hỗ trợ gỡ rối.\n• Glycerin: Hỗ trợ giữ ẩm.\n• Các thành phần silicone dưỡng tóc: Hỗ trợ làm mượt sợi tóc.\n• Bảng INCI chính xác cần đối chiếu trên nhãn phiên bản 320g.\n\nLưu ý: Đây là các thành phần tiêu biểu, không thay thế bảng thành phần INCI đầy đủ trên bao bì. Công thức có thể thay đổi theo phiên bản.\n\n4. HƯỚNG DẪN SỬ DỤNG\n\n1. Sau khi gội, xả sạch dầu gội trên tóc.\n2. Lấy lượng kem xả vừa đủ, thoa từ thân đến ngọn tóc.\n3. Để khoảng 1–3 phút hoặc theo hướng dẫn trên bao bì.\n4. Xả sạch lại bằng nước.\n\nLưu ý: Chỉ sử dụng ngoài da. Tránh tiếp xúc với mắt; nếu dính vào mắt, rửa kỹ bằng nước. Ngừng sử dụng nếu xuất hiện kích ứng kéo dài.\n\n5. ĐỐI TƯỢNG SỬ DỤNG\n\n• Người có tóc khô xơ, dễ rối.\n• Người có tóc hư tổn do tạo kiểu.\n• Người cần kem xả làm mềm tóc sau khi gội.", "en": "1. PRODUCT DESCRIPTION\n\nDove Damage Repair Conditioner is a rinse-off hair-conditioning product designed to improve the softness, smoothness and manageability of damaged-looking hair. Used after shampooing, the conditioner coats and conditions the hair lengths, helping reduce friction and make detangling easier. It is particularly suitable for hair that feels rough or dry due to styling, brushing and environmental exposure. Pairing the conditioner with a suitable shampoo helps complete a regular damage-care routine.\n\n2. BENEFITS\n\n• Helps soften dry and rough hair.\n• Improves the feel and manageability of hair lengths.\n• Helps reduce tangling and friction during combing.\n• Leaves hair looking smoother and more conditioned.\n• Complements a routine for damaged-looking hair.\n\n3. INGREDIENTS\n\nKey ingredients and their functions:\n\n• Cationic Conditioning Agents: Help smooth and detangle hair.\n• Fatty Alcohols: Support the creamy conditioner texture and soften hair.\n• Silicone-Based Conditioning Ingredients: May help improve smoothness and reduce friction.\n• Emollients: Help condition dry hair lengths.\n• The specific ingredients of the 320g variant require verification against its packaging.\n\nNote: These are selected ingredients or ingredient categories, not necessarily the complete INCI list. Verify the formula and labeling of the actual product before publication.\n\n4. DIRECTIONS FOR USE\n\n1. Shampoo the hair and rinse thoroughly.\n2. Gently squeeze out excess water.\n3. Apply conditioner to the mid-lengths and ends.\n4. Distribute evenly using fingers or a wide-tooth comb.\n5. Leave on for the time stated on the label.\n6. Rinse thoroughly with water.\n\nPrecautions: For external use only. Avoid contact with eyes. If contact occurs, rinse thoroughly with water. Discontinue use if irritation occurs.\n\n5. SUITABLE FOR\n\n• Dry or damaged-looking hair.\n• Hair that tangles easily.\n• People using heat-styling tools regularly.\n• Individuals seeking softer and more manageable hair."}, "image": "assets/catalog/product-dove-09.jpg", "gallery": {"vi": [{"src": "assets/catalog/vi/dove-09/thumbnail.webp", "label": "Thumbnail", "order": 0}, {"src": "assets/catalog/vi/dove-09/anh-1.webp", "label": "Ảnh 1", "order": 1}, {"src": "assets/catalog/vi/dove-09/anh-1-ban-2.webp", "label": "Ảnh 1 (bản 2)", "order": 1}, {"src": "assets/catalog/vi/dove-09/anh-2.webp", "label": "Ảnh 2", "order": 2}, {"src": "assets/catalog/vi/dove-09/anh-3.webp", "label": "Ảnh 3", "order": 3}, {"src": "assets/catalog/vi/dove-09/anh-5.webp", "label": "Ảnh 5", "order": 5}, {"src": "assets/catalog/vi/dove-09/anh-6.webp", "label": "Ảnh 6", "order": 6}, {"src": "assets/catalog/vi/dove-09/anh-7.webp", "label": "Ảnh 7", "order": 7}]}}, {"id": "dove-10", "brandId": "dove", "brand": "Dove", "name": {"vi": "KEM XẢ DOVE 1 PHÚT SIÊU DƯỠNG PHỤC HỒI HƯ TỔN 180ML", "en": "Dove 1 Minute Super Nourishing Damage Repair Conditioner 180ml"}, "category": "Haircare", "type": "Kem xả dưỡng tóc chuyên sâu", "size": "Tuýp 180ml", "country": "Hoa Kỳ", "description": {"vi": "1. MÔ TẢ SẢN PHẨM\n\nTên sản phẩm: Kem Xả Dove 1 Phút Siêu Dưỡng Phục Hồi Hư Tổn 180ml\nThương hiệu: Dove\nQuốc gia thương hiệu: Hoa Kỳ\nQuy cách đóng gói: Tuýp 180ml\nPhân loại: Kem xả dưỡng tóc chuyên sâu\n\nKem Xả Dove 1 Phút Siêu Dưỡng Phục Hồi Hư Tổn 180ml là sản phẩm chăm sóc tóc sau bước gội, hướng đến mái tóc khô xơ và hư tổn. Với thời gian dưỡng xả khoảng 1 phút, sản phẩm giúp tóc mềm mại, dễ chải và có cảm giác suôn mượt mà không cần thời gian ủ kéo dài.\n\n2. CÔNG DỤNG\n\n• Hỗ trợ chăm sóc tóc khô xơ, hư tổn.\n• Giúp tóc mềm mượt, dễ chải.\n• Hỗ trợ giảm rối và gãy tóc khi chải.\n• Tiết kiệm thời gian với bước dưỡng xả khoảng 1 phút.\n\n3. THÀNH PHẦN\n\nCác thành phần nổi bật:\n\n• Vitamin E: Thành phần chăm sóc tóc được giới thiệu trong dòng sản phẩm.\n• Dầu Argan: Hỗ trợ làm mềm tóc.\n• Dầu dừa: Thành phần dưỡng tóc.\n• Các chất dưỡng và làm mượt tóc khác cần được xác nhận theo bảng INCI trên bao bì 180ml.\n\nLưu ý: Đây là các thành phần tiêu biểu, không thay thế bảng thành phần INCI đầy đủ trên bao bì. Công thức có thể thay đổi theo phiên bản.\n\n4. HƯỚNG DẪN SỬ DỤNG\n\n1. Gội sạch tóc và xả hết dầu gội.\n2. Thoa lượng kem xả vừa đủ lên thân và ngọn tóc.\n3. Để sản phẩm trên tóc khoảng 1 phút.\n4. Xả sạch lại bằng nước.\n\nLưu ý: Chỉ sử dụng ngoài da. Tránh tiếp xúc với mắt; nếu dính vào mắt, rửa kỹ bằng nước. Ngừng sử dụng nếu xuất hiện kích ứng kéo dài.\n\n5. ĐỐI TƯỢNG SỬ DỤNG\n\n• Người có tóc khô xơ, hư tổn.\n• Người thường xuyên tạo kiểu bằng nhiệt.\n• Người muốn sử dụng sản phẩm dưỡng xả nhanh.", "en": "1. PRODUCT DESCRIPTION\n\nDove 1 Minute Super Nourishing Damage Repair Conditioner is an intensive rinse-off conditioner designed to care for severely damaged-looking hair in a convenient one-minute treatment. Featuring the brand's Advanced Repair Serum concept, the formula combines conditioning agents with vitamin E and several nourishing oils. Its rich texture helps smooth rough hair lengths, improve manageability and reduce the feeling of dryness. The quick application time makes it suitable for people who want a more intensive conditioning step without extending their hair-washing routine.\n\n2. BENEFITS\n\n• Provides intensive conditioning in a one-minute routine.\n• Helps soften rough and damaged-looking hair.\n• Improves smoothness and ease of detangling.\n• Helps reduce friction between hair strands.\n• Leaves hair feeling more manageable and conditioned.\n• Supports a convenient hair-care routine.\n\n3. INGREDIENTS\n\nKey ingredients and their functions:\n\n• Tocopheryl Acetate: A vitamin E derivative.\n• Argania Spinosa Kernel Oil: Argan oil, an emollient that conditions hair.\n• Cocos Nucifera (Coconut) Oil: Helps soften hair fibers.\n• Helianthus Annuus (Sunflower) Seed Oil: A plant-derived conditioning oil.\n• Prunus Amygdalus Dulcis (Sweet Almond) Oil: An emollient oil.\n• Behentrimonium Chloride: A conditioning and detangling ingredient.\n• Dimethicone and Amodimethicone: Silicone-based ingredients that help smooth hair.\n• Cetearyl Alcohol: A fatty alcohol that contributes to conditioning and texture.\n\nNote: These are selected ingredients or ingredient categories, not necessarily the complete INCI list. Verify the formula and labeling of the actual product before publication.\n\n4. DIRECTIONS FOR USE\n\n1. Wash the hair with shampoo and rinse thoroughly.\n2. Gently remove excess water.\n3. Apply a suitable amount to the mid-lengths and ends, keeping it away from the scalp.\n4. Distribute evenly through the hair.\n5. Leave on for approximately one minute.\n6. Rinse thoroughly with lukewarm or cool water.\n\nPrecautions: For external use only. Avoid contact with eyes. If contact occurs, rinse thoroughly with water. Discontinue use if irritation occurs.\n\n5. SUITABLE FOR\n\n• Severely damaged-looking hair.\n• Hair affected by frequent heat styling or chemical treatments.\n• People seeking intensive conditioning with a short application time.\n• Individuals wanting smoother, softer and easier-to-manage hair."}, "image": "assets/catalog/product-dove-10.jpg", "gallery": {"vi": [{"src": "assets/catalog/vi/dove-10/thumbnail.webp", "label": "Thumbnail", "order": 0}, {"src": "assets/catalog/vi/dove-10/anh-1.webp", "label": "Ảnh 1", "order": 1}, {"src": "assets/catalog/vi/dove-10/anh-2.webp", "label": "Ảnh 2", "order": 2}, {"src": "assets/catalog/vi/dove-10/anh-3.webp", "label": "Ảnh 3", "order": 3}, {"src": "assets/catalog/vi/dove-10/anh-4.webp", "label": "Ảnh 4", "order": 4}, {"src": "assets/catalog/vi/dove-10/anh-5.webp", "label": "Ảnh 5", "order": 5}, {"src": "assets/catalog/vi/dove-10/anh-6.webp", "label": "Ảnh 6", "order": 6}, {"src": "assets/catalog/vi/dove-10/anh-7.webp", "label": "Ảnh 7", "order": 7}]}}, {"id": "la-roche-posay-01", "brandId": "la-roche-posay", "brand": "La Roche-Posay", "name": {"vi": "LA ROCHE-POSAY EFFACLAR PURIFYING FOAMING GEL 200ML", "en": "La Roche-Posay Effaclar Purifying Foaming Gel 200ml"}, "category": "Skincare", "type": "Gel rửa mặt cho da dầu, da dễ nổi mụn", "size": "200ml", "country": "Pháp", "description": {"vi": "1. MÔ TẢ SẢN PHẨM\n\nTên sản phẩm: La Roche-Posay Effaclar Purifying Foaming Gel 200ml\nThương hiệu: La Roche-Posay\nQuốc gia thương hiệu: Pháp\nQuy cách đóng gói: 200ml\nPhân loại: Gel rửa mặt cho da dầu, da dễ nổi mụn\n\nLa Roche-Posay Effaclar Purifying Foaming Gel 200ml là gel rửa mặt tạo bọt dành cho da dầu và da dễ nổi mụn. Sản phẩm giúp loại bỏ bụi bẩn, dầu thừa và tạp chất trên bề mặt da. Công thức có Zinc PCA và được thương hiệu giới thiệu với công nghệ Phylobioma, hướng đến việc làm sạch mà vẫn chú trọng khả năng dung nạp của da nhạy cảm.\n\n2. CÔNG DỤNG\n\n- Làm sạch bụi bẩn, dầu thừa và tạp chất.\n- Hỗ trợ giảm bóng nhờn, giúp da thông thoáng.\n- Hỗ trợ chăm sóc da dầu và da dễ nổi mụn.\n- Giúp da có cảm giác sạch thoáng sau khi rửa.\n\n3. THÀNH PHẦN\n\nCác thành phần nổi bật:\n- Zinc PCA: Hỗ trợ kiểm soát dầu thừa.\n- Nước khoáng La Roche-Posay: Thành phần đặc trưng của thương hiệu, hỗ trợ làm dịu da.\n- Công nghệ Phylobioma: Được hãng giới thiệu trên trang sản phẩm.\n- Các chất làm sạch như Sodium Laureth Sulfate và Coco-Betaine: Hỗ trợ loại bỏ bụi bẩn và dầu thừa.\n\nLưu ý: Thành phần nổi bật không thay thế danh sách INCI đầy đủ trên bao bì.\n\n4. HƯỚNG DẪN SỬ DỤNG\n\nLàm ướt mặt, lấy lượng gel vừa đủ ra lòng bàn tay, tạo bọt rồi massage nhẹ nhàng lên mặt và cổ. Rửa sạch với nước. Sử dụng buổi sáng và buổi tối tùy nhu cầu.\n\nLưu ý chung: Chỉ dùng ngoài da. Ngừng sử dụng nếu có kích ứng kéo dài. Bảo quản theo hướng dẫn trên bao bì.\n\n5. ĐỐI TƯỢNG SỬ DỤNG\n\n- Người có da dầu, da hỗn hợp thiên dầu.\n- Người có da dễ nổi mụn.\n- Người cần gel rửa mặt hỗ trợ giảm dầu thừa.\n- Theo website hãng, sản phẩm phù hợp từ 10 tuổi.", "en": "1. PRODUCT DESCRIPTION\n\nLa Roche-Posay Effaclar Purifying Foaming Gel is a daily facial cleanser developed for oily, sensitive and blemish-prone skin. Its gel texture transforms into a light foam to remove excess sebum, dirt and everyday impurities. The formula combines cleansing agents with zinc PCA and La Roche-Posay Thermal Spring Water to help leave the complexion feeling clean, refreshed and comfortable. It is designed to support a consistent cleansing routine without unnecessary scrubbing.\n\n2. BENEFITS\n\n• Removes dirt, excess oil and daily impurities.\n• Helps reduce the appearance of excess facial shine.\n• Leaves skin feeling clean and refreshed.\n• Supports daily cleansing for oily and blemish-prone skin.\n• Prepares skin for serums and moisturizers.\n\n3. INGREDIENTS\n\nKey ingredients and their functions:\n\n• Zinc PCA: Helps control excess surface oil.\n• La Roche-Posay Thermal Spring Water: Mineral-rich water used in the brand's skincare.\n• Sodium Laureth Sulfate: A cleansing and foaming agent.\n• Coco-Betaine: A surfactant that supports cleansing.\n• PEG-8: A moisturizing and formulation-supporting ingredient.\n\nNote: These are selected key ingredients, not a complete INCI declaration. Ingredients may vary by formulation and market. Verify the current packaging before publication.\n\n4. DIRECTIONS FOR USE\n\n1. Wet the face with lukewarm water.\n2. Dispense a small amount of gel into the palms.\n3. Lather gently with water.\n4. Massage over the face, especially oily areas, without scrubbing.\n5. Rinse thoroughly and pat dry.\n6. Follow with a suitable moisturizer; use morning and evening as tolerated.\n\nPrecautions: For external use only. Avoid direct contact with eyes. Discontinue use if irritation occurs. Follow professional guidance for post-procedure skincare.\n\n5. SUITABLE FOR\n\n• Oily and combination skin.\n• Blemish-prone skin.\n• People experiencing excess facial shine.\n• Individuals seeking a daily foaming facial cleanser."}, "image": "assets/catalog/product-la-roche-posay-01.jpg", "gallery": {"vi": [{"src": "assets/catalog/vi/la-roche-posay-01/thumbnail.webp", "label": "Thumbnail", "order": 0}, {"src": "assets/catalog/vi/la-roche-posay-01/anh-1.webp", "label": "Ảnh 1", "order": 1}, {"src": "assets/catalog/vi/la-roche-posay-01/anh-2.webp", "label": "Ảnh 2", "order": 2}, {"src": "assets/catalog/vi/la-roche-posay-01/anh-3.webp", "label": "Ảnh 3", "order": 3}, {"src": "assets/catalog/vi/la-roche-posay-01/anh-4.webp", "label": "Ảnh 4", "order": 4}, {"src": "assets/catalog/vi/la-roche-posay-01/anh-5.webp", "label": "Ảnh 5", "order": 5}, {"src": "assets/catalog/vi/la-roche-posay-01/anh-6.webp", "label": "Ảnh 6", "order": 6}, {"src": "assets/catalog/vi/la-roche-posay-01/anh-7.webp", "label": "Ảnh 7", "order": 7}]}}, {"id": "la-roche-posay-02", "brandId": "la-roche-posay", "brand": "La Roche-Posay", "name": {"vi": "LA ROCHE-POSAY EFFACLAR MICRO-PEELING PURIFYING GEL 400ML", "en": "La Roche-Posay Effaclar Micro-Peeling Purifying Gel 400ml"}, "category": "Skincare", "type": "Gel làm sạch hỗ trợ tẩy tế bào chết cho mặt và cơ thể", "size": "400ml", "country": "Pháp", "description": {"vi": "1. MÔ TẢ SẢN PHẨM\n\nTên sản phẩm: La Roche-Posay Effaclar Micro-Peeling Purifying Gel 400ml\nThương hiệu: La Roche-Posay\nQuốc gia thương hiệu: Pháp\nQuy cách đóng gói: 400ml\nPhân loại: Gel làm sạch hỗ trợ tẩy tế bào chết cho mặt và cơ thể\n\nLa Roche-Posay Effaclar Micro-Peeling Purifying Gel 400ml là gel làm sạch dành cho da dầu, da dễ nổi mụn và có lỗ chân lông dễ bít tắc. Sản phẩm kết hợp Salicylic Acid, LHA và kẽm, giúp làm sạch bã nhờn, hỗ trợ loại bỏ tế bào chết và cải thiện cảm giác sần sùi trên bề mặt da.\n\n2. CÔNG DỤNG\n\n- Làm sạch bụi bẩn, bã nhờn và tạp chất.\n- Hỗ trợ loại bỏ tế bào chết trên bề mặt da.\n- Giúp lỗ chân lông thông thoáng hơn.\n- Hỗ trợ giảm bóng dầu và cải thiện vẻ ngoài của da sần sùi.\n- Có thể sử dụng cho mặt và vùng cơ thể dễ nổi mụn.\n\n3. THÀNH PHẦN\n\nCác thành phần nổi bật:\n- Salicylic Acid (BHA): Hỗ trợ làm sạch tế bào chết và lỗ chân lông.\n- Capryloyl Salicylic Acid (LHA): Hỗ trợ làm mịn bề mặt da.\n- Zinc Gluconate: Hỗ trợ giảm dầu thừa.\n- Glycerin: Giúp duy trì độ ẩm.\n\nLưu ý: Thành phần nổi bật không thay thế danh sách INCI đầy đủ trên bao bì.\n\n4. HƯỚNG DẪN SỬ DỤNG\n\nLàm ướt da, cho lượng gel vừa đủ vào hai bàn tay ướt và tạo bọt. Massage nhẹ nhàng lên vùng cần làm sạch rồi rửa kỹ với nước. Tránh tiếp xúc với mắt. Điều chỉnh tần suất nếu da khô hoặc kích ứng và sử dụng chống nắng vào ban ngày.\n\nLưu ý chung: Chỉ dùng ngoài da. Ngừng sử dụng nếu có kích ứng kéo dài. Bảo quản theo hướng dẫn trên bao bì.\n\n5. ĐỐI TƯỢNG SỬ DỤNG\n\n- Người có da dầu, da dễ nổi mụn.\n- Người có lỗ chân lông dễ bít tắc.\n- Người cần làm sạch vùng mặt hoặc cơ thể có xu hướng nổi mụn.\n- Thanh thiếu niên và người trưởng thành có làn da phù hợp.", "en": "1. PRODUCT DESCRIPTION\n\nLa Roche-Posay Effaclar Micro-Peeling Purifying Gel is a cleansing gel designed for oily, blemish-prone skin on the face and body. It combines cleansing agents with salicylic acid and lipohydroxy acid to help remove accumulated impurities, excess sebum and dead skin cells. The formula supports clearer-looking pores and a smoother skin surface, making it useful for people concerned about clogged pores, rough texture and blemishes on the face, chest or back.\n\n2. BENEFITS\n\n• Cleanses excess oil and accumulated impurities.\n• Helps exfoliate dead skin cells.\n• Supports clearer-looking pores.\n• Helps improve the appearance of rough or uneven skin texture.\n• Suitable for cleansing blemish-prone areas of the face and body.\n\n3. INGREDIENTS\n\nKey ingredients and their functions:\n\n• Salicylic Acid (BHA): Helps exfoliate and clear pore buildup.\n• Capryloyl Salicylic Acid (LHA): A lipohydroxy acid used for surface exfoliation.\n• Zinc Gluconate: A skin-conditioning ingredient used in oily-skin care.\n• Glycerin: A humectant that supports moisture retention.\n• Decyl Glucoside: A cleansing surfactant.\n• Menthol: Provides a cooling sensation.\n\nNote: These are selected key ingredients, not a complete INCI declaration. Ingredients may vary by formulation and market. Verify the current packaging before publication.\n\n4. DIRECTIONS FOR USE\n\n1. Wet the face or body area with water.\n2. Lather a small amount between wet palms.\n3. Massage gently onto the skin, avoiding the eyes.\n4. Rinse thoroughly with water.\n5. Begin with a frequency appropriate for skin tolerance.\n6. Follow with moisturizer and apply sunscreen to exposed skin during the day.\n\nPrecautions: For external use only. Avoid direct contact with eyes. Discontinue use if irritation occurs. Follow professional guidance for post-procedure skincare.\n\n5. SUITABLE FOR\n\n• Oily and blemish-prone skin.\n• People concerned about clogged pores.\n• Individuals experiencing blemishes on the back or chest.\n• Those seeking an exfoliating cleansing gel."}, "image": "assets/catalog/product-la-roche-posay-02.jpg", "gallery": {"vi": [{"src": "assets/catalog/vi/la-roche-posay-02/thumbnail.webp", "label": "Thumbnail", "order": 0}, {"src": "assets/catalog/vi/la-roche-posay-02/anh-1.webp", "label": "Ảnh 1", "order": 1}, {"src": "assets/catalog/vi/la-roche-posay-02/anh-2.webp", "label": "Ảnh 2", "order": 2}, {"src": "assets/catalog/vi/la-roche-posay-02/anh-3.webp", "label": "Ảnh 3", "order": 3}, {"src": "assets/catalog/vi/la-roche-posay-02/anh-4.webp", "label": "Ảnh 4", "order": 4}, {"src": "assets/catalog/vi/la-roche-posay-02/anh-5.webp", "label": "Ảnh 5", "order": 5}, {"src": "assets/catalog/vi/la-roche-posay-02/anh-6.webp", "label": "Ảnh 6", "order": 6}, {"src": "assets/catalog/vi/la-roche-posay-02/anh-7.webp", "label": "Ảnh 7", "order": 7}]}}, {"id": "la-roche-posay-03", "brandId": "la-roche-posay", "brand": "La Roche-Posay", "name": {"vi": "LA ROCHE-POSAY CICAPLAST BAUME B5+ 40ML", "en": "La Roche-Posay Cicaplast Baume B5+ 40ml"}, "category": "Skincare", "type": "Kem dưỡng làm dịu và hỗ trợ hàng rào bảo vệ da", "size": "40ml", "country": "Pháp", "description": {"vi": "1. MÔ TẢ SẢN PHẨM\n\nTên sản phẩm: La Roche-Posay Cicaplast Baume B5+ 40ml\nThương hiệu: La Roche-Posay\nQuốc gia thương hiệu: Pháp\nQuy cách đóng gói: 40ml\nPhân loại: Kem dưỡng làm dịu và hỗ trợ hàng rào bảo vệ da\n\nLa Roche-Posay Cicaplast Baume B5+ 40ml là kem dưỡng đa năng dành cho da khô, da nhạy cảm và da cần được làm dịu. Công thức chứa Panthenol, Madecassoside, chiết xuất rau má cùng phức hợp Tribioma, hỗ trợ chăm sóc hàng rào bảo vệ da và làm mềm các vùng da khô ráp. Sản phẩm có thể sử dụng cho mặt, môi và cơ thể.\n\n2. CÔNG DỤNG\n\n- Làm dịu cảm giác khô căng và khó chịu trên da.\n- Hỗ trợ duy trì hàng rào bảo vệ da.\n- Dưỡng ẩm, làm mềm vùng da khô ráp.\n- Hỗ trợ chăm sóc làn da nhạy cảm trước tác động của môi trường.\n- Có thể dùng cho mặt, môi và cơ thể.\n\n3. THÀNH PHẦN\n\nCác thành phần nổi bật:\n- Panthenol (Vitamin B5): Hỗ trợ làm dịu và chăm sóc hàng rào da.\n- Madecassoside và chiết xuất rau má: Hỗ trợ làm dịu da.\n- Tribioma: Phức hợp được hãng giới thiệu nhằm hỗ trợ cân bằng hệ vi sinh trên da.\n- Bơ hạt mỡ (Shea Butter): Làm mềm và dưỡng ẩm.\n- Glycerin: Hỗ trợ giữ ẩm.\n\nLưu ý: Thành phần nổi bật không thay thế danh sách INCI đầy đủ trên bao bì.\n\n4. HƯỚNG DẪN SỬ DỤNG\n\nLàm sạch và lau khô vùng da cần chăm sóc. Thoa lượng kem vừa đủ, nhẹ nhàng tán đều. Có thể sử dụng khoảng 2 lần mỗi ngày hoặc theo nhu cầu. Tránh vùng mắt và không thoa lên vết thương hở.\n\nLưu ý chung: Chỉ dùng ngoài da. Ngừng sử dụng nếu có kích ứng kéo dài. Bảo quản theo hướng dẫn trên bao bì.\n\n5. ĐỐI TƯỢNG SỬ DỤNG\n\n- Da khô, da nhạy cảm, da dễ bị khô căng.\n- Người cần dưỡng ẩm và chăm sóc hàng rào bảo vệ da.\n- Người có vùng da khô ráp ở mặt, môi hoặc cơ thể.\n- Theo website hãng, sản phẩm phù hợp với người lớn, trẻ em và trẻ từ 3 tháng tuổi.", "en": "1. PRODUCT DESCRIPTION\n\nLa Roche-Posay Cicaplast Baume B5+ is a rich, multi-purpose soothing balm developed for dry, sensitive and uncomfortable skin. Featuring panthenol, madecassoside and the brand's Tribioma complex, the formula helps moisturize and support the skin's protective barrier. Its comforting texture is suitable for localized dry patches and areas affected by everyday environmental stressors. It can be used as part of a gentle face and body skincare routine when the skin requires additional conditioning.\n\n2. BENEFITS\n\n• Helps soothe dryness-related discomfort.\n• Supports the skin's protective moisture barrier.\n• Softens rough and dry areas.\n• Provides rich moisturizing care.\n• Helps reduce the feeling of tightness.\n• Suitable for localized face and body care.\n\n3. INGREDIENTS\n\nKey ingredients and their functions:\n\n• Panthenol (Vitamin B5): A skin-conditioning ingredient associated with soothing care.\n• Madecassoside: A Centella asiatica-derived ingredient.\n• Tribioma Complex: The brand's skin-microbiome-focused ingredient complex.\n• Shea Butter: An emollient that helps soften dry skin.\n• Glycerin: A humectant that supports hydration.\n• Dimethicone: Helps form a protective, skin-conditioning layer.\n\nNote: These are selected key ingredients, not a complete INCI declaration. Ingredients may vary by formulation and market. Verify the current packaging before publication.\n\n4. DIRECTIONS FOR USE\n\n1. Gently cleanse the skin and pat dry.\n2. Apply a suitable amount of balm to the desired area.\n3. Massage lightly until evenly distributed.\n4. Use up to twice daily or as directed on the packaging.\n5. Avoid applying to deep or actively bleeding wounds.\n6. Seek professional advice before use on skin recovering from a medical procedure.\n\nPrecautions: For external use only. Avoid direct contact with eyes. Discontinue use if irritation occurs. Follow professional guidance for post-procedure skincare.\n\n5. SUITABLE FOR\n\n• Dry and sensitive skin.\n• People experiencing rough or uncomfortable skin patches.\n• Individuals seeking intensive barrier-supporting care.\n• Those wanting a multi-purpose moisturizing balm."}, "image": "assets/catalog/product-la-roche-posay-03.jpg", "gallery": {"vi": [{"src": "assets/catalog/vi/la-roche-posay-03/thumbnail.webp", "label": "Thumbnail", "order": 0}, {"src": "assets/catalog/vi/la-roche-posay-03/anh-1.webp", "label": "Ảnh 1", "order": 1}, {"src": "assets/catalog/vi/la-roche-posay-03/anh-2.webp", "label": "Ảnh 2", "order": 2}, {"src": "assets/catalog/vi/la-roche-posay-03/anh-3.webp", "label": "Ảnh 3", "order": 3}, {"src": "assets/catalog/vi/la-roche-posay-03/anh-4.webp", "label": "Ảnh 4", "order": 4}, {"src": "assets/catalog/vi/la-roche-posay-03/anh-5.webp", "label": "Ảnh 5", "order": 5}, {"src": "assets/catalog/vi/la-roche-posay-03/anh-6.webp", "label": "Ảnh 6", "order": 6}, {"src": "assets/catalog/vi/la-roche-posay-03/anh-7.webp", "label": "Ảnh 7", "order": 7}]}}, {"id": "la-roche-posay-04", "brandId": "la-roche-posay", "brand": "La Roche-Posay", "name": {"vi": "LA ROCHE-POSAY CICAPLAST GEL B5 40ML", "en": "La Roche-Posay Cicaplast Gel B5 40ml"}, "category": "Skincare", "type": "Gel chăm sóc da và vùng sẹo đã lành", "size": "40ml", "country": "Pháp", "description": {"vi": "1. MÔ TẢ SẢN PHẨM\n\nTên sản phẩm: La Roche-Posay Cicaplast Gel B5 40ml\nThương hiệu: La Roche-Posay\nQuốc gia thương hiệu: Pháp\nQuy cách đóng gói: 40ml\nPhân loại: Gel chăm sóc da và vùng sẹo đã lành\n\nLa Roche-Posay Cicaplast Gel B5 40ml là gel chăm sóc da có kết cấu silicone trong suốt, mỏng nhẹ. Công thức nổi bật với 5% Panthenol, Madecassoside và phức hợp đồng – kẽm – mangan, hướng đến việc làm dịu và chăm sóc vùng da sau tác động bên ngoài, đặc biệt khi bề mặt da đã lành hoàn toàn.\n\n2. CÔNG DỤNG\n\n- Hỗ trợ làm dịu và chăm sóc hàng rào bảo vệ da.\n- Giúp giảm cảm giác căng tức, khó chịu trên vùng da khô.\n- Hỗ trợ cải thiện vẻ ngoài của vùng sẹo đã lành khi kết hợp massage.\n- Tạo cảm giác dễ chịu nhờ kết cấu gel silicone.\n- Hỗ trợ giữ ẩm cho bề mặt da.\n\n3. THÀNH PHẦN\n\nCác thành phần nổi bật:\n- Panthenol (Vitamin B5) 5%: Hỗ trợ làm dịu da.\n- Madecassoside: Thành phần từ rau má, hỗ trợ chăm sóc da.\n- Copper Gluconate, Zinc Gluconate và Manganese Gluconate: Phức hợp khoáng chất được hãng giới thiệu.\n- Sodium Hyaluronate: Hỗ trợ giữ ẩm.\n- Glycerin và Dimethicone: Giúp làm mềm và tạo kết cấu gel.\n\nLưu ý: Thành phần nổi bật không thay thế danh sách INCI đầy đủ trên bao bì.\n\n4. HƯỚNG DẪN SỬ DỤNG\n\nThoa lên vùng da sạch, khô và massage nhẹ. Với vùng sẹo, chỉ sử dụng khi vết thương đã khép kín hoàn toàn, không còn rỉ dịch và được phép chăm sóc tại chỗ. Có thể dùng 2 lần mỗi ngày trên vùng da khô. Sau thủ thuật da liễu, sử dụng theo hướng dẫn của bác sĩ. Không thoa trực tiếp lên vết thương hở hoặc vùng viền mắt.\n\nLưu ý chung: Chỉ dùng ngoài da. Ngừng sử dụng nếu có kích ứng kéo dài. Bảo quản theo hướng dẫn trên bao bì.\n\n5. ĐỐI TƯỢNG SỬ DỤNG\n\n- Người cần chăm sóc vùng da có sẹo đã lành.\n- Người có vùng da khô, căng tức sau tác động bên ngoài.\n- Người cần sản phẩm gel mỏng nhẹ hỗ trợ hàng rào bảo vệ da.\n- Người sau thủ thuật da liễu khi đã được chuyên gia cho phép sử dụng.", "en": "1. PRODUCT DESCRIPTION\n\nLa Roche-Posay Cicaplast Gel B5 is a transparent, silicone-based gel developed to provide protective and soothing care for skin that has already healed on the surface. Its formula combines 5% panthenol, madecassoside and mineral gluconates to support skin comfort. The smooth gel texture is designed to facilitate gentle massage over fully closed, healed skin, including areas where the appearance of a new scar is a concern. It should not be applied to open wounds.\n\n2. BENEFITS\n\n• Provides a protective, comfortable gel layer.\n• Helps soothe dryness-related discomfort.\n• Supports the skin's moisture barrier.\n• Facilitates gentle massage of fully healed skin.\n• Helps maintain a smoother, more comfortable skin feel.\n\n3. INGREDIENTS\n\nKey ingredients and their functions:\n\n• 5% Panthenol: Supports skin conditioning and soothing care.\n• Madecassoside: A Centella asiatica-derived skin-conditioning ingredient.\n• Glycerin: Helps attract moisture.\n• Dimethicone: A silicone that provides a smooth protective feel.\n• Copper, Zinc and Manganese Gluconates: Mineral-based components of the formula.\n• Sodium Hyaluronate: Helps retain moisture.\n\nNote: These are selected key ingredients, not a complete INCI declaration. Ingredients may vary by formulation and market. Verify the current packaging before publication.\n\n4. DIRECTIONS FOR USE\n\n1. Ensure the intended area is clean, dry and fully closed.\n2. Apply a thin layer of gel to the skin.\n3. Massage gently if appropriate for the area.\n4. Use as directed on the packaging, commonly twice daily.\n5. Do not apply to open, bleeding or weeping wounds.\n6. After dermatological procedures, follow the treating professional's instructions.\n\nPrecautions: For external use only. Avoid direct contact with eyes. Discontinue use if irritation occurs. Follow professional guidance for post-procedure skincare.\n\n5. SUITABLE FOR\n\n• People seeking care for fully healed skin.\n• Individuals concerned about the appearance of new scars after healing.\n• Skin requiring a lightweight protective gel.\n• People advised to use a silicone-textured skincare gel after a procedure."}, "image": "assets/catalog/product-la-roche-posay-04.jpg", "gallery": {"vi": [{"src": "assets/catalog/vi/la-roche-posay-04/thumbnail.webp", "label": "Thumbnail", "order": 0}, {"src": "assets/catalog/vi/la-roche-posay-04/anh-1.webp", "label": "Ảnh 1", "order": 1}, {"src": "assets/catalog/vi/la-roche-posay-04/anh-2.webp", "label": "Ảnh 2", "order": 2}, {"src": "assets/catalog/vi/la-roche-posay-04/anh-3.webp", "label": "Ảnh 3", "order": 3}, {"src": "assets/catalog/vi/la-roche-posay-04/anh-4.webp", "label": "Ảnh 4", "order": 4}, {"src": "assets/catalog/vi/la-roche-posay-04/anh-5.webp", "label": "Ảnh 5", "order": 5}, {"src": "assets/catalog/vi/la-roche-posay-04/anh-6.webp", "label": "Ảnh 6", "order": 6}, {"src": "assets/catalog/vi/la-roche-posay-04/anh-7.webp", "label": "Ảnh 7", "order": 7}]}}, {"id": "la-roche-posay-05", "brandId": "la-roche-posay", "brand": "La Roche-Posay", "name": {"vi": "LA ROCHE-POSAY HYALU B5 SERUM 30ML", "en": "La Roche-Posay Hyalu B5 Serum 30ml"}, "category": "Skincare", "type": "Tinh chất dưỡng ẩm và chăm sóc da có dấu hiệu lão hóa", "size": "30ml", "country": "Pháp", "description": {"vi": "1. MÔ TẢ SẢN PHẨM\n\nTên sản phẩm: La Roche-Posay Hyalu B5 Serum 30ml\nThương hiệu: La Roche-Posay\nQuốc gia thương hiệu: Pháp\nQuy cách đóng gói: 30ml\nPhân loại: Tinh chất dưỡng ẩm và chăm sóc da có dấu hiệu lão hóa\n\nLa Roche-Posay Hyalu B5 Serum 30ml là tinh chất dưỡng da kết hợp Hyaluronic Acid và Vitamin B5, hướng đến nhu cầu cấp ẩm, làm căng mịn và chăm sóc da có dấu hiệu lão hóa. Sản phẩm giúp cải thiện cảm giác khô căng, mang lại bề mặt da mềm mại và căng mọng hơn.\n\n2. CÔNG DỤNG\n\n- Bổ sung độ ẩm cho da.\n- Giúp da trông căng mọng và mềm mại hơn.\n- Hỗ trợ giảm vẻ ngoài của nếp nhăn nhỏ.\n- Hỗ trợ chăm sóc hàng rào bảo vệ da.\n- Cải thiện cảm giác khô căng do thiếu ẩm.\n\n3. THÀNH PHẦN\n\nCác thành phần nổi bật:\n- Hyaluronic Acid: Hỗ trợ giữ nước và cấp ẩm cho da.\n- Panthenol (Vitamin B5): Hỗ trợ làm dịu và chăm sóc da.\n- Madecassoside: Thành phần hỗ trợ chăm sóc hàng rào da.\n- Glycerin: Thành phần hút ẩm.\n\nLưu ý: Thành phần nổi bật không thay thế danh sách INCI đầy đủ trên bao bì.\n\n4. HƯỚNG DẪN SỬ DỤNG\n\nSau khi làm sạch da, thoa lượng tinh chất vừa đủ lên mặt và cổ. Massage hoặc vỗ nhẹ để sản phẩm phân bố đều. Tiếp tục với kem dưỡng. Có thể sử dụng trong quy trình buổi sáng và buổi tối theo hướng dẫn trên nhãn.\n\nLưu ý chung: Chỉ dùng ngoài da. Ngừng sử dụng nếu có kích ứng kéo dài. Bảo quản theo hướng dẫn trên bao bì.\n\n5. ĐỐI TƯỢNG SỬ DỤNG\n\n- Người có da khô, thiếu nước.\n- Người có da kém căng mọng.\n- Người xuất hiện nếp nhăn nhỏ do tuổi tác hoặc thiếu ẩm.\n- Người muốn bổ sung tinh chất dưỡng ẩm trong quy trình chăm sóc da.", "en": "1. PRODUCT DESCRIPTION\n\nLa Roche-Posay Hyalu B5 Serum is a moisturizing facial serum developed to address dehydration and the visible appearance of fine lines. The formula combines hyaluronic acid with vitamin B5 and madecassoside to help replenish moisture, support skin comfort and promote a plumper-looking complexion. Its serum texture is suitable for layering beneath a daily moisturizer, especially when skin feels tight, rough or less supple due to insufficient hydration.\n\n2. BENEFITS\n\n• Provides intensive hydration.\n• Helps improve the appearance of fine dehydration lines.\n• Promotes a plumper and smoother-looking complexion.\n• Supports the skin's moisture barrier.\n• Helps maintain a soft and comfortable skin feel.\n\n3. INGREDIENTS\n\nKey ingredients and their functions:\n\n• Hyaluronic Acid and Sodium Hyaluronate: Humectants that help retain moisture.\n• Panthenol (Vitamin B5): Supports skin conditioning and comfort.\n• Madecassoside: A Centella asiatica-derived ingredient.\n• Glycerin: A moisture-attracting humectant.\n• La Roche-Posay Thermal Spring Water: Mineral-rich water used in the formula.\n\nNote: These are selected key ingredients, not a complete INCI declaration. Ingredients may vary by formulation and market. Verify the current packaging before publication.\n\n4. DIRECTIONS FOR USE\n\n1. Cleanse the face and gently pat dry.\n2. Apply a few drops of serum to the face and neck.\n3. Spread evenly, avoiding direct contact with the eyes.\n4. Allow the serum to absorb.\n5. Follow with a moisturizer.\n6. Use sunscreen during the day.\n\nPrecautions: For external use only. Avoid direct contact with eyes. Discontinue use if irritation occurs. Follow professional guidance for post-procedure skincare.\n\n5. SUITABLE FOR\n\n• Dehydrated skin.\n• People concerned about fine lines caused by dryness.\n• Individuals seeking a plumping hydrating serum.\n• Those wanting daily moisture-barrier support."}, "image": "assets/catalog/product-la-roche-posay-05.jpg", "gallery": {"vi": [{"src": "assets/catalog/vi/la-roche-posay-05/thumbnail.webp", "label": "Thumbnail", "order": 0}, {"src": "assets/catalog/vi/la-roche-posay-05/anh-1.webp", "label": "Ảnh 1", "order": 1}, {"src": "assets/catalog/vi/la-roche-posay-05/anh-2.webp", "label": "Ảnh 2", "order": 2}, {"src": "assets/catalog/vi/la-roche-posay-05/anh-3.webp", "label": "Ảnh 3", "order": 3}, {"src": "assets/catalog/vi/la-roche-posay-05/anh-4.webp", "label": "Ảnh 4", "order": 4}, {"src": "assets/catalog/vi/la-roche-posay-05/anh-5.webp", "label": "Ảnh 5", "order": 5}, {"src": "assets/catalog/vi/la-roche-posay-05/anh-6.webp", "label": "Ảnh 6", "order": 6}, {"src": "assets/catalog/vi/la-roche-posay-05/anh-7.webp", "label": "Ảnh 7", "order": 7}]}}, {"id": "la-roche-posay-06", "brandId": "la-roche-posay", "brand": "La Roche-Posay", "name": {"vi": "LA ROCHE-POSAY PURE VITAMIN C10 SERUM 30ML", "en": "La Roche-Posay Pure Vitamin C10 Serum 30ml"}, "category": "Skincare", "type": "Tinh chất dưỡng sáng và chăm sóc da có dấu hiệu lão hóa", "size": "30ml", "country": "Pháp", "description": {"vi": "1. MÔ TẢ SẢN PHẨM\n\nTên sản phẩm: La Roche-Posay Pure Vitamin C10 Serum 30ml\nThương hiệu: La Roche-Posay\nQuốc gia thương hiệu: Pháp\nQuy cách đóng gói: 30ml\nPhân loại: Tinh chất dưỡng sáng và chăm sóc da có dấu hiệu lão hóa\n\nLa Roche-Posay Pure Vitamin C10 Serum 30ml là tinh chất dưỡng da nổi bật với Vitamin C nguyên chất, hướng đến làn da xỉn màu, không đều màu và có dấu hiệu lão hóa. Công thức kết hợp Salicylic Acid, Hyaluronic Acid và Neurosensine, giúp chăm sóc kết cấu da và hỗ trợ mang lại vẻ ngoài rạng rỡ.\n\n2. CÔNG DỤNG\n\n- Hỗ trợ dưỡng sáng và cải thiện độ đều màu.\n- Giúp da trông rạng rỡ, tươi tắn hơn.\n- Hỗ trợ giảm vẻ ngoài của nếp nhăn nhỏ.\n- Hỗ trợ làm mịn kết cấu da.\n- Bổ sung thành phần chống oxy hóa.\n\n3. THÀNH PHẦN\n\nCác thành phần nổi bật:\n- Ascorbic Acid (Vitamin C nguyên chất): Hỗ trợ chống oxy hóa và dưỡng sáng.\n- Salicylic Acid: Hỗ trợ loại bỏ tế bào chết trên bề mặt.\n- Sodium Hyaluronate và Hydrolyzed Hyaluronic Acid: Hỗ trợ giữ ẩm.\n- Acetyl Dipeptide-1 Cetyl Ester (Neurosensine): Thành phần được hãng giới thiệu để hỗ trợ làm dịu.\n- Glycerin: Hỗ trợ duy trì độ ẩm.\n\nLưu ý: Thành phần nổi bật không thay thế danh sách INCI đầy đủ trên bao bì.\n\n4. HƯỚNG DẪN SỬ DỤNG\n\nThoa lượng tinh chất vừa đủ lên mặt và cổ vào buổi sáng, tránh vùng mắt. Sử dụng kem dưỡng và kem chống nắng phù hợp sau đó. Với làn da nhạy cảm, nên thử trên một vùng nhỏ trước khi dùng toàn mặt.\n\nLưu ý chung: Chỉ dùng ngoài da. Ngừng sử dụng nếu có kích ứng kéo dài. Bảo quản theo hướng dẫn trên bao bì.\n\n5. ĐỐI TƯỢNG SỬ DỤNG\n\n- Người có da xỉn màu, không đều màu.\n- Người xuất hiện nếp nhăn nhỏ.\n- Người muốn bổ sung Vitamin C vào quy trình chăm sóc da.\n- Người có da nhạy cảm nhưng dung nạp tốt công thức.", "en": "1. PRODUCT DESCRIPTION\n\nLa Roche-Posay Pure Vitamin C10 Serum is a facial treatment formulated with pure vitamin C to improve the appearance of dullness, uneven skin tone and early visible signs of aging. The formula combines antioxidant skincare with ingredients that help refine the look of skin texture and support a smoother, brighter complexion. It can be incorporated into a routine focused on radiance and fine lines, provided it is introduced according to skin tolerance. Consistent sunscreen use is important when caring for pigmentation and photoaging concerns.\n\n2. BENEFITS\n\n• Helps improve the appearance of dull skin.\n• Promotes a brighter, more even-looking complexion.\n• Helps reduce the visible appearance of fine lines.\n• Supports smoother-looking skin texture.\n• Provides antioxidant skin-conditioning care.\n\n3. INGREDIENTS\n\nKey ingredients and their functions:\n\n• 10% Pure Vitamin C (Ascorbic Acid): An antioxidant that supports a brighter-looking complexion.\n• Salicylic Acid: An exfoliating ingredient that helps refine skin texture.\n• Neurosensine: A peptide ingredient used in soothing skincare formulas.\n• Glycerin: A moisturizing humectant.\n• La Roche-Posay Thermal Spring Water: Mineral-rich water used in the brand's skincare.\n\nNote: These are selected key ingredients, not a complete INCI declaration. Ingredients may vary by formulation and market. Verify the current packaging before publication.\n\n4. DIRECTIONS FOR USE\n\n1. Cleanse the face and pat dry.\n2. Apply a few drops of serum to the face, avoiding the eye area.\n3. Introduce gradually if the skin is sensitive.\n4. Follow with a suitable moisturizer.\n5. Use broad-spectrum sunscreen during the day.\n6. Discontinue or reduce use if persistent irritation occurs.\n\nPrecautions: For external use only. Avoid direct contact with eyes. Discontinue use if irritation occurs. Follow professional guidance for post-procedure skincare.\n\n5. SUITABLE FOR\n\n• People concerned about dull-looking skin.\n• Individuals experiencing uneven skin tone.\n• Those concerned about early visible signs of aging.\n• People seeking a vitamin C facial serum."}, "image": "assets/catalog/product-la-roche-posay-06.jpg", "gallery": {"vi": [{"src": "assets/catalog/vi/la-roche-posay-06/thumbnail.webp", "label": "Thumbnail", "order": 0}, {"src": "assets/catalog/vi/la-roche-posay-06/anh-1.webp", "label": "Ảnh 1", "order": 1}, {"src": "assets/catalog/vi/la-roche-posay-06/anh-2.webp", "label": "Ảnh 2", "order": 2}, {"src": "assets/catalog/vi/la-roche-posay-06/anh-3.webp", "label": "Ảnh 3", "order": 3}, {"src": "assets/catalog/vi/la-roche-posay-06/anh-4.webp", "label": "Ảnh 4", "order": 4}, {"src": "assets/catalog/vi/la-roche-posay-06/anh-5.webp", "label": "Ảnh 5", "order": 5}, {"src": "assets/catalog/vi/la-roche-posay-06/anh-6.webp", "label": "Ảnh 6", "order": 6}, {"src": "assets/catalog/vi/la-roche-posay-06/anh-7.webp", "label": "Ảnh 7", "order": 7}]}}, {"id": "la-roche-posay-07", "brandId": "la-roche-posay", "brand": "La Roche-Posay", "name": {"vi": "LA ROCHE-POSAY ANTHELIOS UVMUNE 400 ANTI-DARK SPOTS FLUID SPF50+ 50ML", "en": "La Roche-Posay Anthelios UVMune 400 Anti-Dark Spots Fluid SPF50+ 50ml"}, "category": "Skincare", "type": "Sữa chống nắng dưỡng sáng", "size": "50ml", "country": "Pháp", "description": {"vi": "1. MÔ TẢ SẢN PHẨM\n\nTên sản phẩm: La Roche-Posay Anthelios UVMune 400 Anti-Dark Spots Fluid SPF50+ 50ml\nThương hiệu: La Roche-Posay\nQuốc gia thương hiệu: Pháp\nQuy cách đóng gói: 50ml\nPhân loại: Sữa chống nắng dưỡng sáng\n\nLa Roche-Posay Anthelios UVMune 400 Anti-Dark Spots Fluid SPF50+ 50ml là sữa chống nắng có kết cấu lỏng nhẹ, kết hợp công nghệ màng lọc Mexoryl 400 với hoạt chất Melasyl. Sản phẩm giúp bảo vệ da trước tia UV, bao gồm UVA dài, đồng thời hỗ trợ cải thiện vẻ ngoài của đốm nâu và thâm sạm.\n\n2. CÔNG DỤNG\n\n- Bảo vệ da trước tia UVA và UVB theo chỉ số SPF50+ công bố.\n- Hỗ trợ bảo vệ da trước tia UVA dài 380–400nm.\n- Hỗ trợ dưỡng sáng và cải thiện vẻ ngoài của đốm nâu.\n- Giúp da trông đều màu hơn.\n- Kết cấu lỏng nhẹ, dễ tán.\n- Được hãng giới thiệu có khả năng kháng nước, mồ hôi và cát.\n\n3. THÀNH PHẦN\n\nCác thành phần nổi bật:\n- Mexoryl 400: Công nghệ màng lọc chống nắng hỗ trợ bảo vệ trước tia UVA dài.\n- Melasyl: Thành phần được hãng giới thiệu để hỗ trợ cải thiện đốm nâu.\n- Hệ bộ lọc chống nắng kết hợp: Hỗ trợ bảo vệ da trước tia UV.\n- Glycerin: Thành phần giữ ẩm.\n\nLưu ý: Thành phần nổi bật không thay thế danh sách INCI đầy đủ trên bao bì.\n\n4. HƯỚNG DẪN SỬ DỤNG\n\nLắc sản phẩm nếu nhãn yêu cầu. Thoa đều lượng đủ lên toàn bộ vùng da cần bảo vệ trước khi tiếp xúc ánh nắng. Thoa lại thường xuyên, khoảng mỗi 2 giờ khi hoạt động ngoài trời kéo dài, đặc biệt sau khi bơi, đổ mồ hôi hoặc lau da. Tránh để sản phẩm dính vào mắt.\n\nLưu ý chung: Chỉ dùng ngoài da. Ngừng sử dụng nếu có kích ứng kéo dài. Bảo quản theo hướng dẫn trên bao bì.\n\n5. ĐỐI TƯỢNG SỬ DỤNG\n\n- Người cần chống nắng hằng ngày.\n- Người quan tâm đến đốm nâu, thâm sau mụn và da không đều màu.\n- Người cần sản phẩm chống nắng kết cấu lỏng nhẹ.\n- Người thường xuyên tiếp xúc với ánh nắng.", "en": "1. PRODUCT DESCRIPTION\n\nLa Roche-Posay Anthelios UVMune 400 Anti-Dark Spots Fluid SPF50+ is a high-protection facial sunscreen intended for daily defense against ultraviolet radiation. The UVMune 400 technology family includes the Mexoryl 400 UV filter, developed to address long UVA wavelengths, alongside other UV filters that help protect against UVA and UVB exposure. Daily sunscreen use is an essential step in managing the appearance of sun-related dark spots and premature photoaging. The exact Anti-Dark Spots version, including any added pigment-care ingredients or tint, should be confirmed against the 50ml packaging before publication.\n\n2. BENEFITS\n\n• Provides high sun protection with SPF50+.\n• Helps protect skin against UVA and UVB radiation.\n• Supports prevention of UV-related dark spots.\n• Helps reduce the risk of visible photoaging caused by sun exposure.\n• Offers a fluid texture suitable for everyday facial application.\n• Complements skincare routines focused on uneven skin tone.\n\n3. INGREDIENTS\n\nKey ingredients and their functions:\n\n• Mexoryl 400: A UV filter designed to protect against ultra-long UVA wavelengths.\n• Additional UVA and UVB Filters: Work together to provide broad-spectrum sun protection.\n• Glycerin: A humectant used in some UVMune 400 formulations.\n• Tocopherol: An antioxidant ingredient used in some versions.\n• Important: Additional anti-dark-spot actives, pigment ingredients and the complete INCI must be confirmed for this specific product; do not assume they match the Invisible Fluid or Oil Control Fluid.\n\nNote: These are selected key ingredients, not a complete INCI declaration. Ingredients may vary by formulation and market. Verify the current packaging before publication.\n\n4. DIRECTIONS FOR USE\n\n1. Shake the bottle if instructed on the packaging.\n2. Apply generously and evenly over the face and neck before sun exposure.\n3. Use as the final step of the morning skincare routine.\n4. Reapply frequently, particularly after swimming, sweating or towel-drying.\n5. Avoid prolonged direct sunlight and use additional sun-protection measures.\n6. Follow the actual packaging for any specific application instructions.\n\nPrecautions: For external use only. Avoid direct contact with eyes. Discontinue use if irritation occurs. Follow professional guidance for post-procedure skincare.\n\n5. SUITABLE FOR\n\n• People seeking high daily UV protection.\n• Individuals concerned about sun-related dark spots.\n• People with uneven-looking skin tone.\n• Those incorporating sunscreen into an anti-aging skincare routine."}, "image": "assets/catalog/product-la-roche-posay-07.jpg", "gallery": {"vi": [{"src": "assets/catalog/vi/la-roche-posay-07/thumbnail.webp", "label": "Thumbnail", "order": 0}, {"src": "assets/catalog/vi/la-roche-posay-07/anh-1.webp", "label": "Ảnh 1", "order": 1}, {"src": "assets/catalog/vi/la-roche-posay-07/anh-2.webp", "label": "Ảnh 2", "order": 2}, {"src": "assets/catalog/vi/la-roche-posay-07/anh-3.webp", "label": "Ảnh 3", "order": 3}, {"src": "assets/catalog/vi/la-roche-posay-07/anh-4.webp", "label": "Ảnh 4", "order": 4}, {"src": "assets/catalog/vi/la-roche-posay-07/anh-5.webp", "label": "Ảnh 5", "order": 5}, {"src": "assets/catalog/vi/la-roche-posay-07/anh-6.webp", "label": "Ảnh 6", "order": 6}, {"src": "assets/catalog/vi/la-roche-posay-07/anh-7.webp", "label": "Ảnh 7", "order": 7}]}}, {"id": "kyunglab-01", "brandId": "kyunglab", "brand": "KyungLab", "name": {"vi": "KYUNGLAB CLEANSING GEL 150ML", "en": "KYUNGLAB Cleansing Gel 150ml"}, "category": "Skincare", "type": "Gel làm sạch và tẩy trang", "size": "150ml", "country": "Hàn Quốc", "description": {"vi": "1. MÔ TẢ SẢN PHẨM\n\nTên sản phẩm: KYUNGLAB Cleansing Gel 150ml\nThương hiệu: KYUNGLAB\nXuất xứ: Hàn Quốc\nQuy cách: 150ml\nPhân loại: Gel làm sạch và tẩy trang\n\nKYUNGLAB Cleansing Gel là gel làm sạch có khả năng hỗ trợ loại bỏ bụi bẩn, dầu thừa và cặn trang điểm trên bề mặt da. Công thức kết hợp trà xanh Hadong, chiết xuất hoa trà Nhật Bản, rau sam và thành phần dưỡng ẩm, hướng đến trải nghiệm làm sạch dịu nhẹ.\n\n2. CÔNG DỤNG\n\n• Làm sạch bụi bẩn, dầu thừa và cặn trang điểm.\n• Hỗ trợ duy trì độ ẩm sau khi làm sạch.\n• Giúp da có cảm giác mềm mại, thông thoáng.\n• Hỗ trợ làm dịu da trong quá trình làm sạch.\n\n3. THÀNH PHẦN\n\nCác thành phần nổi bật:\n• Trà xanh Hadong: Hỗ trợ chống oxy hóa.\n• Chiết xuất hoa trà Nhật Bản: Thành phần chăm sóc da.\n• Hyaluronic Acid đa phân tử: Hỗ trợ giữ ẩm.\n• Chiết xuất rau sam: Hỗ trợ làm dịu.\n• Bơ hạt mỡ lên men: Hỗ trợ làm mềm da và quá trình làm sạch.\n\nLưu ý: Đây không phải danh sách INCI đầy đủ. Đối chiếu nhãn sản phẩm thực tế khi công bố bảng thành phần.\n\n4. HƯỚNG DẪN SỬ DỤNG\n\nLấy lượng gel vừa đủ, massage nhẹ trên da theo hướng dẫn của bao bì rồi làm sạch lại với nước. Nếu dùng để tẩy trang, cần bảo đảm đã loại bỏ hoàn toàn sản phẩm trang điểm; trang điểm chống nước có thể cần sản phẩm tẩy trang chuyên dụng.\n\nLưu ý: Chỉ dùng ngoài da. Ngừng sử dụng nếu xuất hiện kích ứng. Bảo quản nơi thoáng mát, tránh ánh nắng trực tiếp.\n\n5. ĐỐI TƯỢNG SỬ DỤNG\n\nNgười cần làm sạch hằng ngày; da thường, da hỗn hợp hoặc da nhạy cảm có khả năng dung nạp phù hợp.", "en": "1. PRODUCT DESCRIPTION\n\nKYUNGLAB Cleansing Gel is a gentle daily facial cleanser developed to remove excess oil, dirt and accumulated impurities while helping the skin retain a comfortable level of moisture. Its foaming gel texture provides a refreshing cleansing experience without the need for harsh scrubbing. The formula features Hadong green tea, Japanese camellia flower extract, hyaluronic acid and purslane extract, alongside fermented shea butter. It is designed to prepare the skin for subsequent skincare steps while supporting a softer and more balanced skin feel.\n\n2. BENEFITS\n\n• Removes daily impurities and excess surface oil.\n• Produces a soft, comfortable cleansing foam.\n• Helps maintain skin hydration during cleansing.\n• Supports a smoother, refreshed complexion.\n• Provides botanical skin-conditioning care.\n\n3. INGREDIENTS\n\nKey ingredients and their functions:\n\n• Hadong Green Tea: A botanical ingredient with antioxidant properties.\n• Japanese Camellia Flower Extract: Helps condition the skin.\n• Hyaluronic Acid Complex: Supports moisture retention.\n• Purslane Extract: A botanical ingredient used in soothing skincare.\n• Fermented Shea Butter: A skin-conditioning ingredient featured in the cleansing formula.\n\nNote: These are selected ingredients from published product information, not the complete INCI list. Verify the actual packaging, particularly when distinguishing original and upgraded formulations.\n\n4. DIRECTIONS FOR USE\n\n1. Wet the face with lukewarm water.\n2. Dispense an appropriate amount of cleansing gel.\n3. Work into a light foam between the palms.\n4. Massage gently over the face, avoiding the eye area.\n5. Rinse thoroughly and pat dry.\n6. Follow with toner, ampoule and moisturizer.\n\nPrecautions: For external use only. Avoid direct contact with eyes. Discontinue use if irritation occurs. Keep out of reach of children.\n\n5. SUITABLE FOR\n\n• Normal, combination and oily skin.\n• People seeking gentle daily facial cleansing.\n• Dehydrated skin requiring a comfortable cleansing routine.\n• Sensitive skin, subject to individual tolerance."}, "image": "assets/catalog/product-kyunglab-01.png", "gallery": {"vi": [{"src": "assets/catalog/vi/kyunglab-01/thumbnail.webp", "label": "Thumbnail", "order": 0}, {"src": "assets/catalog/vi/kyunglab-01/anh-1.webp", "label": "Ảnh 1", "order": 1}, {"src": "assets/catalog/vi/kyunglab-01/anh-2.webp", "label": "Ảnh 2", "order": 2}, {"src": "assets/catalog/vi/kyunglab-01/anh-3.webp", "label": "Ảnh 3", "order": 3}, {"src": "assets/catalog/vi/kyunglab-01/anh-4.webp", "label": "Ảnh 4", "order": 4}, {"src": "assets/catalog/vi/kyunglab-01/anh-5.webp", "label": "Ảnh 5", "order": 5}, {"src": "assets/catalog/vi/kyunglab-01/anh-6.webp", "label": "Ảnh 6", "order": 6}, {"src": "assets/catalog/vi/kyunglab-01/anh-7.webp", "label": "Ảnh 7", "order": 7}]}}, {"id": "kyunglab-02", "brandId": "kyunglab", "brand": "KyungLab", "name": {"vi": "KYUNGLAB CLEANSING WATER 300ML", "en": "KYUNGLAB Cleansing Water 300ml"}, "category": "Skincare", "type": "Nước tẩy trang", "size": "300ml", "country": "Hàn Quốc", "description": {"vi": "1. MÔ TẢ SẢN PHẨM\n\nTên sản phẩm: KYUNGLAB Cleansing Water 300ml\nThương hiệu: KYUNGLAB\nXuất xứ: Hàn Quốc\nQuy cách: 300ml\nPhân loại: Nước tẩy trang\n\nKYUNGLAB Cleansing Water là nước tẩy trang dành cho bước làm sạch hằng ngày, giúp loại bỏ bụi bẩn, dầu thừa và lớp trang điểm nhẹ. Công thức được giới thiệu với trà xanh Hadong, hoa trà Nhật Bản, rau sam và thành phần dưỡng ẩm.\n\n2. CÔNG DỤNG\n\n• Hỗ trợ làm sạch bụi bẩn và lớp trang điểm nhẹ.\n• Giúp bề mặt da thông thoáng.\n• Hỗ trợ duy trì cảm giác ẩm mượt.\n• Phù hợp bổ sung vào quy trình làm sạch buổi tối.\n\n3. THÀNH PHẦN\n\nCác thành phần nổi bật:\n• Trà xanh Hadong: Hỗ trợ chống oxy hóa.\n• Chiết xuất hoa trà Nhật Bản: Chăm sóc bề mặt da.\n• Hyaluronic Acid đa phân tử: Hỗ trợ cấp ẩm.\n• Chiết xuất rau sam: Hỗ trợ làm dịu.\n• Bơ hạt mỡ lên men: Thành phần được hãng giới thiệu trong công thức làm sạch.\n\nLưu ý: Đây không phải danh sách INCI đầy đủ. Đối chiếu nhãn sản phẩm thực tế khi công bố bảng thành phần.\n\n4. HƯỚNG DẪN SỬ DỤNG\n\nThấm sản phẩm lên bông tẩy trang, lau nhẹ theo chiều da đến khi bông sạch. Không chà xát mạnh, đặc biệt ở vùng mắt. Tiếp tục với bước rửa mặt nếu phù hợp hướng dẫn trên nhãn.\n\nLưu ý: Chỉ dùng ngoài da. Ngừng sử dụng nếu xuất hiện kích ứng. Bảo quản nơi thoáng mát, tránh ánh nắng trực tiếp.\n\n5. ĐỐI TƯỢNG SỬ DỤNG\n\nNgười cần tẩy trang hằng ngày; người sử dụng kem chống nắng hoặc trang điểm nhẹ; người ưu tiên sản phẩm làm sạch dạng nước.", "en": "1. PRODUCT DESCRIPTION\n\nKYUNGLAB Cleansing Water is a gentle water-based makeup remover designed to lift everyday makeup, sunscreen residue, surface oil and impurities from the skin. It features botanical extracts and moisturizing ingredients intended to support a comfortable cleansing experience. The formula includes Hadong green tea, Japanese camellia flower extract, hyaluronic acid, purslane extract and fermented shea butter. It is suitable as the first cleansing step before a facial wash, particularly for people who prefer lightweight makeup-removing products.\n\n2. BENEFITS\n\n• Helps remove everyday makeup and surface impurities.\n• Lifts excess oil and sunscreen residue.\n• Supports a comfortable, moisturized skin feel.\n• Helps minimize the need for excessive rubbing.\n• Prepares the face for a second cleansing step.\n\n3. INGREDIENTS\n\nKey ingredients and their functions:\n\n• Hadong Green Tea: Provides botanical antioxidant care.\n• Japanese Camellia Flower Extract: A skin-conditioning botanical ingredient.\n• Hyaluronic Acid Complex: Helps retain moisture.\n• Purslane Extract: Supports soothing skincare.\n• Fermented Shea Butter: Included as part of the product's conditioning formula.\n\nNote: These are selected ingredients from published product information, not the complete INCI list. Verify the actual packaging, particularly when distinguishing original and upgraded formulations.\n\n4. DIRECTIONS FOR USE\n\n1. Apply an adequate amount to a clean cotton pad.\n2. Gently wipe the face to remove makeup and impurities.\n3. Hold the cotton pad briefly over areas with makeup before wiping.\n4. Repeat with a fresh cotton pad until the skin is clean.\n5. Follow with a gentle facial cleanser if desired.\n6. Continue with the regular skincare routine.\n\nPrecautions: For external use only. Avoid direct contact with eyes. Discontinue use if irritation occurs. Keep out of reach of children.\n\n5. SUITABLE FOR\n\n• People who wear everyday makeup or sunscreen.\n• Normal, combination and sensitive skin.\n• Individuals looking for gentle makeup removal.\n• Those seeking a lightweight first-step cleanser."}, "image": "assets/catalog/product-kyunglab-02.jpg", "gallery": {"vi": [{"src": "assets/catalog/vi/kyunglab-02/thumbnail.webp", "label": "Thumbnail", "order": 0}, {"src": "assets/catalog/vi/kyunglab-02/anh-1.webp", "label": "Ảnh 1", "order": 1}, {"src": "assets/catalog/vi/kyunglab-02/anh-2.webp", "label": "Ảnh 2", "order": 2}, {"src": "assets/catalog/vi/kyunglab-02/anh-3.webp", "label": "Ảnh 3", "order": 3}, {"src": "assets/catalog/vi/kyunglab-02/anh-4.webp", "label": "Ảnh 4", "order": 4}, {"src": "assets/catalog/vi/kyunglab-02/anh-5.webp", "label": "Ảnh 5", "order": 5}, {"src": "assets/catalog/vi/kyunglab-02/anh-6.webp", "label": "Ảnh 6", "order": 6}, {"src": "assets/catalog/vi/kyunglab-02/anh-7.webp", "label": "Ảnh 7", "order": 7}]}}, {"id": "kyunglab-03", "brandId": "kyunglab", "brand": "KyungLab", "name": {"vi": "KYUNGLAB CENTELLA ASIATICA ENERGY AMPOULE 50ML", "en": "KYUNGLAB Centella Asiatica Energy Ampoule 50ml"}, "category": "Skincare", "type": "Tinh chất chăm sóc da dầu, dễ nổi mụn", "size": "50ml", "country": "Hàn Quốc", "description": {"vi": "1. MÔ TẢ SẢN PHẨM\n\nTên sản phẩm: KYUNGLAB Centella Asiatica Energy Ampoule 50ml – Phiên bản nâng cấp\nThương hiệu: KYUNGLAB\nXuất xứ: Hàn Quốc\nQuy cách: 50ml\nPhân loại: Tinh chất chăm sóc da dầu, dễ nổi mụn\n\nKYUNGLAB Centella Asiatica Energy Ampoule là tinh chất chăm sóc da có xu hướng tiết dầu và dễ nổi mụn. Phiên bản nâng cấp 50ml kết hợp chiết xuất tràm trà, rau má, Panthenol và các thành phần dưỡng ẩm, hướng đến việc làm dịu và chăm sóc bề mặt da.\n\n2. CÔNG DỤNG\n\n• Hỗ trợ làm dịu da dễ ửng đỏ.\n• Hỗ trợ chăm sóc da dầu, dễ nổi mụn.\n• Bổ sung độ ẩm và giảm cảm giác khô căng.\n• Hỗ trợ duy trì hàng rào bảo vệ da.\n• Giúp da trông mịn màng hơn.\n\n3. THÀNH PHẦN\n\nCác thành phần nổi bật:\n• Chiết xuất tràm trà và rau má: Hỗ trợ làm dịu, chăm sóc da dầu.\n• Phức hợp 17 amino acid: Thành phần dưỡng da.\n• Panthenol: Hỗ trợ giữ ẩm và làm dịu.\n• Betaine: Hỗ trợ duy trì độ ẩm.\n• Chiết xuất rễ hà thủ ô: Thành phần chống oxy hóa được hãng giới thiệu.\n\nLưu ý: Đây không phải danh sách INCI đầy đủ. Đối chiếu nhãn sản phẩm thực tế khi công bố bảng thành phần.\n\n4. HƯỚNG DẪN SỬ DỤNG\n\nSau khi làm sạch da và dùng toner nếu có, lấy lượng tinh chất vừa đủ thoa lên mặt, vỗ nhẹ rồi dùng kem dưỡng. Bắt đầu với lượng nhỏ nếu da nhạy cảm.\n\nLưu ý: Chỉ dùng ngoài da. Ngừng sử dụng nếu xuất hiện kích ứng. Bảo quản nơi thoáng mát, tránh ánh nắng trực tiếp.\n\n5. ĐỐI TƯỢNG SỬ DỤNG\n\nDa dầu, da hỗn hợp thiên dầu, da dễ nổi mụn hoặc da có nhu cầu làm dịu và bổ sung độ ẩm.", "en": "1. PRODUCT DESCRIPTION\n\nKYUNGLAB Centella Asiatica Energy Ampoule is a targeted skincare ampoule designed for oily and blemish-prone skin that needs soothing and moisturizing care. The upgraded 50ml formula features centella asiatica, tea tree extract, a complex of 17 amino acids, panthenol, betaine and polygonum multiflorum root extract. These ingredients support skin comfort and help maintain the moisture barrier while improving the appearance of skin affected by dryness and blemishes. The lightweight ampoule can be used as part of a daily skincare routine.\n\n2. BENEFITS\n\n• Helps soothe the appearance of stressed or blemish-prone skin.\n• Supports skin hydration and comfort.\n• Helps maintain the skin's protective moisture barrier.\n• Provides conditioning care for oily skin.\n• Supports a smoother, more balanced-looking complexion.\n\n3. INGREDIENTS\n\nKey ingredients and their functions:\n\n• Centella Asiatica Extract: A botanical ingredient associated with soothing care.\n• Tea Tree Extract: Used in skincare for oily and blemish-prone skin.\n• 17-Amino-Acid Complex: Provides skin-conditioning components.\n• Panthenol (Vitamin B5): Helps maintain skin comfort and hydration.\n• Betaine: A humectant that supports moisture balance.\n• Polygonum Multiflorum Root Extract: A botanical ingredient used for antioxidant skincare.\n\nNote: These are selected ingredients from published product information, not the complete INCI list. Verify the actual packaging, particularly when distinguishing original and upgraded formulations.\n\n4. DIRECTIONS FOR USE\n\n1. Cleanse the face and apply toner if desired.\n2. Dispense a suitable amount of ampoule.\n3. Spread evenly across the face, avoiding the eyes.\n4. Gently press until absorbed.\n5. Follow with moisturizer.\n6. Use morning and evening as tolerated, with sunscreen during the day.\n\nPrecautions: For external use only. Avoid direct contact with eyes. Discontinue use if irritation occurs. Keep out of reach of children.\n\n5. SUITABLE FOR\n\n• Oily and blemish-prone skin.\n• Skin that feels uncomfortable or stressed.\n• People seeking a centella-based ampoule.\n• Individuals needing lightweight soothing and moisturizing care."}, "image": "assets/catalog/product-kyunglab-03.jpg", "gallery": {"vi": [{"src": "assets/catalog/vi/kyunglab-03/thumbnail.webp", "label": "Thumbnail", "order": 0}, {"src": "assets/catalog/vi/kyunglab-03/anh-1.webp", "label": "Ảnh 1", "order": 1}, {"src": "assets/catalog/vi/kyunglab-03/anh-2.webp", "label": "Ảnh 2", "order": 2}, {"src": "assets/catalog/vi/kyunglab-03/anh-3.webp", "label": "Ảnh 3", "order": 3}, {"src": "assets/catalog/vi/kyunglab-03/anh-4.webp", "label": "Ảnh 4", "order": 4}, {"src": "assets/catalog/vi/kyunglab-03/anh-5.webp", "label": "Ảnh 5", "order": 5}, {"src": "assets/catalog/vi/kyunglab-03/anh-6.webp", "label": "Ảnh 6", "order": 6}, {"src": "assets/catalog/vi/kyunglab-03/anh-7.webp", "label": "Ảnh 7", "order": 7}]}}, {"id": "kyunglab-04", "brandId": "kyunglab", "brand": "KyungLab", "name": {"vi": "KYUNGLAB HA PLUS HYDRA AMPOULE 50ML", "en": "KYUNGLAB HA Plus Hydra Ampoule 50ml"}, "category": "Skincare", "type": "Tinh chất cấp ẩm", "size": "50ml", "country": "Hàn Quốc", "description": {"vi": "1. MÔ TẢ SẢN PHẨM\n\nTên sản phẩm: KYUNGLAB HA Plus Hydra Ampoule 50ml – Phiên bản nâng cấp\nThương hiệu: KYUNGLAB\nXuất xứ: Hàn Quốc\nQuy cách: 50ml\nPhân loại: Tinh chất cấp ẩm\n\nKYUNGLAB HA Plus Hydra Ampoule là tinh chất dưỡng ẩm với Hyaluronic Acid đa phân tử, Panthenol, Beta-Glucan và peptide. Phiên bản nâng cấp 50ml hướng đến làn da thiếu nước, khô căng và cần cải thiện cảm giác mềm mại.\n\n2. CÔNG DỤNG\n\n• Bổ sung và duy trì độ ẩm.\n• Giúp da trông căng mượt, mềm mại.\n• Hỗ trợ làm dịu cảm giác khô căng.\n• Hỗ trợ hàng rào giữ ẩm của da.\n• Giúp cải thiện vẻ ngoài của nếp nhăn nhỏ do thiếu ẩm.\n\n3. THÀNH PHẦN\n\nCác thành phần nổi bật:\n• Hyaluronic Acid đa phân tử: Hỗ trợ cấp ẩm.\n• Guaiazulene: Hỗ trợ làm dịu.\n• Panthenol: Hỗ trợ giữ ẩm.\n• Beta-Glucan: Thành phần dưỡng ẩm.\n• Phức hợp 28 peptide: Thành phần chăm sóc da.\n• Chiết xuất cây tre mỡ và phức hợp 9 loại thảo dược: Được hãng giới thiệu trong công thức.\n\nLưu ý: Đây không phải danh sách INCI đầy đủ. Đối chiếu nhãn sản phẩm thực tế khi công bố bảng thành phần.\n\n4. HƯỚNG DẪN SỬ DỤNG\n\nLàm sạch da, dùng toner nếu có. Thoa lượng tinh chất vừa đủ lên mặt và cổ, vỗ nhẹ. Tiếp tục bằng kem dưỡng để hỗ trợ duy trì độ ẩm. Có thể dùng sáng và tối nếu da dung nạp tốt.\n\nLưu ý: Chỉ dùng ngoài da. Ngừng sử dụng nếu xuất hiện kích ứng. Bảo quản nơi thoáng mát, tránh ánh nắng trực tiếp.\n\n5. ĐỐI TƯỢNG SỬ DỤNG\n\nDa khô, da thiếu nước, da thường hoặc da hỗn hợp cần bổ sung độ ẩm; người muốn da trông căng mượt hơn.", "en": "1. PRODUCT DESCRIPTION\n\nKYUNGLAB HA Plus Hydra Ampoule is a concentrated moisturizing treatment developed for dehydrated skin. The upgraded formula combines a multi-molecular-weight hyaluronic acid complex with panthenol, beta-glucan, bamboo extract and a peptide complex. It is designed to replenish moisture, improve the appearance of fine dehydration lines and support a soft, supple complexion. Its serum-like texture makes it suitable for layering beneath moisturizer in both morning and evening skincare routines.\n\n2. BENEFITS\n\n• Helps replenish moisture in dehydrated skin.\n• Supports a plumper and smoother-looking complexion.\n• Helps soften fine lines associated with dryness.\n• Supports skin comfort and moisture-barrier care.\n• Provides additional hydration beneath daily moisturizer.\n\n3. INGREDIENTS\n\nKey ingredients and their functions:\n\n• Multi-Molecular-Weight Hyaluronic Acid Complex: Helps attract and retain moisture.\n• Panthenol: Supports hydration and skin comfort.\n• Beta-Glucan: A moisturizing and skin-conditioning polysaccharide.\n• Bambusa Vulgaris Extract: A bamboo-derived botanical ingredient.\n• Guaiazulene: A skin-conditioning ingredient associated with soothing care.\n• 28-Peptide Complex: A blend of peptides featured in the upgraded formulation.\n\nNote: These are selected ingredients from published product information, not the complete INCI list. Verify the actual packaging, particularly when distinguishing original and upgraded formulations.\n\n4. DIRECTIONS FOR USE\n\n1. Cleanse and tone the face.\n2. Apply an appropriate amount of ampoule.\n3. Distribute evenly over the face and neck.\n4. Gently pat until absorbed.\n5. Seal in moisture with a suitable cream.\n6. Use morning and evening, followed by sunscreen during the day.\n\nPrecautions: For external use only. Avoid direct contact with eyes. Discontinue use if irritation occurs. Keep out of reach of children.\n\n5. SUITABLE FOR\n\n• Dry and dehydrated skin.\n• People concerned about tightness from moisture loss.\n• Individuals seeking a hydrating ampoule.\n• Skin requiring additional moisture-barrier support."}, "image": "assets/catalog/product-kyunglab-04.jpg", "gallery": {"vi": [{"src": "assets/catalog/vi/kyunglab-04/thumbnail.webp", "label": "Thumbnail", "order": 0}, {"src": "assets/catalog/vi/kyunglab-04/anh-1.webp", "label": "Ảnh 1", "order": 1}, {"src": "assets/catalog/vi/kyunglab-04/anh-2.webp", "label": "Ảnh 2", "order": 2}, {"src": "assets/catalog/vi/kyunglab-04/anh-3.webp", "label": "Ảnh 3", "order": 3}, {"src": "assets/catalog/vi/kyunglab-04/anh-4.webp", "label": "Ảnh 4", "order": 4}, {"src": "assets/catalog/vi/kyunglab-04/anh-5.webp", "label": "Ảnh 5", "order": 5}, {"src": "assets/catalog/vi/kyunglab-04/anh-6.webp", "label": "Ảnh 6", "order": 6}, {"src": "assets/catalog/vi/kyunglab-04/anh-7.webp", "label": "Ảnh 7", "order": 7}]}}, {"id": "kyunglab-05", "brandId": "kyunglab", "brand": "KyungLab", "name": {"vi": "KYUNGLAB DAY CREAM 50ML", "en": "KYUNGLAB Day Cream 50ml"}, "category": "Skincare", "type": "Kem dưỡng ban ngày nâng tông", "size": "50ml", "country": "Hàn Quốc", "description": {"vi": "1. MÔ TẢ SẢN PHẨM\n\nTên sản phẩm: KYUNGLAB Day Cream 50ml\nThương hiệu: KYUNGLAB\nXuất xứ: Hàn Quốc\nQuy cách: 50ml\nPhân loại: Kem dưỡng ban ngày nâng tông\n\nKYUNGLAB Day Cream là kem dưỡng ban ngày có hiệu ứng nâng tông tự nhiên. Sản phẩm kết hợp các chiết xuất thực vật, Hyaluronic Acid, Niacinamide và thành phần làm mềm da, giúp bề mặt da trông tươi sáng và ẩm mượt.\n\n2. CÔNG DỤNG\n\n• Dưỡng ẩm và hỗ trợ hạn chế khô căng.\n• Tạo hiệu ứng nâng tông tức thì.\n• Giúp da trông đều màu, tươi tắn.\n• Hỗ trợ chống oxy hóa và làm dịu.\n• Có thể dùng như bước dưỡng trước trang điểm.\n\n3. THÀNH PHẦN\n\nCác thành phần nổi bật:\n• Chiết xuất quả mâm xôi: Thành phần chống oxy hóa.\n• Chiết xuất cây tre mỡ, ngải cứu và rau má: Hỗ trợ làm dịu.\n• Hyaluronic Acid đa phân tử: Hỗ trợ giữ ẩm.\n• Bơ hạt mỡ: Làm mềm da.\n• Niacinamide và Glutathione: Hỗ trợ dưỡng sáng.\n• Titanium Dioxide: Thành phần có trong công thức; không đồng nghĩa sản phẩm có chỉ số SPF được công bố.\n\nLưu ý: Đây không phải danh sách INCI đầy đủ. Đối chiếu nhãn sản phẩm thực tế khi công bố bảng thành phần.\n\n4. HƯỚNG DẪN SỬ DỤNG\n\nBuổi sáng, sau khi làm sạch, toner và tinh chất, thoa lượng kem vừa đủ lên mặt và cổ. Tiếp tục sử dụng kem chống nắng có chỉ số SPF phù hợp. Có thể dùng trước bước trang điểm.\n\nLưu ý: Chỉ dùng ngoài da. Ngừng sử dụng nếu xuất hiện kích ứng. Bảo quản nơi thoáng mát, tránh ánh nắng trực tiếp.\n\n5. ĐỐI TƯỢNG SỬ DỤNG\n\nNgười muốn dưỡng ẩm và nâng tông nhẹ ban ngày; người có da xỉn màu hoặc không đều màu; các loại da có khả năng dung nạp phù hợp.", "en": "1. PRODUCT DESCRIPTION\n\nKYUNGLAB Day Cream is a daytime facial moisturizer designed to hydrate the skin while creating an immediately brighter, more even-looking appearance. Its lightweight, milky texture provides a natural tone-up effect that can complement a simple daytime makeup routine. The formula features botanical extracts, hyaluronic acid, niacinamide and glutathione, alongside titanium dioxide for the cosmetic finish. It should be used with a separately labeled sunscreen because the presence of titanium dioxide alone does not establish an SPF rating.\n\n2. BENEFITS\n\n• Moisturizes and softens the skin.\n• Creates an immediate tone-up appearance.\n• Helps improve the look of dull or uneven skin tone.\n• Provides lightweight daytime conditioning.\n• Helps create a smoother-looking base for makeup.\n\n3. INGREDIENTS\n\nKey ingredients and their functions:\n\n• Niacinamide: Supports a more even-looking complexion.\n• Glutathione: An antioxidant ingredient used in brightening skincare.\n• Hyaluronic Acid and Sodium Hyaluronate: Help retain moisture.\n• Centella Asiatica Extract: Supports skin comfort.\n• Bamboo and Mugwort Extracts: Botanical skin-conditioning ingredients.\n• Raspberry Extract: A botanical antioxidant ingredient.\n• Shea Butter Extract: Helps soften the skin.\n• Titanium Dioxide: A pigment that can contribute to a tone-up finish.\n\nNote: These are selected ingredients from published product information, not the complete INCI list. Verify the actual packaging, particularly when distinguishing original and upgraded formulations.\n\n4. DIRECTIONS FOR USE\n\n1. Cleanse the face and apply toner and serum.\n2. Apply a suitable amount of day cream evenly over the face.\n3. Blend gently along the jawline and neck for a natural finish.\n4. Allow the product to settle.\n5. Apply a separately labeled broad-spectrum sunscreen before sun exposure.\n6. Continue with makeup if desired.\n\nPrecautions: For external use only. Avoid direct contact with eyes. Discontinue use if irritation occurs. Keep out of reach of children.\n\n5. SUITABLE FOR\n\n• People seeking a moisturizing daytime cream.\n• Individuals who prefer a natural tone-up effect.\n• Dull or uneven-looking skin.\n• Those looking for a lightweight makeup-preparation cream."}, "image": "assets/catalog/product-kyunglab-05.jpg", "gallery": {"vi": [{"src": "assets/catalog/vi/kyunglab-05/thumbnail.webp", "label": "Thumbnail", "order": 0}, {"src": "assets/catalog/vi/kyunglab-05/anh-1.webp", "label": "Ảnh 1", "order": 1}, {"src": "assets/catalog/vi/kyunglab-05/anh-2.webp", "label": "Ảnh 2", "order": 2}, {"src": "assets/catalog/vi/kyunglab-05/anh-3.webp", "label": "Ảnh 3", "order": 3}, {"src": "assets/catalog/vi/kyunglab-05/anh-4.webp", "label": "Ảnh 4", "order": 4}, {"src": "assets/catalog/vi/kyunglab-05/anh-5.webp", "label": "Ảnh 5", "order": 5}, {"src": "assets/catalog/vi/kyunglab-05/anh-6.webp", "label": "Ảnh 6", "order": 6}, {"src": "assets/catalog/vi/kyunglab-05/anh-7.webp", "label": "Ảnh 7", "order": 7}]}}, {"id": "kyunglab-06", "brandId": "kyunglab", "brand": "KyungLab", "name": {"vi": "KYUNGLAB ETERNAL FIT CUSHION 14G", "en": "KYUNGLAB Eternal Fit Cushion 14g"}, "category": "Makeup", "type": "Phấn nước trang điểm", "size": "14g", "country": "Hàn Quốc", "description": {"vi": "1. MÔ TẢ SẢN PHẨM\n\nTên sản phẩm: KYUNGLAB Eternal Fit Cushion 14g\nThương hiệu: KYUNGLAB\nXuất xứ: Hàn Quốc\nQuy cách: 14g\nPhân loại: Phấn nước trang điểm\n\nKYUNGLAB Eternal Fit Cushion là phấn nước trang điểm 14g với hiệu ứng lớp nền mịn lì, hỗ trợ che phủ khuyết điểm và làm đều màu da. Website Việt Nam giới thiệu ba tông màu Pink, Rose và Fairlight cùng chỉ số SPF50+ PA+++.\n\n2. CÔNG DỤNG\n\n• Tạo lớp nền trang điểm mịn màng.\n• Hỗ trợ che phủ khuyết điểm và vết thâm.\n• Giúp da trông đều màu hơn.\n• Tạo hiệu ứng nâng tông theo màu đã chọn.\n• Có chỉ số chống nắng SPF50+ PA+++ theo thông tin hãng.\n\n3. THÀNH PHẦN\n\nCác thành phần nổi bật:\n• Niacinamide: Thành phần dưỡng da được hãng giới thiệu.\n• Adenosine: Thành phần chăm sóc da.\n• Hệ sắc tố trang điểm và bộ lọc chống nắng: Cần đối chiếu bảng INCI trên bao bì để xác định cụ thể.\n• Màu sắc: Pink (trắng sáng), Rose (trắng hồng), Fairlight (tự nhiên).\n\nLưu ý: Đây không phải danh sách INCI đầy đủ. Đối chiếu nhãn sản phẩm thực tế khi công bố bảng thành phần.\n\n4. HƯỚNG DẪN SỬ DỤNG\n\nSau bước dưỡng da và chống nắng, dùng bông phấn lấy lượng cushion vừa đủ, dặm đều từ giữa mặt ra ngoài. Có thể dặm thêm ở vùng cần che phủ. Không nên dựa vào lớp cushion mỏng như nguồn chống nắng duy nhất khi tiếp xúc nắng kéo dài.\n\nLưu ý: Chỉ dùng ngoài da. Ngừng sử dụng nếu xuất hiện kích ứng. Bảo quản nơi thoáng mát, tránh ánh nắng trực tiếp.\n\n5. ĐỐI TƯỢNG SỬ DỤNG\n\nNgười cần lớp nền trang điểm tự nhiên; người muốn che phủ khuyết điểm nhẹ đến vừa; người thích hiệu ứng mịn lì.", "en": "1. PRODUCT DESCRIPTION\n\nKYUNGLAB Eternal Fit Cushion is a compact cushion foundation designed to create an even-looking complexion with a smooth, softly radiant finish. The product provides cosmetic coverage to help conceal visible redness, uneven tone and minor imperfections while maintaining a lightweight makeup feel. The brand lists SPF50+ PA+++ protection for this cushion, although adequate sunscreen should still be applied separately for reliable daily protection. The cushion is available in Pink, Rose and Fairlight shades, so the exact shade must be selected when creating a product variant.\n\n2. BENEFITS\n\n• Helps create an even-looking skin tone.\n• Provides coverage for minor visible imperfections.\n• Offers a lightweight cushion makeup texture.\n• Creates a smooth, naturally radiant finish.\n• Convenient for makeup application and touch-ups.\n• Carries an SPF50+ PA+++ rating according to the brand's product information.\n\n3. INGREDIENTS\n\nKey ingredients and their functions:\n\n• Niacinamide: A skin-conditioning ingredient.\n• Adenosine: Used in cosmetic formulas focused on the appearance of fine lines.\n• Color Pigments: Provide shade-specific foundation coverage.\n• UV Filters: Provide the labeled sun-protection function; exact filter names require INCI verification.\n• Additional Emollients and Film Formers: Support the cushion's smooth makeup texture.\n\nNote: These are selected ingredients from published product information, not the complete INCI list. Verify the actual packaging, particularly when distinguishing original and upgraded formulations.\n\n4. DIRECTIONS FOR USE\n\n1. Complete the skincare routine and apply sunscreen.\n2. Press the cushion puff lightly onto the product.\n3. Pat onto the face, beginning at the center.\n4. Blend outward to create an even finish.\n5. Build coverage gradually on areas requiring additional correction.\n6. Close the compact securely after use and clean the puff regularly.\n\nPrecautions: For external use only. Avoid direct contact with eyes. Discontinue use if irritation occurs. Keep out of reach of children.\n\n5. SUITABLE FOR\n\n• People seeking a convenient cushion foundation.\n• Individuals wanting an even-looking complexion.\n• Those who prefer lightweight foundation textures.\n• Makeup users seeking a softly radiant finish."}, "image": "assets/catalog/product-kyunglab-06.jpg", "gallery": {"vi": [{"src": "assets/catalog/vi/kyunglab-06/thumbnail.webp", "label": "Thumbnail", "order": 0}, {"src": "assets/catalog/vi/kyunglab-06/anh-1.webp", "label": "Ảnh 1", "order": 1}, {"src": "assets/catalog/vi/kyunglab-06/anh-2.webp", "label": "Ảnh 2", "order": 2}, {"src": "assets/catalog/vi/kyunglab-06/anh-3.webp", "label": "Ảnh 3", "order": 3}, {"src": "assets/catalog/vi/kyunglab-06/anh-4.webp", "label": "Ảnh 4", "order": 4}, {"src": "assets/catalog/vi/kyunglab-06/anh-5.webp", "label": "Ảnh 5", "order": 5}, {"src": "assets/catalog/vi/kyunglab-06/anh-6.webp", "label": "Ảnh 6", "order": 6}, {"src": "assets/catalog/vi/kyunglab-06/anh-7.webp", "label": "Ảnh 7", "order": 7}]}}, {"id": "kyunglab-07", "brandId": "kyunglab", "brand": "KyungLab", "name": {"vi": "KYUNGLAB PDRN THERAPY AMPOULE 50ML", "en": "KYUNGLAB PDRN Therapy Ampoule 50ml"}, "category": "Skincare", "type": "Tinh chất dưỡng da", "size": "50ml", "country": "Hàn Quốc", "description": {"vi": "1. MÔ TẢ SẢN PHẨM\n\nTên sản phẩm: KYUNGLAB PDRN Therapy Ampoule 50ml – Phiên bản nâng cấp\nThương hiệu: KYUNGLAB\nXuất xứ: Hàn Quốc\nQuy cách: 50ml\nPhân loại: Tinh chất dưỡng da\n\nKYUNGLAB PDRN Therapy Ampoule 50ml là tinh chất thuộc dòng chăm sóc da có dấu hiệu lão hóa. Công thức được website Việt Nam giới thiệu với Sodium DNA (PDRN), Betaine, chiết xuất rễ hà thủ ô và Adenosine, hướng đến nhu cầu dưỡng ẩm và cải thiện vẻ ngoài của da.\n\n2. CÔNG DỤNG\n\n• Bổ sung độ ẩm, giúp da mềm mại.\n• Hỗ trợ cải thiện vẻ ngoài của nếp nhăn nhỏ.\n• Giúp da trông căng mượt hơn.\n• Hỗ trợ chăm sóc da có dấu hiệu lão hóa.\n• Bổ sung thành phần chống oxy hóa.\n\n3. THÀNH PHẦN\n\nCác thành phần nổi bật:\n• Sodium DNA (PDRN) 30.000 ppm: Thành phần được hãng công bố cho phiên bản này.\n• Betaine: Hỗ trợ giữ ẩm.\n• Chiết xuất rễ hà thủ ô: Hỗ trợ chống oxy hóa.\n• Adenosine: Thành phần chăm sóc da có dấu hiệu lão hóa.\n\nLưu ý: Đây không phải danh sách INCI đầy đủ. Đối chiếu nhãn sản phẩm thực tế khi công bố bảng thành phần.\n\n4. HƯỚNG DẪN SỬ DỤNG\n\nSau bước làm sạch và toner, thoa lượng tinh chất vừa đủ lên mặt và cổ. Vỗ nhẹ rồi dùng kem dưỡng. Có thể sử dụng trong quy trình sáng hoặc tối theo khả năng dung nạp.\n\nLưu ý: Chỉ dùng ngoài da. Ngừng sử dụng nếu xuất hiện kích ứng. Bảo quản nơi thoáng mát, tránh ánh nắng trực tiếp.\n\n5. ĐỐI TƯỢNG SỬ DỤNG\n\nNgười có da khô, thiếu ẩm; người quan tâm đến dấu hiệu lão hóa; người muốn bổ sung tinh chất dưỡng da.", "en": "1. PRODUCT DESCRIPTION\n\nKYUNGLAB PDRN Therapy Ampoule is a concentrated facial skincare product developed to support hydration and improve the appearance of tired, dry and mature-looking skin. The upgraded formula features sodium DNA, also referred to in the product's marketing as PDRN, alongside betaine, adenosine and polygonum multiflorum root extract. It is intended to support a smoother, more supple complexion and improve skin comfort as part of a consistent cosmetic skincare routine. It is a topical skincare product, not an injectable treatment or a substitute for medical care.\n\n2. BENEFITS\n\n• Helps improve skin hydration and softness.\n• Supports smoother and more supple-looking skin.\n• Helps improve the appearance of fine lines associated with dryness.\n• Provides antioxidant and skin-conditioning care.\n• Supports a more refreshed-looking complexion.\n\n3. INGREDIENTS\n\nKey ingredients and their functions:\n\n• Sodium DNA (PDRN): Listed at 30,000 ppm in the brand's upgraded 50ml product information; a skin-conditioning ingredient.\n• Betaine: Helps attract and retain moisture.\n• Adenosine: Used in anti-aging cosmetic skincare.\n• Polygonum Multiflorum Root Extract: A botanical ingredient used for antioxidant care.\n• Other Ingredients: The complete INCI must be verified against the actual packaging.\n\nNote: These are selected ingredients from published product information, not the complete INCI list. Verify the actual packaging, particularly when distinguishing original and upgraded formulations.\n\n4. DIRECTIONS FOR USE\n\n1. Cleanse and tone the face.\n2. Dispense a suitable amount of ampoule.\n3. Apply evenly to the face and neck.\n4. Gently pat until absorbed.\n5. Follow with a moisturizer.\n6. Use as directed on the product packaging; apply sunscreen during the day.\n\nPrecautions: For external use only. Avoid direct contact with eyes. Discontinue use if irritation occurs. Keep out of reach of children.\n\n5. SUITABLE FOR\n\n• Dry or dehydrated skin.\n• People concerned about early visible signs of aging.\n• Individuals seeking a PDRN-containing cosmetic serum.\n• Skin needing additional conditioning and moisturizing care."}, "image": "assets/catalog/product-kyunglab-07.jpg", "gallery": {"vi": [{"src": "assets/catalog/vi/kyunglab-07/thumbnail.webp", "label": "Thumbnail", "order": 0}, {"src": "assets/catalog/vi/kyunglab-07/anh-1.webp", "label": "Ảnh 1", "order": 1}, {"src": "assets/catalog/vi/kyunglab-07/anh-2.webp", "label": "Ảnh 2", "order": 2}, {"src": "assets/catalog/vi/kyunglab-07/anh-3.webp", "label": "Ảnh 3", "order": 3}, {"src": "assets/catalog/vi/kyunglab-07/anh-4.webp", "label": "Ảnh 4", "order": 4}, {"src": "assets/catalog/vi/kyunglab-07/anh-5.webp", "label": "Ảnh 5", "order": 5}, {"src": "assets/catalog/vi/kyunglab-07/anh-6.webp", "label": "Ảnh 6", "order": 6}, {"src": "assets/catalog/vi/kyunglab-07/anh-7.webp", "label": "Ảnh 7", "order": 7}]}}, {"id": "kyunglab-08", "brandId": "kyunglab", "brand": "KyungLab", "name": {"vi": "KYUNGLAB PDRN THERAPY MIST 150ML", "en": "KYUNGLAB PDRN Therapy Mist 150ml"}, "category": "Skincare", "type": "Xịt dưỡng ẩm da", "size": "150ml", "country": "Hàn Quốc", "description": {"vi": "1. MÔ TẢ SẢN PHẨM\n\nTên sản phẩm: KYUNGLAB PDRN Therapy Mist 150ml\nThương hiệu: KYUNGLAB\nXuất xứ: Hàn Quốc\nQuy cách: 150ml\nPhân loại: Xịt dưỡng ẩm da\n\nKYUNGLAB PDRN Therapy Mist là sản phẩm xịt dưỡng da 150ml, được giới thiệu với Sodium DNA (PDRN), Panthenol, Betaine, rau má và Glutathione. Sản phẩm hướng đến nhu cầu cấp ẩm nhanh, hỗ trợ làm dịu và mang lại cảm giác tươi mát.\n\n2. CÔNG DỤNG\n\n• Bổ sung độ ẩm cho da.\n• Giúp giảm cảm giác khô căng.\n• Hỗ trợ làm dịu và chăm sóc hàng rào bảo vệ da.\n• Giúp da có cảm giác tươi mát.\n• Hỗ trợ chống oxy hóa.\n\n3. THÀNH PHẦN\n\nCác thành phần nổi bật:\n• Sodium DNA (PDRN) 50.000 ppm: Hàm lượng được hãng giới thiệu.\n• Panthenol: Hỗ trợ dưỡng ẩm và làm dịu.\n• Betaine: Hỗ trợ giữ nước.\n• Chiết xuất rau má: Hỗ trợ làm dịu.\n• Glutathione: Thành phần chống oxy hóa.\n\nLưu ý: Đây không phải danh sách INCI đầy đủ. Đối chiếu nhãn sản phẩm thực tế khi công bố bảng thành phần.\n\n4. HƯỚNG DẪN SỬ DỤNG\n\nGiữ chai ở khoảng cách phù hợp theo nhãn, nhắm mắt và xịt đều lên mặt. Để sản phẩm tự phân bố hoặc vỗ nhẹ. Có thể sử dụng khi da cần bổ sung độ ẩm. Tránh xịt trực tiếp vào mắt và không hít phải dạng sương.\n\nLưu ý: Chỉ dùng ngoài da. Ngừng sử dụng nếu xuất hiện kích ứng. Bảo quản nơi thoáng mát, tránh ánh nắng trực tiếp.\n\n5. ĐỐI TƯỢNG SỬ DỤNG\n\nNgười có da thiếu ẩm, khô căng; người muốn xịt dưỡng trong quy trình chăm sóc da; người cần làm dịu da sau tác động của môi trường.", "en": "1. PRODUCT DESCRIPTION\n\nKYUNGLAB PDRN Therapy Mist is a facial spray developed to refresh and moisturize the skin throughout the day. The formula features sodium DNA (PDRN), panthenol, betaine, centella asiatica extract and glutathione, combining hydration with skin-conditioning care. Its fine-mist format offers a convenient way to add moisture after cleansing or whenever the skin feels dry. The mist can complement a daily skincare routine, but it should not be presented as a medical treatment for damaged skin.\n\n2. BENEFITS\n\n• Provides a refreshing burst of hydration.\n• Helps soothe dryness-related discomfort.\n• Supports a soft and supple skin feel.\n• Provides convenient moisture care throughout the day.\n• Complements daily skin-barrier-supporting routines.\n\n3. INGREDIENTS\n\nKey ingredients and their functions:\n\n• Sodium DNA (PDRN): Listed at 50,000 ppm on the brand's current 150ml product page.\n• Panthenol: Supports moisture retention and skin comfort.\n• Betaine: A moisturizing humectant.\n• Centella Asiatica Extract: A botanical skin-conditioning ingredient.\n• Glutathione: An antioxidant ingredient used in cosmetic skincare.\n\nNote: These are selected ingredients from published product information, not the complete INCI list. Verify the actual packaging, particularly when distinguishing original and upgraded formulations.\n\n4. DIRECTIONS FOR USE\n\n1. Close the eyes and hold the bottle a suitable distance from the face.\n2. Spray evenly across the face without inhaling the mist.\n3. Allow the product to settle or gently pat until absorbed.\n4. Use after cleansing, before moisturizer or whenever additional hydration is desired.\n5. Avoid spraying directly into the eyes.\n6. Follow with moisturizer when needed.\n\nPrecautions: For external use only. Avoid direct contact with eyes. Discontinue use if irritation occurs. Keep out of reach of children.\n\n5. SUITABLE FOR\n\n• Dehydrated skin.\n• People seeking a refreshing facial mist.\n• Individuals who experience dryness during the day.\n• Those interested in PDRN-based skin-conditioning products."}, "image": "assets/catalog/product-kyunglab-08.jpg", "gallery": {"vi": [{"src": "assets/catalog/vi/kyunglab-08/thumbnail.webp", "label": "Thumbnail", "order": 0}, {"src": "assets/catalog/vi/kyunglab-08/anh-1.webp", "label": "Ảnh 1", "order": 1}, {"src": "assets/catalog/vi/kyunglab-08/anh-2.webp", "label": "Ảnh 2", "order": 2}, {"src": "assets/catalog/vi/kyunglab-08/anh-3.webp", "label": "Ảnh 3", "order": 3}, {"src": "assets/catalog/vi/kyunglab-08/anh-4.webp", "label": "Ảnh 4", "order": 4}, {"src": "assets/catalog/vi/kyunglab-08/anh-5.webp", "label": "Ảnh 5", "order": 5}, {"src": "assets/catalog/vi/kyunglab-08/anh-6.webp", "label": "Ảnh 6", "order": 6}, {"src": "assets/catalog/vi/kyunglab-08/anh-7.webp", "label": "Ảnh 7", "order": 7}]}}, {"id": "kyunglab-09", "brandId": "kyunglab", "brand": "KyungLab", "name": {"vi": "KYUNGLAB TRX PIGMENT CONTROL 50ML", "en": "KYUNGLAB TRX Pigment Control 50ml"}, "category": "Skincare", "type": "Tinh chất dưỡng sáng da", "size": "50ml", "country": "Hàn Quốc", "description": {"vi": "1. MÔ TẢ SẢN PHẨM\n\nTên sản phẩm: KYUNGLAB TRX Pigment Control 50ml – Phiên bản nâng cấp\nThương hiệu: KYUNGLAB\nXuất xứ: Hàn Quốc\nQuy cách: 50ml\nPhân loại: Tinh chất dưỡng sáng da\n\nKYUNGLAB TRX Pigment Control 50ml là tinh chất chăm sóc da không đều màu, được giới thiệu với Tranexamic Acid, Glutathione và Niacinamide. Phiên bản nâng cấp có dung tích 50ml, hướng đến nhu cầu dưỡng sáng và cải thiện vẻ ngoài của đốm sạm, thâm sau mụn.\n\n2. CÔNG DỤNG\n\n• Hỗ trợ dưỡng sáng và cải thiện độ đều màu.\n• Giúp làm mờ vẻ ngoài của vết thâm sau mụn.\n• Hỗ trợ chăm sóc da xỉn màu.\n• Bổ sung độ ẩm.\n• Hỗ trợ chống oxy hóa.\n\n3. THÀNH PHẦN\n\nCác thành phần nổi bật:\n• Tranexamic Acid 2%: Thành phần dưỡng da không đều màu.\n• Glutathione 5%: Hỗ trợ chống oxy hóa.\n• Niacinamide 5%: Hỗ trợ dưỡng sáng và hàng rào bảo vệ da.\n• Chiết xuất chanh vàng: Thành phần thực vật.\n• Panthenol và Betaine: Hỗ trợ dưỡng ẩm.\n• Chiết xuất rau má và dầu Jojoba: Hỗ trợ làm dịu, làm mềm.\n\nLưu ý: Đây không phải danh sách INCI đầy đủ. Đối chiếu nhãn sản phẩm thực tế khi công bố bảng thành phần.\n\n4. HƯỚNG DẪN SỬ DỤNG\n\nSau bước làm sạch và toner, thoa lượng tinh chất vừa đủ lên mặt hoặc vùng da cần chăm sóc. Tiếp tục bằng kem dưỡng. Sử dụng kem chống nắng vào ban ngày. Người có da nhạy cảm nên thử trên vùng nhỏ trước.\n\nLưu ý: Chỉ dùng ngoài da. Ngừng sử dụng nếu xuất hiện kích ứng. Bảo quản nơi thoáng mát, tránh ánh nắng trực tiếp.\n\n5. ĐỐI TƯỢNG SỬ DỤNG\n\nNgười có da xỉn màu, không đều màu; người có vết thâm sau mụn; người muốn bổ sung bước dưỡng sáng.", "en": "1. PRODUCT DESCRIPTION\n\nKYUNGLAB TRX Pigment Control is a targeted facial treatment developed to improve the appearance of uneven skin tone, dark spots and post-blemish marks. The upgraded formula features tranexamic acid, glutathione and niacinamide alongside botanical ingredients such as centella asiatica and lemon fruit extract. Its cosmetic brightening approach is intended to support a more radiant, even-looking complexion over time. Consistent broad-spectrum sunscreen use is important when caring for visible pigmentation concerns.\n\n2. BENEFITS\n\n• Helps improve the appearance of dark spots.\n• Supports a brighter and more even-looking skin tone.\n• Helps reduce the appearance of post-blemish discoloration.\n• Provides moisturizing and skin-conditioning care.\n• Supports a smoother and more radiant-looking complexion.\n\n3. INGREDIENTS\n\nKey ingredients and their functions:\n\n• Tranexamic Acid (2%): A cosmetic ingredient used to address visible discoloration.\n• Glutathione (5%): An antioxidant ingredient used in brightening formulas.\n• Niacinamide (5%): Helps improve the appearance of uneven skin tone and supports barrier care.\n• Panthenol: Helps maintain hydration and comfort.\n• Betaine: A moisture-retaining ingredient.\n• Centella Asiatica Extract: Supports skin conditioning.\n• Lemon Fruit Extract: A botanical ingredient used in the formula.\n• Jojoba Seed Oil: An emollient that helps soften the skin.\n\nNote: These are selected ingredients from published product information, not the complete INCI list. Verify the actual packaging, particularly when distinguishing original and upgraded formulations.\n\n4. DIRECTIONS FOR USE\n\n1. Cleanse the face and apply toner.\n2. Dispense an appropriate amount of the treatment.\n3. Apply evenly to the face or areas with uneven-looking pigmentation.\n4. Avoid direct contact with the eyes.\n5. Follow with moisturizer.\n6. Use broad-spectrum sunscreen every morning and reapply as needed.\n\nPrecautions: For external use only. Avoid direct contact with eyes. Discontinue use if irritation occurs. Keep out of reach of children.\n\n5. SUITABLE FOR\n\n• People concerned about visible dark spots.\n• Uneven or dull-looking skin.\n• Individuals with post-blemish marks.\n• Those seeking a targeted cosmetic brightening treatment."}, "image": "assets/catalog/product-kyunglab-09.jpg", "gallery": {"vi": [{"src": "assets/catalog/vi/kyunglab-09/thumbnail.webp", "label": "Thumbnail", "order": 0}, {"src": "assets/catalog/vi/kyunglab-09/anh-1.webp", "label": "Ảnh 1", "order": 1}, {"src": "assets/catalog/vi/kyunglab-09/anh-2.webp", "label": "Ảnh 2", "order": 2}, {"src": "assets/catalog/vi/kyunglab-09/anh-3.webp", "label": "Ảnh 3", "order": 3}, {"src": "assets/catalog/vi/kyunglab-09/anh-4.webp", "label": "Ảnh 4", "order": 4}, {"src": "assets/catalog/vi/kyunglab-09/anh-5.webp", "label": "Ảnh 5", "order": 5}, {"src": "assets/catalog/vi/kyunglab-09/anh-6.webp", "label": "Ảnh 6", "order": 6}, {"src": "assets/catalog/vi/kyunglab-09/anh-7.webp", "label": "Ảnh 7", "order": 7}]}}, {"id": "kyunglab-10", "brandId": "kyunglab", "brand": "KyungLab", "name": {"vi": "KYUNGLAB ULTRA HYDRATING MULTI CREAM 50ML", "en": "KYUNGLAB Ultra Hydrating Multi Cream 50ml"}, "category": "Skincare", "type": "Kem dưỡng ẩm", "size": "50ml", "country": "Hàn Quốc", "description": {"vi": "1. MÔ TẢ SẢN PHẨM\n\nTên sản phẩm: KYUNGLAB Ultra Hydrating Multi Cream 50ml – Phiên bản nâng cấp\nThương hiệu: KYUNGLAB\nXuất xứ: Hàn Quốc\nQuy cách: 50ml\nPhân loại: Kem dưỡng ẩm\n\nKYUNGLAB Ultra Hydrating Multi Cream là kem dưỡng ẩm phiên bản nâng cấp 50ml. Theo website Việt Nam, công thức nổi bật với chiết xuất cây tre mỡ, dầu hạt nho, hoa oải hương và Beta-Glucan, hướng đến việc duy trì độ ẩm và cải thiện cảm giác khô căng.\n\n2. CÔNG DỤNG\n\n• Dưỡng ẩm và hỗ trợ khóa ẩm.\n• Giúp da mềm mại, căng mượt.\n• Hỗ trợ giảm tình trạng mất nước trên bề mặt.\n• Làm dịu cảm giác khô căng.\n• Hỗ trợ chăm sóc hàng rào bảo vệ da.\n\n3. THÀNH PHẦN\n\nCác thành phần nổi bật:\n• Bambusa Vulgaris Extract (chiết xuất cây tre mỡ): Hỗ trợ làm dịu.\n• Dầu hạt nho: Thành phần làm mềm và chống oxy hóa.\n• Chiết xuất hoa oải hương: Thành phần chăm sóc da.\n• Beta-Glucan: Hỗ trợ giữ ẩm và làm dịu.\n\nLưu ý: Đây không phải danh sách INCI đầy đủ. Đối chiếu nhãn sản phẩm thực tế khi công bố bảng thành phần.\n\n4. HƯỚNG DẪN SỬ DỤNG\n\nSau bước làm sạch, toner và tinh chất, lấy lượng kem vừa đủ thoa đều lên mặt và cổ. Dùng sáng hoặc tối tùy nhu cầu. Buổi sáng kết hợp kem chống nắng.\n\nLưu ý: Chỉ dùng ngoài da. Ngừng sử dụng nếu xuất hiện kích ứng. Bảo quản nơi thoáng mát, tránh ánh nắng trực tiếp.\n\n5. ĐỐI TƯỢNG SỬ DỤNG\n\nNgười có da khô, thiếu ẩm; người cần kem dưỡng khóa ẩm; người muốn cải thiện cảm giác mềm mại của da.", "en": "1. PRODUCT DESCRIPTION\n\nKYUNGLAB Ultra Hydrating Multi Cream is a moisturizing facial cream designed to replenish hydration and improve the appearance of dry, rough and dehydrated skin. The upgraded formula features bamboo extract, grape seed oil, lavender flower extract and beta-glucan, providing a combination of emollient, moisturizing and antioxidant skin-conditioning care. Its nourishing texture helps maintain a soft, supple complexion and supports the skin's moisture barrier. It can be used as the final moisturizing step in both morning and evening skincare routines.\n\n2. BENEFITS\n\n• Helps replenish and retain skin moisture.\n• Softens rough and dry-feeling skin.\n• Supports the skin's protective moisture barrier.\n• Helps improve the appearance of dehydration-related dullness.\n• Leaves skin feeling smoother and more supple.\n\n3. INGREDIENTS\n\nKey ingredients and their functions:\n\n• Bambusa Vulgaris Extract: A bamboo-derived botanical skin-conditioning ingredient.\n• Grape Seed Oil: An emollient containing antioxidant-associated compounds.\n• Lavender Flower Extract: A botanical ingredient used for skin conditioning.\n• Beta-Glucan: A polysaccharide that supports hydration and skin comfort.\n• Other Moisturizing Components: The complete INCI should be checked against the current 50ml packaging.\n\nNote: These are selected ingredients from published product information, not the complete INCI list. Verify the actual packaging, particularly when distinguishing original and upgraded formulations.\n\n4. DIRECTIONS FOR USE\n\n1. Cleanse the face and apply toner.\n2. Apply any serums or ampoules included in the routine.\n3. Take an appropriate amount of cream.\n4. Spread evenly over the face and neck.\n5. Massage gently until absorbed.\n6. Use morning and evening; finish the daytime routine with sunscreen.\n\nPrecautions: For external use only. Avoid direct contact with eyes. Discontinue use if irritation occurs. Keep out of reach of children.\n\n5. SUITABLE FOR\n\n• Dry and dehydrated skin.\n• People experiencing roughness or moisture-related tightness.\n• Individuals seeking a nourishing facial cream.\n• Skin requiring additional moisturizing and conditioning care."}, "image": "assets/catalog/product-kyunglab-10.jpg", "gallery": {"vi": [{"src": "assets/catalog/vi/kyunglab-10/thumbnail.webp", "label": "Thumbnail", "order": 0}, {"src": "assets/catalog/vi/kyunglab-10/anh-1.webp", "label": "Ảnh 1", "order": 1}, {"src": "assets/catalog/vi/kyunglab-10/anh-2.webp", "label": "Ảnh 2", "order": 2}, {"src": "assets/catalog/vi/kyunglab-10/anh-3.webp", "label": "Ảnh 3", "order": 3}, {"src": "assets/catalog/vi/kyunglab-10/anh-4.webp", "label": "Ảnh 4", "order": 4}, {"src": "assets/catalog/vi/kyunglab-10/anh-5.webp", "label": "Ảnh 5", "order": 5}, {"src": "assets/catalog/vi/kyunglab-10/anh-6.webp", "label": "Ảnh 6", "order": 6}, {"src": "assets/catalog/vi/kyunglab-10/anh-7.webp", "label": "Ảnh 7", "order": 7}]}}, {"id": "cerave-01", "brandId": "cerave", "brand": "CeraVe", "name": {"vi": "CERAVE HYDRATING CLEANSER 236ML", "en": "CeraVe Hydrating Cleanser 236ml"}, "category": "Skincare", "type": "Sữa rửa mặt dưỡng ẩm", "size": "236ml", "country": "Hoa Kỳ", "description": {"vi": "1. MÔ TẢ SẢN PHẨM\n\nTên sản phẩm: CeraVe Hydrating Cleanser 236ml\nThương hiệu: CeraVe\nQuốc gia thương hiệu: Hoa Kỳ\nQuy cách đóng gói: 236ml\nPhân loại: Sữa rửa mặt dưỡng ẩm\n\nCeraVe Hydrating Cleanser 236ml là sữa rửa mặt dạng lotion dành cho da thường đến da khô. Sản phẩm được phát triển cùng bác sĩ da liễu, giúp làm sạch bụi bẩn và tạp chất mà vẫn duy trì cảm giác mềm mại sau khi rửa. Công thức nổi bật với ba ceramide thiết yếu và Hyaluronic Acid, hỗ trợ hàng rào giữ ẩm của da.\n\n2. CÔNG DỤNG\n\n• Làm sạch nhẹ nhàng bụi bẩn và tạp chất.\n• Hỗ trợ duy trì độ ẩm tự nhiên.\n• Giảm cảm giác khô căng sau khi rửa mặt.\n• Hỗ trợ bảo vệ hàng rào độ ẩm của da.\n\n3. THÀNH PHẦN\n\nCác thành phần nổi bật:\n\n• Ceramide NP, Ceramide AP, Ceramide EOP: Ba ceramide thiết yếu hỗ trợ hàng rào bảo vệ da.\n• Hyaluronic Acid/Sodium Hyaluronate: Hỗ trợ giữ nước và cấp ẩm.\n• Glycerin: Thành phần hút ẩm, giúp da mềm mại.\n\nLưu ý: Đây là thành phần nổi bật, không phải bảng INCI đầy đủ. Cần đối chiếu nhãn phiên bản thực tế.\n\n4. HƯỚNG DẪN SỬ DỤNG\n\nLàm ướt da bằng nước ấm vừa phải. Lấy lượng sản phẩm phù hợp, massage nhẹ nhàng trên da rồi rửa sạch. Có thể sử dụng buổi sáng và buổi tối.\n\nLưu ý: Chỉ dùng ngoài da. Tránh tiếp xúc với mắt. Ngừng sử dụng nếu xuất hiện kích ứng kéo dài. Bảo quản theo hướng dẫn trên bao bì.\n\n5. ĐỐI TƯỢNG SỬ DỤNG\n\n• Da thường đến da khô.\n• Da thiếu ẩm, dễ khô căng.\n• Người muốn sữa rửa mặt không tạo bọt mạnh.", "en": "1. PRODUCT DESCRIPTION\n\nCeraVe Hydrating Cleanser is a gentle, non-foaming facial cleanser developed with dermatologists for normal to dry skin. Its creamy lotion-like texture helps remove dirt, excess surface impurities and everyday buildup without leaving the skin feeling stripped or tight. Formulated with three essential ceramides and hyaluronic acid, it helps maintain the skin's natural protective barrier while supporting hydration during cleansing. The fragrance-free formula is suitable for a simple daily skincare routine, particularly when skin feels dry or uncomfortable after washing.\n\n2. BENEFITS\n\n• Gently removes dirt and everyday impurities.\n• Cleanses without creating a harsh, foaming sensation.\n• Helps maintain the skin's natural protective barrier.\n• Supports hydration during and after cleansing.\n• Leaves skin feeling soft, comfortable and refreshed.\n• Suitable for everyday morning and evening use.\n\n3. INGREDIENTS\n\nKey ingredients and their functions:\n\n• Ceramide NP, Ceramide AP and Ceramide EOP: Three essential ceramides that help maintain the skin's protective barrier.\n• Sodium Hyaluronate: A hyaluronic acid derivative that helps retain moisture.\n• Glycerin: A humectant that attracts water to the skin.\n• Cetearyl Alcohol: A fatty alcohol that helps soften skin and support the creamy texture.\n• Cholesterol: A skin-identical lipid that complements ceramide-based barrier care.\n• Phytosphingosine: A lipid-related ingredient that supports skin conditioning.\n\nNote: These are selected key ingredients and product technologies, not a complete INCI declaration. Formulas may vary by market and manufacturing version. Verify the current product packaging before publication.\n\n4. DIRECTIONS FOR USE\n\n1. Wet the face with lukewarm water.\n2. Dispense a suitable amount of cleanser into clean hands.\n3. Massage gently over the face using circular motions.\n4. Rinse thoroughly with water.\n5. Pat dry with a clean, soft towel.\n6. Follow with moisturizer and apply sunscreen during the day.\n\nPrecautions: For external use only. Avoid direct contact with eyes. Discontinue use if irritation occurs. Keep out of reach of children.\n\n5. SUITABLE FOR\n\n• Normal to dry skin.\n• People experiencing dryness or tightness after cleansing.\n• Sensitive skin seeking a fragrance-free cleanser.\n• Individuals who prefer a creamy, non-foaming cleansing texture."}, "image": "assets/catalog/product-cerave-01.jpg", "gallery": {"vi": [{"src": "assets/catalog/vi/cerave-01/thumbnail.webp", "label": "Thumbnail", "order": 0}, {"src": "assets/catalog/vi/cerave-01/anh-1.webp", "label": "Ảnh 1", "order": 1}, {"src": "assets/catalog/vi/cerave-01/anh-2.webp", "label": "Ảnh 2", "order": 2}, {"src": "assets/catalog/vi/cerave-01/anh-3.webp", "label": "Ảnh 3", "order": 3}, {"src": "assets/catalog/vi/cerave-01/anh-4.webp", "label": "Ảnh 4", "order": 4}, {"src": "assets/catalog/vi/cerave-01/anh-5.webp", "label": "Ảnh 5", "order": 5}, {"src": "assets/catalog/vi/cerave-01/anh-6.webp", "label": "Ảnh 6", "order": 6}, {"src": "assets/catalog/vi/cerave-01/anh-7.webp", "label": "Ảnh 7", "order": 7}]}}, {"id": "cerave-02", "brandId": "cerave", "brand": "CeraVe", "name": {"vi": "CERAVE FOAMING CLEANSER 236ML", "en": "CeraVe Foaming Cleanser 236ml"}, "category": "Skincare", "type": "Gel rửa mặt tạo bọt", "size": "236ml", "country": "Hoa Kỳ", "description": {"vi": "1. MÔ TẢ SẢN PHẨM\n\nTên sản phẩm: CeraVe Foaming Cleanser 236ml\nThương hiệu: CeraVe\nQuốc gia thương hiệu: Hoa Kỳ\nQuy cách đóng gói: 236ml\nPhân loại: Gel rửa mặt tạo bọt\n\nCeraVe Foaming Cleanser 236ml là gel rửa mặt tạo bọt dành cho da thường đến da dầu. Sản phẩm giúp loại bỏ bụi bẩn, dầu thừa và tạp chất tích tụ trong ngày, đồng thời hỗ trợ duy trì hàng rào bảo vệ da nhờ công thức chứa ceramide, Niacinamide và Hyaluronic Acid.\n\n2. CÔNG DỤNG\n\n• Làm sạch dầu thừa và bụi bẩn.\n• Giúp bề mặt da thông thoáng.\n• Hỗ trợ hạn chế cảm giác khô căng sau khi làm sạch.\n• Hỗ trợ duy trì hàng rào bảo vệ da.\n\n3. THÀNH PHẦN\n\nCác thành phần nổi bật:\n\n• Ba ceramide thiết yếu: Hỗ trợ hàng rào bảo vệ da.\n• Niacinamide: Hỗ trợ làm dịu và chăm sóc da.\n• Hyaluronic Acid: Hỗ trợ duy trì độ ẩm.\n• Các chất làm sạch tạo bọt: Giúp loại bỏ dầu thừa và tạp chất.\n\nLưu ý: Đây là thành phần nổi bật, không phải bảng INCI đầy đủ. Cần đối chiếu nhãn phiên bản thực tế.\n\n4. HƯỚNG DẪN SỬ DỤNG\n\nLàm ướt da, lấy một lượng gel vừa đủ, massage nhẹ để tạo bọt rồi rửa sạch bằng nước. Sử dụng sáng và tối tùy nhu cầu.\n\nLưu ý: Chỉ dùng ngoài da. Tránh tiếp xúc với mắt. Ngừng sử dụng nếu xuất hiện kích ứng kéo dài. Bảo quản theo hướng dẫn trên bao bì.\n\n5. ĐỐI TƯỢNG SỬ DỤNG\n\n• Da thường, da hỗn hợp và da dầu.\n• Người có da dễ bóng nhờn.\n• Người thích sản phẩm rửa mặt dạng gel tạo bọt.", "en": "1. PRODUCT DESCRIPTION\n\nCeraVe Foaming Cleanser is a refreshing gel-to-foam facial cleanser developed with dermatologists for normal to oily skin. It helps remove excess sebum, dirt and everyday impurities while maintaining the skin's natural protective barrier. The formula combines three essential ceramides, hyaluronic acid and niacinamide to support cleansing and skin comfort. Its lightweight foaming texture is particularly useful for people who experience excess shine but want to avoid an excessively tight or dry feeling after washing.\n\n2. BENEFITS\n\n• Removes excess oil, dirt and daily impurities.\n• Helps reduce the feeling of greasy skin.\n• Creates a refreshing foaming cleansing experience.\n• Supports the skin's protective moisture barrier.\n• Helps maintain hydration and skin comfort.\n• Suitable for consistent daily cleansing.\n\n3. INGREDIENTS\n\nKey ingredients and their functions:\n\n• Ceramide NP, Ceramide AP and Ceramide EOP: Help maintain the skin's protective barrier.\n• Niacinamide: A form of vitamin B3 used for skin-conditioning care.\n• Sodium Hyaluronate: Helps attract and retain moisture.\n• Glycerin: A moisturizing humectant.\n• Cocamidopropyl Hydroxysultaine: A mild cleansing and foam-supporting surfactant.\n• Sodium Lauroyl Sarcosinate: A cleansing ingredient that helps remove impurities.\n\nNote: These are selected key ingredients and product technologies, not a complete INCI declaration. Formulas may vary by market and manufacturing version. Verify the current product packaging before publication.\n\n4. DIRECTIONS FOR USE\n\n1. Wet the face with lukewarm water.\n2. Apply a small amount of cleanser to the palms.\n3. Massage gently over the face to create a light foam.\n4. Pay attention to areas with excess oil, such as the forehead, nose and chin.\n5. Rinse thoroughly and pat dry.\n6. Follow with a suitable moisturizer and daytime sunscreen.\n\nPrecautions: For external use only. Avoid direct contact with eyes. Discontinue use if irritation occurs. Keep out of reach of children.\n\n5. SUITABLE FOR\n\n• Normal to oily skin.\n• Combination skin with excess sebum.\n• People concerned about facial shine.\n• Individuals seeking a fragrance-free foaming cleanser."}, "image": "assets/catalog/product-cerave-02.jpg", "gallery": {"vi": [{"src": "assets/catalog/vi/cerave-02/thumbnail.webp", "label": "Thumbnail", "order": 0}, {"src": "assets/catalog/vi/cerave-02/anh-1.webp", "label": "Ảnh 1", "order": 1}, {"src": "assets/catalog/vi/cerave-02/anh-2.webp", "label": "Ảnh 2", "order": 2}, {"src": "assets/catalog/vi/cerave-02/anh-3.webp", "label": "Ảnh 3", "order": 3}, {"src": "assets/catalog/vi/cerave-02/anh-4.webp", "label": "Ảnh 4", "order": 4}, {"src": "assets/catalog/vi/cerave-02/anh-5.webp", "label": "Ảnh 5", "order": 5}, {"src": "assets/catalog/vi/cerave-02/anh-6.webp", "label": "Ảnh 6", "order": 6}, {"src": "assets/catalog/vi/cerave-02/anh-7.webp", "label": "Ảnh 7", "order": 7}]}}, {"id": "cerave-03", "brandId": "cerave", "brand": "CeraVe", "name": {"vi": "CERAVE HYDRATING CREAM-TO-FOAM CLEANSER 236ML", "en": "CeraVe Hydrating Cream-to-Foam Cleanser 236ml"}, "category": "Skincare", "type": "Sữa rửa mặt dạng kem tạo bọt", "size": "236ml", "country": "Hoa Kỳ", "description": {"vi": "1. MÔ TẢ SẢN PHẨM\n\nTên sản phẩm: CeraVe Hydrating Cream-to-Foam Cleanser 236ml\nThương hiệu: CeraVe\nQuốc gia thương hiệu: Hoa Kỳ\nQuy cách đóng gói: 236ml\nPhân loại: Sữa rửa mặt dạng kem tạo bọt\n\nCeraVe Hydrating Cream-to-Foam Cleanser 236ml là sản phẩm làm sạch có kết cấu dạng kem chuyển thành bọt nhẹ khi sử dụng với nước. Công thức kết hợp ceramide, Hyaluronic Acid và amino acid, hướng đến việc loại bỏ bụi bẩn, dầu thừa và lớp trang điểm nhẹ mà vẫn hỗ trợ duy trì độ ẩm cho da.\n\n2. CÔNG DỤNG\n\n• Làm sạch bụi bẩn và dầu thừa.\n• Hỗ trợ loại bỏ lớp trang điểm nhẹ.\n• Giúp da mềm mại sau khi rửa.\n• Hỗ trợ duy trì hàng rào bảo vệ da.\n\n3. THÀNH PHẦN\n\nCác thành phần nổi bật:\n\n• Ba ceramide thiết yếu: Hỗ trợ hàng rào bảo vệ da.\n• Hyaluronic Acid: Hỗ trợ giữ ẩm.\n• Amino Acids: Nhóm thành phần hỗ trợ chăm sóc da.\n• Hệ chất làm sạch: Tạo bọt nhẹ để làm sạch da.\n\nLưu ý: Đây là thành phần nổi bật, không phải bảng INCI đầy đủ. Cần đối chiếu nhãn phiên bản thực tế.\n\n4. HƯỚNG DẪN SỬ DỤNG\n\nLàm ướt mặt, lấy sản phẩm vừa đủ, massage để kết cấu kem tạo thành bọt rồi rửa sạch. Với lớp trang điểm đậm hoặc chống nước, nên dùng sản phẩm tẩy trang chuyên dụng trước.\n\nLưu ý: Chỉ dùng ngoài da. Tránh tiếp xúc với mắt. Ngừng sử dụng nếu xuất hiện kích ứng kéo dài. Bảo quản theo hướng dẫn trên bao bì.\n\n5. ĐỐI TƯỢNG SỬ DỤNG\n\n• Da thường đến da khô.\n• Người muốn làm sạch nhưng vẫn ưu tiên dưỡng ẩm.\n• Người thích kết cấu kem chuyển thành bọt.", "en": "1. PRODUCT DESCRIPTION\n\nCeraVe Hydrating Cream-to-Foam Cleanser is a facial cleanser that begins as a creamy texture and transforms into a soft foam when mixed with water. Developed with dermatologists, it is designed to remove dirt, excess oil and everyday makeup while helping maintain skin hydration. Its formula combines three essential ceramides, hyaluronic acid and amino-acid-based cleansing technology. The product offers a balance between effective foaming cleansing and moisturizing care, making it particularly appealing to people with normal to dry skin who prefer a foaming cleanser.\n\n2. BENEFITS\n\n• Removes everyday impurities and non-waterproof makeup.\n• Transforms from a cream into a gentle foam.\n• Helps maintain skin hydration during cleansing.\n• Supports the skin's protective moisture barrier.\n• Leaves skin feeling clean without excessive tightness.\n• Combines the comfort of a cream cleanser with the freshness of foam.\n\n3. INGREDIENTS\n\nKey ingredients and their functions:\n\n• Ceramide NP, Ceramide AP and Ceramide EOP: Support the skin's protective barrier.\n• Sodium Hyaluronate: Helps maintain hydration.\n• Glycerin: A humectant that attracts moisture.\n• Sodium Cocoyl Glycinate: An amino-acid-derived cleansing ingredient.\n• Sodium Methyl Cocoyl Taurate: A mild cleansing surfactant.\n• Amino Acids: Contribute to the formula's skin-conditioning approach.\n\nNote: These are selected key ingredients and product technologies, not a complete INCI declaration. Formulas may vary by market and manufacturing version. Verify the current product packaging before publication.\n\n4. DIRECTIONS FOR USE\n\n1. Wet the face with lukewarm water.\n2. Dispense an appropriate amount into the palms.\n3. Massage over damp skin until the creamy cleanser develops a soft foam.\n4. Gently cleanse the face without excessive rubbing.\n5. Rinse thoroughly with water.\n6. Follow with toner, serum and moisturizer as desired.\n\nPrecautions: For external use only. Avoid direct contact with eyes. Discontinue use if irritation occurs. Keep out of reach of children.\n\n5. SUITABLE FOR\n\n• Normal to dry skin.\n• People seeking hydration during facial cleansing.\n• Individuals who prefer a cream-to-foam texture.\n• Those who want a gentle cleanser for everyday makeup and impurities."}, "image": "assets/catalog/product-cerave-03.jpg", "gallery": {"vi": [{"src": "assets/catalog/vi/cerave-03/thumbnail.webp", "label": "Thumbnail", "order": 0}, {"src": "assets/catalog/vi/cerave-03/anh-1.webp", "label": "Ảnh 1", "order": 1}, {"src": "assets/catalog/vi/cerave-03/anh-2.webp", "label": "Ảnh 2", "order": 2}, {"src": "assets/catalog/vi/cerave-03/anh-3.webp", "label": "Ảnh 3", "order": 3}, {"src": "assets/catalog/vi/cerave-03/anh-4.webp", "label": "Ảnh 4", "order": 4}, {"src": "assets/catalog/vi/cerave-03/anh-5.webp", "label": "Ảnh 5", "order": 5}, {"src": "assets/catalog/vi/cerave-03/anh-6.webp", "label": "Ảnh 6", "order": 6}, {"src": "assets/catalog/vi/cerave-03/anh-7.webp", "label": "Ảnh 7", "order": 7}]}}, {"id": "cerave-04", "brandId": "cerave", "brand": "CeraVe", "name": {"vi": "CERAVE RENEWING SA CLEANSER 237ML", "en": "CeraVe Renewing SA Cleanser 237ml"}, "category": "Skincare", "type": "Sữa rửa mặt chứa Salicylic Acid", "size": "237ml", "country": "Hoa Kỳ", "description": {"vi": "1. MÔ TẢ SẢN PHẨM\n\nTên sản phẩm: CeraVe Renewing SA Cleanser 237ml\nThương hiệu: CeraVe\nQuốc gia thương hiệu: Hoa Kỳ\nQuy cách đóng gói: 237ml\nPhân loại: Sữa rửa mặt chứa Salicylic Acid\n\nCeraVe Renewing SA Cleanser 237ml là sữa rửa mặt chứa Salicylic Acid, hướng đến làn da có bề mặt thô ráp hoặc sần sùi. Sản phẩm kết hợp bước làm sạch với hỗ trợ loại bỏ tế bào chết trên bề mặt da, đồng thời bổ sung ceramide để chăm sóc hàng rào bảo vệ da. Tên gọi SA Cleanser có thể khác theo thị trường.\n\n2. CÔNG DỤNG\n\n• Làm sạch bụi bẩn và dầu thừa.\n• Hỗ trợ loại bỏ tế bào chết trên bề mặt.\n• Giúp bề mặt da trông mịn màng hơn.\n• Hỗ trợ duy trì độ ẩm của da.\n\n3. THÀNH PHẦN\n\nCác thành phần nổi bật:\n\n• Salicylic Acid: Thành phần BHA hỗ trợ loại bỏ tế bào chết.\n• Ceramides thiết yếu: Hỗ trợ hàng rào bảo vệ da.\n• Niacinamide: Hỗ trợ làm dịu.\n• Hyaluronic Acid: Hỗ trợ giữ ẩm.\n\nLưu ý: Đây là thành phần nổi bật, không phải bảng INCI đầy đủ. Cần đối chiếu nhãn phiên bản thực tế.\n\n4. HƯỚNG DẪN SỬ DỤNG\n\nLàm ướt da, massage nhẹ với lượng sản phẩm vừa đủ rồi rửa sạch. Tránh vùng mắt. Người mới dùng sản phẩm chứa acid nên bắt đầu với tần suất phù hợp khả năng dung nạp và sử dụng chống nắng ban ngày.\n\nLưu ý: Chỉ dùng ngoài da. Tránh tiếp xúc với mắt. Ngừng sử dụng nếu xuất hiện kích ứng kéo dài. Bảo quản theo hướng dẫn trên bao bì.\n\n5. ĐỐI TƯỢNG SỬ DỤNG\n\n• Người có da sần sùi, thô ráp.\n• Người cần sản phẩm làm sạch có thành phần hỗ trợ tẩy tế bào chết.\n• Người có da dễ bít tắc, nếu dung nạp tốt.\n\nLƯU Ý XÁC MINH\nTên Renewing SA Cleanser 237ml là phiên bản tham khảo; cần xác nhận có đúng hàng phân phối tại Việt Nam hay không.", "en": "1. PRODUCT DESCRIPTION\n\nCeraVe Renewing SA Cleanser is an exfoliating facial cleanser developed to help improve the appearance of rough, uneven skin texture. Its formula contains salicylic acid, a beta hydroxy acid that helps remove accumulated dead skin cells, alongside three essential ceramides and moisturizing ingredients. Unlike abrasive facial scrubs, the cleanser provides chemical exfoliation during washing. It can be incorporated into a skincare routine for rough or bumpy-looking skin, with frequency adjusted according to individual skin tolerance.\n\n2. BENEFITS\n\n• Helps remove accumulated dead skin cells.\n• Supports smoother-looking skin texture.\n• Helps improve the appearance of rough or bumpy skin.\n• Cleanses dirt, oil and everyday impurities.\n• Supports the skin's moisture barrier.\n• Provides exfoliating care without physical scrub particles.\n\n3. INGREDIENTS\n\nKey ingredients and their functions:\n\n• Salicylic Acid (BHA): Helps exfoliate dead skin cells and improve the appearance of rough texture.\n• Ceramide NP, Ceramide AP and Ceramide EOP: Help maintain the skin's protective barrier.\n• Niacinamide: Supports skin conditioning.\n• Sodium Hyaluronate: Helps retain moisture.\n• Glycerin: A moisturizing humectant.\n• Gluconolactone: A polyhydroxy acid associated with gentle exfoliating and skin-conditioning care.\n\nNote: These are selected key ingredients and product technologies, not a complete INCI declaration. Formulas may vary by market and manufacturing version. Verify the current product packaging before publication.\n\n4. DIRECTIONS FOR USE\n\n1. Wet the face with lukewarm water.\n2. Apply a small amount of cleanser to the palms.\n3. Massage gently over the skin, avoiding the eyes.\n4. Rinse thoroughly and pat dry.\n5. Introduce gradually if the skin is not accustomed to exfoliating acids.\n6. Follow with moisturizer and use broad-spectrum sunscreen during the day.\n\nPrecautions: For external use only. Avoid direct contact with eyes. Discontinue use if irritation occurs. Keep out of reach of children.\n\n5. SUITABLE FOR\n\n• Rough or uneven-looking skin.\n• People concerned about bumpy skin texture.\n• Individuals seeking a salicylic acid cleanser.\n• Skin that tolerates gentle exfoliating skincare."}, "image": "assets/catalog/product-cerave-04.jpg", "gallery": {"vi": [{"src": "assets/catalog/vi/cerave-04/thumbnail.webp", "label": "Thumbnail", "order": 0}, {"src": "assets/catalog/vi/cerave-04/anh-1.webp", "label": "Ảnh 1", "order": 1}, {"src": "assets/catalog/vi/cerave-04/anh-2.webp", "label": "Ảnh 2", "order": 2}, {"src": "assets/catalog/vi/cerave-04/anh-3.webp", "label": "Ảnh 3", "order": 3}, {"src": "assets/catalog/vi/cerave-04/anh-4.webp", "label": "Ảnh 4", "order": 4}, {"src": "assets/catalog/vi/cerave-04/anh-5.webp", "label": "Ảnh 5", "order": 5}, {"src": "assets/catalog/vi/cerave-04/anh-6.webp", "label": "Ảnh 6", "order": 6}, {"src": "assets/catalog/vi/cerave-04/anh-7.webp", "label": "Ảnh 7", "order": 7}]}}, {"id": "cerave-05", "brandId": "cerave", "brand": "CeraVe", "name": {"vi": "CERAVE BLEMISH CONTROL CLEANSER 236ML", "en": "CeraVe Blemish Control Cleanser 236ml"}, "category": "Skincare", "type": "Gel rửa mặt cho da dầu dễ nổi mụn", "size": "236ml", "country": "Hoa Kỳ", "description": {"vi": "1. MÔ TẢ SẢN PHẨM\n\nTên sản phẩm: CeraVe Blemish Control Cleanser 236ml\nThương hiệu: CeraVe\nQuốc gia thương hiệu: Hoa Kỳ\nQuy cách đóng gói: 236ml\nPhân loại: Gel rửa mặt cho da dầu dễ nổi mụn\n\nCeraVe Blemish Control Cleanser 236ml là gel rửa mặt dành cho da dầu và da dễ nổi mụn. Sản phẩm được thiết kế để làm sạch dầu thừa, hỗ trợ làm thông thoáng lỗ chân lông và cải thiện vẻ ngoài của bề mặt da có khuyết điểm. Công thức kết hợp Salicylic Acid, Niacinamide và ceramide.\n\n2. CÔNG DỤNG\n\n• Làm sạch bụi bẩn và dầu thừa.\n• Hỗ trợ làm thông thoáng lỗ chân lông.\n• Giúp cải thiện vẻ ngoài của mụn đầu đen và khuyết điểm trên da.\n• Hỗ trợ duy trì hàng rào bảo vệ da.\n\n3. THÀNH PHẦN\n\nCác thành phần nổi bật:\n\n• Salicylic Acid: Hỗ trợ làm sạch tế bào chết và lỗ chân lông.\n• Niacinamide: Hỗ trợ làm dịu da.\n• Ceramides thiết yếu: Hỗ trợ hàng rào bảo vệ da.\n• Các thành phần làm sạch: Giúp loại bỏ dầu thừa.\n\nLưu ý: Đây là thành phần nổi bật, không phải bảng INCI đầy đủ. Cần đối chiếu nhãn phiên bản thực tế.\n\n4. HƯỚNG DẪN SỬ DỤNG\n\nLàm ướt mặt, massage một lượng nhỏ sản phẩm lên da rồi rửa sạch. Tránh vùng mắt. Điều chỉnh tần suất nếu da khô hoặc kích ứng. Sử dụng kem chống nắng ban ngày.\n\nLưu ý: Chỉ dùng ngoài da. Tránh tiếp xúc với mắt. Ngừng sử dụng nếu xuất hiện kích ứng kéo dài. Bảo quản theo hướng dẫn trên bao bì.\n\n5. ĐỐI TƯỢNG SỬ DỤNG\n\n• Da dầu và hỗn hợp thiên dầu.\n• Da dễ nổi mụn, có mụn đầu đen.\n• Người có lỗ chân lông dễ bít tắc.\n\nLƯU Ý XÁC MINH\nCần đối chiếu nồng độ Salicylic Acid và phiên bản 236ml trên bao bì Việt Nam trước khi xuất bản.", "en": "1. PRODUCT DESCRIPTION\n\nCeraVe Blemish Control Cleanser is a foaming facial cleanser designed for oily and blemish-prone skin. The formula features 2% salicylic acid to help exfoliate the skin and clear accumulated impurities from pores, together with three essential ceramides, niacinamide and oil-absorbing clay. It is intended to improve the appearance of blemishes, blackheads and excess shine while supporting the skin's moisture barrier. The cleanser can be used as part of a targeted skincare routine for congested-looking skin.\n\n2. BENEFITS\n\n• Helps reduce the appearance of blemishes and blackheads.\n• Supports clearer-looking pores.\n• Helps remove excess oil and daily impurities.\n• Provides salicylic acid exfoliating care.\n• Helps control the appearance of shine.\n• Supports the skin's moisture barrier.\n\n3. INGREDIENTS\n\nKey ingredients and their functions:\n\n• 2% Salicylic Acid (BHA): Helps exfoliate and clear pore buildup.\n• Ceramide NP, Ceramide AP and Ceramide EOP: Support barrier care.\n• Niacinamide: Helps maintain skin comfort and conditioning.\n• Hectorite Clay: Helps absorb excess surface oil.\n• Glycerin: Supports moisture retention.\n• Sodium Hyaluronate: Helps maintain hydration.\n\nNote: These are selected key ingredients and product technologies, not a complete INCI declaration. Formulas may vary by market and manufacturing version. Verify the current product packaging before publication.\n\n4. DIRECTIONS FOR USE\n\n1. Wet the face with lukewarm water.\n2. Dispense a small amount into the hands.\n3. Massage gently onto the skin, avoiding the eyes and lips.\n4. Rinse thoroughly with water.\n5. Begin with a frequency suitable for skin tolerance.\n6. Apply moisturizer afterward and use sunscreen every morning.\n\nPrecautions: For external use only. Avoid direct contact with eyes. Discontinue use if irritation occurs. Keep out of reach of children.\n\n5. SUITABLE FOR\n\n• Oily and blemish-prone skin.\n• People concerned about blackheads and clogged pores.\n• Individuals experiencing excess facial shine.\n• Those seeking a targeted salicylic acid cleansing routine."}, "image": "assets/catalog/product-cerave-05.jpg", "gallery": {"vi": [{"src": "assets/catalog/vi/cerave-05/thumbnail.webp", "label": "Thumbnail", "order": 0}, {"src": "assets/catalog/vi/cerave-05/anh-1.webp", "label": "Ảnh 1", "order": 1}, {"src": "assets/catalog/vi/cerave-05/anh-2.webp", "label": "Ảnh 2", "order": 2}, {"src": "assets/catalog/vi/cerave-05/anh-3.webp", "label": "Ảnh 3", "order": 3}, {"src": "assets/catalog/vi/cerave-05/anh-4.webp", "label": "Ảnh 4", "order": 4}, {"src": "assets/catalog/vi/cerave-05/anh-5.webp", "label": "Ảnh 5", "order": 5}, {"src": "assets/catalog/vi/cerave-05/anh-6.webp", "label": "Ảnh 6", "order": 6}, {"src": "assets/catalog/vi/cerave-05/anh-7.webp", "label": "Ảnh 7", "order": 7}]}}, {"id": "cerave-06", "brandId": "cerave", "brand": "CeraVe", "name": {"vi": "CERAVE MOISTURIZING CREAM 340G", "en": "CeraVe Moisturizing Cream 340g"}, "category": "Skincare", "type": "Kem dưỡng ẩm cho mặt và cơ thể", "size": "340g", "country": "Hoa Kỳ", "description": {"vi": "1. MÔ TẢ SẢN PHẨM\n\nTên sản phẩm: CeraVe Moisturizing Cream 340g\nThương hiệu: CeraVe\nQuốc gia thương hiệu: Hoa Kỳ\nQuy cách đóng gói: 340g\nPhân loại: Kem dưỡng ẩm cho mặt và cơ thể\n\nCeraVe Moisturizing Cream 340g là kem dưỡng ẩm dành cho da khô đến rất khô, có thể sử dụng cho mặt và cơ thể. Kết cấu kem giàu chất dưỡng ẩm, kết hợp ba ceramide thiết yếu và Hyaluronic Acid, giúp làm mềm da và hỗ trợ duy trì hàng rào giữ ẩm.\n\n2. CÔNG DỤNG\n\n• Dưỡng ẩm cho da mặt và cơ thể.\n• Giúp giảm cảm giác khô căng, bong tróc.\n• Hỗ trợ duy trì hàng rào bảo vệ da.\n• Giúp bề mặt da mềm mại và mịn màng hơn.\n\n3. THÀNH PHẦN\n\nCác thành phần nổi bật:\n\n• Ceramide NP, AP, EOP: Hỗ trợ hàng rào bảo vệ da.\n• Hyaluronic Acid: Hỗ trợ giữ ẩm.\n• Glycerin: Hút ẩm và làm mềm da.\n• Các chất làm mềm da: Giúp hạn chế mất nước.\n\nLưu ý: Đây là thành phần nổi bật, không phải bảng INCI đầy đủ. Cần đối chiếu nhãn phiên bản thực tế.\n\n4. HƯỚNG DẪN SỬ DỤNG\n\nThoa kem lên vùng da sạch sau khi tắm, rửa mặt hoặc bất cứ khi nào da cảm thấy khô. Có thể dùng nhiều lần trong ngày tùy nhu cầu.\n\nLưu ý: Chỉ dùng ngoài da. Tránh tiếp xúc với mắt. Ngừng sử dụng nếu xuất hiện kích ứng kéo dài. Bảo quản theo hướng dẫn trên bao bì.\n\n5. ĐỐI TƯỢNG SỬ DỤNG\n\n• Da khô đến rất khô.\n• Người có da cơ thể khô ráp.\n• Người cần kem dưỡng ẩm hằng ngày.", "en": "1. PRODUCT DESCRIPTION\n\nCeraVe Moisturizing Cream is a rich, fragrance-free moisturizer developed with dermatologists for dry to very dry skin. Suitable for both the face and body, it combines three essential ceramides with hyaluronic acid and the brand's MVE Delivery Technology to help provide long-lasting hydration. Its nourishing cream texture helps soften rough, dry areas while supporting the skin's protective barrier. The generous 340g jar is convenient for regular moisturizing care, especially for skin exposed to dry weather, frequent washing or air-conditioned environments.\n\n2. BENEFITS\n\n• Provides rich moisturizing care for dry skin.\n• Helps maintain the skin's natural protective barrier.\n• Supports long-lasting hydration.\n• Softens rough and flaky-feeling areas.\n• Helps reduce dryness-related tightness.\n• Suitable for daily face and body moisturizing.\n\n3. INGREDIENTS\n\nKey ingredients and their functions:\n\n• Ceramide NP, Ceramide AP and Ceramide EOP: Three essential ceramides that support the moisture barrier.\n• Sodium Hyaluronate: Helps retain moisture.\n• Glycerin: A humectant that attracts water.\n• Petrolatum: An occlusive ingredient that helps reduce moisture loss.\n• Cholesterol: A skin-identical lipid.\n• Dimethicone: A skin protectant and conditioning ingredient.\n• MVE Delivery Technology: A controlled-release system designed to support sustained moisturization.\n\nNote: These are selected key ingredients and product technologies, not a complete INCI declaration. Formulas may vary by market and manufacturing version. Verify the current product packaging before publication.\n\n4. DIRECTIONS FOR USE\n\n1. Cleanse the skin and gently pat dry.\n2. Take a suitable amount of cream with clean hands.\n3. Apply evenly to the face, body or particularly dry areas.\n4. Massage gently until absorbed.\n5. Reapply whenever the skin feels dry, especially after bathing.\n6. Use morning and evening or as needed.\n\nPrecautions: For external use only. Avoid direct contact with eyes. Discontinue use if irritation occurs. Keep out of reach of children.\n\n5. SUITABLE FOR\n\n• Dry to very dry skin.\n• People experiencing roughness or tightness from dryness.\n• Individuals seeking a rich face and body moisturizer.\n• Skin requiring intensive moisture-barrier support."}, "image": "assets/catalog/product-cerave-06.jpg", "gallery": {"vi": [{"src": "assets/catalog/vi/cerave-06/thumbnail.webp", "label": "Thumbnail", "order": 0}, {"src": "assets/catalog/vi/cerave-06/anh-1.webp", "label": "Ảnh 1", "order": 1}, {"src": "assets/catalog/vi/cerave-06/anh-2.webp", "label": "Ảnh 2", "order": 2}, {"src": "assets/catalog/vi/cerave-06/anh-3.webp", "label": "Ảnh 3", "order": 3}, {"src": "assets/catalog/vi/cerave-06/anh-4.webp", "label": "Ảnh 4", "order": 4}, {"src": "assets/catalog/vi/cerave-06/anh-5.webp", "label": "Ảnh 5", "order": 5}, {"src": "assets/catalog/vi/cerave-06/anh-6.webp", "label": "Ảnh 6", "order": 6}, {"src": "assets/catalog/vi/cerave-06/anh-7.webp", "label": "Ảnh 7", "order": 7}]}}, {"id": "cerave-07", "brandId": "cerave", "brand": "CeraVe", "name": {"vi": "CERAVE MOISTURIZING LOTION 236ML", "en": "CeraVe Moisturizing Lotion 236ml"}, "category": "Skincare", "type": "Sữa dưỡng ẩm cho mặt và cơ thể", "size": "236ml", "country": "Hoa Kỳ", "description": {"vi": "1. MÔ TẢ SẢN PHẨM\n\nTên sản phẩm: CeraVe Moisturizing Lotion 236ml\nThương hiệu: CeraVe\nQuốc gia thương hiệu: Hoa Kỳ\nQuy cách đóng gói: 236ml\nPhân loại: Sữa dưỡng ẩm cho mặt và cơ thể\n\nCeraVe Moisturizing Lotion 236ml là sữa dưỡng ẩm có kết cấu lotion dễ tán, phù hợp cho mặt và cơ thể. Công thức tập trung bổ sung độ ẩm và hỗ trợ hàng rào bảo vệ da, phù hợp với nhu cầu dưỡng ẩm thường xuyên.\n\n2. CÔNG DỤNG\n\n• Cung cấp độ ẩm hằng ngày.\n• Hỗ trợ giảm cảm giác khô căng.\n• Giúp da mềm mại và mịn màng.\n• Hỗ trợ duy trì hàng rào giữ ẩm.\n\n3. THÀNH PHẦN\n\nCác thành phần nổi bật:\n\n• Ba ceramide thiết yếu: Hỗ trợ hàng rào bảo vệ da.\n• Hyaluronic Acid: Hỗ trợ giữ ẩm.\n• Glycerin: Giúp da duy trì độ ẩm.\n• Các thành phần làm mềm da: Hỗ trợ giảm khô ráp.\n\nLưu ý: Đây là thành phần nổi bật, không phải bảng INCI đầy đủ. Cần đối chiếu nhãn phiên bản thực tế.\n\n4. HƯỚNG DẪN SỬ DỤNG\n\nThoa đều lên vùng da sạch, đặc biệt sau khi tắm. Sử dụng buổi sáng, buổi tối hoặc khi cần bổ sung độ ẩm.\n\nLưu ý: Chỉ dùng ngoài da. Tránh tiếp xúc với mắt. Ngừng sử dụng nếu xuất hiện kích ứng kéo dài. Bảo quản theo hướng dẫn trên bao bì.\n\n5. ĐỐI TƯỢNG SỬ DỤNG\n\n• Da thường đến da khô.\n• Người muốn dưỡng ẩm toàn thân bằng lotion.\n• Người không thích kết cấu kem quá đặc.", "en": "1. PRODUCT DESCRIPTION\n\nCeraVe Moisturizing Lotion is a lightweight, fragrance-free moisturizer developed with dermatologists for normal to dry skin. Designed for use on the face and body, the lotion combines three essential ceramides, hyaluronic acid and MVE Delivery Technology to support long-lasting hydration. Its fluid, non-greasy texture spreads easily and absorbs comfortably, making it suitable for people who prefer a lighter moisturizer than a traditional rich cream. Regular use helps maintain softness and support the skin's protective moisture barrier.\n\n2. BENEFITS\n\n• Provides everyday hydration for normal to dry skin.\n• Helps maintain the skin's moisture barrier.\n• Leaves skin feeling soft and comfortable.\n• Offers a lightweight, non-greasy texture.\n• Suitable for both facial and body use.\n• Supports sustained moisturizing care.\n\n3. INGREDIENTS\n\nKey ingredients and their functions:\n\n• Ceramide NP, Ceramide AP and Ceramide EOP: Help maintain the protective skin barrier.\n• Sodium Hyaluronate: Supports moisture retention.\n• Glycerin: A humectant that attracts water.\n• Caprylic/Capric Triglyceride: An emollient that helps soften skin.\n• Cholesterol: A skin-conditioning lipid.\n• Dimethicone: Supports a smooth, comfortable skin feel.\n• MVE Delivery Technology: Helps deliver moisturizing ingredients over time.\n\nNote: These are selected key ingredients and product technologies, not a complete INCI declaration. Formulas may vary by market and manufacturing version. Verify the current product packaging before publication.\n\n4. DIRECTIONS FOR USE\n\n1. Apply to clean, slightly damp or dry skin.\n2. Dispense a suitable amount into the palms.\n3. Spread evenly across the face and body.\n4. Massage gently until absorbed.\n5. Reapply after showering or whenever additional moisture is needed.\n6. Use daily, morning and evening.\n\nPrecautions: For external use only. Avoid direct contact with eyes. Discontinue use if irritation occurs. Keep out of reach of children.\n\n5. SUITABLE FOR\n\n• Normal to dry skin.\n• People who prefer lightweight body lotion.\n• Individuals seeking daily face and body hydration.\n• Those wanting a fragrance-free moisturizing product."}, "image": "assets/catalog/product-cerave-07.jpg", "gallery": {"vi": [{"src": "assets/catalog/vi/cerave-07/thumbnail.webp", "label": "Thumbnail", "order": 0}, {"src": "assets/catalog/vi/cerave-07/anh-1.webp", "label": "Ảnh 1", "order": 1}, {"src": "assets/catalog/vi/cerave-07/anh-2.webp", "label": "Ảnh 2", "order": 2}, {"src": "assets/catalog/vi/cerave-07/anh-3.webp", "label": "Ảnh 3", "order": 3}, {"src": "assets/catalog/vi/cerave-07/anh-4.webp", "label": "Ảnh 4", "order": 4}, {"src": "assets/catalog/vi/cerave-07/anh-5.webp", "label": "Ảnh 5", "order": 5}, {"src": "assets/catalog/vi/cerave-07/anh-6.webp", "label": "Ảnh 6", "order": 6}, {"src": "assets/catalog/vi/cerave-07/anh-7.webp", "label": "Ảnh 7", "order": 7}]}}, {"id": "cerave-08", "brandId": "cerave", "brand": "CeraVe", "name": {"vi": "CERAVE PM FACIAL MOISTURIZING LOTION 52ML", "en": "CeraVe PM Facial Moisturizing Lotion 52ml"}, "category": "Skincare", "type": "Sữa dưỡng ẩm da mặt ban đêm", "size": "52ml", "country": "Hoa Kỳ", "description": {"vi": "1. MÔ TẢ SẢN PHẨM\n\nTên sản phẩm: CeraVe PM Facial Moisturizing Lotion 52ml\nThương hiệu: CeraVe\nQuốc gia thương hiệu: Hoa Kỳ\nQuy cách đóng gói: 52ml\nPhân loại: Sữa dưỡng ẩm da mặt ban đêm\n\nCeraVe PM Facial Moisturizing Lotion 52ml là sữa dưỡng ẩm da mặt có kết cấu nhẹ, phù hợp bổ sung vào quy trình chăm sóc da buổi tối. Công thức kết hợp ceramide, Niacinamide và Hyaluronic Acid, giúp duy trì độ ẩm và chăm sóc hàng rào bảo vệ da.\n\n2. CÔNG DỤNG\n\n• Bổ sung độ ẩm cho da mặt.\n• Hỗ trợ chăm sóc hàng rào bảo vệ da.\n• Giúp giảm cảm giác khô căng.\n• Giúp da mềm mại, mịn màng.\n• Phù hợp bước dưỡng cuối trong quy trình buổi tối.\n\n3. THÀNH PHẦN\n\nCác thành phần nổi bật:\n\n• Ba ceramide thiết yếu: Hỗ trợ hàng rào bảo vệ da.\n• Niacinamide: Hỗ trợ làm dịu.\n• Hyaluronic Acid: Hỗ trợ giữ ẩm.\n• Glycerin: Thành phần hút ẩm.\n\nLưu ý: Đây là thành phần nổi bật, không phải bảng INCI đầy đủ. Cần đối chiếu nhãn phiên bản thực tế.\n\n4. HƯỚNG DẪN SỬ DỤNG\n\nSau khi làm sạch da và sử dụng tinh chất nếu có, thoa lượng lotion vừa đủ lên mặt và cổ. Ưu tiên sử dụng buổi tối.\n\nLưu ý: Chỉ dùng ngoài da. Tránh tiếp xúc với mắt. Ngừng sử dụng nếu xuất hiện kích ứng kéo dài. Bảo quản theo hướng dẫn trên bao bì.\n\n5. ĐỐI TƯỢNG SỬ DỤNG\n\n• Da thường, da hỗn hợp.\n• Da dầu thiếu nước.\n• Người cần dưỡng ẩm ban đêm với kết cấu nhẹ.", "en": "1. PRODUCT DESCRIPTION\n\nCeraVe PM Facial Moisturizing Lotion is a lightweight nighttime facial moisturizer developed with dermatologists to help replenish moisture while the skin rests. Its formula features three essential ceramides, niacinamide and hyaluronic acid to support the protective skin barrier and maintain a comfortable, hydrated complexion. MVE Delivery Technology helps provide sustained moisturizing care. The lotion has a light texture suitable for layering after facial serums and can also be used during the day when followed by sunscreen.\n\n2. BENEFITS\n\n• Provides lightweight nighttime hydration.\n• Supports the skin's natural moisture barrier.\n• Helps maintain a soft and comfortable complexion.\n• Contains niacinamide for skin-conditioning care.\n• Helps reduce dryness-related tightness.\n• Offers a non-greasy moisturizing finish.\n\n3. INGREDIENTS\n\nKey ingredients and their functions:\n\n• Ceramide NP, Ceramide AP and Ceramide EOP: Support the skin's protective barrier.\n• Niacinamide: A form of vitamin B3 that helps condition skin.\n• Sodium Hyaluronate: Helps retain moisture.\n• Glycerin: A moisturizing humectant.\n• Cholesterol: A barrier-supporting lipid.\n• Phytosphingosine: A skin-conditioning lipid-related ingredient.\n• MVE Delivery Technology: Supports sustained hydration.\n\nNote: These are selected key ingredients and product technologies, not a complete INCI declaration. Formulas may vary by market and manufacturing version. Verify the current product packaging before publication.\n\n4. DIRECTIONS FOR USE\n\n1. Cleanse the face in the evening.\n2. Apply toner or serum if included in the routine.\n3. Dispense a suitable amount of lotion.\n4. Spread evenly over the face and neck.\n5. Gently massage until absorbed.\n6. Use nightly; if applied in the morning, follow with sunscreen.\n\nPrecautions: For external use only. Avoid direct contact with eyes. Discontinue use if irritation occurs. Keep out of reach of children.\n\n5. SUITABLE FOR\n\n• Normal to dry skin.\n• Combination skin seeking lightweight nighttime moisture.\n• People concerned about dehydration.\n• Individuals wanting fragrance-free facial barrier care."}, "image": "assets/catalog/product-cerave-08.jpg", "gallery": {"vi": [{"src": "assets/catalog/vi/cerave-08/thumbnail.webp", "label": "Thumbnail", "order": 0}, {"src": "assets/catalog/vi/cerave-08/anh-1.webp", "label": "Ảnh 1", "order": 1}, {"src": "assets/catalog/vi/cerave-08/anh-2.webp", "label": "Ảnh 2", "order": 2}, {"src": "assets/catalog/vi/cerave-08/anh-3.webp", "label": "Ảnh 3", "order": 3}, {"src": "assets/catalog/vi/cerave-08/anh-4.webp", "label": "Ảnh 4", "order": 4}, {"src": "assets/catalog/vi/cerave-08/anh-5.webp", "label": "Ảnh 5", "order": 5}, {"src": "assets/catalog/vi/cerave-08/anh-6.webp", "label": "Ảnh 6", "order": 6}, {"src": "assets/catalog/vi/cerave-08/anh-7.webp", "label": "Ảnh 7", "order": 7}]}}, {"id": "cerave-09", "brandId": "cerave", "brand": "CeraVe", "name": {"vi": "CERAVE OIL CONTROL MOISTURIZING GEL-CREAM 52ML", "en": "CeraVe Oil Control Moisturizing Gel-Cream 52ml"}, "category": "Skincare", "type": "Gel kem dưỡng ẩm kiểm soát dầu", "size": "52ml", "country": "Hoa Kỳ", "description": {"vi": "1. MÔ TẢ SẢN PHẨM\n\nTên sản phẩm: CeraVe Oil Control Moisturizing Gel-Cream 52ml\nThương hiệu: CeraVe\nQuốc gia thương hiệu: Hoa Kỳ\nQuy cách đóng gói: 52ml\nPhân loại: Gel kem dưỡng ẩm kiểm soát dầu\n\nCeraVe Oil Control Moisturizing Gel-Cream 52ml là gel kem dưỡng ẩm hướng đến da dầu và da hỗn hợp. Sản phẩm kết hợp thành phần dưỡng ẩm với công nghệ hỗ trợ hấp thụ dầu được hãng giới thiệu tại một số thị trường, nhằm mang lại cảm giác khô thoáng trên bề mặt da.\n\n2. CÔNG DỤNG\n\n• Bổ sung độ ẩm cho da.\n• Hỗ trợ giảm bóng dầu.\n• Giúp bề mặt da thông thoáng.\n• Hỗ trợ duy trì hàng rào bảo vệ da.\n• Tạo cảm giác nhẹ hơn so với kem dưỡng đặc.\n\n3. THÀNH PHẦN\n\nCác thành phần nổi bật:\n\n• Ceramides thiết yếu: Hỗ trợ hàng rào bảo vệ da.\n• Niacinamide: Hỗ trợ làm dịu.\n• Hyaluronic Acid: Hỗ trợ giữ ẩm.\n• Thành phần hỗ trợ hấp thụ dầu: Giúp giảm cảm giác bóng nhờn.\n\nLưu ý: Đây là thành phần nổi bật, không phải bảng INCI đầy đủ. Cần đối chiếu nhãn phiên bản thực tế.\n\n4. HƯỚNG DẪN SỬ DỤNG\n\nThoa lượng gel kem vừa đủ lên mặt sau khi làm sạch và sử dụng tinh chất. Có thể dùng sáng và tối. Buổi sáng kết hợp kem chống nắng.\n\nLưu ý: Chỉ dùng ngoài da. Tránh tiếp xúc với mắt. Ngừng sử dụng nếu xuất hiện kích ứng kéo dài. Bảo quản theo hướng dẫn trên bao bì.\n\n5. ĐỐI TƯỢNG SỬ DỤNG\n\n• Da dầu, da hỗn hợp thiên dầu.\n• Người cần dưỡng ẩm nhưng không thích bóng nhờn.\n• Người thích kết cấu gel kem.\n\nLƯU Ý XÁC MINH\nCần xác nhận phiên bản Oil Control Gel-Cream 52ml đang được phân phối tại Việt Nam.", "en": "1. PRODUCT DESCRIPTION\n\nCeraVe Oil Control Moisturizing Gel-Cream is a lightweight facial moisturizer developed with dermatologists for combination to oily skin. Its gel-cream texture provides hydration while helping absorb excess surface oil and reduce the appearance of shine. The formula combines three essential ceramides, niacinamide and hyaluronic acid with oil-absorbing technology to support a balanced, comfortable complexion. It is particularly suitable for people who experience both oily areas and dehydration and prefer a moisturizer that does not feel heavy on the skin.\n\n2. BENEFITS\n\n• Provides lightweight hydration for oily skin.\n• Helps absorb excess surface oil.\n• Reduces the appearance of unwanted shine.\n• Supports the skin's protective moisture barrier.\n• Leaves a comfortable, non-greasy finish.\n• Helps maintain a balanced-looking complexion.\n\n3. INGREDIENTS\n\nKey ingredients and their functions:\n\n• Ceramide NP, Ceramide AP and Ceramide EOP: Support moisture-barrier care.\n• Niacinamide: Helps condition the skin.\n• Sodium Hyaluronate: A hyaluronic acid derivative that helps retain moisture.\n• Silica: Helps absorb excess oil and create a matte appearance.\n• Glycerin: A moisturizing humectant.\n• Oil-Absorbing Technology: The brand's formulation approach to managing surface shine.\n\nNote: These are selected key ingredients and product technologies, not a complete INCI declaration. Formulas may vary by market and manufacturing version. Verify the current product packaging before publication.\n\n4. DIRECTIONS FOR USE\n\n1. Cleanse the face and pat dry.\n2. Apply any suitable toner or serum.\n3. Dispense a small amount of gel-cream.\n4. Spread evenly over the face and neck.\n5. Allow the product to absorb before applying makeup.\n6. Use morning and evening; apply sunscreen during the day.\n\nPrecautions: For external use only. Avoid direct contact with eyes. Discontinue use if irritation occurs. Keep out of reach of children.\n\n5. SUITABLE FOR\n\n• Combination to oily skin.\n• People concerned about excess shine.\n• Individuals who prefer lightweight gel moisturizers.\n• Dehydrated skin with excess sebum production."}, "image": "assets/catalog/product-cerave-09.jpg", "gallery": {"vi": [{"src": "assets/catalog/vi/cerave-09/thumbnail.webp", "label": "Thumbnail", "order": 0}, {"src": "assets/catalog/vi/cerave-09/anh-1.webp", "label": "Ảnh 1", "order": 1}, {"src": "assets/catalog/vi/cerave-09/anh-2.webp", "label": "Ảnh 2", "order": 2}, {"src": "assets/catalog/vi/cerave-09/anh-3.webp", "label": "Ảnh 3", "order": 3}, {"src": "assets/catalog/vi/cerave-09/anh-4.webp", "label": "Ảnh 4", "order": 4}, {"src": "assets/catalog/vi/cerave-09/anh-5.webp", "label": "Ảnh 5", "order": 5}, {"src": "assets/catalog/vi/cerave-09/anh-6.webp", "label": "Ảnh 6", "order": 6}, {"src": "assets/catalog/vi/cerave-09/anh-7.webp", "label": "Ảnh 7", "order": 7}]}}, {"id": "cerave-10", "brandId": "cerave", "brand": "CeraVe", "name": {"vi": "CERAVE AM FACIAL MOISTURIZING LOTION SPF50 52ML", "en": "CeraVe AM Facial Moisturizing Lotion SPF50 52ml"}, "category": "Skincare", "type": "Sữa dưỡng ẩm ban ngày kết hợp chống nắng", "size": "52ml", "country": "Hoa Kỳ", "description": {"vi": "1. MÔ TẢ SẢN PHẨM\n\nTên sản phẩm: CeraVe AM Facial Moisturizing Lotion SPF50 52ml\nThương hiệu: CeraVe\nQuốc gia thương hiệu: Hoa Kỳ\nQuy cách đóng gói: 52ml\nPhân loại: Sữa dưỡng ẩm ban ngày kết hợp chống nắng\n\nCeraVe AM Facial Moisturizing Lotion SPF50 52ml là sản phẩm dưỡng ẩm ban ngày kết hợp chống nắng, hướng đến nhu cầu bảo vệ da trước tia UV và bổ sung độ ẩm. Công thức kết hợp các bộ lọc chống nắng với ceramide và những thành phần chăm sóc da.\n\n2. CÔNG DỤNG\n\n• Hỗ trợ bảo vệ da trước tia UVA và UVB theo chỉ số trên bao bì.\n• Cung cấp độ ẩm ban ngày.\n• Hỗ trợ duy trì hàng rào bảo vệ da.\n• Giúp da mềm mại và hạn chế khô căng.\n\n3. THÀNH PHẦN\n\nCác thành phần nổi bật:\n\n• Ceramides thiết yếu: Hỗ trợ hàng rào bảo vệ da.\n• Niacinamide: Hỗ trợ làm dịu da.\n• Hyaluronic Acid: Hỗ trợ giữ ẩm.\n• Hệ màng lọc chống nắng: Bảo vệ da trước tia UV; thành phần cụ thể tùy phiên bản.\n\nLưu ý: Đây là thành phần nổi bật, không phải bảng INCI đầy đủ. Cần đối chiếu nhãn phiên bản thực tế.\n\n4. HƯỚNG DẪN SỬ DỤNG\n\nThoa đều lên mặt và cổ ở bước cuối quy trình chăm sóc da buổi sáng. Dùng đủ lượng theo hướng dẫn nhãn để đạt mức bảo vệ công bố. Thoa lại khoảng mỗi 2 giờ khi tiếp xúc nắng liên tục và sau bơi, đổ mồ hôi hoặc lau mặt.\n\nLưu ý: Chỉ dùng ngoài da. Tránh tiếp xúc với mắt. Ngừng sử dụng nếu xuất hiện kích ứng kéo dài. Bảo quản theo hướng dẫn trên bao bì.\n\n5. ĐỐI TƯỢNG SỬ DỤNG\n\n• Người cần dưỡng ẩm và chống nắng ban ngày.\n• Người muốn kết hợp hai bước chăm sóc da trong một sản phẩm.\n• Người có loại da phù hợp với kết cấu của phiên bản thực tế.\n\nLƯU Ý XÁC MINH\nChỉ công bố SPF50 và dung tích 52ml khi bao bì thực tế xác nhận đúng phiên bản.", "en": "1. PRODUCT DESCRIPTION\n\nCeraVe AM Facial Moisturizing Lotion SPF50 is a daytime facial moisturizer developed with dermatologists to combine daily hydration with high sun protection. Its formula contains broad-spectrum UV filters alongside three essential ceramides, niacinamide and hyaluronic acid to help protect against ultraviolet exposure while supporting the skin's moisture barrier. Designed as a convenient final step in the morning skincare routine, the lotion helps maintain skin comfort and moisture while providing SPF50 protection when applied correctly and in sufficient quantity.\n\n2. BENEFITS\n\n• Provides high SPF50 sun protection.\n• Helps protect the skin against UVA and UVB radiation when used as directed.\n• Moisturizes the skin during daytime wear.\n• Supports the skin's natural protective barrier.\n• Helps maintain a comfortable, hydrated complexion.\n• Combines moisturizer and sunscreen in one product.\n\n3. INGREDIENTS\n\nKey ingredients and their functions:\n\n• Broad-Spectrum UV Filters: Provide UVA and UVB protection; the exact filter combination must be checked against the 52ml regional formulation.\n• Ceramide NP, Ceramide AP and Ceramide EOP: Help maintain the skin's protective barrier.\n• Niacinamide: Supports skin-conditioning care.\n• Sodium Hyaluronate: Helps retain moisture.\n• Glycerin: A moisturizing humectant.\n• MVE Delivery Technology: Used in the CeraVe moisturizing product range to support sustained hydration.\n\nNote: These are selected key ingredients and product technologies, not a complete INCI declaration. Formulas may vary by market and manufacturing version. Verify the current product packaging before publication.\n\n4. DIRECTIONS FOR USE\n\n1. Cleanse the face and apply any desired facial serum.\n2. Apply generously and evenly over the face and neck before sun exposure.\n3. Use as the final step of the morning skincare routine.\n4. Reapply at least every two hours while exposed to the sun, and after swimming, sweating or towel-drying.\n5. Avoid prolonged sun exposure and use additional sun-protection measures.\n6. Follow the specific label instructions for the product sold in your market.\n\nPrecautions: For external use only. Avoid direct contact with eyes. Discontinue use if irritation occurs. Keep out of reach of children.\n\n5. SUITABLE FOR\n\n• People seeking daily facial SPF50 protection.\n• Normal to dry skin requiring daytime moisture.\n• Individuals concerned about sun-related skin aging.\n• Those wanting a combined moisturizer and sunscreen."}, "image": "assets/catalog/product-cerave-10.jpg", "gallery": {"vi": [{"src": "assets/catalog/vi/cerave-10/thumbnail.webp", "label": "Thumbnail", "order": 0}, {"src": "assets/catalog/vi/cerave-10/anh-1.webp", "label": "Ảnh 1", "order": 1}, {"src": "assets/catalog/vi/cerave-10/anh-2.webp", "label": "Ảnh 2", "order": 2}, {"src": "assets/catalog/vi/cerave-10/anh-3.webp", "label": "Ảnh 3", "order": 3}, {"src": "assets/catalog/vi/cerave-10/anh-4.webp", "label": "Ảnh 4", "order": 4}, {"src": "assets/catalog/vi/cerave-10/anh-5.webp", "label": "Ảnh 5", "order": 5}, {"src": "assets/catalog/vi/cerave-10/anh-6.webp", "label": "Ảnh 6", "order": 6}, {"src": "assets/catalog/vi/cerave-10/anh-7.webp", "label": "Ảnh 7", "order": 7}]}}, {"id": "l-oreal-paris-01", "brandId": "l-oreal-paris", "brand": "L'Oréal Paris", "name": {"vi": "L'Oréal Paris Glycolic Bright 1.0% Glycolic Acid (AHA) Serum 15ml", "en": "L'Oréal Paris Glycolic Bright 1.0% Glycolic Acid (AHA) Serum 15ml"}, "category": "Skincare", "type": "Tinh chất dưỡng da (Serum)", "size": "15ml", "country": "Pháp", "description": {"vi": "SKU 01 – L'ORÉAL PARIS GLYCOLIC BRIGHT SERUM 15ML\n\n1. MÔ TẢ SẢN PHẨM\nTên sản phẩm: Serum Dưỡng Sáng Mờ Thâm Nám L'Oréal Paris Glycolic Bright 1.0% Glycolic Acid (AHA) 15ml\nThương hiệu: L'Oréal Paris\nXuất xứ thương hiệu: Pháp\nDung tích: 15ml\nPhân loại: Tinh chất dưỡng da (Serum)\n\nL'Oréal Paris Glycolic Bright Instant Glowing Serum là tinh chất dưỡng sáng da với công thức chứa 1.0% Glycolic Acid (AHA), kết hợp cùng Niacinamide và dẫn xuất Vitamin C.\n\nSản phẩm hỗ trợ cải thiện tình trạng da xỉn màu, thâm sạm, giúp làn da trông sáng hơn, đều màu và rạng rỡ hơn.\n\n2. CÔNG DỤNG\n• Hỗ trợ làm sáng da, cải thiện vẻ ngoài của làn da xỉn màu.\n• Hỗ trợ làm mờ sự xuất hiện của vết thâm và đốm sạm màu.\n• Giúp cải thiện tình trạng da không đều màu.\n• Hỗ trợ làm mịn bề mặt da.\n• Góp phần duy trì độ ẩm cho da.\n\n3. THÀNH PHẦN\n• Glycolic Acid 1.0% (AHA): Hỗ trợ loại bỏ tế bào chết trên bề mặt da.\n• Niacinamide (Vitamin B3): Hỗ trợ dưỡng sáng và làm đều màu da.\n• 3-O-Ethyl Ascorbic Acid: Dẫn xuất Vitamin C, hỗ trợ chống oxy hóa.\n• Glycerin: Giúp duy trì độ ẩm.\n• Sodium Hyaluronate: Hỗ trợ cấp ẩm.\n• Salicylic Acid: Hỗ trợ chăm sóc bề mặt da.\n\nLưu ý: Công thức có chứa cồn và hương liệu. Danh sách INCI đầy đủ cần đối chiếu trên bao bì thực tế.\n\n4. HƯỚNG DẪN SỬ DỤNG\nBước 1: Làm sạch da mặt.\nBước 2: Lấy lượng serum vừa đủ và thoa đều lên da, tránh vùng mắt.\nBước 3: Tiếp tục sử dụng kem dưỡng ẩm.\n\nTần suất: Sử dụng theo hướng dẫn trên bao bì. Người mới dùng AHA nên bắt đầu với tần suất thấp.\n\nLưu ý: Sử dụng kem chống nắng vào ban ngày. Không thoa trên vùng da tổn thương hoặc đang kích ứng.\n\n5. ĐỐI TƯỢNG SỬ DỤNG\n• Người có làn da xỉn màu, thiếu sức sống.\n• Người có làn da không đều màu.\n• Người có vết thâm sau mụn hoặc đốm sạm.\n• Người có nhu cầu dưỡng sáng và cải thiện bề mặt da.\n\nNgười có làn da nhạy cảm nên thử sản phẩm trên một vùng da nhỏ trước khi sử dụng.", "en": "1. PRODUCT DESCRIPTION\n\nL'Oréal Paris Glycolic Bright 1.0% Glycolic Acid (AHA) Serum is a targeted facial serum developed to improve the appearance of dullness, uneven skin tone and visible dark spots. Formulated with 1.0% glycolic acid, an alpha hydroxy acid, it helps exfoliate accumulated dead skin cells on the surface of the skin and promote a smoother, brighter-looking complexion. Its lightweight serum texture can be incorporated into a regular skincare routine with careful attention to skin tolerance and daily sun protection.\n\n2. BENEFITS\n\n• Helps improve the appearance of dull and uneven skin tone.\n• Supports gentle chemical exfoliation of dead skin cells.\n• Helps refine the appearance of rough skin texture.\n• Promotes a smoother and more radiant-looking complexion.\n• Helps reduce the visible appearance of dark spots over time.\n\n3. INGREDIENTS\n\nKey ingredients and their functions:\n\n• 1.0% Glycolic Acid (AHA): An exfoliating acid that helps remove accumulated surface dead skin cells.\n• Humectants: Help support hydration within the serum formula.\n• Skin-Conditioning Ingredients: Support a comfortable application experience.\n• Other Brightening Ingredients: The exact complete formula should be verified against the 15ml packaging.\n\nNote: These are selected or representative ingredients and ingredient categories, not a verified complete INCI declaration. Formulas may differ by market and product generation. Confirm against the actual product packaging before publication.\n\n4. DIRECTIONS FOR USE\n\n1. Cleanse the face and gently pat dry.\n2. Apply a small amount of serum to the face, avoiding the eyes and lips.\n3. Introduce gradually, particularly if the skin is new to exfoliating acids.\n4. Follow with a suitable moisturizer.\n5. Use broad-spectrum sunscreen every morning.\n6. Avoid combining with multiple strong exfoliating products in the same routine unless skin tolerance is established.\n\nPrecautions: For external use only. Avoid direct contact with eyes. Discontinue use if irritation occurs. Follow the product label for specific warnings and application frequency.\n\n5. SUITABLE FOR\n\n• People concerned about dull-looking skin.\n• Individuals with uneven skin tone or visible dark spots.\n• Those seeking smoother-looking skin texture.\n• Skin that tolerates AHA-based exfoliating skincare."}, "image": "assets/catalog/product-l-oreal-paris-01.webp", "gallery": {"vi": [{"src": "assets/catalog/vi/l-oreal-paris-01/thumbnail.webp", "label": "Thumbnail", "order": 0}, {"src": "assets/catalog/vi/l-oreal-paris-01/anh-1.webp", "label": "Ảnh 1", "order": 1}, {"src": "assets/catalog/vi/l-oreal-paris-01/anh-2.webp", "label": "Ảnh 2", "order": 2}, {"src": "assets/catalog/vi/l-oreal-paris-01/anh-3.webp", "label": "Ảnh 3", "order": 3}, {"src": "assets/catalog/vi/l-oreal-paris-01/anh-4.webp", "label": "Ảnh 4", "order": 4}, {"src": "assets/catalog/vi/l-oreal-paris-01/anh-5.webp", "label": "Ảnh 5", "order": 5}, {"src": "assets/catalog/vi/l-oreal-paris-01/anh-6.webp", "label": "Ảnh 6", "order": 6}, {"src": "assets/catalog/vi/l-oreal-paris-01/anh-7.webp", "label": "Ảnh 7", "order": 7}]}}, {"id": "l-oreal-paris-02", "brandId": "l-oreal-paris", "brand": "L'Oréal Paris", "name": {"vi": "L'ORÉAL PARIS GLYCOLIC BRIGHT GLOWING CREAM NIGHT 15ML", "en": "L'Oréal Paris Glycolic Bright Glowing Cream Night 15ml"}, "category": "Skincare", "type": "Kem dưỡng da ban đêm", "size": "15ml", "country": "Pháp", "description": {"vi": "1. MÔ TẢ SẢN PHẨM\nTên sản phẩm: Kem Đêm Dưỡng Sáng Mờ Thâm Nám L'Oréal Paris Glycolic (AHA) Bright 15ml\n\nThương hiệu: L'Oréal Paris\nXuất xứ thương hiệu: Pháp\nDung tích: 15ml\nPhân loại: Kem dưỡng da ban đêm\n\nL'Oréal Paris Glycolic Bright Glowing Cream Night là kem dưỡng da ban đêm thuộc dòng Glycolic Bright, được phát triển để chăm sóc làn da xỉn màu, không đều màu và có các đốm thâm sạm.\n\nCông thức kết hợp Glycolic Acid (AHA), Niacinamide và Vitamin E, hỗ trợ dưỡng sáng, duy trì độ ẩm và cải thiện vẻ ngoài của làn da trong quá trình chăm sóc ban đêm.\n\n2. CÔNG DỤNG\n• Hỗ trợ làm sáng da và giảm tình trạng da xỉn màu.\n• Hỗ trợ làm mờ sự xuất hiện của các đốm thâm sạm.\n• Giúp làn da trông đều màu và rạng rỡ hơn.\n• Cung cấp độ ẩm, hỗ trợ cải thiện hàng rào giữ ẩm của da.\n• Hỗ trợ chăm sóc bề mặt da nhờ thành phần Glycolic Acid.\n• Bổ sung thành phần chống oxy hóa Vitamin E.\n\n3. THÀNH PHẦN\n• Glycolic Acid (AHA): Hỗ trợ loại bỏ tế bào chết trên bề mặt, giúp da trông sáng và mịn hơn.\n• Niacinamide (Vitamin B3): Hỗ trợ cải thiện tình trạng da không đều màu.\n• Tocopheryl Acetate (dẫn xuất Vitamin E): Hỗ trợ chống oxy hóa.\n• Glycerin: Giúp hút ẩm và duy trì độ ẩm cho da.\n• Sodium Hyaluronate: Hỗ trợ cấp ẩm, giúp da mềm mại.\n• Ascorbyl Glucoside (dẫn xuất Vitamin C): Hỗ trợ chống oxy hóa và dưỡng sáng.\n\nLưu ý: Công thức có chứa Alcohol và Fragrance (hương liệu). Thành phần có thể thay đổi theo phiên bản và lô sản xuất; cần đối chiếu bao bì thực tế khi công bố danh sách INCI đầy đủ.\n\n4. HƯỚNG DẪN SỬ DỤNG\nBước 1: Làm sạch da mặt vào buổi tối.\nBước 2: Sử dụng serum hoặc các bước dưỡng da trước kem dưỡng nếu có.\nBước 3: Lấy một lượng kem vừa đủ, thoa đều lên mặt và cổ.\nBước 4: Massage nhẹ nhàng cho kem trải đều trên da.\n\nTần suất sử dụng: Mỗi tối theo hướng dẫn của hãng.\n\nLưu ý:\n• Tránh để sản phẩm tiếp xúc với mắt.\n• Người có da nhạy cảm nên thử trên vùng da nhỏ trước khi dùng.\n• Sử dụng kem chống nắng vào ban ngày khi đang chăm sóc da bằng sản phẩm chứa AHA.\n• Ngừng sử dụng nếu xuất hiện kích ứng kéo dài.\n\n5. ĐỐI TƯỢNG SỬ DỤNG\n• Người có làn da xỉn màu, kém rạng rỡ.\n• Người có làn da không đều màu.\n• Người có các đốm thâm sạm hoặc vết thâm sau mụn.\n• Người có nhu cầu dưỡng ẩm và chăm sóc da vào ban đêm.\n• Người muốn kết hợp dưỡng sáng và dưỡng ẩm trong cùng một sản phẩm.\n\nNgười có da đang tổn thương hoặc kích ứng nên thận trọng và tham khảo chuyên gia da liễu trước khi sử dụng.", "en": "1. PRODUCT DESCRIPTION\n\nL'Oréal Paris Glycolic Bright Glowing Cream Night is a nighttime facial moisturizer developed to support a brighter and more even-looking complexion. Part of the Glycolic Bright skincare range, the cream combines moisturizing care with the brand's glycolic-acid-focused brightening approach. Its nourishing texture helps soften the skin overnight while addressing the appearance of dullness and uneven tone. The compact 15ml size is suitable for travel or for trying the product before purchasing a larger format.\n\n2. BENEFITS\n\n• Provides moisturizing care during the night.\n• Helps improve the appearance of dull skin.\n• Supports a smoother and more radiant-looking complexion.\n• Helps maintain skin softness and comfort.\n• Complements a skincare routine focused on uneven skin tone.\n\n3. INGREDIENTS\n\nKey ingredients and their functions:\n\n• Glycolic Acid: An AHA associated with exfoliating and brightening skincare.\n• Glycerin: A humectant that helps retain moisture.\n• Emollient Ingredients: Help soften and condition the skin.\n• Skin-Conditioning Agents: Support the cream's moisturizing texture.\n• The exact key ingredients and concentrations should be verified against the specific 15ml packaging.\n\nNote: These are selected or representative ingredients and ingredient categories, not a verified complete INCI declaration. Formulas may differ by market and product generation. Confirm against the actual product packaging before publication.\n\n4. DIRECTIONS FOR USE\n\n1. Cleanse the face in the evening.\n2. Apply toner or serum if included in the routine.\n3. Take a suitable amount of night cream.\n4. Spread evenly over the face and neck, avoiding the eye area.\n5. Massage gently until absorbed.\n6. Apply broad-spectrum sunscreen the following morning.\n\nPrecautions: For external use only. Avoid direct contact with eyes. Discontinue use if irritation occurs. Follow the product label for specific warnings and application frequency.\n\n5. SUITABLE FOR\n\n• People concerned about dullness and uneven skin tone.\n• Individuals seeking a nighttime moisturizer.\n• Skin requiring additional overnight conditioning.\n• Those following a brightening skincare routine."}, "image": "assets/catalog/product-l-oreal-paris-02.webp", "gallery": {"vi": [{"src": "assets/catalog/vi/l-oreal-paris-02/thumbnail.webp", "label": "Thumbnail", "order": 0}, {"src": "assets/catalog/vi/l-oreal-paris-02/anh-1.webp", "label": "Ảnh 1", "order": 1}, {"src": "assets/catalog/vi/l-oreal-paris-02/anh-2.webp", "label": "Ảnh 2", "order": 2}, {"src": "assets/catalog/vi/l-oreal-paris-02/anh-3.webp", "label": "Ảnh 3", "order": 3}, {"src": "assets/catalog/vi/l-oreal-paris-02/anh-4.webp", "label": "Ảnh 4", "order": 4}, {"src": "assets/catalog/vi/l-oreal-paris-02/anh-5.webp", "label": "Ảnh 5", "order": 5}, {"src": "assets/catalog/vi/l-oreal-paris-02/anh-6.webp", "label": "Ảnh 6", "order": 6}, {"src": "assets/catalog/vi/l-oreal-paris-02/anh-7.webp", "label": "Ảnh 7", "order": 7}]}}, {"id": "l-oreal-paris-03", "brandId": "l-oreal-paris", "brand": "L'Oréal Paris", "name": {"vi": "L'ORÉAL PARIS GLYCOLIC BRIGHT DAY CREAM SPF17 15ML", "en": "L'Oréal Paris Glycolic Bright Day Cream SPF17 15ml"}, "category": "Skincare", "type": "Kem dưỡng da ban ngày", "size": "15ml", "country": "Pháp", "description": {"vi": "1. MÔ TẢ SẢN PHẨM\n\nTên sản phẩm: Kem Ngày Dưỡng Sáng Mờ Thâm Nám L'Oréal Paris Glycolic (AHA) Bright SPF17 15ml\n\nThương hiệu: L'Oréal Paris\nXuất xứ thương hiệu: Pháp\nDung tích: 15ml\nPhân loại: Kem dưỡng da ban ngày\n\nL'Oréal Paris Glycolic Bright Glowing Cream Day SPF17 là kem dưỡng da ban ngày thuộc dòng Glycolic Bright, được phát triển nhằm hỗ trợ cải thiện làn da xỉn màu, không đều màu và có các đốm thâm sạm.\n\nSản phẩm chứa Glycolic Acid (AHA), kết hợp thành phần dưỡng ẩm và bộ lọc tia UV, giúp làn da được chăm sóc, duy trì độ ẩm và trông sáng đều màu hơn. Công thức được thương hiệu giới thiệu là đã kiểm chứng trên làn da châu Á.\n\n2. CÔNG DỤNG\n\n• Hỗ trợ làm sáng da, cải thiện vẻ ngoài của làn da xỉn màu.\n• Hỗ trợ làm giảm sự xuất hiện của các đốm thâm sạm.\n• Giúp da trông đều màu và rạng rỡ hơn.\n• Cung cấp độ ẩm, giúp da mềm mại và mịn màng.\n• Hỗ trợ bảo vệ da trước tác động của tia UV với chỉ số SPF17.\n• Có thể sử dụng như một lớp kem dưỡng trước khi trang điểm.\n\n3. THÀNH PHẦN\n\nCác thành phần nổi bật theo danh sách thành phần được hãng công bố:\n\n• Glycolic Acid (AHA): Hỗ trợ loại bỏ tế bào chết trên bề mặt da, giúp cải thiện vẻ ngoài của làn da xỉn màu.\n• Glycerin: Thành phần hút ẩm, giúp duy trì độ ẩm cho da.\n• Ascorbyl Glucoside: Dẫn xuất Vitamin C, hỗ trợ chống oxy hóa và dưỡng sáng.\n• Phenylethyl Resorcinol: Thành phần được sử dụng trong các công thức chăm sóc da không đều màu.\n• Ethylhexyl Methoxycinnamate: Bộ lọc UVB.\n• Diethylamino Hydroxybenzoyl Hexyl Benzoate: Bộ lọc UVA.\n• Titanium Dioxide: Thành phần góp phần bảo vệ da trước tia UV trong công thức.\n• Capryloyl Salicylic Acid: Thành phần hỗ trợ chăm sóc và làm mịn bề mặt da.\n\nLưu ý: Sản phẩm có chứa hương liệu và một số thành phần tạo mùi. Danh sách INCI đầy đủ cần đối chiếu với bao bì thực tế trước khi đăng tải.\n\n4. HƯỚNG DẪN SỬ DỤNG\n\nBước 1: Làm sạch da mặt vào buổi sáng.\nBước 2: Sử dụng toner hoặc serum nếu có trong quy trình chăm sóc da.\nBước 3: Lấy một lượng kem vừa đủ, thoa đều lên mặt và cổ.\nBước 4: Massage nhẹ nhàng để kem trải đều trên da.\n\nTần suất sử dụng: Mỗi buổi sáng.\n\nCó thể sử dụng sản phẩm làm lớp lót trước khi trang điểm.\n\nLưu ý:\n• Tránh tiếp xúc trực tiếp với mắt.\n• Người có làn da nhạy cảm nên thử sản phẩm trên một vùng da nhỏ trước khi sử dụng.\n• SPF17 không thay thế hoàn toàn kem chống nắng phổ rộng SPF30 trở lên khi tiếp xúc với ánh nắng.\n• Ngừng sử dụng nếu xuất hiện kích ứng kéo dài.\n• Bảo quản nơi khô ráo, thoáng mát, tránh ánh nắng trực tiếp.\n\n5. ĐỐI TƯỢNG SỬ DỤNG\n\n• Người có làn da xỉn màu, kém rạng rỡ.\n• Người có làn da không đều màu.\n• Người có các đốm thâm sạm hoặc vết thâm sau mụn.\n• Người có nhu cầu dưỡng sáng và dưỡng ẩm vào ban ngày.\n• Người muốn sử dụng kem dưỡng có kết hợp chỉ số chống nắng SPF17.\n\nNgười có làn da đang tổn thương, kích ứng hoặc quá nhạy cảm với AHA nên thận trọng khi sử dụng.", "en": "1. PRODUCT DESCRIPTION\n\nL'Oréal Paris Glycolic Bright Day Cream SPF17 is a daytime facial moisturizer designed to combine hydration with a brighter-looking complexion and labeled SPF17 sun protection. As part of the Glycolic Bright range, the product supports skincare routines focused on dullness, uneven tone and visible dark spots. Its cream texture helps soften the skin and create a comfortable base for daily makeup. Because SPF17 offers limited protection compared with higher-SPF sunscreens, additional broad-spectrum sun protection is recommended for extended outdoor exposure.\n\n2. BENEFITS\n\n• Provides everyday facial moisturizing care.\n• Helps improve the appearance of dull or uneven skin tone.\n• Offers SPF17 protection when applied as directed.\n• Supports a smoother-looking complexion.\n• Can be used as part of a daytime brightening routine.\n\n3. INGREDIENTS\n\nKey ingredients and their functions:\n\n• Glycolic-Acid-Related Brightening Ingredients: Associated with the Glycolic Bright product range; confirm the specific day-cream formula.\n• Moisturizing Ingredients: Help maintain hydration and skin comfort.\n• UV Filters: Provide the product's labeled SPF17 protection; exact filter names require packaging verification.\n• Emollients: Support a smooth cream texture.\n• The complete INCI should be checked against the 15ml product label.\n\nNote: These are selected or representative ingredients and ingredient categories, not a verified complete INCI declaration. Formulas may differ by market and product generation. Confirm against the actual product packaging before publication.\n\n4. DIRECTIONS FOR USE\n\n1. Cleanse the face and apply any suitable serum.\n2. Apply the day cream evenly over the face and neck.\n3. Avoid direct contact with the eyes.\n4. For meaningful sun exposure, apply a separate broad-spectrum SPF30 or higher sunscreen in an adequate amount.\n5. Reapply sunscreen regularly during outdoor exposure.\n6. Continue with makeup if desired.\n\nPrecautions: For external use only. Avoid direct contact with eyes. Discontinue use if irritation occurs. Follow the product label for specific warnings and application frequency.\n\n5. SUITABLE FOR\n\n• People seeking a daytime brightening moisturizer.\n• Individuals concerned about dull or uneven-looking skin.\n• Those wanting a moisturizing base for makeup.\n• People using additional sunscreen for daily UV protection."}, "image": "assets/catalog/product-l-oreal-paris-03.webp", "gallery": {"vi": [{"src": "assets/catalog/vi/l-oreal-paris-03/thumbnail.webp", "label": "Thumbnail", "order": 0}, {"src": "assets/catalog/vi/l-oreal-paris-03/anh-1.webp", "label": "Ảnh 1", "order": 1}, {"src": "assets/catalog/vi/l-oreal-paris-03/anh-2.webp", "label": "Ảnh 2", "order": 2}, {"src": "assets/catalog/vi/l-oreal-paris-03/anh-3.webp", "label": "Ảnh 3", "order": 3}, {"src": "assets/catalog/vi/l-oreal-paris-03/anh-4.webp", "label": "Ảnh 4", "order": 4}, {"src": "assets/catalog/vi/l-oreal-paris-03/anh-5.webp", "label": "Ảnh 5", "order": 5}, {"src": "assets/catalog/vi/l-oreal-paris-03/anh-6.webp", "label": "Ảnh 6", "order": 6}, {"src": "assets/catalog/vi/l-oreal-paris-03/anh-7.webp", "label": "Ảnh 7", "order": 7}]}}, {"id": "l-oreal-paris-04", "brandId": "l-oreal-paris", "brand": "L'Oréal Paris", "name": {"vi": "L'ORÉAL PARIS GLYCOLIC BRIGHT GLOWING DAILY CLEANSER FOAM 50ML", "en": "L'Oréal Paris Glycolic Bright Glowing Daily Cleanser Foam 50ml"}, "category": "Skincare", "type": "Sữa rửa mặt", "size": "50ml", "country": "Pháp", "description": {"vi": "1. MÔ TẢ SẢN PHẨM\n\nTên sản phẩm: Sữa Rửa Mặt Sáng Da L'Oréal Paris Glycolic (AHA) Bright 50ml\nThương hiệu: L'Oréal Paris\nXuất xứ thương hiệu: Pháp\nDung tích: 50ml\nPhân loại: Sữa rửa mặt\n\nL'Oréal Paris Glycolic Bright Glowing Daily Cleanser Foam là sữa rửa mặt tạo bọt thuộc dòng Glycolic Bright. Sản phẩm kết hợp khả năng làm sạch bụi bẩn, bã nhờn và tạp chất với thành phần Glycolic Acid (AHA), hỗ trợ loại bỏ tế bào chết trên bề mặt da.\n\nKết cấu bọt kem giúp làm sạch da trong bước chăm sóc hằng ngày, hỗ trợ mang lại làn da sạch thoáng, sáng và đều màu hơn.\n\n2. CÔNG DỤNG\n\n• Làm sạch bụi bẩn, bã nhờn và tạp chất tích tụ trên da.\n• Hỗ trợ làm sạch lớp trang điểm nhẹ theo thông tin hãng giới thiệu.\n• Hỗ trợ loại bỏ tế bào chết trên bề mặt da.\n• Giúp làn da trông sáng và đều màu hơn.\n• Chuẩn bị bề mặt da cho các bước dưỡng tiếp theo.\n\n3. THÀNH PHẦN\n\nCác thành phần nổi bật:\n\n• Glycolic Acid (AHA): Hỗ trợ loại bỏ tế bào chết trên bề mặt, cải thiện vẻ ngoài của da xỉn màu.\n• Glycerin: Thành phần hút ẩm, góp phần hạn chế cảm giác khô da sau làm sạch.\n• Myristic Acid, Palmitic Acid và Stearic Acid: Các acid béo tham gia cấu trúc nền làm sạch và tạo bọt.\n• Salicylic Acid: Hỗ trợ chăm sóc bề mặt da.\n• Pancratium Maritimum Extract: Chiết xuất thực vật có trong công thức.\n• Paeonia Suffruticosa Root Extract: Chiết xuất rễ mẫu đơn có trong công thức.\n• Ascorbyl Glucoside: Dẫn xuất Vitamin C có trong danh sách thành phần.\n\nLưu ý: Sản phẩm có chứa hương liệu. Tên Ascorbyl Glucoside được chuẩn hóa từ cách ghi có lỗi chính tả trên trang hãng. Danh sách INCI đầy đủ cần đối chiếu bao bì thực tế.\n\n4. HƯỚNG DẪN SỬ DỤNG\n\nBước 1: Làm ướt da mặt bằng nước sạch.\nBước 2: Lấy một lượng sữa rửa mặt vừa đủ ra lòng bàn tay.\nBước 3: Tạo bọt và massage nhẹ nhàng trên da mặt.\nBước 4: Rửa sạch lại với nước.\n\nTần suất sử dụng: Có thể dùng trong quy trình làm sạch hằng ngày, tùy khả năng dung nạp của da.\n\nLưu ý:\n• Tránh vùng mắt.\n• Không chà xát mạnh trên da.\n• Người có da nhạy cảm với acid tẩy tế bào chết nên thận trọng.\n• Ngừng sử dụng nếu có kích ứng kéo dài.\n\n5. ĐỐI TƯỢNG SỬ DỤNG\n\n• Người có nhu cầu làm sạch da mặt hằng ngày.\n• Người có làn da xỉn màu, không đều màu.\n• Người có da tích tụ bụi bẩn, dầu thừa.\n• Người muốn kết hợp làm sạch và hỗ trợ cải thiện bề mặt da.\n\nNgười có da đang kích ứng, tổn thương hoặc quá nhạy cảm với AHA nên tham khảo chuyên gia da liễu trước khi sử dụng.", "en": "1. PRODUCT DESCRIPTION\n\nL'Oréal Paris Glycolic Bright Glowing Daily Cleanser Foam is a facial cleanser developed to remove daily impurities and support a fresher, brighter-looking complexion. Part of the Glycolic Bright skincare range, it combines foaming cleansing with an approach focused on dullness and uneven skin texture. The cleanser helps wash away surface oil, dirt and buildup while preparing the skin for subsequent brightening serums and moisturizers. Its convenient 50ml format is suitable for travel and everyday use.\n\n2. BENEFITS\n\n• Removes dirt, surface oil and daily impurities.\n• Leaves the complexion feeling clean and refreshed.\n• Helps improve the appearance of dull skin.\n• Supports a smoother-looking skin surface.\n• Prepares the face for the next skincare steps.\n\n3. INGREDIENTS\n\nKey ingredients and their functions:\n\n• Glycolic Acid: An AHA used in brightening and exfoliating skincare; verify its presence and concentration on this cleanser's label.\n• Cleansing Surfactants: Help remove oil and impurities.\n• Humectants: Support moisture retention during cleansing.\n• Foam-Forming Ingredients: Create the product's cleansing texture.\n• The exact ingredient declaration may vary by regional formulation.\n\nNote: These are selected or representative ingredients and ingredient categories, not a verified complete INCI declaration. Formulas may differ by market and product generation. Confirm against the actual product packaging before publication.\n\n4. DIRECTIONS FOR USE\n\n1. Wet the face with lukewarm water.\n2. Dispense a small amount of cleanser into the palms.\n3. Work into a gentle foam.\n4. Massage lightly over the face, avoiding the eye area.\n5. Rinse thoroughly and pat dry.\n6. Follow with a suitable serum and moisturizer.\n\nPrecautions: For external use only. Avoid direct contact with eyes. Discontinue use if irritation occurs. Follow the product label for specific warnings and application frequency.\n\n5. SUITABLE FOR\n\n• People concerned about dull-looking skin.\n• Individuals seeking a daily foaming cleanser.\n• Normal and combination skin, depending on tolerance.\n• Those following a Glycolic Bright skincare routine."}, "image": "assets/catalog/product-l-oreal-paris-04.jpg", "gallery": {"vi": [{"src": "assets/catalog/vi/l-oreal-paris-04/thumbnail.webp", "label": "Thumbnail", "order": 0}, {"src": "assets/catalog/vi/l-oreal-paris-04/anh-1.webp", "label": "Ảnh 1", "order": 1}, {"src": "assets/catalog/vi/l-oreal-paris-04/anh-2.webp", "label": "Ảnh 2", "order": 2}, {"src": "assets/catalog/vi/l-oreal-paris-04/anh-3.webp", "label": "Ảnh 3", "order": 3}, {"src": "assets/catalog/vi/l-oreal-paris-04/anh-4.webp", "label": "Ảnh 4", "order": 4}, {"src": "assets/catalog/vi/l-oreal-paris-04/anh-5.webp", "label": "Ảnh 5", "order": 5}, {"src": "assets/catalog/vi/l-oreal-paris-04/anh-6.webp", "label": "Ảnh 6", "order": 6}, {"src": "assets/catalog/vi/l-oreal-paris-04/anh-7.webp", "label": "Ảnh 7", "order": 7}]}}, {"id": "l-oreal-paris-05", "brandId": "l-oreal-paris", "brand": "L'Oréal Paris", "name": {"vi": "L'ORÉAL PARIS REVITALIFT CRYSTAL MICRO ESSENCE 130ML", "en": "L'Oréal Paris Revitalift Crystal Micro Essence 130ml"}, "category": "Skincare", "type": "Dưỡng chất chăm sóc da (Micro Essence)", "size": "130ml", "country": "Pháp", "description": {"vi": "1. MÔ TẢ SẢN PHẨM\n\nTên sản phẩm: Dưỡng Chất Căng Mướt Da L'Oréal Paris Revitalift Crystal Micro Essence 130ml\nThương hiệu: L'Oréal Paris\nXuất xứ thương hiệu: Pháp\nDung tích: 130ml\nPhân loại: Dưỡng chất chăm sóc da (Micro Essence)\n\nL'Oréal Paris Revitalift Crystal Micro Essence là sản phẩm kết hợp nền nước và các thành phần dưỡng da, được hãng giới thiệu là phù hợp với làn da châu Á.\n\nVới công nghệ micronized theo giới thiệu của thương hiệu, sản phẩm hỗ trợ chăm sóc, duy trì độ ẩm và giúp làn da trông căng mượt, mềm mại hơn. Kết cấu dưỡng chất được sử dụng sau bước làm sạch và trước kem dưỡng.\n\n2. CÔNG DỤNG\n\nTheo thông tin hãng công bố, sản phẩm hướng đến 7 lợi ích:\n\n• Cấp ẩm tức thì cho da.\n• Hỗ trợ làm da sáng mịn.\n• Giúp lỗ chân lông trông nhỏ hơn.\n• Hỗ trợ cải thiện vẻ ngoài săn chắc và đàn hồi của da.\n• Hỗ trợ làm giảm sự xuất hiện của vết thâm và đốm nâu.\n• Hỗ trợ chăm sóc và nuôi dưỡng làn da.\n• Giúp làn da trông tươi trẻ hơn.\n\n3. THÀNH PHẦN\n\nCác thành phần nổi bật từ danh sách INCI chính thức:\n\n• Butylene Glycol: Thành phần hút ẩm, hỗ trợ duy trì độ ẩm cho da.\n• Propanediol: Hỗ trợ giữ ẩm và cải thiện cảm giác khi sử dụng.\n• Hydroxyethylpiperazine Ethane Sulfonic Acid (HEPES): Thành phần được sử dụng trong các công thức chăm sóc bề mặt da.\n• Salicylic Acid: Hỗ trợ chăm sóc bề mặt da.\n• Capryloyl Salicylic Acid (LHA): Hỗ trợ cải thiện bề mặt da.\n• Adenosine: Thành phần thường được sử dụng trong sản phẩm chăm sóc da có dấu hiệu lão hóa.\n• Madecassoside: Thành phần hỗ trợ chăm sóc và làm dịu da.\n• Tocopherol (Vitamin E): Thành phần chống oxy hóa.\n• Yeast Extract: Chiết xuất nấm men có trong công thức.\n\nLưu ý: Sản phẩm có chứa Alcohol và Fragrance (hương liệu). Danh sách INCI đầy đủ được hãng công bố tại đường dẫn nguồn; cần đối chiếu với bao bì nếu dùng cho hồ sơ sản phẩm.\n\n4. HƯỚNG DẪN SỬ DỤNG\n\nBước 1: Làm sạch da mặt.\nBước 2: Lấy một lượng dưỡng chất vừa đủ, khoảng bằng một hạt bắp nhỏ.\nBước 3: Chia đều lên 5 điểm: trán, mũi, cằm và hai bên má.\nBước 4: Thoa nhẹ nhàng khắp mặt và vỗ nhẹ.\nBước 5: Có thể sử dụng thêm cho vùng cổ, sau đó tiếp tục với kem dưỡng.\n\nTần suất sử dụng: Hằng ngày, vào buổi sáng và buổi tối.\n\nLưu ý:\n• Sử dụng sau bước làm sạch và trước kem dưỡng.\n• Tránh vùng da quanh mắt.\n• Người có làn da nhạy cảm nên thử trên vùng da nhỏ trước khi dùng.\n• Sử dụng kem chống nắng vào ban ngày.\n\n5. ĐỐI TƯỢNG SỬ DỤNG\n\n• Người có nhu cầu cấp ẩm và chăm sóc da hằng ngày.\n• Người có làn da thiếu ẩm, kém căng mượt.\n• Người có làn da xỉn màu hoặc không đều màu.\n• Người quan tâm đến các dấu hiệu lão hóa sớm.\n• Người muốn bổ sung một bước dưỡng chất trước kem dưỡng.\n\nSản phẩm được hãng giới thiệu là phù hợp với làn da châu Á. Người có da nhạy cảm với cồn, hương liệu hoặc các acid chăm sóc bề mặt nên thận trọng.", "en": "1. PRODUCT DESCRIPTION\n\nL'Oréal Paris Revitalift Crystal Micro Essence is a lightweight facial essence designed to hydrate the skin while improving the appearance of dullness, uneven texture and visible pores. Its fluid, water-like texture absorbs easily and fits between cleansing and serum application. The product is associated with the Revitalift Crystal skincare range, which focuses on smoother and clearer-looking skin. With consistent use, the essence helps support a refreshed complexion and a comfortable, lightweight hydration step.\n\n2. BENEFITS\n\n• Provides lightweight hydration.\n• Helps improve the appearance of rough or uneven skin texture.\n• Supports a smoother and more refined-looking complexion.\n• Helps reduce the appearance of dullness.\n• Absorbs easily without the heaviness of a rich cream.\n• Prepares the skin for subsequent skincare products.\n\n3. INGREDIENTS\n\nKey ingredients and their functions:\n\n• Salicylic Acid: An exfoliating ingredient associated with the Revitalift Crystal Micro Essence range.\n• Glycerin: A moisturizing humectant.\n• Skin-Conditioning Ingredients: Help maintain comfort and hydration.\n• Solvents and Texture Agents: Support the lightweight essence consistency.\n• The exact ingredients and concentrations must be verified against the 130ml regional product.\n\nNote: These are selected or representative ingredients and ingredient categories, not a verified complete INCI declaration. Formulas may differ by market and product generation. Confirm against the actual product packaging before publication.\n\n4. DIRECTIONS FOR USE\n\n1. Cleanse the face thoroughly.\n2. Dispense a small amount of essence into clean palms.\n3. Gently pat over the face and neck, avoiding the eyes.\n4. Allow the product to absorb.\n5. Follow with serum and moisturizer.\n6. Use sunscreen during the day, particularly when using exfoliating skincare.\n\nPrecautions: For external use only. Avoid direct contact with eyes. Discontinue use if irritation occurs. Follow the product label for specific warnings and application frequency.\n\n5. SUITABLE FOR\n\n• People concerned about dull-looking skin.\n• Individuals seeking lightweight facial hydration.\n• Those concerned about uneven skin texture.\n• People who prefer water-like skincare products."}, "image": "assets/catalog/product-l-oreal-paris-05.png", "gallery": {"vi": [{"src": "assets/catalog/vi/l-oreal-paris-05/thumbnail.webp", "label": "Thumbnail", "order": 0}, {"src": "assets/catalog/vi/l-oreal-paris-05/anh-1.webp", "label": "Ảnh 1", "order": 1}, {"src": "assets/catalog/vi/l-oreal-paris-05/anh-2.webp", "label": "Ảnh 2", "order": 2}, {"src": "assets/catalog/vi/l-oreal-paris-05/anh-3.webp", "label": "Ảnh 3", "order": 3}, {"src": "assets/catalog/vi/l-oreal-paris-05/anh-4.webp", "label": "Ảnh 4", "order": 4}, {"src": "assets/catalog/vi/l-oreal-paris-05/anh-5.webp", "label": "Ảnh 5", "order": 5}, {"src": "assets/catalog/vi/l-oreal-paris-05/anh-6.webp", "label": "Ảnh 6", "order": 6}, {"src": "assets/catalog/vi/l-oreal-paris-05/anh-7.webp", "label": "Ảnh 7", "order": 7}]}}, {"id": "l-oreal-paris-06", "brandId": "l-oreal-paris", "brand": "L'Oréal Paris", "name": {"vi": "L'ORÉAL PARIS AURA PERFECT CLINICAL SERUM 30ML", "en": "L'Oréal Paris Aura Perfect Clinical Serum 30ml"}, "category": "Skincare", "type": "Tinh chất dưỡng sáng da (Serum)", "size": "30ml", "country": "Pháp", "description": {"vi": "1. MÔ TẢ SẢN PHẨM\n\nTên sản phẩm: Tinh Chất Tăng Cường Dưỡng Da Trắng Mịn Và Giảm Thâm Nám L'Oréal Paris Aura Perfect Clinical 30ml\nThương hiệu: L'Oréal Paris\nXuất xứ thương hiệu: Pháp\nDung tích: 30ml\nPhân loại: Tinh chất dưỡng sáng da (Serum)\n\nL'Oréal Paris Aura Perfect Clinical Serum là tinh chất dưỡng da thuộc dòng Aura Perfect Clinical, được phát triển nhằm hỗ trợ cải thiện tình trạng da không đều màu và các đốm thâm sạm.\n\nTheo giới thiệu của hãng, sản phẩm kết hợp các thành phần dưỡng sáng, chăm sóc da và hỗ trợ cải thiện độ mịn màng, giúp làn da trông sáng và rạng rỡ hơn khi sử dụng đều đặn.\n\n2. CÔNG DỤNG\n\n• Hỗ trợ làm giảm sự xuất hiện của vết thâm và đốm nám.\n• Giúp làn da trông sáng và đều màu hơn.\n• Hỗ trợ cải thiện vẻ ngoài của làn da xỉn màu.\n• Cung cấp độ ẩm, giúp da mềm mại.\n• Hỗ trợ cải thiện cảm giác mịn màng của bề mặt da.\n• Góp phần chăm sóc da trước các dấu hiệu lão hóa sớm.\n\n3. THÀNH PHẦN\n\nCác thành phần nổi bật theo thông tin hãng công bố:\n\n• 3-O-Ethyl Ascorbic Acid (dẫn xuất Vitamin C, được hãng giới thiệu trong nhóm Actyl C): Hỗ trợ chống oxy hóa và dưỡng sáng da.\n• Niacinamide (Vitamin B3): Hỗ trợ cải thiện tình trạng da không đều màu.\n• Adenosine: Thành phần được hãng nhấn mạnh trong công thức chăm sóc da có đốm sạm.\n• Glycerin: Thành phần hút ẩm, giúp duy trì độ ẩm.\n• Sodium Hyaluronate: Hỗ trợ cấp ẩm cho da.\n• Hydroxyethylpiperazine Ethane Sulfonic Acid (HEPES): Thành phần sử dụng trong các công thức chăm sóc bề mặt da.\n• Tocopheryl Acetate: Dẫn xuất Vitamin E, hỗ trợ chống oxy hóa.\n• Salicylic Acid: Hỗ trợ chăm sóc bề mặt da.\n\nHãng còn giới thiệu công nghệ hoặc phức hợp FIBRELASTYL trong phần mô tả sản phẩm. Đây không phải tên một thành phần INCI đơn lẻ, vì vậy không nên ghi như một hoạt chất riêng trong danh sách thành phần.\n\nLưu ý: Sản phẩm có chứa Alcohol và Fragrance (hương liệu). Danh sách INCI chính thức có một số tên chất tạo mùi cần được đối chiếu với bao bì hiện hành trước khi công bố đầy đủ.\n\n4. HƯỚNG DẪN SỬ DỤNG\n\nBước 1: Làm sạch da mặt.\nBước 2: Lấy lượng tinh chất vừa đủ, khoảng bằng một hạt bắp nhỏ.\nBước 3: Chia đều lên 5 điểm: trán, mũi, cằm và hai bên má.\nBước 4: Thoa nhẹ nhàng khắp mặt và vỗ nhẹ.\nBước 5: Có thể sử dụng thêm cho vùng cổ, sau đó tiếp tục với kem dưỡng.\n\nTần suất sử dụng: Hằng ngày, vào buổi sáng và buổi tối.\n\nLưu ý:\n• Sử dụng sau bước làm sạch và trước kem dưỡng.\n• Tránh vùng da quanh mắt.\n• Người có da nhạy cảm nên thử sản phẩm trên vùng da nhỏ.\n• Sử dụng kem chống nắng vào ban ngày.\n• Ngừng sử dụng nếu xuất hiện kích ứng kéo dài.\n\n5. ĐỐI TƯỢNG SỬ DỤNG\n\n• Người có làn da xỉn màu, thiếu rạng rỡ.\n• Người có làn da không đều màu.\n• Người có các đốm thâm sạm hoặc vết thâm sau mụn.\n• Người có nhu cầu dưỡng sáng và duy trì độ ẩm.\n• Người muốn bổ sung tinh chất chăm sóc da vào quy trình sáng và tối.\n\nNgười có làn da đang kích ứng, tổn thương hoặc nhạy cảm với cồn và hương liệu nên thận trọng khi sử dụng.", "en": "1. PRODUCT DESCRIPTION\n\nL'Oréal Paris Aura Perfect Clinical Serum is a facial skincare treatment developed to improve the appearance of uneven skin tone, dullness and visible dark spots. As part of the Aura Perfect brightening range, it is designed to complement a routine focused on achieving a smoother, more radiant-looking complexion. The serum format allows targeted application before moisturizer. Since Aura Perfect formulas differ by market and product generation, the precise brightening actives and their concentrations should be confirmed on the actual 30ml product packaging.\n\n2. BENEFITS\n\n• Helps improve the appearance of dullness.\n• Supports a more even-looking skin tone.\n• Helps reduce the visible appearance of dark spots.\n• Promotes a brighter and smoother-looking complexion.\n• Can be layered beneath daily moisturizer.\n\n3. INGREDIENTS\n\nKey ingredients and their functions:\n\n• Brightening Actives: The specific combination must be verified for this Aura Perfect Clinical Serum version.\n• Humectants: Help maintain moisture within the serum formula.\n• Skin-Conditioning Agents: Support a smooth application.\n• Antioxidant Ingredients: May be included depending on the regional formulation.\n• The complete INCI and any claimed active percentages require label verification.\n\nNote: These are selected or representative ingredients and ingredient categories, not a verified complete INCI declaration. Formulas may differ by market and product generation. Confirm against the actual product packaging before publication.\n\n4. DIRECTIONS FOR USE\n\n1. Cleanse the face and pat dry.\n2. Apply a small amount of serum evenly over the face.\n3. Focus on areas of uneven-looking skin tone if directed by the label.\n4. Avoid direct contact with the eyes.\n5. Follow with a suitable moisturizer.\n6. Apply broad-spectrum sunscreen every morning.\n\nPrecautions: For external use only. Avoid direct contact with eyes. Discontinue use if irritation occurs. Follow the product label for specific warnings and application frequency.\n\n5. SUITABLE FOR\n\n• People concerned about uneven skin tone.\n• Individuals with visible dark spots.\n• Those seeking a brightening facial serum.\n• People looking to improve the appearance of dull skin."}, "image": "assets/catalog/product-l-oreal-paris-06.png", "gallery": {"vi": [{"src": "assets/catalog/vi/l-oreal-paris-06/thumbnail.webp", "label": "Thumbnail", "order": 0}, {"src": "assets/catalog/vi/l-oreal-paris-06/anh-1.webp", "label": "Ảnh 1", "order": 1}, {"src": "assets/catalog/vi/l-oreal-paris-06/anh-2.webp", "label": "Ảnh 2", "order": 2}, {"src": "assets/catalog/vi/l-oreal-paris-06/anh-3.webp", "label": "Ảnh 3", "order": 3}, {"src": "assets/catalog/vi/l-oreal-paris-06/anh-4.webp", "label": "Ảnh 4", "order": 4}, {"src": "assets/catalog/vi/l-oreal-paris-06/anh-5.webp", "label": "Ảnh 5", "order": 5}, {"src": "assets/catalog/vi/l-oreal-paris-06/anh-6.webp", "label": "Ảnh 6", "order": 6}]}}, {"id": "l-oreal-paris-07", "brandId": "l-oreal-paris", "brand": "L'Oréal Paris", "name": {"vi": "L'ORÉAL PARIS ELSEVE TOTAL REPAIR 5 REPAIRING SHAMPOO 650ML", "en": "L'Oréal Paris Elseve Total Repair 5 Repairing Shampoo 650ml"}, "category": "Haircare", "type": "Dầu gội chăm sóc tóc hư tổn", "size": "650ml", "country": "Pháp", "description": {"vi": "1. MÔ TẢ SẢN PHẨM\n\nTên sản phẩm: Dầu Gội Giảm 5 Dấu Hiệu Tóc Hư Tổn L'Oréal Paris Elseve Total Repair 5 Repairing Shampoo 650ml\n\nThương hiệu: L'Oréal Paris\nXuất xứ thương hiệu: Pháp\nDung tích: 650ml\nPhân loại: Dầu gội chăm sóc tóc hư tổn\n\nL'Oréal Paris Elseve Total Repair 5 Repairing Shampoo là dầu gội thuộc dòng Total Repair 5, giúp làm sạch tóc và da đầu, đồng thời chăm sóc mái tóc có dấu hiệu hư tổn.\n\nSản phẩm được hãng giới thiệu với công nghệ Ceramide, hỗ trợ cải thiện 5 dấu hiệu tóc hư tổn gồm dễ gãy, khô, xỉn màu, thô ráp và chẻ ngọn. Sau khi sử dụng, tóc có thể trông suôn mềm, bóng mượt và dễ chải hơn.\n\n2. CÔNG DỤNG\n\n• Làm sạch bụi bẩn và dầu thừa trên tóc, da đầu.\n• Hỗ trợ giảm tình trạng tóc dễ gãy do hư tổn.\n• Giúp tóc khô xơ trở nên mềm mại hơn.\n• Hỗ trợ cải thiện vẻ ngoài của tóc xỉn màu.\n• Giúp bề mặt sợi tóc trông mượt mà, bớt thô ráp.\n• Hỗ trợ chăm sóc phần tóc có dấu hiệu chẻ ngọn.\n\n3. THÀNH PHẦN\n\nCác thành phần nổi bật:\n\n• Sodium Laureth Sulfate: Chất hoạt động bề mặt, giúp làm sạch tóc và da đầu.\n• Coco-Betaine: Thành phần hỗ trợ làm sạch và tạo bọt.\n• Dimethicone: Giúp tạo cảm giác tóc mềm mượt, giảm ma sát giữa các sợi tóc.\n• Glycol Distearate: Thành phần góp phần tạo kết cấu sản phẩm.\n• Guar Hydroxypropyltrimonium Chloride: Chất điều hòa tóc, hỗ trợ giảm rối.\n• Lactic Acid: Thành phần hỗ trợ điều chỉnh công thức.\n• Polyquaternium-7: Hỗ trợ điều hòa tóc, cải thiện độ mềm mượt.\n• Thành phần thuộc nhóm Ceramide được hãng giới thiệu trong công nghệ chăm sóc tóc hư tổn.\n\nLưu ý: Danh sách thành phần trên website hãng có tên một thành phần Ceramide bị lỗi ký tự và có chất tạo mùi cần đối chiếu với bao bì hiện hành. Không sử dụng nguyên danh sách INCI đó cho hồ sơ công bố khi chưa xác minh.\n\n4. HƯỚNG DẪN SỬ DỤNG\n\nBước 1: Làm ướt tóc và da đầu bằng nước.\nBước 2: Lấy một lượng dầu gội vừa đủ ra lòng bàn tay.\nBước 3: Thoa đều lên tóc và da đầu, massage nhẹ nhàng theo chuyển động tròn.\nBước 4: Xả sạch lại bằng nước.\nBước 5: Có thể gội lần hai nếu cần.\n\nTần suất sử dụng: Theo nhu cầu làm sạch tóc và da đầu.\n\nLưu ý:\n• Tránh để sản phẩm tiếp xúc trực tiếp với mắt.\n• Nếu dính vào mắt, rửa ngay bằng nước sạch.\n• Có thể kết hợp với dầu xả cùng dòng Total Repair 5.\n• Ngừng sử dụng nếu da đầu xuất hiện kích ứng kéo dài.\n\n5. ĐỐI TƯỢNG SỬ DỤNG\n\n• Người có mái tóc khô xơ, thô ráp.\n• Người có tóc dễ gãy do hư tổn.\n• Người có tóc xỉn màu, thiếu độ bóng.\n• Người có phần ngọn tóc dễ chẻ.\n• Người muốn chăm sóc tóc hư tổn trong bước gội đầu hằng ngày.", "en": "1. PRODUCT DESCRIPTION\n\nL'Oréal Paris Elseve Total Repair 5 Repairing Shampoo is a daily hair cleanser developed for damaged-looking hair affected by dryness, roughness, dullness, weakness and split ends. It helps remove scalp oil and accumulated impurities while conditioning the hair to improve its overall appearance and manageability. The Total Repair 5 range is designed to address multiple visible signs of hair damage, making this shampoo a practical choice for hair exposed to frequent brushing, heat styling and environmental stress. The 650ml size is convenient for regular household use.\n\n2. BENEFITS\n\n• Cleanses the scalp and hair effectively.\n• Helps improve the appearance of damaged hair.\n• Supports smoother and softer-feeling hair.\n• Helps reduce the feeling of roughness and tangling.\n• Improves the appearance of dull hair.\n• Prepares hair for conditioner or a repair mask.\n\n3. INGREDIENTS\n\nKey ingredients and their functions:\n\n• Cleansing Surfactants: Remove excess scalp oil and impurities.\n• Conditioning Polymers: Help improve manageability.\n• Silicone-Based Ingredients: May help smooth hair fibers and reduce friction.\n• Protein-Related or Repair Complex Ingredients: Depend on the specific regional Total Repair 5 formula.\n• The exact INCI should be verified against the 650ml bottle.\n\nNote: These are selected or representative ingredients and ingredient categories, not a verified complete INCI declaration. Formulas may differ by market and product generation. Confirm against the actual product packaging before publication.\n\n4. DIRECTIONS FOR USE\n\n1. Wet the hair and scalp thoroughly.\n2. Apply a suitable amount of shampoo.\n3. Massage gently into the scalp using fingertips.\n4. Work the lather through the hair lengths.\n5. Rinse thoroughly with water.\n6. Follow with Elseve Total Repair 5 Conditioner or Hair Mask.\n\nPrecautions: For external use only. Avoid direct contact with eyes. Discontinue use if irritation occurs. Follow the product label for specific warnings and application frequency.\n\n5. SUITABLE FOR\n\n• Dry or damaged-looking hair.\n• Hair affected by heat styling.\n• People concerned about roughness and dullness.\n• Individuals seeking daily shampoo for weakened hair lengths."}, "image": "assets/catalog/product-l-oreal-paris-07.webp", "gallery": {"vi": [{"src": "assets/catalog/vi/l-oreal-paris-07/thumbnail.webp", "label": "Thumbnail", "order": 0}, {"src": "assets/catalog/vi/l-oreal-paris-07/anh-1.webp", "label": "Ảnh 1", "order": 1}, {"src": "assets/catalog/vi/l-oreal-paris-07/anh-2.webp", "label": "Ảnh 2", "order": 2}, {"src": "assets/catalog/vi/l-oreal-paris-07/anh-3.webp", "label": "Ảnh 3", "order": 3}, {"src": "assets/catalog/vi/l-oreal-paris-07/anh-4.webp", "label": "Ảnh 4", "order": 4}, {"src": "assets/catalog/vi/l-oreal-paris-07/anh-5.webp", "label": "Ảnh 5", "order": 5}, {"src": "assets/catalog/vi/l-oreal-paris-07/anh-6.webp", "label": "Ảnh 6", "order": 6}, {"src": "assets/catalog/vi/l-oreal-paris-07/anh-7.webp", "label": "Ảnh 7", "order": 7}]}}, {"id": "l-oreal-paris-08", "brandId": "l-oreal-paris", "brand": "L'Oréal Paris", "name": {"vi": "L'ORÉAL PARIS ELSEVE TOTAL REPAIR 5 REPAIRING CONDITIONER 325ML", "en": "L'Oréal Paris Elseve Total Repair 5 Repairing Conditioner 325ml"}, "category": "Haircare", "type": "Dầu xả chăm sóc tóc hư tổn", "size": "325ml", "country": "Pháp", "description": {"vi": "1. MÔ TẢ SẢN PHẨM\n\nTên sản phẩm: Dầu Xả Giảm 5 Dấu Hiệu Tóc Hư Tổn L'Oréal Paris Elseve Total Repair 5 Repairing Conditioner 325ml\n\nThương hiệu: L'Oréal Paris\nXuất xứ thương hiệu: Pháp\nDung tích: 325ml\nPhân loại: Dầu xả chăm sóc tóc hư tổn\n\nL'Oréal Paris Elseve Total Repair 5 Repairing Conditioner là sản phẩm chăm sóc tóc sau bước gội, thuộc dòng Total Repair 5.\n\nHãng giới thiệu công nghệ KERATINXS với phức hợp Arginine và Serine, hướng đến việc cải thiện vẻ ngoài của tóc hư tổn. Sản phẩm giúp tóc suôn mềm, giảm rối và trông chắc khỏe hơn.\n\n2. CÔNG DỤNG\n\n• Hỗ trợ chăm sóc 5 dấu hiệu tóc hư tổn: dễ gãy, khô, xỉn màu, thô ráp và chẻ ngọn.\n• Giúp tóc mềm mại, dễ chải hơn sau khi gội.\n• Hỗ trợ giảm rối và ma sát khi chải tóc.\n• Giúp bề mặt sợi tóc trông mượt mà hơn.\n• Hỗ trợ cải thiện độ bóng của tóc.\n• Góp phần chăm sóc tóc khô xơ và tóc yếu do tác động bên ngoài.\n\n3. THÀNH PHẦN\n\nCác thành phần nổi bật:\n\n• Cetyl Alcohol: Cồn béo, giúp làm mềm và điều hòa tóc.\n• Stearyl Alcohol: Cồn béo hỗ trợ tạo kết cấu kem và làm mềm tóc.\n• Amodimethicone: Silicone điều hòa tóc, giúp tóc mềm mượt và giảm rối.\n• Behentrimonium Chloride: Chất điều hòa tóc, hỗ trợ gỡ rối.\n• Cetrimonium Chloride: Thành phần giúp cải thiện khả năng chải tóc.\n• Lactic Acid: Hỗ trợ điều chỉnh công thức.\n• Cetyl Esters: Thành phần làm mềm và tạo cảm giác mượt cho tóc.\n\nHãng giới thiệu phức hợp KERATINXS liên quan đến Arginine và Serine trong phần mô tả. Tuy nhiên, cần phân biệt tên công nghệ với danh sách INCI của phiên bản sản phẩm.\n\nLưu ý: Sản phẩm có chứa hương liệu. Danh sách INCI đầy đủ cần đối chiếu bao bì thực tế vì trang hãng có một số tên thành phần bị lỗi ký tự.\n\n4. HƯỚNG DẪN SỬ DỤNG\n\nBước 1: Gội sạch tóc bằng dầu gội phù hợp.\nBước 2: Xả sạch dầu gội và loại bỏ bớt nước thừa trên tóc.\nBước 3: Lấy một lượng dầu xả vừa đủ, thoa đều theo chiều dài tóc.\nBước 4: Tập trung vào thân và ngọn tóc, tránh thoa trực tiếp lên da đầu.\nBước 5: Xả sạch lại bằng nước.\n\nTần suất sử dụng: Sau mỗi lần gội hoặc theo nhu cầu chăm sóc tóc.\n\nLưu ý:\n• Không để sản phẩm tiếp xúc trực tiếp với mắt.\n• Nếu dính vào mắt, rửa ngay bằng nước sạch.\n• Điều chỉnh lượng dùng theo độ dài và độ dày của tóc.\n\n5. ĐỐI TƯỢNG SỬ DỤNG\n\n• Người có mái tóc khô xơ, thiếu độ mềm mại.\n• Người có tóc dễ rối, khó chải.\n• Người có tóc yếu và dễ gãy do hư tổn.\n• Người có tóc xỉn màu, thô ráp hoặc chẻ ngọn.\n• Người muốn bổ sung bước dưỡng tóc sau khi gội.", "en": "1. PRODUCT DESCRIPTION\n\nL'Oréal Paris Elseve Total Repair 5 Repairing Conditioner is a rinse-off conditioning product designed for damaged-looking hair. Used after shampooing, it helps soften rough hair lengths, improve detangling and enhance the appearance of smoothness and shine. The Total Repair 5 approach focuses on multiple visible signs of hair damage, including dryness, roughness, dullness, weakness and split ends. Its creamy texture is suitable for regular use as part of a hair-care routine intended to make damaged hair easier to manage.\n\n2. BENEFITS\n\n• Helps soften dry and rough hair.\n• Improves detangling and manageability.\n• Supports smoother-looking hair lengths.\n• Helps improve the appearance of dull hair.\n• Reduces friction during combing.\n• Complements the Total Repair 5 shampoo routine.\n\n3. INGREDIENTS\n\nKey ingredients and their functions:\n\n• Cationic Conditioning Agents: Help smooth and detangle hair.\n• Fatty Alcohols: Support softness and a creamy texture.\n• Silicone-Based Ingredients: May help reduce friction and improve shine.\n• Emollients: Help condition dry hair lengths.\n• Repair-Complex Ingredients: The exact composition should be verified against the 325ml packaging.\n\nNote: These are selected or representative ingredients and ingredient categories, not a verified complete INCI declaration. Formulas may differ by market and product generation. Confirm against the actual product packaging before publication.\n\n4. DIRECTIONS FOR USE\n\n1. Shampoo the hair and rinse thoroughly.\n2. Gently squeeze out excess water.\n3. Apply conditioner to the mid-lengths and ends.\n4. Distribute evenly through the hair.\n5. Leave on for the time stated on the product label.\n6. Rinse thoroughly with water.\n\nPrecautions: For external use only. Avoid direct contact with eyes. Discontinue use if irritation occurs. Follow the product label for specific warnings and application frequency.\n\n5. SUITABLE FOR\n\n• Damaged-looking hair.\n• Dry and rough hair lengths.\n• Hair prone to tangling.\n• People seeking a daily rinse-off conditioner."}, "image": "assets/catalog/product-l-oreal-paris-08.webp", "gallery": {"vi": [{"src": "assets/catalog/vi/l-oreal-paris-08/thumbnail.webp", "label": "Thumbnail", "order": 0}, {"src": "assets/catalog/vi/l-oreal-paris-08/anh-1.webp", "label": "Ảnh 1", "order": 1}, {"src": "assets/catalog/vi/l-oreal-paris-08/anh-2.webp", "label": "Ảnh 2", "order": 2}, {"src": "assets/catalog/vi/l-oreal-paris-08/anh-3.webp", "label": "Ảnh 3", "order": 3}, {"src": "assets/catalog/vi/l-oreal-paris-08/anh-4.webp", "label": "Ảnh 4", "order": 4}, {"src": "assets/catalog/vi/l-oreal-paris-08/anh-5.webp", "label": "Ảnh 5", "order": 5}, {"src": "assets/catalog/vi/l-oreal-paris-08/anh-6.webp", "label": "Ảnh 6", "order": 6}, {"src": "assets/catalog/vi/l-oreal-paris-08/anh-7.webp", "label": "Ảnh 7", "order": 7}]}}, {"id": "l-oreal-paris-09", "brandId": "l-oreal-paris", "brand": "L'Oréal Paris", "name": {"vi": "L'ORÉAL PARIS ELSEVE EXTRAORDINARY OIL SERUM 100ML", "en": "L'Oréal Paris Elseve Extraordinary Oil Serum 100ml"}, "category": "Haircare", "type": "Serum dưỡng tóc không cần xả", "size": "100ml", "country": "Pháp", "description": {"vi": "1. MÔ TẢ SẢN PHẨM\n\nTên sản phẩm: Tinh Chất Dưỡng Tóc L'Oréal Paris Elseve Extraordinary Oil Serum 100ml\n\nThương hiệu: L'Oréal Paris\nXuất xứ thương hiệu: Pháp\nDung tích: 100ml\nPhân loại: Serum dưỡng tóc không cần xả\n\nL'Oréal Paris Elseve Extraordinary Oil Serum là tinh chất dưỡng tóc thuộc dòng Extraordinary Oil, được hãng giới thiệu với công thức chứa các loại dầu và chiết xuất hoa.\n\nSản phẩm giúp tóc trông bóng mượt, mềm mại, giảm tình trạng xù rối và dễ tạo kiểu hơn. Công thức được giới thiệu có cảm giác không bết dính, phù hợp sử dụng trên tóc ẩm hoặc tóc khô.\n\n2. CÔNG DỤNG\n\n• Hỗ trợ làm mềm và dưỡng mượt thân tóc.\n• Giúp tóc trông bóng khỏe, rạng rỡ hơn.\n• Hỗ trợ giảm tình trạng tóc xù rối.\n• Giúp tóc dễ chải và dễ tạo kiểu hơn.\n• Hỗ trợ chăm sóc tóc trước khi sấy hoặc tạo kiểu.\n• Có thể sử dụng trước khi gội hoặc làm bước dưỡng tóc qua đêm theo hướng dẫn của hãng.\n\nHãng có công bố các kết quả như tăng độ bóng và giảm xù rối cho phiên bản này. Các tỷ lệ phần trăm cụ thể chỉ nên dùng trong nội dung quảng cáo khi có đầy đủ điều kiện thử nghiệm đi kèm.\n\n3. THÀNH PHẦN\n\nCác thành phần nổi bật:\n\n• Isododecane: Dung môi nhẹ, hỗ trợ tạo cảm giác dễ tán trên tóc.\n• Caprylic/Capric Triglyceride: Thành phần làm mềm, giúp tóc có cảm giác mượt mà.\n• Dimethicone: Silicone điều hòa tóc, giúp giảm ma sát và tăng độ bóng.\n• Dimethiconol: Hỗ trợ làm mượt và giảm xù rối.\n• Chamomilla Recutita Flower Extract: Chiết xuất hoa cúc.\n• Cocos Nucifera Oil (Coconut Oil): Dầu dừa, thành phần làm mềm tóc.\n• Helianthus Annuus Seed Oil (Sunflower Seed Oil): Dầu hạt hướng dương.\n• Nelumbo Nucifera Flower Extract: Chiết xuất hoa sen.\n• Linum Usitatissimum Flower Extract: Chiết xuất hoa lanh.\n• Rosa Canina Flower Extract: Chiết xuất hoa hồng dại.\n• Tocopherol: Vitamin E, thành phần chống oxy hóa.\n• Squalane: Thành phần làm mềm.\n\nLưu ý: Công thức có chứa hương liệu và các chất tạo mùi. Thành phần được lấy từ trang Extraordinary Oil Serum 100ml, không dùng lẫn với phiên bản Extraordinary Oil 100ml có công thức khác.\n\n4. HƯỚNG DẪN SỬ DỤNG\n\nBước 1: Lấy khoảng 3–4 giọt serum ra lòng bàn tay.\nBước 2: Xoa nhẹ hai lòng bàn tay để phân bố sản phẩm.\nBước 3: Thoa đều lên thân và ngọn tóc, khi tóc còn ẩm hoặc đã khô.\nBước 4: Chải tóc và tạo kiểu như bình thường.\n\nKhông cần xả lại với nước.\n\nCác cách sử dụng được hãng giới thiệu:\n• Trước khi gội đầu để bổ sung bước dưỡng tóc.\n• Trước khi sấy để hỗ trợ chăm sóc tóc.\n• Trước khi tạo kiểu để giảm xù rối.\n• Sau khi tạo kiểu để tăng độ bóng.\n• Dùng như bước dưỡng tóc qua đêm.\n\nLưu ý:\n• Điều chỉnh lượng serum theo độ dài và độ dày của tóc.\n• Tránh thoa quá nhiều ở chân tóc nếu dễ bết.\n• Tránh tiếp xúc trực tiếp với mắt.\n• Ngừng sử dụng nếu có dấu hiệu kích ứng.\n\n5. ĐỐI TƯỢNG SỬ DỤNG\n\n• Người có mái tóc khô xơ, thiếu độ bóng.\n• Người có tóc xù rối, khó vào nếp.\n• Người có tóc thô ráp hoặc hư tổn.\n• Người muốn dưỡng tóc trước hoặc sau khi tạo kiểu.\n• Người có tóc thường, tóc khô hoặc tóc cần tăng độ mềm mượt.\n\nHãng giới thiệu sản phẩm phù hợp với nhiều loại tóc.", "en": "1. PRODUCT DESCRIPTION\n\nL'Oréal Paris Elseve Extraordinary Oil Serum is a leave-in hair treatment developed to enhance softness, smoothness and shine. Its lightweight oil-serum texture helps condition dry or rough hair lengths, reduce the appearance of frizz and improve manageability without requiring rinsing. The Extraordinary Oil range is associated with a blend of botanical flower oils and conditioning ingredients, although the precise blend varies by product version and market. It can be used before styling, after washing or on dry hair for a polished-looking finish.\n\n2. BENEFITS\n\n• Helps smooth dry and rough hair lengths.\n• Adds a healthy-looking shine.\n• Reduces the appearance of frizz and flyaways.\n• Improves hair manageability.\n• Provides leave-in conditioning care.\n• Can be used before or after styling.\n\n3. INGREDIENTS\n\nKey ingredients and their functions:\n\n• Silicone-Based Conditioning Ingredients: Help smooth hair fibers and enhance shine.\n• Botanical Flower Oil Blend: Associated with the Extraordinary Oil range; the specific oils depend on the version.\n• Emollient Ingredients: Help soften dry hair lengths.\n• Fragrance: Provides the product's characteristic scent.\n• The complete INCI should be verified against the 100ml bottle.\n\nNote: These are selected or representative ingredients and ingredient categories, not a verified complete INCI declaration. Formulas may differ by market and product generation. Confirm against the actual product packaging before publication.\n\n4. DIRECTIONS FOR USE\n\n1. Dispense one or two pumps into the palms, adjusting for hair length and thickness.\n2. Rub hands together to distribute the serum.\n3. Apply mainly to the mid-lengths and ends.\n4. Avoid excessive application near the scalp if hair becomes oily easily.\n5. Use on damp hair before styling or on dry hair to smooth flyaways.\n6. Do not rinse out.\n\nPrecautions: For external use only. Avoid direct contact with eyes. Discontinue use if irritation occurs. Follow the product label for specific warnings and application frequency.\n\n5. SUITABLE FOR\n\n• Dry or frizzy hair.\n• Dull hair lacking visible shine.\n• People seeking a leave-in smoothing product.\n• Individuals who frequently style their hair."}, "image": "assets/catalog/product-l-oreal-paris-09.webp", "gallery": {"vi": [{"src": "assets/catalog/vi/l-oreal-paris-09/thumbnail.webp", "label": "Thumbnail", "order": 0}, {"src": "assets/catalog/vi/l-oreal-paris-09/anh-1.webp", "label": "Ảnh 1", "order": 1}, {"src": "assets/catalog/vi/l-oreal-paris-09/anh-2.webp", "label": "Ảnh 2", "order": 2}, {"src": "assets/catalog/vi/l-oreal-paris-09/anh-3.webp", "label": "Ảnh 3", "order": 3}, {"src": "assets/catalog/vi/l-oreal-paris-09/anh-4.webp", "label": "Ảnh 4", "order": 4}, {"src": "assets/catalog/vi/l-oreal-paris-09/anh-5.webp", "label": "Ảnh 5", "order": 5}, {"src": "assets/catalog/vi/l-oreal-paris-09/anh-6.webp", "label": "Ảnh 6", "order": 6}, {"src": "assets/catalog/vi/l-oreal-paris-09/anh-7.webp", "label": "Ảnh 7", "order": 7}]}}, {"id": "l-oreal-paris-10", "brandId": "l-oreal-paris", "brand": "L'Oréal Paris", "name": {"vi": "L'ORÉAL PARIS ELSEVE TOTAL REPAIR 5 DEEP REPAIRING MASK 200ML", "en": "L'Oréal Paris Elseve Total Repair 5 Deep Repairing Mask 200ml"}, "category": "Haircare", "type": "Kem ủ tóc / Mặt nạ dưỡng tóc", "size": "200ml", "country": "Pháp", "description": {"vi": "1. MÔ TẢ SẢN PHẨM\n\nTên sản phẩm: Kem Ủ Giảm 5 Dấu Hiệu Tóc Hư Tổn L'Oréal Paris Elseve Total Repair 5 Deep Repairing Mask 200ml\n\nThương hiệu: L'Oréal Paris\nXuất xứ thương hiệu: Pháp\nDung tích: 200ml\nPhân loại: Kem ủ tóc / Mặt nạ dưỡng tóc\n\nL'Oréal Paris Elseve Total Repair 5 Deep Repairing Mask là kem ủ chăm sóc tóc thuộc dòng Total Repair 5, hướng đến mái tóc có dấu hiệu khô xơ và hư tổn.\n\nSản phẩm giúp bổ sung bước dưỡng sau khi gội, hỗ trợ cải thiện cảm giác mềm mại, mượt mà và vẻ ngoài chắc khỏe của tóc. Hãng giới thiệu sản phẩm nhằm chăm sóc 5 dấu hiệu tóc hư tổn gồm dễ gãy, khô, xỉn màu, thô ráp và chẻ ngọn.\n\n2. CÔNG DỤNG\n\n• Hỗ trợ chăm sóc tóc khô xơ, hư tổn.\n• Giúp tóc mềm mại và suôn mượt hơn.\n• Hỗ trợ giảm cảm giác thô ráp của sợi tóc.\n• Giúp tóc dễ chải và dễ vào nếp hơn.\n• Hỗ trợ cải thiện vẻ ngoài của tóc thiếu độ bóng.\n• Góp phần chăm sóc phần thân và ngọn tóc có dấu hiệu chẻ.\n\n3. THÀNH PHẦN\n\nCác thành phần nổi bật từ danh sách hãng công bố:\n\n• Aqua (Water): Thành phần nền của công thức.\n• Cetearyl Alcohol: Cồn béo, giúp làm mềm tóc và tạo kết cấu kem.\n• Paraffinum Liquidum (Mineral Oil): Thành phần làm mềm, hỗ trợ giảm mất ẩm trên bề mặt sợi tóc.\n• Cetyl Esters: Thành phần giúp tóc có cảm giác mềm mượt.\n• Lactic Acid: Thành phần hỗ trợ điều chỉnh công thức.\n• Arginine: Amino acid có trong công thức chăm sóc tóc.\n• Amodimethicone: Silicone điều hòa tóc, giúp làm mượt và giảm rối.\n• Citric Acid: Thành phần hỗ trợ điều chỉnh độ pH của công thức.\n\nLưu ý: Danh sách thành phần trên website hãng có thể chưa phản ánh đầy đủ công thức của mọi lô sản xuất. Cần đối chiếu với bao bì thực tế trước khi sử dụng làm danh sách INCI chính thức.\n\n4. HƯỚNG DẪN SỬ DỤNG\n\nBước 1: Gội sạch tóc bằng dầu gội phù hợp.\nBước 2: Loại bỏ bớt nước thừa trên tóc.\nBước 3: Lấy lượng kem ủ vừa đủ.\nBước 4: Vuốt đều theo chiều dài thân tóc, tập trung vào phần tóc khô xơ và ngọn tóc.\nBước 5: Tránh thoa trực tiếp lên da đầu.\nBước 6: Xả sạch lại bằng nước.\n\nTần suất sử dụng: Theo nhu cầu dưỡng tóc và hướng dẫn trên bao bì.\n\nLưu ý:\n• Không để sản phẩm tiếp xúc với mắt.\n• Nếu dính vào mắt, rửa ngay bằng nước sạch.\n• Không tự ý ủ quá lâu nếu bao bì không hướng dẫn.\n• Điều chỉnh lượng dùng theo độ dài và độ dày của tóc.\n\n5. ĐỐI TƯỢNG SỬ DỤNG\n\n• Người có mái tóc khô xơ, hư tổn.\n• Người có tóc thô ráp, thiếu mềm mại.\n• Người có tóc dễ gãy do hư tổn.\n• Người có phần ngọn tóc chẻ hoặc thiếu độ bóng.\n• Người muốn bổ sung bước dưỡng chuyên sâu sau khi gội.", "en": "1. PRODUCT DESCRIPTION\n\nL'Oréal Paris Elseve Total Repair 5 Deep Repairing Mask is an intensive rinse-off hair treatment developed for damaged-looking hair that requires additional conditioning beyond regular shampoo and conditioner. Its rich mask texture helps soften rough lengths, improve detangling and enhance the appearance of smoothness and shine. Designed to complement the Total Repair 5 range, the mask focuses on the cosmetic appearance of dryness, roughness, dullness, weakness and split ends. It is suitable for periodic use as part of a damage-care hair routine.\n\n2. BENEFITS\n\n• Provides intensive conditioning for damaged-looking hair.\n• Helps soften dry and rough hair lengths.\n• Improves detangling and manageability.\n• Supports smoother and shinier-looking hair.\n• Helps reduce the appearance of frizz.\n• Complements a regular damaged-hair care routine.\n\n3. INGREDIENTS\n\nKey ingredients and their functions:\n\n• Conditioning Agents: Help soften and detangle hair.\n• Fatty Alcohols: Support the rich mask texture.\n• Emollients: Help condition dry hair fibers.\n• Silicone-Based Ingredients: May help smooth the hair surface.\n• Total Repair 5 Complex: The exact ingredients vary by formulation and should be confirmed on the 200ml packaging.\n\nNote: These are selected or representative ingredients and ingredient categories, not a verified complete INCI declaration. Formulas may differ by market and product generation. Confirm against the actual product packaging before publication.\n\n4. DIRECTIONS FOR USE\n\n1. Shampoo the hair and rinse thoroughly.\n2. Gently squeeze out excess water.\n3. Apply a generous but appropriate amount to the mid-lengths and ends.\n4. Distribute evenly, focusing on damaged-looking areas.\n5. Leave on for the time specified on the packaging.\n6. Rinse thoroughly and style as usual.\n\nPrecautions: For external use only. Avoid direct contact with eyes. Discontinue use if irritation occurs. Follow the product label for specific warnings and application frequency.\n\n5. SUITABLE FOR\n\n• Damaged-looking hair.\n• Dry, rough or frizzy hair lengths.\n• Hair affected by frequent heat styling.\n• People seeking an intensive rinse-off conditioning treatment."}, "image": "assets/catalog/product-l-oreal-paris-10.webp", "gallery": {"vi": [{"src": "assets/catalog/vi/l-oreal-paris-10/thumbnail.webp", "label": "Thumbnail", "order": 0}, {"src": "assets/catalog/vi/l-oreal-paris-10/anh-1.webp", "label": "Ảnh 1", "order": 1}, {"src": "assets/catalog/vi/l-oreal-paris-10/anh-2.webp", "label": "Ảnh 2", "order": 2}, {"src": "assets/catalog/vi/l-oreal-paris-10/anh-3.webp", "label": "Ảnh 3", "order": 3}, {"src": "assets/catalog/vi/l-oreal-paris-10/anh-4.webp", "label": "Ảnh 4", "order": 4}, {"src": "assets/catalog/vi/l-oreal-paris-10/anh-5.webp", "label": "Ảnh 5", "order": 5}, {"src": "assets/catalog/vi/l-oreal-paris-10/anh-6.webp", "label": "Ảnh 6", "order": 6}, {"src": "assets/catalog/vi/l-oreal-paris-10/anh-7.webp", "label": "Ảnh 7", "order": 7}]}}, {"id": "usolab-01", "brandId": "usolab", "brand": "Usolab", "name": {"vi": "USOLAB BIO PREMIUM K AMPOULE 30ML", "en": "USOLAB Bio Premium K Ampoule 30ml"}, "category": "Skincare", "type": "Tinh chất dưỡng da (Ampoule)", "size": "30ml", "country": "Hàn Quốc", "description": {"vi": "1. MÔ TẢ SẢN PHẨM\n\nTên sản phẩm: Tinh chất làm dịu và phục hồi da USOLAB Bio Premium K Ampoule 30ml\nThương hiệu: USOLAB\nXuất xứ thương hiệu: Hàn Quốc\nDung tích: 30ml\nPhân loại: Tinh chất dưỡng da (Ampoule)\n\nUSOLAB Bio Premium K Ampoule là tinh chất chăm sóc da thuộc dòng K Line, hướng đến làn da nhạy cảm, dễ ửng đỏ và có hàng rào bảo vệ suy yếu. Công thức kết hợp các dẫn xuất Vitamin K cùng chiết xuất rau má, Panthenol và Niacinamide, hỗ trợ làm dịu, dưỡng ẩm và cải thiện vẻ ngoài của làn da.\n\nSản phẩm có kết cấu tinh chất dễ tán, phù hợp bổ sung vào quy trình chăm sóc da hằng ngày, đặc biệt khi da cần được làm dịu và phục hồi độ ẩm.\n\n2. CÔNG DỤNG\n\n• Hỗ trợ làm dịu làn da có biểu hiện ửng đỏ, khó chịu.\n• Cung cấp độ ẩm, giảm cảm giác khô căng.\n• Hỗ trợ củng cố hàng rào bảo vệ da.\n• Giúp cải thiện vẻ ngoài của da không đều màu và thâm đỏ.\n• Hỗ trợ duy trì làn da mềm mại, mịn màng.\n• Bổ sung bước chăm sóc cho da nhạy cảm hoặc da đang trong giai đoạn phục hồi.\n\n3. THÀNH PHẦN\n\nCác thành phần nổi bật được USOLAB Việt Nam giới thiệu:\n\n• Menadione và Phytonadione Epoxide: Các hợp chất liên quan đến Vitamin K, được hãng sử dụng trong dòng chăm sóc da dễ ửng đỏ.\n• Centella Asiatica Extract (chiết xuất rau má): Hỗ trợ làm dịu và chăm sóc hàng rào bảo vệ da.\n• Panthenol (Pro-vitamin B5): Hỗ trợ giữ ẩm, giảm cảm giác khô căng.\n• Glycyrrhiza Glabra Root Extract (chiết xuất rễ cam thảo): Hỗ trợ làm dịu và dưỡng sáng.\n• Niacinamide (Vitamin B3): Hỗ trợ cải thiện vẻ ngoài của da không đều màu.\n• Glutathione: Thành phần chống oxy hóa được hãng giới thiệu trong công thức.\n\nĐây là các thành phần nổi bật, không phải danh sách INCI đầy đủ. Cần đối chiếu bao bì thực tế trước khi công bố toàn bộ thành phần.\n\n4. HƯỚNG DẪN SỬ DỤNG\n\nBước 1: Làm sạch da mặt bằng sản phẩm phù hợp.\nBước 2: Sử dụng toner nếu có trong quy trình dưỡng da.\nBước 3: Lấy khoảng 2–3 giọt tinh chất, thoa đều lên da.\nBước 4: Vỗ nhẹ để sản phẩm phân bố trên da, sau đó dùng kem dưỡng nếu cần.\n\nLưu ý:\n• Chỉ sử dụng ngoài da.\n• Tránh tiếp xúc trực tiếp với mắt.\n• Với da vừa thực hiện thủ thuật thẩm mỹ, cần tuân thủ hướng dẫn của người thực hiện thủ thuật trước khi dùng.\n• Bảo quản tránh ánh nắng trực tiếp và để xa tầm tay trẻ em.\n\n5. ĐỐI TƯỢNG SỬ DỤNG\n\n• Người có làn da nhạy cảm, dễ ửng đỏ.\n• Người có da khô căng, hàng rào bảo vệ da suy yếu.\n• Người có nhu cầu chăm sóc da sau các tác động từ môi trường.\n• Người muốn bổ sung tinh chất làm dịu và dưỡng ẩm.\n• Người có nhu cầu chăm sóc da sau thủ thuật khi được chuyên gia cho phép.", "en": "1. PRODUCT DESCRIPTION\n\nUSOLAB Bio Premium K Ampoule is a concentrated facial skincare product intended for skin that needs additional soothing and conditioning care. Its ampoule format is suitable for targeted application when the complexion appears stressed, dry or uncomfortable. The product can be incorporated into a gentle moisturizing routine to support a smoother and more comfortable skin feel. The exact active ingredients and their concentrations should be confirmed against the product packaging before making specific formula claims.\n\n2. BENEFITS\n\n• Supports a more comfortable skin feel.\n• Provides targeted skin-conditioning care.\n• Helps improve the appearance of dryness-related discomfort.\n• Complements a gentle moisturizing routine.\n• Suitable for use before facial moisturizer.\n\n3. INGREDIENTS\n\nKey ingredient categories and their functions:\n\n• K Complex: The exact identity and concentration of the product's signature K ingredients require label verification.\n• Humectants: Help attract moisture to the skin; confirm the specific ingredients on the label.\n• Skin-Conditioning Agents: Support a smoother skin feel.\n• The complete INCI list must be verified against the 30ml packaging.\n\nNote: Ingredient information is provisional and does not constitute a verified INCI declaration. Confirm the actual ingredients, concentrations and claims against the product packaging or official manufacturer documentation before publication.\n\n4. DIRECTIONS FOR USE\n\n1. Cleanse the face and pat dry.\n2. Apply toner if desired.\n3. Dispense an appropriate amount of ampoule.\n4. Spread gently across the face, avoiding the eyes.\n5. Allow to absorb before applying moisturizer.\n6. Use according to the product label and individual skin tolerance.\n\nPrecautions: For external use only. Avoid direct contact with eyes unless specifically intended for the eye area. Discontinue use if irritation occurs. Follow all warnings on the product label.\n\n5. SUITABLE FOR\n\n• Skin requiring gentle conditioning.\n• Dry or uncomfortable-feeling skin.\n• People seeking a targeted facial ampoule.\n• Individuals following a soothing skincare routine."}, "image": "assets/catalog/product-usolab-01.png", "gallery": {"vi": [{"src": "assets/catalog/vi/usolab-01/thumbnail.webp", "label": "Thumbnail", "order": 0}, {"src": "assets/catalog/vi/usolab-01/anh-1.webp", "label": "Ảnh 1", "order": 1}, {"src": "assets/catalog/vi/usolab-01/anh-1-ban-2.webp", "label": "Ảnh 1 (bản 2)", "order": 1}, {"src": "assets/catalog/vi/usolab-01/anh-2.webp", "label": "Ảnh 2", "order": 2}, {"src": "assets/catalog/vi/usolab-01/anh-3.webp", "label": "Ảnh 3", "order": 3}, {"src": "assets/catalog/vi/usolab-01/anh-5.webp", "label": "Ảnh 5", "order": 5}, {"src": "assets/catalog/vi/usolab-01/anh-6.webp", "label": "Ảnh 6", "order": 6}, {"src": "assets/catalog/vi/usolab-01/anh-7.webp", "label": "Ảnh 7", "order": 7}]}}, {"id": "usolab-02", "brandId": "usolab", "brand": "Usolab", "name": {"vi": "USOLAB BIO INTENSIVE K CREAM 50ML", "en": "USOLAB Bio Intensive K Cream 50ml"}, "category": "Skincare", "type": "Kem dưỡng phục hồi và làm dịu da", "size": "50ml", "country": "Hàn Quốc", "description": {"vi": "1. MÔ TẢ SẢN PHẨM\n\nTên sản phẩm: Kem dưỡng làm dịu và phục hồi da USOLAB Bio Intensive K Cream 50ml\nThương hiệu: USOLAB\nXuất xứ thương hiệu: Hàn Quốc\nDung tích: 50ml\nPhân loại: Kem dưỡng phục hồi và làm dịu da\n\nUSOLAB Bio Intensive K Cream là kem dưỡng thuộc dòng K Line, hướng đến việc chăm sóc làn da nhạy cảm, dễ ửng đỏ và cần tăng cường hàng rào giữ ẩm.\n\nTheo thông tin từ USOLAB Việt Nam, phiên bản nâng cấp năm 2026 có công thức cải tiến với các thành phần liên quan đến Vitamin K, peptide, Ceramide và các chất dưỡng da. Phiên bản 50ml được giới thiệu với thiết kế chai pump mới, giúp lấy sản phẩm thuận tiện và vệ sinh hơn.\n\n2. CÔNG DỤNG\n\n• Hỗ trợ làm dịu da dễ ửng đỏ, khó chịu.\n• Cung cấp độ ẩm, giảm tình trạng khô căng.\n• Hỗ trợ củng cố hàng rào bảo vệ da và hạn chế mất nước.\n• Giúp da trông mềm mại, mịn màng hơn.\n• Hỗ trợ cải thiện vẻ ngoài của các vùng thâm đỏ.\n• Bổ sung bước dưỡng cho làn da nhạy cảm hoặc đang trong quá trình phục hồi.\n\n3. THÀNH PHẦN\n\nCác thành phần nổi bật được giới thiệu cho phiên bản mới:\n\n• Vitamin K và các hợp chất liên quan: Thành phần đặc trưng của dòng K Line.\n• Phức hợp peptide, bao gồm các peptide được hãng giới thiệu như GHK-Cu: Hỗ trợ chăm sóc da có dấu hiệu suy yếu.\n• Ceramide: Thành phần lipid giúp củng cố hàng rào bảo vệ da và hạn chế mất nước.\n• Glutathione: Hỗ trợ chống oxy hóa.\n• Hydrolyzed Pea Protein: Protein đậu Hà Lan thủy phân, hỗ trợ dưỡng ẩm và làm mềm da.\n• Centella Asiatica Extract: Chiết xuất rau má, hỗ trợ làm dịu.\n• Panthenol: Hỗ trợ dưỡng ẩm và chăm sóc da nhạy cảm.\n\nLưu ý: USOLAB đã thông báo nâng cấp công thức và bao bì của Bio Intensive K Cream trong năm 2026. Cần kiểm tra đúng phiên bản sản phẩm trước khi sử dụng danh sách INCI chi tiết.\n\n4. HƯỚNG DẪN SỬ DỤNG\n\nBước 1: Làm sạch da mặt.\nBước 2: Sử dụng toner và tinh chất nếu có.\nBước 3: Lấy lượng kem vừa đủ, thoa nhẹ lên mặt hoặc vùng da cần chăm sóc.\nBước 4: Tán đều để kem phân bố trên da.\n\nTần suất sử dụng: Buổi sáng và buổi tối.\n\nCó thể sử dụng trước bước trang điểm.\n\nLưu ý:\n• Chỉ dùng ngoài da, tránh tiếp xúc với mắt.\n• Không tự ý thoa lên vết thương hở hoặc vùng da mới thực hiện thủ thuật khi chưa được chuyên gia cho phép.\n• Ngừng dùng nếu xuất hiện kích ứng kéo dài.\n• Kiểm tra bao bì mới hoặc cũ để đối chiếu đúng công thức.\n\n5. ĐỐI TƯỢNG SỬ DỤNG\n\n• Người có da nhạy cảm, dễ ửng đỏ.\n• Người có làn da khô, thiếu ẩm.\n• Người có hàng rào bảo vệ da suy yếu.\n• Người cần sản phẩm dưỡng làm dịu trong quy trình chăm sóc da.\n• Người chăm sóc da sau thủ thuật theo hướng dẫn của chuyên gia.", "en": "1. PRODUCT DESCRIPTION\n\nUSOLAB Bio Intensive K Cream is a facial moisturizer developed for skin requiring intensive conditioning and comfort. Its cream texture is intended to help soften dry areas and reduce the feeling of tightness associated with moisture loss. It can be used after a facial ampoule to complete a gentle skincare routine. The product name indicates a K-focused formulation, but the exact ingredients and specific effects must be verified against the manufacturer's current information.\n\n2. BENEFITS\n\n• Provides moisturizing and conditioning care.\n• Helps soften dry-feeling skin.\n• Supports a comfortable skin feel.\n• Helps reduce moisture-related tightness.\n• Complements the Bio Premium K skincare routine.\n\n3. INGREDIENTS\n\nKey ingredient categories and their functions:\n\n• Signature K Ingredients: Specific composition requires confirmation from the actual label.\n• Moisturizing Agents: Support skin hydration.\n• Emollients: Help soften the skin and reduce dryness-related roughness.\n• Texture-Stabilizing Ingredients: Support the cream consistency.\n• Exact INCI and active percentages require packaging verification.\n\nNote: Ingredient information is provisional and does not constitute a verified INCI declaration. Confirm the actual ingredients, concentrations and claims against the product packaging or official manufacturer documentation before publication.\n\n4. DIRECTIONS FOR USE\n\n1. Cleanse the face and apply any suitable toner or ampoule.\n2. Take a small amount of cream.\n3. Spread evenly across the face and neck.\n4. Massage gently until absorbed.\n5. Use morning or evening as directed.\n6. Apply sunscreen during the day.\n\nPrecautions: For external use only. Avoid direct contact with eyes unless specifically intended for the eye area. Discontinue use if irritation occurs. Follow all warnings on the product label.\n\n5. SUITABLE FOR\n\n• Dry or uncomfortable-feeling skin.\n• People seeking a richer moisturizing step.\n• Skin needing additional daily conditioning.\n• Individuals using the USOLAB Bio K range."}, "image": "assets/catalog/product-usolab-02.png", "gallery": {"vi": [{"src": "assets/catalog/vi/usolab-02/thumbnail.webp", "label": "Thumbnail", "order": 0}, {"src": "assets/catalog/vi/usolab-02/anh-1.webp", "label": "Ảnh 1", "order": 1}, {"src": "assets/catalog/vi/usolab-02/anh-2.webp", "label": "Ảnh 2", "order": 2}, {"src": "assets/catalog/vi/usolab-02/anh-3.webp", "label": "Ảnh 3", "order": 3}, {"src": "assets/catalog/vi/usolab-02/anh-4.webp", "label": "Ảnh 4", "order": 4}, {"src": "assets/catalog/vi/usolab-02/anh-5.webp", "label": "Ảnh 5", "order": 5}, {"src": "assets/catalog/vi/usolab-02/anh-6.webp", "label": "Ảnh 6", "order": 6}, {"src": "assets/catalog/vi/usolab-02/anh-7.webp", "label": "Ảnh 7", "order": 7}]}}, {"id": "usolab-03", "brandId": "usolab", "brand": "Usolab", "name": {"vi": "USOLAB BIO MOISTURIZING HYALURON AMPOULE 50ML", "en": "USOLAB Bio Moisturizing Hyaluron Ampoule 50ml"}, "category": "Skincare", "type": "Tinh chất cấp ẩm (Ampoule)", "size": "50ml", "country": "Hàn Quốc", "description": {"vi": "1. MÔ TẢ SẢN PHẨM\n\nTên sản phẩm: Tinh chất cấp ẩm HA USOLAB Bio Moisturizing Hyaluron Ampoule 50ml\nThương hiệu: USOLAB\nXuất xứ thương hiệu: Hàn Quốc\nDung tích: 50ml\nPhân loại: Tinh chất cấp ẩm (Ampoule)\n\nUSOLAB Bio Moisturizing Hyaluron Ampoule là tinh chất dưỡng ẩm với công thức kết hợp nhiều dạng Hyaluronic Acid, Guaiazulene, Panthenol và phức hợp peptide.\n\nSản phẩm hướng đến nhu cầu bổ sung độ ẩm, giúp làn da mềm mại, căng mượt và hạn chế cảm giác khô căng. Kết cấu tinh chất được hãng giới thiệu là mỏng nhẹ, dễ sử dụng trong quy trình dưỡng da hằng ngày.\n\n2. CÔNG DỤNG\n\n• Cung cấp độ ẩm, giúp da căng mọng và mềm mại hơn.\n• Hỗ trợ duy trì độ ẩm và giảm cảm giác khô căng.\n• Giúp cải thiện vẻ ngoài của các nếp nhăn nhỏ do thiếu ẩm.\n• Hỗ trợ làm dịu làn da nhạy cảm.\n• Hỗ trợ củng cố hàng rào giữ ẩm tự nhiên.\n• Giúp da trông mịn màng và có sức sống hơn.\n\n3. THÀNH PHẦN\n\nCác thành phần nổi bật:\n\n• Sodium Hyaluronate: Dạng muối của Hyaluronic Acid, giúp hút và giữ ẩm.\n• Hydrolyzed Hyaluronic Acid: Hyaluronic Acid thủy phân, hỗ trợ cấp ẩm.\n• Hydrolyzed Sodium Hyaluronate: Dạng HA thủy phân, góp phần cải thiện độ ẩm của da.\n• Sodium Hyaluronate Crosspolymer: HA liên kết chéo, hỗ trợ duy trì độ ẩm trên bề mặt.\n• Guaiazulene: Thành phần hỗ trợ làm dịu da.\n• Panthenol (Vitamin B5): Giúp dưỡng ẩm và chăm sóc hàng rào bảo vệ da.\n• Phức hợp 31 peptide: Nhóm thành phần được hãng giới thiệu trong công thức dưỡng da.\n\nĐây là danh sách thành phần nổi bật, chưa phải INCI đầy đủ của sản phẩm.\n\n4. HƯỚNG DẪN SỬ DỤNG\n\nBước 1: Làm sạch da mặt.\nBước 2: Lấy lượng tinh chất vừa đủ.\nBước 3: Thoa đều lên mặt, vỗ nhẹ để sản phẩm phân bố trên da.\nBước 4: Tiếp tục với kem dưỡng để duy trì độ ẩm.\n\nTần suất sử dụng: Buổi sáng và buổi tối.\n\nCó thể dùng trước khi trang điểm như một bước cấp ẩm.\n\nLưu ý:\n• Chỉ dùng ngoài da.\n• Tránh tiếp xúc trực tiếp với mắt.\n• Bảo quản nơi khô ráo, tránh ánh nắng trực tiếp.\n• Ngừng sử dụng nếu xuất hiện kích ứng.\n\n5. ĐỐI TƯỢNG SỬ DỤNG\n\n• Người có làn da khô, thiếu nước.\n• Người có da căng rát do thiếu ẩm.\n• Người có các nếp nhăn nhỏ do da thiếu ẩm.\n• Người muốn cải thiện độ mềm mại và căng mượt.\n• Người có da thường, da hỗn hợp hoặc da nhạy cảm cần cấp ẩm.", "en": "1. PRODUCT DESCRIPTION\n\nUSOLAB Bio Moisturizing Hyaluron Ampoule is a facial treatment designed to support hydration and improve the appearance of dehydrated skin. The product's hyaluron-focused concept centers on moisture retention and a plumper-looking complexion. Its ampoule format allows it to be layered beneath a facial cream to help reduce the feeling of dryness and tightness. The specific forms of hyaluronic acid, other supporting ingredients and their concentrations should be checked against the product's INCI declaration.\n\n2. BENEFITS\n\n• Helps replenish skin moisture.\n• Supports a plumper-looking complexion.\n• Helps soften the appearance of fine dehydration lines.\n• Reduces the feeling of dryness-related tightness.\n• Provides a hydrating step before moisturizer.\n\n3. INGREDIENTS\n\nKey ingredient categories and their functions:\n\n• Hyaluronic Acid or Hyaluronate Derivatives: Moisture-binding ingredients associated with the product's hyaluron concept; verify exact INCI names.\n• Humectants: Support hydration.\n• Skin-Conditioning Ingredients: Help maintain a comfortable feel.\n• Exact supporting ingredients and concentrations require label verification.\n\nNote: Ingredient information is provisional and does not constitute a verified INCI declaration. Confirm the actual ingredients, concentrations and claims against the product packaging or official manufacturer documentation before publication.\n\n4. DIRECTIONS FOR USE\n\n1. Cleanse the face and apply toner if desired.\n2. Apply an appropriate amount of ampoule.\n3. Distribute gently over the face and neck.\n4. Pat until absorbed.\n5. Follow with a moisturizing cream.\n6. Use morning and evening as tolerated.\n\nPrecautions: For external use only. Avoid direct contact with eyes unless specifically intended for the eye area. Discontinue use if irritation occurs. Follow all warnings on the product label.\n\n5. SUITABLE FOR\n\n• Dry and dehydrated skin.\n• People concerned about moisture-related tightness.\n• Individuals seeking a hydrating ampoule.\n• Skin with visible fine lines caused by dehydration."}, "image": "assets/catalog/product-usolab-03.jpg", "gallery": {"vi": [{"src": "assets/catalog/vi/usolab-03/thumbnail.webp", "label": "Thumbnail", "order": 0}, {"src": "assets/catalog/vi/usolab-03/anh-1.webp", "label": "Ảnh 1", "order": 1}, {"src": "assets/catalog/vi/usolab-03/anh-2.webp", "label": "Ảnh 2", "order": 2}, {"src": "assets/catalog/vi/usolab-03/anh-3.webp", "label": "Ảnh 3", "order": 3}, {"src": "assets/catalog/vi/usolab-03/anh-4.webp", "label": "Ảnh 4", "order": 4}, {"src": "assets/catalog/vi/usolab-03/anh-5.webp", "label": "Ảnh 5", "order": 5}, {"src": "assets/catalog/vi/usolab-03/anh-6.webp", "label": "Ảnh 6", "order": 6}, {"src": "assets/catalog/vi/usolab-03/anh-7.webp", "label": "Ảnh 7", "order": 7}]}}, {"id": "usolab-04", "brandId": "usolab", "brand": "Usolab", "name": {"vi": "USOLAB BIO INTENSIVE HYALURON CREAM 50ML", "en": "USOLAB Bio Intensive Hyaluron Cream 50ml"}, "category": "Skincare", "type": "Kem dưỡng ẩm, khóa ẩm", "size": "50ml", "country": "Hàn Quốc", "description": {"vi": "1. MÔ TẢ SẢN PHẨM\n\nTên sản phẩm: Kem dưỡng khóa ẩm USOLAB Bio Intensive Hyaluron Cream 50ml\nThương hiệu: USOLAB\nXuất xứ thương hiệu: Hàn Quốc\nDung tích: 50ml\nPhân loại: Kem dưỡng ẩm, khóa ẩm\n\nUSOLAB Bio Intensive Hyaluron Cream là kem dưỡng ẩm thuộc dòng Hyaluron, được phát triển nhằm hỗ trợ chăm sóc làn da khô, rất khô và thiếu ẩm.\n\nCông thức nổi bật với Hyaluronic Acid ở nhiều dạng cùng peptide và Vitamin B5, giúp duy trì độ ẩm, cải thiện cảm giác khô căng và hỗ trợ củng cố hàng rào bảo vệ da. Sản phẩm có thể dùng trong quy trình dưỡng da mặt và chăm sóc các vùng da cơ thể cần bổ sung độ ẩm.\n\n2. CÔNG DỤNG\n\n• Bổ sung và duy trì độ ẩm cho da.\n• Hỗ trợ giảm cảm giác khô căng, bong tróc do thiếu ẩm.\n• Giúp da mềm mại, mịn màng hơn.\n• Hỗ trợ củng cố hàng rào giữ ẩm tự nhiên.\n• Cải thiện vẻ ngoài của làn da sần sùi do khô.\n• Giúp làn da trông căng mượt và khỏe khoắn hơn.\n\n3. THÀNH PHẦN\n\nCác thành phần nổi bật được hãng giới thiệu:\n\n• Sodium Hyaluronate: Hỗ trợ hút và giữ nước trên bề mặt da.\n• Hydrolyzed Hyaluronic Acid: Hyaluronic Acid thủy phân, hỗ trợ dưỡng ẩm.\n• HA liên kết chéo: Hỗ trợ duy trì độ ẩm và tạo cảm giác căng mượt.\n• GHK-Cu: Peptide đồng được hãng giới thiệu trong công thức chăm sóc da.\n• Vitamin B5 (Panthenol): Hỗ trợ làm dịu và duy trì độ ẩm.\n\nLưu ý: Các thành phần trên là thành phần nổi bật từ trang USOLAB Việt Nam, chưa phải danh sách INCI đầy đủ.\n\n4. HƯỚNG DẪN SỬ DỤNG\n\nBước 1: Làm sạch vùng da cần dưỡng.\nBước 2: Sử dụng serum hoặc tinh chất nếu có.\nBước 3: Lấy lượng kem vừa đủ, thoa đều lên da.\nBước 4: Vỗ nhẹ hoặc massage nhẹ nhàng để kem trải đều.\n\nCó thể sử dụng vào buổi sáng và buổi tối tùy nhu cầu dưỡng ẩm.\n\nLưu ý:\n• Chỉ sử dụng ngoài da.\n• Tránh tiếp xúc với mắt.\n• Ban ngày nên kết hợp kem chống nắng phù hợp.\n• Bảo quản nơi khô ráo, thoáng mát, tránh ánh nắng trực tiếp.\n\n5. ĐỐI TƯỢNG SỬ DỤNG\n\n• Người có da khô hoặc rất khô.\n• Người có làn da thiếu ẩm, dễ bong tróc.\n• Người có da sần sùi do khô.\n• Người muốn bổ sung kem dưỡng khóa ẩm.\n• Người có làn da nhạy cảm cần chăm sóc độ ẩm, sau khi kiểm tra khả năng dung nạp.", "en": "1. PRODUCT DESCRIPTION\n\nUSOLAB Bio Intensive Hyaluron Cream is a moisturizing facial cream intended to support hydration and help maintain soft, supple skin. Its hyaluron-focused formulation is designed for people who experience dryness, roughness or tightness associated with moisture loss. Applied after cleansing and serum, the cream helps complete a daily skincare routine by providing a conditioning layer over the skin. Exact hyaluronic acid derivatives and additional active ingredients must be confirmed from the current product packaging.\n\n2. BENEFITS\n\n• Provides intensive moisturizing care.\n• Helps maintain soft and supple skin.\n• Supports the skin's moisture barrier.\n• Reduces the feeling of dryness-related tightness.\n• Complements a hyaluron-focused skincare routine.\n\n3. INGREDIENTS\n\nKey ingredient categories and their functions:\n\n• Hyaluronic Acid-Related Ingredients: Support moisture retention; exact forms require verification.\n• Emollients: Help soften and condition the skin.\n• Humectants: Attract and retain moisture.\n• Cream-Forming Ingredients: Support a smooth application texture.\n• Complete INCI information should be checked against the label.\n\nNote: Ingredient information is provisional and does not constitute a verified INCI declaration. Confirm the actual ingredients, concentrations and claims against the product packaging or official manufacturer documentation before publication.\n\n4. DIRECTIONS FOR USE\n\n1. Cleanse and tone the face.\n2. Apply any hydrating ampoule or serum.\n3. Take a suitable amount of cream.\n4. Spread evenly across the face and neck.\n5. Massage gently until absorbed.\n6. Use morning and evening, with sunscreen during the day.\n\nPrecautions: For external use only. Avoid direct contact with eyes unless specifically intended for the eye area. Discontinue use if irritation occurs. Follow all warnings on the product label.\n\n5. SUITABLE FOR\n\n• Dry or dehydrated skin.\n• People seeking intensive facial hydration.\n• Skin that feels tight after cleansing.\n• Individuals using USOLAB Hyaluron skincare products."}, "image": "assets/catalog/product-usolab-04.jpg", "gallery": {"vi": [{"src": "assets/catalog/vi/usolab-04/thumbnail.webp", "label": "Thumbnail", "order": 0}, {"src": "assets/catalog/vi/usolab-04/anh-1.webp", "label": "Ảnh 1", "order": 1}, {"src": "assets/catalog/vi/usolab-04/anh-2.webp", "label": "Ảnh 2", "order": 2}, {"src": "assets/catalog/vi/usolab-04/anh-3.webp", "label": "Ảnh 3", "order": 3}, {"src": "assets/catalog/vi/usolab-04/anh-4.webp", "label": "Ảnh 4", "order": 4}, {"src": "assets/catalog/vi/usolab-04/anh-5.webp", "label": "Ảnh 5", "order": 5}, {"src": "assets/catalog/vi/usolab-04/anh-6.webp", "label": "Ảnh 6", "order": 6}, {"src": "assets/catalog/vi/usolab-04/anh-7.webp", "label": "Ảnh 7", "order": 7}]}}, {"id": "usolab-05", "brandId": "usolab", "brand": "Usolab", "name": {"vi": "USOLAB BIO RENATURATION REPAIR AMPOULE 50ML", "en": "USOLAB Bio Renaturation Repair Ampoule 50ml"}, "category": "Skincare", "type": "Tinh chất chăm sóc da (Ampoule)", "size": "50ml", "country": "Hàn Quốc", "description": {"vi": "1. MÔ TẢ SẢN PHẨM\n\nTên sản phẩm: Tinh chất dưỡng phục hồi da USOLAB Bio Renaturation Repair Ampoule 50ml\nThương hiệu: USOLAB\nXuất xứ thương hiệu: Hàn Quốc\nDung tích: 50ml\nPhân loại: Tinh chất chăm sóc da (Ampoule)\n\nUSOLAB Bio Renaturation Repair Ampoule là tinh chất chăm sóc da thuộc dòng Repair, được giới thiệu với công thức kết hợp PDRN có nguồn gốc từ cá hồi, chiết xuất nấm tuyết, peptide và các thành phần dưỡng ẩm.\n\nSản phẩm hướng đến làn da khô, nhạy cảm và có dấu hiệu lão hóa, giúp bổ sung độ ẩm, hỗ trợ chăm sóc hàng rào bảo vệ da và cải thiện vẻ ngoài của làn da kém mịn màng.\n\n2. CÔNG DỤNG\n\n• Hỗ trợ dưỡng ẩm và giảm tình trạng khô căng.\n• Giúp da trông căng mượt, mềm mại hơn.\n• Hỗ trợ cải thiện vẻ ngoài của làn da xỉn màu.\n• Bổ sung thành phần chống oxy hóa trong quy trình dưỡng da.\n• Hỗ trợ chăm sóc da có dấu hiệu lão hóa.\n• Giúp cải thiện cảm giác mịn màng và vẻ ngoài khỏe khoắn của da.\n\n3. THÀNH PHẦN\n\nCác thành phần nổi bật được USOLAB Việt Nam giới thiệu:\n\n• Chiết xuất nấm tuyết trắng 10%: Thành phần hỗ trợ giữ ẩm và làm mềm da.\n• PDRN 30.000 ppm: Thành phần có nguồn gốc từ cá hồi được hãng giới thiệu trong công thức.\n• Phức hợp 31 peptide: Bao gồm các peptide được hãng nhắc đến như GHK-Cu.\n• Niacinamide (Vitamin B3): Hỗ trợ dưỡng sáng và cải thiện vẻ ngoài của da không đều màu.\n• Lactobacillus: Thành phần liên quan đến công nghệ lên men được giới thiệu trong công thức.\n• Adenosine: Thành phần thường dùng trong sản phẩm chăm sóc da có dấu hiệu lão hóa.\n• Glutathione: Hỗ trợ chống oxy hóa.\n• Panthenol: Hỗ trợ dưỡng ẩm và làm dịu da.\n\nLưu ý: Cách gọi “tế bào gốc cá hồi” xuất hiện trong nội dung tiếp thị của hãng, nhưng không nên hiểu rằng sản phẩm chứa tế bào gốc sống. Danh sách trên là thành phần nổi bật, không phải INCI đầy đủ.\n\n4. HƯỚNG DẪN SỬ DỤNG\n\nBước 1: Làm sạch da mặt.\nBước 2: Lấy lượng tinh chất vừa đủ.\nBước 3: Thoa nhẹ lên da mặt và vùng cổ.\nBước 4: Tiếp tục với kem dưỡng nếu cần.\n\nTần suất sử dụng: Hằng ngày, vào buổi sáng và buổi tối.\n\nLưu ý:\n• Chỉ sử dụng ngoài da.\n• Tránh tiếp xúc trực tiếp với mắt.\n• Không tự ý sử dụng trên vùng da đang có vết thương hở.\n• Với da đang kích ứng nặng hoặc sau thủ thuật, cần tham khảo chuyên gia trước khi dùng.\n• Bảo quản nơi khô ráo, thoáng mát, tránh ánh nắng trực tiếp.\n\n5. ĐỐI TƯỢNG SỬ DỤNG\n\n• Người có làn da khô, thiếu ẩm.\n• Người có da nhạy cảm cần chăm sóc nhẹ nhàng.\n• Người có làn da kém mịn màng, thiếu sức sống.\n• Người quan tâm đến các dấu hiệu lão hóa da.\n• Người muốn bổ sung tinh chất dưỡng ẩm và chăm sóc da trong quy trình hằng ngày.", "en": "1. PRODUCT DESCRIPTION\n\nUSOLAB Bio Renaturation Repair Ampoule is a concentrated skincare treatment intended to condition skin affected by dryness and environmental stress. Its repair-focused positioning makes it suitable for a routine designed to support the appearance and comfort of the skin's moisture barrier. The ampoule can be applied before moisturizer to help maintain a smoother, softer-looking complexion. It is a cosmetic skincare product and should not be described as treating wounds, burns or dermatological conditions.\n\n2. BENEFITS\n\n• Supports skin-conditioning care.\n• Helps improve the appearance of dry and stressed skin.\n• Promotes a softer and smoother skin feel.\n• Complements moisture-barrier-focused routines.\n• Provides an additional step before moisturizing cream.\n\n3. INGREDIENTS\n\nKey ingredient categories and their functions:\n\n• Repair-Focused Skin-Conditioning Complex: Exact components require label verification.\n• Humectants: Help maintain moisture.\n• Emollient or Barrier-Supporting Ingredients: Depend on the current formulation.\n• The complete INCI and active percentages must be confirmed from the actual packaging.\n\nNote: Ingredient information is provisional and does not constitute a verified INCI declaration. Confirm the actual ingredients, concentrations and claims against the product packaging or official manufacturer documentation before publication.\n\n4. DIRECTIONS FOR USE\n\n1. Cleanse the face gently.\n2. Apply toner if included in the routine.\n3. Dispense a suitable amount of ampoule.\n4. Spread evenly without rubbing aggressively.\n5. Follow with a suitable moisturizing cream.\n6. Avoid applying to open or actively irritated wounds unless specifically directed by a healthcare professional.\n\nPrecautions: For external use only. Avoid direct contact with eyes unless specifically intended for the eye area. Discontinue use if irritation occurs. Follow all warnings on the product label.\n\n5. SUITABLE FOR\n\n• Dry and stressed-looking skin.\n• People seeking moisture-barrier support.\n• Skin requiring additional cosmetic conditioning.\n• Individuals following a gentle repair-focused routine."}, "image": "assets/catalog/product-usolab-05.jpg", "gallery": {"vi": [{"src": "assets/catalog/vi/usolab-05/thumbnail.webp", "label": "Thumbnail", "order": 0}, {"src": "assets/catalog/vi/usolab-05/anh-1.webp", "label": "Ảnh 1", "order": 1}, {"src": "assets/catalog/vi/usolab-05/anh-2.webp", "label": "Ảnh 2", "order": 2}, {"src": "assets/catalog/vi/usolab-05/anh-3.webp", "label": "Ảnh 3", "order": 3}, {"src": "assets/catalog/vi/usolab-05/anh-4.webp", "label": "Ảnh 4", "order": 4}, {"src": "assets/catalog/vi/usolab-05/anh-5.webp", "label": "Ảnh 5", "order": 5}, {"src": "assets/catalog/vi/usolab-05/anh-6.webp", "label": "Ảnh 6", "order": 6}, {"src": "assets/catalog/vi/usolab-05/anh-7.webp", "label": "Ảnh 7", "order": 7}]}}, {"id": "usolab-06", "brandId": "usolab", "brand": "Usolab", "name": {"vi": "USOLAB BIO RENATURATION REPAIR CREAM 50ML", "en": "USOLAB Bio Renaturation Repair Cream 50ml"}, "category": "Skincare", "type": "Kem dưỡng ẩm và chăm sóc da", "size": "50ml", "country": "Hàn Quốc", "description": {"vi": "1. MÔ TẢ SẢN PHẨM\n\nTên sản phẩm: Kem dưỡng phục hồi da USOLAB Bio Renaturation Repair Cream 50ml\nThương hiệu: USOLAB\nXuất xứ thương hiệu: Hàn Quốc\nDung tích: 50ml\nPhân loại: Kem dưỡng ẩm và chăm sóc da\n\nUSOLAB Bio Renaturation Repair Cream là kem dưỡng thuộc dòng Repair, hướng đến làn da khô, nhạy cảm và có dấu hiệu lão hóa. Sản phẩm được giới thiệu với công thức kết hợp Sodium DNA, chiết xuất nấm tuyết, peptide và các thành phần dưỡng da, giúp bổ sung độ ẩm và cải thiện vẻ ngoài của da.\n\n2. CÔNG DỤNG\n\n• Cung cấp độ ẩm, giảm cảm giác khô căng.\n• Hỗ trợ chăm sóc hàng rào giữ ẩm của da.\n• Giúp da mềm mại và mịn màng hơn.\n• Hỗ trợ làm dịu da khô, dễ khó chịu.\n• Giúp cải thiện vẻ ngoài của làn da thiếu sức sống.\n• Hỗ trợ chăm sóc da có dấu hiệu lão hóa.\n\n3. THÀNH PHẦN\n\nCác thành phần nổi bật theo USOLAB Việt Nam:\n\n• Tremella Fuciformis Extract: Chiết xuất nấm tuyết, hỗ trợ giữ ẩm.\n• Sodium DNA (PDRN): Thành phần được hãng giới thiệu trong dòng chăm sóc da Repair.\n• Propolis Extract: Chiết xuất keo ong, hỗ trợ chăm sóc da.\n• Peptide Complex 36: Phức hợp peptide được hãng giới thiệu trong công thức.\n• Panthenol (Vitamin B5): Hỗ trợ dưỡng ẩm và làm dịu.\n• Niacinamide: Hỗ trợ cải thiện vẻ ngoài của da không đều màu.\n• Glutathione: Thành phần chống oxy hóa.\n\nĐây là thành phần nổi bật, không phải danh sách INCI đầy đủ. Hàm lượng và công thức cần đối chiếu bao bì thực tế.\n\n4. HƯỚNG DẪN SỬ DỤNG\n\nBước 1: Làm sạch da mặt.\nBước 2: Sử dụng toner hoặc serum nếu có.\nBước 3: Lấy lượng kem vừa đủ, thoa đều lên da.\nBước 4: Massage nhẹ nhàng.\n\nTần suất sử dụng: Hai lần mỗi ngày, sáng và tối, theo hướng dẫn trên trang sản phẩm.\n\nLưu ý:\n• Tránh thoa vào mắt.\n• Không tự ý sử dụng trên vết thương hở.\n• Ngừng sử dụng nếu xuất hiện kích ứng.\n• Bảo quản tránh ánh nắng trực tiếp.\n\n5. ĐỐI TƯỢNG SỬ DỤNG\n\n• Người có làn da khô, thiếu ẩm.\n• Người có làn da nhạy cảm.\n• Người có da kém mềm mại, dễ bong tróc.\n• Người quan tâm đến dấu hiệu lão hóa.\n• Người cần kem dưỡng trong quy trình chăm sóc da hằng ngày.", "en": "1. PRODUCT DESCRIPTION\n\nUSOLAB Bio Renaturation Repair Cream is a facial moisturizer intended to provide comforting care for skin that feels dry, rough or stressed. Its rich cream format helps condition the skin and supports a routine focused on maintaining the moisture barrier. The product can be used after a facial ampoule as the final moisturizing step. Although the name includes the word Repair, the cream should be presented as cosmetic skin care rather than a treatment for damaged tissue or medical skin conditions.\n\n2. BENEFITS\n\n• Helps moisturize dry-feeling skin.\n• Supports a comfortable skin feel.\n• Softens the appearance of rough areas.\n• Complements skin-barrier-focused routines.\n• Provides a nourishing final skincare step.\n\n3. INGREDIENTS\n\nKey ingredient categories and their functions:\n\n• Moisturizing and Barrier-Conditioning Ingredients: Specific substances require INCI verification.\n• Emollients: Help soften the skin.\n• Humectants: Support hydration.\n• Texture and Stability Ingredients: Support the cream formula.\n• The current 50ml product label is required for exact ingredient identification.\n\nNote: Ingredient information is provisional and does not constitute a verified INCI declaration. Confirm the actual ingredients, concentrations and claims against the product packaging or official manufacturer documentation before publication.\n\n4. DIRECTIONS FOR USE\n\n1. Cleanse the skin and pat dry.\n2. Apply any suitable toner or ampoule.\n3. Take a small amount of cream.\n4. Spread gently over the face and neck.\n5. Use as the final moisturizing step.\n6. Apply sunscreen in the morning.\n\nPrecautions: For external use only. Avoid direct contact with eyes unless specifically intended for the eye area. Discontinue use if irritation occurs. Follow all warnings on the product label.\n\n5. SUITABLE FOR\n\n• Dry or rough-feeling skin.\n• People seeking daily barrier-supporting care.\n• Skin experiencing moisture-related discomfort.\n• Individuals using the Bio Renaturation Repair range."}, "image": "assets/catalog/product-usolab-06.jpg", "gallery": {"vi": [{"src": "assets/catalog/vi/usolab-06/thumbnail.webp", "label": "Thumbnail", "order": 0}, {"src": "assets/catalog/vi/usolab-06/anh-1.webp", "label": "Ảnh 1", "order": 1}, {"src": "assets/catalog/vi/usolab-06/anh-2.webp", "label": "Ảnh 2", "order": 2}, {"src": "assets/catalog/vi/usolab-06/anh-3.webp", "label": "Ảnh 3", "order": 3}, {"src": "assets/catalog/vi/usolab-06/anh-4.webp", "label": "Ảnh 4", "order": 4}, {"src": "assets/catalog/vi/usolab-06/anh-5.webp", "label": "Ảnh 5", "order": 5}, {"src": "assets/catalog/vi/usolab-06/anh-6.webp", "label": "Ảnh 6", "order": 6}, {"src": "assets/catalog/vi/usolab-06/anh-7.webp", "label": "Ảnh 7", "order": 7}]}}, {"id": "usolab-07", "brandId": "usolab", "brand": "Usolab", "name": {"vi": "USOLAB BIO BRIGHTENING BLEACHING AMPOULE 50ML", "en": "USOLAB Bio Brightening Bleaching Ampoule 50ml"}, "category": "Skincare", "type": "Tinh chất dưỡng sáng da (Ampoule)", "size": "50ml", "country": "Hàn Quốc", "description": {"vi": "1. MÔ TẢ SẢN PHẨM\n\nTên sản phẩm: Tinh chất dưỡng sáng da USOLAB Bio Brightening Bleaching Ampoule 50ml\nThương hiệu: USOLAB\nXuất xứ thương hiệu: Hàn Quốc\nDung tích: 50ml\nPhân loại: Tinh chất dưỡng sáng da (Ampoule)\n\nUSOLAB Bio Brightening Bleaching Ampoule là tinh chất chăm sóc da không đều màu, được giới thiệu với công thức kết hợp Glutathione, Arbutin, Niacinamide và các thành phần dưỡng da khác.\n\nSản phẩm hướng đến làn da xỉn màu, có đốm sạm và vết thâm, giúp cải thiện vẻ ngoài của da và bổ sung độ ẩm trong quy trình dưỡng da.\n\n2. CÔNG DỤNG\n\n• Hỗ trợ làm sáng da.\n• Giúp da trông đều màu hơn.\n• Hỗ trợ làm mờ vẻ ngoài của các đốm thâm sạm.\n• Cung cấp độ ẩm cho da.\n• Giúp bề mặt da trông mịn màng hơn.\n• Hỗ trợ chăm sóc da có dấu hiệu xỉn màu.\n\n3. THÀNH PHẦN\n\nCác thành phần nổi bật được giới thiệu trên website USOLAB Việt Nam:\n\n• Glutathione 5%: Thành phần chống oxy hóa, được sử dụng trong công thức dưỡng sáng.\n• Arbutin 2%: Hỗ trợ cải thiện vẻ ngoài của da không đều màu.\n• Niacinamide: Hỗ trợ dưỡng sáng và chăm sóc hàng rào da.\n• Citrus Limon Fruit Extract: Chiết xuất chanh có trong công thức.\n• Amino Acids: Nhóm amino acid hỗ trợ chăm sóc và duy trì độ ẩm.\n• Peptide Complex: Phức hợp peptide được hãng giới thiệu.\n• Sodium Hyaluronate: Hỗ trợ hút và giữ ẩm.\n\nTrang sản phẩm còn nhắc đến Tranexamic Acid trong phần giới thiệu. Cần đối chiếu danh sách INCI trên bao bì để xác nhận thành phần này ở phiên bản đang bán.\n\n4. HƯỚNG DẪN SỬ DỤNG\n\nBước 1: Làm sạch da mặt.\nBước 2: Lấy lượng tinh chất vừa đủ.\nBước 3: Thoa đều lên mặt hoặc vùng da cần chăm sóc.\nBước 4: Vỗ nhẹ và tiếp tục với kem dưỡng.\n\nTần suất: Sử dụng theo hướng dẫn trên bao bì và khả năng dung nạp của da.\n\nLưu ý:\n• Tránh vùng mắt.\n• Người có da nhạy cảm nên thử trên vùng nhỏ.\n• Sử dụng kem chống nắng vào ban ngày.\n• Không thoa trên vùng da đang tổn thương.\n\n5. ĐỐI TƯỢNG SỬ DỤNG\n\n• Người có da xỉn màu.\n• Người có làn da không đều màu.\n• Người có vết thâm sau mụn hoặc đốm sạm.\n• Người có nhu cầu dưỡng sáng.\n• Người muốn kết hợp dưỡng sáng và cấp ẩm.", "en": "1. PRODUCT DESCRIPTION\n\nUSOLAB Bio Brightening Bleaching Ampoule is a facial skincare treatment positioned for brightening and improving the appearance of uneven skin tone. Despite the product's commercial use of the word Bleaching, its cosmetic purpose should be described as helping the complexion appear brighter and more even, rather than chemically bleaching the skin. It can be incorporated into a routine focused on dullness and visible discoloration. Specific brightening actives and concentrations require verification against the manufacturer's ingredient declaration.\n\n2. BENEFITS\n\n• Helps improve the appearance of dullness.\n• Supports a more even-looking complexion.\n• Helps improve the appearance of visible discoloration.\n• Provides an additional brightening skincare step.\n• Complements a routine focused on skin radiance.\n\n3. INGREDIENTS\n\nKey ingredient categories and their functions:\n\n• Brightening Complex: Specific active ingredients and concentrations must be verified.\n• Humectants: Help maintain hydration.\n• Skin-Conditioning Ingredients: Support a smooth application.\n• Antioxidant Ingredients: Confirm their presence against the product's INCI before making antioxidant claims.\n• Complete ingredient information requires packaging verification.\n\nNote: Ingredient information is provisional and does not constitute a verified INCI declaration. Confirm the actual ingredients, concentrations and claims against the product packaging or official manufacturer documentation before publication.\n\n4. DIRECTIONS FOR USE\n\n1. Cleanse the face and pat dry.\n2. Apply toner if desired.\n3. Dispense a small amount of ampoule.\n4. Apply evenly to the face, avoiding the eyes.\n5. Follow with moisturizer.\n6. Use broad-spectrum sunscreen daily when addressing pigmentation concerns.\n\nPrecautions: For external use only. Avoid direct contact with eyes unless specifically intended for the eye area. Discontinue use if irritation occurs. Follow all warnings on the product label.\n\n5. SUITABLE FOR\n\n• Dull-looking skin.\n• People concerned about uneven skin tone.\n• Individuals with visible dark spots.\n• Those seeking a cosmetic brightening ampoule."}, "image": "assets/catalog/product-usolab-07.jpg", "gallery": {"vi": [{"src": "assets/catalog/vi/usolab-07/thumbnail.webp", "label": "Thumbnail", "order": 0}, {"src": "assets/catalog/vi/usolab-07/anh-1.webp", "label": "Ảnh 1", "order": 1}, {"src": "assets/catalog/vi/usolab-07/anh-2.webp", "label": "Ảnh 2", "order": 2}, {"src": "assets/catalog/vi/usolab-07/anh-3.webp", "label": "Ảnh 3", "order": 3}, {"src": "assets/catalog/vi/usolab-07/anh-4.webp", "label": "Ảnh 4", "order": 4}, {"src": "assets/catalog/vi/usolab-07/anh-5.webp", "label": "Ảnh 5", "order": 5}, {"src": "assets/catalog/vi/usolab-07/anh-6.webp", "label": "Ảnh 6", "order": 6}, {"src": "assets/catalog/vi/usolab-07/anh-7.webp", "label": "Ảnh 7", "order": 7}]}}, {"id": "usolab-08", "brandId": "usolab", "brand": "Usolab", "name": {"vi": "USOLAB BIO SENSITIVE PURIFYING AMPOULE 50ML", "en": "USOLAB Bio Sensitive Purifying Ampoule 50ml"}, "category": "Skincare", "type": "Tinh chất chăm sóc da dầu (Ampoule)", "size": "50ml", "country": "Hàn Quốc", "description": {"vi": "1. MÔ TẢ SẢN PHẨM\n\nTên sản phẩm: Tinh chất chăm sóc da dầu mụn USOLAB Bio Sensitive Purifying Ampoule 50ml\nThương hiệu: USOLAB\nXuất xứ thương hiệu: Hàn Quốc\nDung tích: 50ml\nPhân loại: Tinh chất chăm sóc da dầu (Ampoule)\n\nUSOLAB Bio Sensitive Purifying Ampoule là tinh chất thuộc dòng Sensitive, được phát triển cho làn da dầu, dễ nổi mụn và có nhu cầu làm dịu.\n\nTheo USOLAB Việt Nam, sản phẩm chứa chiết xuất trà xanh, Madecassoside và phức hợp peptide, hướng đến việc chăm sóc da tiết dầu, hỗ trợ duy trì bề mặt da thông thoáng và hạn chế cảm giác khó chịu.\n\n2. CÔNG DỤNG\n\n• Hỗ trợ kiểm soát dầu thừa trên bề mặt da.\n• Giúp da có cảm giác thông thoáng.\n• Hỗ trợ làm dịu vùng da dễ ửng đỏ.\n• Bổ sung độ ẩm, giảm cảm giác khô căng.\n• Hỗ trợ cải thiện vẻ ngoài của làn da dễ nổi mụn.\n• Góp phần chăm sóc bề mặt da kém mịn màng.\n\n3. THÀNH PHẦN\n\nCác thành phần nổi bật theo website USOLAB Việt Nam:\n\n• Green Tea Extract (chiết xuất trà xanh): Hỗ trợ chống oxy hóa và chăm sóc da dầu.\n• Madecassoside: Thành phần từ rau má, hỗ trợ làm dịu da.\n• Peptide Complex 31: Phức hợp peptide được hãng giới thiệu trong công thức.\n\nWebsite xác nhận các nhóm thành phần nổi bật trên nhưng chưa đủ dữ liệu để lập bảng INCI đầy đủ. Không tự bổ sung hoạt chất hoặc hàm lượng chưa được xác minh.\n\n4. HƯỚNG DẪN SỬ DỤNG\n\nBước 1: Làm sạch da mặt bằng sản phẩm phù hợp.\nBước 2: Lấy lượng tinh chất vừa đủ.\nBước 3: Thoa đều lên mặt, tập trung vào những vùng có nhu cầu chăm sóc.\nBước 4: Vỗ nhẹ, sau đó sử dụng kem dưỡng phù hợp.\n\nTần suất: Sử dụng theo hướng dẫn trên bao bì.\n\nLưu ý:\n• Tránh tiếp xúc trực tiếp với mắt.\n• Không thoa trên vết thương hở.\n• Người có da nhạy cảm nên thử trên vùng nhỏ trước.\n• Nếu có mụn viêm nặng, cần tham khảo bác sĩ da liễu.\n\n5. ĐỐI TƯỢNG SỬ DỤNG\n\n• Người có da dầu hoặc hỗn hợp thiên dầu.\n• Người có làn da dễ nổi mụn.\n• Người có da dễ bóng nhờn.\n• Người có làn da dễ ửng đỏ.\n• Người muốn bổ sung tinh chất chăm sóc da dầu trong quy trình hằng ngày.", "en": "1. PRODUCT DESCRIPTION\n\nUSOLAB Bio Sensitive Purifying Ampoule is a facial skincare product intended for skin that requires lightweight conditioning and a balanced-looking complexion. Its purifying positioning makes it relevant to routines for oily or blemish-prone skin, while the sensitive-focused name suggests attention to skin comfort. The ampoule can be applied after cleansing and before moisturizer. The precise ingredients, oil-control claims and suitability for highly reactive skin should be verified against the current packaging.\n\n2. BENEFITS\n\n• Provides lightweight skin-conditioning care.\n• Supports a fresher-looking complexion.\n• Complements skincare for oily or blemish-prone skin.\n• Helps maintain a comfortable skin feel.\n• Fits into a simple daily facial routine.\n\n3. INGREDIENTS\n\nKey ingredient categories and their functions:\n\n• Purifying Complex: Specific components require manufacturer verification.\n• Moisture-Supporting Ingredients: Help maintain skin hydration.\n• Skin-Conditioning Agents: Support a smooth skin feel.\n• Exact exfoliating or oil-control actives, if present, must be confirmed on the label.\n\nNote: Ingredient information is provisional and does not constitute a verified INCI declaration. Confirm the actual ingredients, concentrations and claims against the product packaging or official manufacturer documentation before publication.\n\n4. DIRECTIONS FOR USE\n\n1. Cleanse the face with a suitable gentle cleanser.\n2. Apply toner if desired.\n3. Dispense an appropriate amount of ampoule.\n4. Spread gently across the face.\n5. Follow with a lightweight moisturizer.\n6. Adjust frequency according to skin tolerance and label directions.\n\nPrecautions: For external use only. Avoid direct contact with eyes unless specifically intended for the eye area. Discontinue use if irritation occurs. Follow all warnings on the product label.\n\n5. SUITABLE FOR\n\n• Combination and oily skin.\n• People seeking a lightweight facial ampoule.\n• Blemish-prone skin requiring gentle cosmetic care.\n• Individuals interested in a purifying skincare routine."}, "image": "assets/catalog/product-usolab-08.png", "gallery": {"vi": [{"src": "assets/catalog/vi/usolab-08/thumbnail.webp", "label": "Thumbnail", "order": 0}, {"src": "assets/catalog/vi/usolab-08/anh-1.webp", "label": "Ảnh 1", "order": 1}, {"src": "assets/catalog/vi/usolab-08/anh-2.webp", "label": "Ảnh 2", "order": 2}, {"src": "assets/catalog/vi/usolab-08/anh-3.webp", "label": "Ảnh 3", "order": 3}, {"src": "assets/catalog/vi/usolab-08/anh-4.webp", "label": "Ảnh 4", "order": 4}, {"src": "assets/catalog/vi/usolab-08/anh-5.webp", "label": "Ảnh 5", "order": 5}, {"src": "assets/catalog/vi/usolab-08/anh-6.webp", "label": "Ảnh 6", "order": 6}, {"src": "assets/catalog/vi/usolab-08/anh-7.webp", "label": "Ảnh 7", "order": 7}]}}, {"id": "usolab-09", "brandId": "usolab", "brand": "Usolab", "name": {"vi": "USOLAB BIO SENSITIVE SUN BLOCK MATTE 50ML", "en": "USOLAB Bio Sensitive Sun Block Matte 50ml"}, "category": "Skincare", "type": "Kem chống nắng", "size": "50ml", "country": "Hàn Quốc", "description": {"vi": "1. MÔ TẢ SẢN PHẨM\n\nTên sản phẩm: Kem chống nắng cho da dầu mụn USOLAB Bio Sensitive Sun Block Matte 50ml\nThương hiệu: USOLAB\nXuất xứ thương hiệu: Hàn Quốc\nDung tích: 50ml\nPhân loại: Kem chống nắng\n\nUSOLAB Bio Sensitive Sun Block Matte là sản phẩm chống nắng dành cho da dầu và da dễ nổi mụn, được giới thiệu với kết cấu mỏng nhẹ, lớp hoàn thiện thiên lì và khả năng hỗ trợ kiểm soát bóng dầu.\n\nSản phẩm kết hợp các thành phần chống nắng với chiết xuất thực vật, hướng đến việc bảo vệ da trước tia UV và duy trì cảm giác thoáng nhẹ khi sử dụng ban ngày.\n\n2. CÔNG DỤNG\n\n• Hỗ trợ bảo vệ da trước tác động của tia UVA và UVB.\n• Giúp giảm cảm giác bóng dầu trên bề mặt.\n• Tạo lớp hoàn thiện thiên lì, khô thoáng.\n• Hỗ trợ dưỡng ẩm nhẹ.\n• Giúp da trông đều màu hơn nhờ hiệu ứng nâng tông.\n• Hỗ trợ chăm sóc da dầu, da dễ nổi mụn.\n\n3. THÀNH PHẦN\n\nCác thành phần nổi bật được USOLAB Việt Nam giới thiệu:\n\n• Zinc Oxide: Bộ lọc chống nắng khoáng chất.\n• Tea Tree Extract: Chiết xuất tràm trà, hỗ trợ chăm sóc da dầu.\n• Nelumbo Nucifera Extract: Chiết xuất hoa sen, hỗ trợ chống oxy hóa và làm dịu.\n• Hydrolyzed Collagen: Thành phần hỗ trợ giữ ẩm và làm mềm da.\n\nĐây không phải bảng INCI đầy đủ. Chỉ số SPF/PA cụ thể cần kiểm tra trực tiếp trên bao bì phiên bản bán tại Việt Nam trước khi công bố.\n\n4. HƯỚNG DẪN SỬ DỤNG\n\nBước 1: Hoàn thành các bước dưỡng da buổi sáng.\nBước 2: Lấy lượng kem chống nắng đủ để phủ đều vùng mặt và cổ.\nBước 3: Thoa đều trước khi ra ngoài.\nBước 4: Thoa lại định kỳ, đặc biệt sau khi đổ mồ hôi, bơi hoặc lau mặt.\n\nNên thoa lại khoảng mỗi 2 giờ khi tiếp xúc ánh nắng liên tục.\n\nLưu ý:\n• Không sử dụng thay kem dưỡng điều trị mụn.\n• Tránh tiếp xúc trực tiếp với mắt.\n• Kết hợp che chắn bằng mũ, kính và trang phục chống nắng.\n• Ngừng sử dụng nếu có kích ứng kéo dài.\n\n5. ĐỐI TƯỢNG SỬ DỤNG\n\n• Người có da dầu.\n• Người có da hỗn hợp thiên dầu.\n• Người có làn da dễ nổi mụn.\n• Người muốn lớp chống nắng ít bóng nhờn.\n• Người cần kem chống nắng sử dụng hằng ngày.", "en": "1. PRODUCT DESCRIPTION\n\nUSOLAB Bio Sensitive Sun Block Matte is a facial sun-protection product designed for people who prefer a less shiny finish. Its matte-oriented positioning makes it suitable for daily skincare routines, particularly for combination and oily skin. A sunscreen's actual UV protection depends on its tested and labeled SPF and UVA rating. Since those values have not been provided for this specific 50ml product, they should be confirmed on the packaging before the website publishes any numerical protection claims.\n\n2. BENEFITS\n\n• Provides a sunscreen step in the daytime skincare routine.\n• Designed to create a less shiny-looking finish.\n• Suitable for use before everyday makeup.\n• Complements skincare for combination and oily skin.\n• Offers a convenient facial sun-care format.\n\n3. INGREDIENTS\n\nKey ingredient categories and their functions:\n\n• UV Filters: The exact sunscreen filters must be confirmed from the INCI list.\n• Mattifying Ingredients: Specific oil-absorbing agents require verification.\n• Emollients: Support product spreadability.\n• Film-Forming Ingredients: May support even sunscreen application; confirm the formula.\n• SPF and UVA protection ratings must be taken directly from the actual label.\n\nNote: Ingredient information is provisional and does not constitute a verified INCI declaration. Confirm the actual ingredients, concentrations and claims against the product packaging or official manufacturer documentation before publication.\n\n4. DIRECTIONS FOR USE\n\n1. Complete the morning cleansing and moisturizing routine.\n2. Apply sunscreen generously and evenly to the face and neck before sun exposure.\n3. Allow the product to settle before makeup.\n4. Reapply frequently during sun exposure, especially after sweating, swimming or towel-drying.\n5. Avoid prolonged sun exposure and use additional protective measures.\n6. Follow the specific label for timing, quantity and reapplication instructions.\n\nPrecautions: For external use only. Avoid direct contact with eyes unless specifically intended for the eye area. Discontinue use if irritation occurs. Follow all warnings on the product label.\n\n5. SUITABLE FOR\n\n• Combination and oily skin.\n• People seeking a matte-looking sunscreen finish.\n• Individuals who wear makeup during the day.\n• Those wanting daily facial sun protection."}, "image": "assets/catalog/product-usolab-09.jpg", "gallery": {"vi": [{"src": "assets/catalog/vi/usolab-09/thumbnail.webp", "label": "Thumbnail", "order": 0}, {"src": "assets/catalog/vi/usolab-09/anh-1.webp", "label": "Ảnh 1", "order": 1}, {"src": "assets/catalog/vi/usolab-09/anh-2.webp", "label": "Ảnh 2", "order": 2}, {"src": "assets/catalog/vi/usolab-09/anh-3.webp", "label": "Ảnh 3", "order": 3}, {"src": "assets/catalog/vi/usolab-09/anh-4.webp", "label": "Ảnh 4", "order": 4}, {"src": "assets/catalog/vi/usolab-09/anh-5.webp", "label": "Ảnh 5", "order": 5}, {"src": "assets/catalog/vi/usolab-09/anh-6.webp", "label": "Ảnh 6", "order": 6}, {"src": "assets/catalog/vi/usolab-09/anh-7.webp", "label": "Ảnh 7", "order": 7}]}}, {"id": "usolab-10", "brandId": "usolab", "brand": "Usolab", "name": {"vi": "USOLAB BIO RENATURATION REPAIR CREAM 250ML – SALON SIZE", "en": "USOLAB Bio Renaturation Repair Cream 250ml – Salon Size"}, "category": "Skincare", "type": "Kem dưỡng da chuyên dùng cho spa và chăm sóc chuyên sâu", "size": "250ml", "country": "Hàn Quốc", "description": {"vi": "1. MÔ TẢ SẢN PHẨM\n\nTên sản phẩm: Kem dưỡng chăm sóc da USOLAB Bio Renaturation Repair Cream 250ml – Salon Size\nThương hiệu: USOLAB\nXuất xứ thương hiệu: Hàn Quốc\nDung tích: 250ml\nPhân loại: Kem dưỡng da chuyên dùng cho spa và chăm sóc chuyên sâu\n\nUSOLAB Bio Renaturation Repair Cream 250ml là phiên bản dung tích lớn thuộc dòng Repair, được giới thiệu cho spa, phòng khám da liễu và cơ sở chăm sóc da.\n\nCông thức chứa Sodium DNA, phức hợp peptide, Niacinamide, Panthenol và các thành phần chăm sóc da khác, hướng đến việc dưỡng ẩm, làm mềm và cải thiện vẻ ngoài của làn da có dấu hiệu lão hóa.\n\n2. CÔNG DỤNG\n\n• Cung cấp độ ẩm, giúp da mềm mại.\n• Hỗ trợ chăm sóc hàng rào giữ ẩm.\n• Giúp da trông căng mượt hơn.\n• Hỗ trợ cải thiện vẻ ngoài của làn da xỉn màu.\n• Chăm sóc da có dấu hiệu lão hóa.\n• Hỗ trợ làm dịu cảm giác khô căng.\n\n3. THÀNH PHẦN\n\nCác thành phần nổi bật theo USOLAB Việt Nam:\n\n• Sodium DNA: Thành phần được hãng giới thiệu trong dòng Repair.\n• Peptide Complex 31: Phức hợp peptide chăm sóc da.\n• Herb Complex 10: Phức hợp chiết xuất thực vật.\n• Niacinamide: Hỗ trợ dưỡng sáng và cải thiện da không đều màu.\n• Panthenol: Hỗ trợ dưỡng ẩm và làm dịu.\n• Adenosine: Thành phần thường dùng trong sản phẩm chăm sóc da có dấu hiệu lão hóa.\n\nDanh sách trên là thành phần nổi bật, không phải INCI đầy đủ.\n\n4. HƯỚNG DẪN SỬ DỤNG\n\nBước 1: Làm sạch vùng da cần chăm sóc.\nBước 2: Lấy lượng kem phù hợp.\nBước 3: Thoa đều lên mặt, tránh vùng mắt.\nBước 4: Massage nhẹ nhàng.\n\nTần suất: Theo quy trình chăm sóc da hoặc hướng dẫn trên bao bì.\n\nLưu ý:\n• Sản phẩm chỉ dùng ngoài da.\n• Tránh vùng mắt và vết thương hở.\n• Khi sử dụng tại spa hoặc phòng khám, cần tuân thủ quy trình chuyên môn.\n• Bảo quản nơi khô ráo, thoáng mát.\n\n5. ĐỐI TƯỢNG SỬ DỤNG\n\n• Người có làn da khô, thiếu ẩm.\n• Người có da nhạy cảm cần dưỡng ẩm.\n• Người quan tâm đến các dấu hiệu lão hóa.\n• Spa và cơ sở chăm sóc da cần sản phẩm dung tích lớn.\n• Người có nhu cầu chăm sóc da chuyên sâu theo quy trình phù hợp.", "en": "1. PRODUCT DESCRIPTION\n\nUSOLAB Bio Renaturation Repair Cream 250ml is a larger salon-size presentation of the Bio Renaturation Repair Cream range. Designed for convenient use in professional skincare settings or frequent moisturizing routines, it provides cosmetic conditioning for skin that feels dry, rough or stressed. Its cream texture supports softness and a comfortable skin feel. The 250ml size offers a practical format for repeated application, but the ingredient list should be checked independently rather than assuming it is identical to the 50ml version.\n\n2. BENEFITS\n\n• Provides moisturizing and conditioning care.\n• Helps soften dry-feeling skin.\n• Supports skin comfort and moisture-barrier care.\n• Offers a larger format for repeated use.\n• Suitable for professional skincare routines where appropriate.\n\n3. INGREDIENTS\n\nKey ingredient categories and their functions:\n\n• Moisturizing Complex: Exact ingredients require verification against the 250ml packaging.\n• Emollients: Help soften and condition skin.\n• Humectants: Support moisture retention.\n• Formula-Supporting Ingredients: Maintain product texture and stability.\n• Do not assume the 250ml INCI is identical to the 50ml version without verification.\n\nNote: Ingredient information is provisional and does not constitute a verified INCI declaration. Confirm the actual ingredients, concentrations and claims against the product packaging or official manufacturer documentation before publication.\n\n4. DIRECTIONS FOR USE\n\n1. Ensure the skin is clean and dry.\n2. Dispense a hygienic amount of cream.\n3. Apply evenly to the intended area.\n4. Massage gently until absorbed.\n5. Reapply as appropriate for the skincare routine.\n6. For salon use, follow professional hygiene and product handling practices.\n\nPrecautions: For external use only. Avoid direct contact with eyes unless specifically intended for the eye area. Discontinue use if irritation occurs. Follow all warnings on the product label.\n\n5. SUITABLE FOR\n\n• People seeking a larger moisturizing cream format.\n• Dry or stressed-looking skin.\n• Professional skincare settings.\n• Individuals using the Bio Renaturation Repair range regularly."}, "image": "assets/catalog/product-usolab-10.jpg"}, {"id": "usolab-11", "brandId": "usolab", "brand": "Usolab", "name": {"vi": "USOLAB BIO INTENSIVE FOAMING K CLEANSER 120ML", "en": "USOLAB Bio Intensive Foaming K Cleanser 120ml"}, "category": "Skincare", "type": "Sữa rửa mặt tạo bọt", "size": "120ml", "country": "Hàn Quốc", "description": {"vi": "1. MÔ TẢ SẢN PHẨM\n\nTên sản phẩm: USOLAB Bio Intensive Foaming K Cleanser 120ml\nThương hiệu: USOLAB\nQuốc gia thương hiệu: Hàn Quốc\nQuy cách đóng gói: 120ml\nPhân loại: Sữa rửa mặt tạo bọt\n\nUSOLAB Bio Intensive Foaming K Cleanser 120ml là sản phẩm làm sạch thuộc dòng K Line, hướng đến nhu cầu chăm sóc làn da nhạy cảm và dễ xuất hiện cảm giác khó chịu. Sản phẩm giúp loại bỏ bụi bẩn, dầu thừa và tạp chất trên bề mặt da, đồng thời chú trọng duy trì cảm giác mềm mại sau khi rửa. Đây là bước làm sạch phù hợp để chuẩn bị da cho toner, tinh chất và kem dưỡng.\n\n2. CÔNG DỤNG\n\n• Làm sạch bụi bẩn và dầu thừa.\n• Hỗ trợ duy trì cảm giác mềm mại sau khi rửa.\n• Giúp da thông thoáng trước bước dưỡng.\n• Phù hợp với quy trình chăm sóc da nhạy cảm.\n\n3. THÀNH PHẦN\n\nCác thành phần và nhóm thành phần nổi bật:\n\n• Dòng K Line được hãng giới thiệu với định hướng chăm sóc da nhạy cảm và thành phần vitamin K.\n• Hệ chất làm sạch tạo bọt: Hỗ trợ loại bỏ tạp chất.\n• Các chất dưỡng ẩm và làm mềm: Cần đối chiếu tên INCI trên nhãn 120ml.\n• Chưa xác minh bảng INCI đầy đủ và hàm lượng vitamin K của riêng sản phẩm này.\n\nLưu ý: Chưa có bảng INCI đầy đủ đã xác minh cho SKU này. Không sử dụng phần mô tả nhóm thành phần để thay thế nhãn thành phần thực tế.\n\n4. HƯỚNG DẪN SỬ DỤNG\n\n1. Làm ướt mặt bằng nước sạch.\n2. Lấy lượng sữa rửa mặt vừa đủ và tạo bọt.\n3. Massage nhẹ trên da, tránh vùng mắt.\n4. Rửa sạch và thấm khô bằng khăn mềm.\n5. Tiếp tục các bước dưỡng ẩm.\n\nLưu ý: Chỉ sử dụng ngoài da. Tránh tiếp xúc trực tiếp với mắt. Ngừng sử dụng nếu xuất hiện kích ứng. Ưu tiên hướng dẫn trên bao bì sản phẩm thực tế.\n\n5. ĐỐI TƯỢNG SỬ DỤNG\n\n• Người có da nhạy cảm.\n• Người muốn sữa rửa mặt thuộc dòng K Line.\n• Người cần làm sạch da hằng ngày.", "en": "1. PRODUCT DESCRIPTION\n\nUSOLAB Bio Intensive Foaming K Cleanser is a facial cleansing product intended to remove everyday impurities, excess surface oil and buildup from the skin. Its foaming texture helps distribute the cleanser across the face for a refreshing washing experience. Positioned within the Bio K range, it can be used as the cleansing step before a targeted ampoule and moisturizing cream. Specific K-complex ingredients and claims regarding skin sensitivity should be verified from the actual 120ml packaging.\n\n2. BENEFITS\n\n• Helps remove dirt and everyday impurities.\n• Cleanses excess surface oil.\n• Provides a refreshing foaming texture.\n• Prepares the skin for subsequent skincare steps.\n• Complements the USOLAB Bio K routine.\n\n3. INGREDIENTS\n\nKey ingredient categories and their functions:\n\n• Cleansing Surfactants: Help remove surface impurities; specific agents require label verification.\n• Foam-Forming Ingredients: Support the cleanser texture.\n• K-Focused Conditioning Ingredients: Exact composition requires verification.\n• Moisturizing Ingredients: Check the current INCI for specific humectants.\n\nNote: Ingredient information is provisional and does not constitute a verified INCI declaration. Confirm the actual ingredients, concentrations and claims against the product packaging or official manufacturer documentation before publication.\n\n4. DIRECTIONS FOR USE\n\n1. Wet the face with lukewarm water.\n2. Dispense a suitable amount of cleanser.\n3. Work into a gentle foam.\n4. Massage lightly over the face, avoiding the eyes.\n5. Rinse thoroughly with water.\n6. Follow with ampoule and moisturizer.\n\nPrecautions: For external use only. Avoid direct contact with eyes unless specifically intended for the eye area. Discontinue use if irritation occurs. Follow all warnings on the product label.\n\n5. SUITABLE FOR\n\n• People seeking a daily foaming facial cleanser.\n• Normal and combination skin, subject to tolerance.\n• Individuals following a Bio K skincare routine.\n• Those who prefer a rinse-off cleanser."}, "image": "assets/catalog/product-usolab-11.jpg", "gallery": {"vi": [{"src": "assets/catalog/vi/usolab-11/thumbnail.webp", "label": "Thumbnail", "order": 0}, {"src": "assets/catalog/vi/usolab-11/anh-1.webp", "label": "Ảnh 1", "order": 1}, {"src": "assets/catalog/vi/usolab-11/anh-2.webp", "label": "Ảnh 2", "order": 2}, {"src": "assets/catalog/vi/usolab-11/anh-3.webp", "label": "Ảnh 3", "order": 3}, {"src": "assets/catalog/vi/usolab-11/anh-4.webp", "label": "Ảnh 4", "order": 4}, {"src": "assets/catalog/vi/usolab-11/anh-5.webp", "label": "Ảnh 5", "order": 5}, {"src": "assets/catalog/vi/usolab-11/anh-6.webp", "label": "Ảnh 6", "order": 6}, {"src": "assets/catalog/vi/usolab-11/anh-7.webp", "label": "Ảnh 7", "order": 7}]}}, {"id": "usolab-12", "brandId": "usolab", "brand": "Usolab", "name": {"vi": "USOLAB BIO DEEP CLEANSING WATER 200ML", "en": "USOLAB Bio Deep Cleansing Water 200ml"}, "category": "Skincare", "type": "Nước tẩy trang", "size": "200ml", "country": "Hàn Quốc", "description": {"vi": "1. MÔ TẢ SẢN PHẨM\n\nTên sản phẩm: USOLAB Bio Deep Cleansing Water 200ml\nThương hiệu: USOLAB\nQuốc gia thương hiệu: Hàn Quốc\nQuy cách đóng gói: 200ml\nPhân loại: Nước tẩy trang\n\nUSOLAB Bio Deep Cleansing Water 200ml là sản phẩm làm sạch bước đầu, hỗ trợ loại bỏ bụi bẩn, dầu thừa và lớp trang điểm thông thường trên bề mặt da. Kết cấu dạng nước giúp thao tác tẩy trang thuận tiện, phù hợp bổ sung vào quy trình làm sạch trước khi sử dụng sữa rửa mặt.\n\n2. CÔNG DỤNG\n\n• Hỗ trợ làm sạch lớp trang điểm thông thường.\n• Loại bỏ bụi bẩn và dầu thừa.\n• Giúp chuẩn bị da cho bước rửa mặt.\n• Thuận tiện sử dụng hằng ngày.\n\n3. THÀNH PHẦN\n\nCác thành phần và nhóm thành phần nổi bật:\n\n• Hệ chất làm sạch hòa tan trong nước: Hỗ trợ loại bỏ tạp chất.\n• Các thành phần hỗ trợ giữ ẩm: Chưa xác minh tên INCI.\n• Danh sách thành phần cụ thể cần đối chiếu trên bao bì 200ml.\n\nLưu ý: Chưa có bảng INCI đầy đủ đã xác minh cho SKU này. Không sử dụng phần mô tả nhóm thành phần để thay thế nhãn thành phần thực tế.\n\n4. HƯỚNG DẪN SỬ DỤNG\n\n1. Thấm sản phẩm lên bông tẩy trang.\n2. Lau nhẹ từ giữa mặt ra ngoài.\n3. Lặp lại đến khi bông sạch.\n4. Tiếp tục rửa mặt bằng sản phẩm phù hợp.\n\nLưu ý: Chỉ sử dụng ngoài da. Tránh tiếp xúc trực tiếp với mắt. Ngừng sử dụng nếu xuất hiện kích ứng. Ưu tiên hướng dẫn trên bao bì sản phẩm thực tế.\n\n5. ĐỐI TƯỢNG SỬ DỤNG\n\n• Người cần tẩy trang hằng ngày.\n• Người sử dụng kem chống nắng hoặc trang điểm nhẹ.\n• Người muốn sản phẩm làm sạch dạng nước.", "en": "1. PRODUCT DESCRIPTION\n\nUSOLAB Bio Deep Cleansing Water is a water-based facial cleansing product intended to remove everyday makeup, surface oil and impurities. It can serve as the first cleansing step before a rinse-off facial wash, helping prepare the skin for subsequent skincare products. Its lightweight liquid format is convenient for use with cotton pads. Removal of waterproof makeup and any claims about sensitive-skin suitability should be confirmed from the specific 200ml product label.\n\n2. BENEFITS\n\n• Helps remove everyday makeup and surface impurities.\n• Lifts excess oil and accumulated residue.\n• Offers a convenient water-based cleansing format.\n• Supports the first step of a double-cleansing routine.\n• Prepares the skin for subsequent facial cleansing.\n\n3. INGREDIENTS\n\nKey ingredient categories and their functions:\n\n• Cleansing Solubilizers or Surfactants: Help lift makeup and impurities.\n• Water-Based Components: Form the liquid cleansing base.\n• Skin-Conditioning Ingredients: Support comfortable cleansing.\n• The exact INCI, including fragrance and preservative ingredients, requires packaging verification.\n\nNote: Ingredient information is provisional and does not constitute a verified INCI declaration. Confirm the actual ingredients, concentrations and claims against the product packaging or official manufacturer documentation before publication.\n\n4. DIRECTIONS FOR USE\n\n1. Saturate a clean cotton pad with cleansing water.\n2. Gently wipe over the face to remove makeup and impurities.\n3. Use a fresh cotton pad as needed.\n4. Avoid excessive rubbing around the eyes.\n5. Follow with a rinse-off cleanser if appropriate.\n6. Continue with the usual skincare routine.\n\nPrecautions: For external use only. Avoid direct contact with eyes unless specifically intended for the eye area. Discontinue use if irritation occurs. Follow all warnings on the product label.\n\n5. SUITABLE FOR\n\n• People who wear everyday makeup.\n• Individuals seeking a first-step cleanser.\n• Normal and combination skin.\n• Those who prefer a lightweight cleansing-water format."}, "image": "assets/catalog/product-usolab-12.jpg", "gallery": {"vi": [{"src": "assets/catalog/vi/usolab-12/thumbnail.webp", "label": "Thumbnail", "order": 0}, {"src": "assets/catalog/vi/usolab-12/anh-1.webp", "label": "Ảnh 1", "order": 1}, {"src": "assets/catalog/vi/usolab-12/anh-2.webp", "label": "Ảnh 2", "order": 2}, {"src": "assets/catalog/vi/usolab-12/anh-3.webp", "label": "Ảnh 3", "order": 3}, {"src": "assets/catalog/vi/usolab-12/anh-4.webp", "label": "Ảnh 4", "order": 4}, {"src": "assets/catalog/vi/usolab-12/anh-5.webp", "label": "Ảnh 5", "order": 5}, {"src": "assets/catalog/vi/usolab-12/anh-6.webp", "label": "Ảnh 6", "order": 6}, {"src": "assets/catalog/vi/usolab-12/anh-7.webp", "label": "Ảnh 7", "order": 7}]}}, {"id": "usolab-13", "brandId": "usolab", "brand": "Usolab", "name": {"vi": "USOLAB BIO INTENSIVE SENSITIVE CLEANSER 120ML", "en": "USOLAB Bio Intensive Sensitive Cleanser 120ml"}, "category": "Skincare", "type": "Sữa rửa mặt", "size": "120ml", "country": "Hàn Quốc", "description": {"vi": "1. MÔ TẢ SẢN PHẨM\n\nTên sản phẩm: USOLAB Bio Intensive Sensitive Cleanser 120ml\nThương hiệu: USOLAB\nQuốc gia thương hiệu: Hàn Quốc\nQuy cách đóng gói: 120ml\nPhân loại: Sữa rửa mặt\n\nUSOLAB Bio Intensive Sensitive Cleanser 120ml là sản phẩm làm sạch dành cho nhu cầu chăm sóc da nhạy cảm, da dầu và da dễ nổi mụn theo danh mục giới thiệu của USOLAB Việt Nam. Sản phẩm hỗ trợ loại bỏ bụi bẩn, dầu thừa và tạp chất, giúp da sạch thoáng để tiếp tục các bước chăm sóc.\n\n2. CÔNG DỤNG\n\n• Làm sạch bụi bẩn và dầu thừa.\n• Giúp bề mặt da thông thoáng.\n• Hỗ trợ quy trình chăm sóc da dầu mụn.\n• Chuẩn bị da cho bước dưỡng tiếp theo.\n\n3. THÀNH PHẦN\n\nCác thành phần và nhóm thành phần nổi bật:\n\n• Hệ chất làm sạch: Hỗ trợ loại bỏ tạp chất.\n• Các thành phần hỗ trợ chăm sóc da: Cần đối chiếu INCI trên bao bì.\n• Chưa có đủ dữ liệu để xác nhận tên và nồng độ hoạt chất riêng của phiên bản 120ml.\n\nLưu ý: Chưa có bảng INCI đầy đủ đã xác minh cho SKU này. Không sử dụng phần mô tả nhóm thành phần để thay thế nhãn thành phần thực tế.\n\n4. HƯỚNG DẪN SỬ DỤNG\n\n1. Làm ướt mặt.\n2. Lấy lượng sữa rửa mặt vừa đủ.\n3. Massage nhẹ trên da, tránh mắt.\n4. Rửa sạch bằng nước.\n5. Dưỡng ẩm sau khi rửa.\n\nLưu ý: Chỉ sử dụng ngoài da. Tránh tiếp xúc trực tiếp với mắt. Ngừng sử dụng nếu xuất hiện kích ứng. Ưu tiên hướng dẫn trên bao bì sản phẩm thực tế.\n\n5. ĐỐI TƯỢNG SỬ DỤNG\n\n• Người có da dầu hoặc da dễ nổi mụn.\n• Người có da nhạy cảm cần chọn sản phẩm làm sạch phù hợp.\n• Người cần rửa mặt hằng ngày.", "en": "1. PRODUCT DESCRIPTION\n\nUSOLAB Bio Intensive Sensitive Cleanser is a facial cleansing product intended for skin that requires careful, gentle daily cleansing. It is positioned for sensitive-feeling skin and designed to remove dirt and routine impurities without the need for harsh physical scrubbing. The cleanser can be used before a soothing ampoule and moisturizer. Since sensitive skin can react differently to individual ingredients, the exact surfactants, fragrance content and other components should be checked against the current label.\n\n2. BENEFITS\n\n• Removes daily dirt and impurities.\n• Supports a gentle cleansing routine.\n• Helps prepare skin for moisturizing care.\n• Reduces the need for harsh scrubbing.\n• Complements skincare for sensitive-feeling skin.\n\n3. INGREDIENTS\n\nKey ingredient categories and their functions:\n\n• Cleansing Agents: Exact surfactants require label verification.\n• Skin-Conditioning Ingredients: Support a comfortable skin feel.\n• Moisture-Supporting Components: Confirm their presence in the current INCI.\n• Fragrance and Preservatives: Review the packaging if the skin is particularly reactive.\n\nNote: Ingredient information is provisional and does not constitute a verified INCI declaration. Confirm the actual ingredients, concentrations and claims against the product packaging or official manufacturer documentation before publication.\n\n4. DIRECTIONS FOR USE\n\n1. Wet the face with lukewarm water.\n2. Apply a small amount of cleanser.\n3. Massage gently without scrubbing.\n4. Rinse thoroughly.\n5. Pat dry using a soft towel.\n6. Follow with a suitable soothing moisturizer.\n\nPrecautions: For external use only. Avoid direct contact with eyes unless specifically intended for the eye area. Discontinue use if irritation occurs. Follow all warnings on the product label.\n\n5. SUITABLE FOR\n\n• Sensitive-feeling skin.\n• People seeking a gentle daily cleanser.\n• Skin prone to dryness-related discomfort.\n• Individuals following a minimal skincare routine."}, "image": "assets/catalog/product-usolab-13.jpg", "gallery": {"vi": [{"src": "assets/catalog/vi/usolab-13/thumbnail.webp", "label": "Thumbnail", "order": 0}, {"src": "assets/catalog/vi/usolab-13/anh-1.webp", "label": "Ảnh 1", "order": 1}, {"src": "assets/catalog/vi/usolab-13/anh-2.webp", "label": "Ảnh 2", "order": 2}, {"src": "assets/catalog/vi/usolab-13/anh-3.webp", "label": "Ảnh 3", "order": 3}, {"src": "assets/catalog/vi/usolab-13/anh-4.webp", "label": "Ảnh 4", "order": 4}, {"src": "assets/catalog/vi/usolab-13/anh-5.webp", "label": "Ảnh 5", "order": 5}, {"src": "assets/catalog/vi/usolab-13/anh-6.webp", "label": "Ảnh 6", "order": 6}, {"src": "assets/catalog/vi/usolab-13/anh-7.webp", "label": "Ảnh 7", "order": 7}]}}, {"id": "usolab-14", "brandId": "usolab", "brand": "Usolab", "name": {"vi": "USOLAB BIO INTENSIVE THERAPY BODY LOTION 250ML", "en": "USOLAB Bio Intensive Therapy Body Lotion 250ml"}, "category": "Body care", "type": "Sữa dưỡng thể", "size": "250ml", "country": "Hàn Quốc", "description": {"vi": "1. MÔ TẢ SẢN PHẨM\n\nTên sản phẩm: USOLAB Bio Intensive Therapy Body Lotion 250ml\nThương hiệu: USOLAB\nQuốc gia thương hiệu: Hàn Quốc\nQuy cách đóng gói: 250ml\nPhân loại: Sữa dưỡng thể\n\nUSOLAB Bio Intensive Therapy Body Lotion 250ml là sản phẩm dưỡng ẩm dành cho da cơ thể. Kết cấu lotion giúp sản phẩm dễ thoa trên vùng da rộng, hỗ trợ bổ sung độ ẩm, làm mềm những vùng da khô ráp và cải thiện cảm giác căng da sau khi tắm hoặc tiếp xúc với môi trường khô.\n\n2. CÔNG DỤNG\n\n• Bổ sung độ ẩm cho da cơ thể.\n• Giúp da mềm mại và mịn màng.\n• Hỗ trợ giảm cảm giác khô ráp.\n• Phù hợp sử dụng sau khi tắm.\n\n3. THÀNH PHẦN\n\nCác thành phần và nhóm thành phần nổi bật:\n\n• Các chất hút ẩm và làm mềm da: Hỗ trợ duy trì độ ẩm.\n• Các thành phần tạo nền lotion: Giúp sản phẩm dễ phân bố trên da.\n• Bảng INCI cụ thể của chai 250ml cần đối chiếu với bao bì thực tế.\n\nLưu ý: Chưa có bảng INCI đầy đủ đã xác minh cho SKU này. Không sử dụng phần mô tả nhóm thành phần để thay thế nhãn thành phần thực tế.\n\n4. HƯỚNG DẪN SỬ DỤNG\n\n1. Làm sạch và lau khô nhẹ da cơ thể.\n2. Lấy lượng lotion vừa đủ.\n3. Thoa đều lên tay, chân và các vùng da cần dưỡng.\n4. Massage nhẹ đến khi sản phẩm thấm.\n5. Sử dụng hằng ngày, đặc biệt sau khi tắm.\n\nLưu ý: Chỉ sử dụng ngoài da. Tránh tiếp xúc trực tiếp với mắt. Ngừng sử dụng nếu xuất hiện kích ứng. Ưu tiên hướng dẫn trên bao bì sản phẩm thực tế.\n\n5. ĐỐI TƯỢNG SỬ DỤNG\n\n• Người có da cơ thể khô hoặc thiếu ẩm.\n• Người muốn chăm sóc da body hằng ngày.\n• Người thích kết cấu sữa dưỡng dễ thoa.", "en": "1. PRODUCT DESCRIPTION\n\nUSOLAB Bio Intensive Therapy Body Lotion is a body moisturizer intended to improve the feel of dry, rough and uncomfortable skin. Its lotion format allows convenient application over larger areas of the body, helping maintain softness and hydration as part of daily care. It is particularly suitable for use after bathing, when skin may benefit from additional moisturizing. Despite the word Therapy in the product name, it should be described as a cosmetic body lotion rather than a medical treatment.\n\n2. BENEFITS\n\n• Moisturizes dry-feeling body skin.\n• Helps soften rough areas.\n• Supports a smoother skin feel.\n• Reduces the sensation of moisture-related tightness.\n• Suitable for regular after-shower moisturizing.\n\n3. INGREDIENTS\n\nKey ingredient categories and their functions:\n\n• Humectants: Help attract and retain moisture.\n• Emollients: Help soften dry skin.\n• Barrier-Conditioning Ingredients: Specific components require label verification.\n• The complete INCI and any claimed active ingredients must be checked against the 250ml bottle.\n\nNote: Ingredient information is provisional and does not constitute a verified INCI declaration. Confirm the actual ingredients, concentrations and claims against the product packaging or official manufacturer documentation before publication.\n\n4. DIRECTIONS FOR USE\n\n1. Cleanse the body and gently pat dry.\n2. Dispense a suitable amount of lotion.\n3. Apply evenly to arms, legs and other dry areas.\n4. Massage gently until absorbed.\n5. Reapply after bathing or whenever skin feels dry.\n6. Avoid application to open wounds unless the label specifically permits it.\n\nPrecautions: For external use only. Avoid direct contact with eyes unless specifically intended for the eye area. Discontinue use if irritation occurs. Follow all warnings on the product label.\n\n5. SUITABLE FOR\n\n• Normal to dry body skin.\n• People with rough or tight-feeling skin.\n• Individuals seeking everyday body moisturizing.\n• Those wanting a lotion for regular after-shower use."}, "image": "assets/catalog/product-usolab-14.jpg", "gallery": {"vi": [{"src": "assets/catalog/vi/usolab-14/thumbnail.webp", "label": "Thumbnail", "order": 0}, {"src": "assets/catalog/vi/usolab-14/anh-1.webp", "label": "Ảnh 1", "order": 1}, {"src": "assets/catalog/vi/usolab-14/anh-2.webp", "label": "Ảnh 2", "order": 2}, {"src": "assets/catalog/vi/usolab-14/anh-3.webp", "label": "Ảnh 3", "order": 3}, {"src": "assets/catalog/vi/usolab-14/anh-4.webp", "label": "Ảnh 4", "order": 4}, {"src": "assets/catalog/vi/usolab-14/anh-5.webp", "label": "Ảnh 5", "order": 5}, {"src": "assets/catalog/vi/usolab-14/anh-6.webp", "label": "Ảnh 6", "order": 6}, {"src": "assets/catalog/vi/usolab-14/anh-7.webp", "label": "Ảnh 7", "order": 7}]}}, {"id": "usolab-15", "brandId": "usolab", "brand": "Usolab", "name": {"vi": "USOLAB BIO INTENSIVE RESCUE LIP GEL 10ML", "en": "USOLAB Bio Intensive Rescue Lip Gel 10ml"}, "category": "Skincare", "type": "Gel dưỡng môi", "size": "10ml", "country": "Hàn Quốc", "description": {"vi": "1. MÔ TẢ SẢN PHẨM\n\nTên sản phẩm: USOLAB Bio Intensive Rescue Lip Gel 10ml\nThương hiệu: USOLAB\nQuốc gia thương hiệu: Hàn Quốc\nQuy cách đóng gói: 10ml\nPhân loại: Gel dưỡng môi\n\nUSOLAB Bio Intensive Rescue Lip Gel 10ml là sản phẩm chăm sóc môi dạng gel, hướng đến nhu cầu làm mềm và bổ sung độ ẩm cho môi khô. Sản phẩm giúp tạo lớp dưỡng trên bề mặt môi, hỗ trợ hạn chế cảm giác căng ráp và mang lại vẻ mềm mại, mịn màng hơn khi sử dụng thường xuyên.\n\n2. CÔNG DỤNG\n\n• Hỗ trợ dưỡng ẩm cho môi.\n• Làm mềm vùng môi khô ráp.\n• Giúp môi có cảm giác dễ chịu.\n• Thuận tiện sử dụng trong ngày.\n\n3. THÀNH PHẦN\n\nCác thành phần và nhóm thành phần nổi bật:\n\n• Các chất làm mềm và giữ ẩm trong nền gel dưỡng môi.\n• Các thành phần chăm sóc môi chuyên biệt: Cần đối chiếu bảng INCI của tuýp 10ml.\n• Không mặc định sản phẩm chứa một hoạt chất cụ thể khi chưa có thông tin nhãn.\n\nLưu ý: Chưa có bảng INCI đầy đủ đã xác minh cho SKU này. Không sử dụng phần mô tả nhóm thành phần để thay thế nhãn thành phần thực tế.\n\n4. HƯỚNG DẪN SỬ DỤNG\n\n1. Làm sạch môi.\n2. Lấy lượng gel vừa đủ.\n3. Thoa nhẹ lên bề mặt môi.\n4. Dặm lại khi môi có cảm giác khô.\n5. Đóng kín nắp sau khi sử dụng.\n\nLưu ý: Chỉ sử dụng ngoài da. Tránh tiếp xúc trực tiếp với mắt. Ngừng sử dụng nếu xuất hiện kích ứng. Ưu tiên hướng dẫn trên bao bì sản phẩm thực tế.\n\n5. ĐỐI TƯỢNG SỬ DỤNG\n\n• Người có môi khô.\n• Người thường xuyên sử dụng son lì.\n• Người muốn sản phẩm dưỡng môi dạng gel.", "en": "1. PRODUCT DESCRIPTION\n\nUSOLAB Bio Intensive Rescue Lip Gel is a targeted lip-care product intended to moisturize and condition dry-feeling lips. Its gel texture provides a convenient way to apply a conditioning layer over the lip surface, helping improve softness and reduce the feeling of tightness caused by dryness. It can be incorporated into a daily lip-care routine or used when lips need additional cosmetic moisturizing. The exact active ingredients and any specific protective claims should be confirmed against the 10ml packaging.\n\n2. BENEFITS\n\n• Helps moisturize dry lips.\n• Softens rough-feeling lip skin.\n• Supports a smoother lip appearance.\n• Helps reduce dryness-related tightness.\n• Offers convenient targeted lip care.\n\n3. INGREDIENTS\n\nKey ingredient categories and their functions:\n\n• Moisturizing Agents: Help support lip hydration.\n• Emollients: Condition the lip surface.\n• Film-Forming Ingredients: May contribute to the gel's protective feel; verify the formula.\n• The exact INCI, including fragrance or flavoring ingredients, requires label verification.\n\nNote: Ingredient information is provisional and does not constitute a verified INCI declaration. Confirm the actual ingredients, concentrations and claims against the product packaging or official manufacturer documentation before publication.\n\n4. DIRECTIONS FOR USE\n\n1. Ensure the lips are clean and dry.\n2. Apply a thin, even layer of lip gel.\n3. Reapply when the lips feel dry.\n4. Avoid licking the product off the lips.\n5. Discontinue use if irritation occurs.\n6. Follow the product label for any additional precautions.\n\nPrecautions: For external use only. Avoid direct contact with eyes unless specifically intended for the eye area. Discontinue use if irritation occurs. Follow all warnings on the product label.\n\n5. SUITABLE FOR\n\n• Dry or rough-feeling lips.\n• People seeking daily moisturizing lip care.\n• Individuals who prefer a gel lip product.\n• Those wanting targeted cosmetic lip conditioning."}, "image": "assets/catalog/product-usolab-15.jpg"}, {"id": "usolab-16", "brandId": "usolab", "brand": "Usolab", "name": {"vi": "USOLAB BIO RENATURATION REPAIR PREMIUM MASK PACK", "en": "USOLAB Bio Renaturation Repair Premium Mask Pack"}, "category": "Skincare", "type": "Mặt nạ chăm sóc da", "size": "Cần đối chiếu quy cách hộp/gói", "country": "Hàn Quốc", "description": {"vi": "1. MÔ TẢ SẢN PHẨM\n\nTên sản phẩm: USOLAB Bio Renaturation Repair Premium Mask Pack\nThương hiệu: USOLAB\nQuốc gia thương hiệu: Hàn Quốc\nQuy cách đóng gói: Cần đối chiếu quy cách hộp/gói\nPhân loại: Mặt nạ chăm sóc da\n\nUSOLAB Bio Renaturation Repair Premium Mask Pack là sản phẩm mặt nạ thuộc dòng Repair, hướng đến nhu cầu dưỡng ẩm và chăm sóc làn da khô, thiếu sức sống. Mặt nạ hỗ trợ bổ sung dưỡng chất trong thời gian đắp, giúp da có cảm giác mềm mại và dễ chịu sau khi sử dụng. Đây là bước chăm sóc bổ sung, không thay thế kem dưỡng hằng ngày.\n\n2. CÔNG DỤNG\n\n• Bổ sung độ ẩm trong thời gian đắp mặt nạ.\n• Hỗ trợ làm mềm da.\n• Giúp da có cảm giác dễ chịu.\n• Bổ sung bước chăm sóc trong quy trình dưỡng da.\n\n3. THÀNH PHẦN\n\nCác thành phần và nhóm thành phần nổi bật:\n\n• Các chất giữ ẩm và làm mềm da trong tinh chất mặt nạ.\n• Các thành phần chăm sóc thuộc dòng Repair: Cần xác minh trên nhãn.\n• Chưa đủ dữ liệu xác nhận bảng INCI và số miếng trong hộp.\n\nLưu ý: Chưa có bảng INCI đầy đủ đã xác minh cho SKU này. Không sử dụng phần mô tả nhóm thành phần để thay thế nhãn thành phần thực tế.\n\n4. HƯỚNG DẪN SỬ DỤNG\n\n1. Làm sạch da và sử dụng toner nếu cần.\n2. Mở bao bì, lấy mặt nạ theo hướng dẫn.\n3. Đắp đều lên mặt, tránh mắt và môi.\n4. Giữ trên da đúng thời gian ghi trên nhãn.\n5. Gỡ mặt nạ và vỗ nhẹ phần tinh chất còn lại nếu hướng dẫn cho phép.\n\nLưu ý: Chỉ sử dụng ngoài da. Tránh tiếp xúc trực tiếp với mắt. Ngừng sử dụng nếu xuất hiện kích ứng. Ưu tiên hướng dẫn trên bao bì sản phẩm thực tế.\n\n5. ĐỐI TƯỢNG SỬ DỤNG\n\n• Người có da thiếu ẩm.\n• Người muốn tăng cường bước dưỡng da.\n• Người cần mặt nạ chăm sóc da định kỳ.", "en": "1. PRODUCT DESCRIPTION\n\nUSOLAB Bio Renaturation Repair Premium Mask Pack is a facial mask product intended to provide an additional moisturizing and conditioning step in a skincare routine. Positioned within the Bio Renaturation Repair range, it is designed for skin that feels dry, stressed or in need of extra comfort. The precise mask format, essence composition, number of sheets and net weight have not been specified, so these details should be confirmed before publication. The product should be described as cosmetic skincare rather than a medical skin-repair treatment.\n\n2. BENEFITS\n\n• Provides an additional facial conditioning step.\n• Helps maintain a soft and moisturized skin feel.\n• Supports a comfortable skincare routine.\n• Complements the Bio Renaturation Repair range.\n• Convenient for periodic facial care.\n\n3. INGREDIENTS\n\nKey ingredient categories and their functions:\n\n• Moisturizing Complex: Exact ingredients require packaging verification.\n• Skin-Conditioning Ingredients: Support a comfortable skin feel.\n• Barrier-Supporting Ingredients: Specific substances must be confirmed from the INCI.\n• The full ingredient list and mask essence composition are not yet verified.\n\nNote: Ingredient information is provisional and does not constitute a verified INCI declaration. Confirm the actual ingredients, concentrations and claims against the product packaging or official manufacturer documentation before publication.\n\n4. DIRECTIONS FOR USE\n\n1. Cleanse the face thoroughly.\n2. Open the packaging and remove the mask according to its format.\n3. If it is a sheet mask, unfold and place it evenly over the face.\n4. Leave on only for the time specified on the packaging.\n5. Remove and gently pat remaining essence into the skin if directed.\n6. Follow with moisturizer as needed; do not reuse a single-use mask.\n\nPrecautions: For external use only. Avoid direct contact with eyes unless specifically intended for the eye area. Discontinue use if irritation occurs. Follow all warnings on the product label.\n\n5. SUITABLE FOR\n\n• Dry or dehydrated skin.\n• People seeking occasional facial moisturizing care.\n• Skin requiring additional conditioning.\n• Individuals following the Bio Renaturation Repair routine."}, "image": "assets/catalog/product-usolab-16.jpg", "gallery": {"vi": [{"src": "assets/catalog/vi/usolab-16/thumbnail.webp", "label": "Thumbnail", "order": 0}, {"src": "assets/catalog/vi/usolab-16/anh-1.webp", "label": "Ảnh 1", "order": 1}, {"src": "assets/catalog/vi/usolab-16/anh-2.webp", "label": "Ảnh 2", "order": 2}, {"src": "assets/catalog/vi/usolab-16/anh-3.webp", "label": "Ảnh 3", "order": 3}, {"src": "assets/catalog/vi/usolab-16/anh-4.webp", "label": "Ảnh 4", "order": 4}, {"src": "assets/catalog/vi/usolab-16/anh-5.webp", "label": "Ảnh 5", "order": 5}, {"src": "assets/catalog/vi/usolab-16/anh-6.webp", "label": "Ảnh 6", "order": 6}, {"src": "assets/catalog/vi/usolab-16/anh-7.webp", "label": "Ảnh 7", "order": 7}]}}]};
